INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (11, 'M11.21', 'Exam Question Bank', 21)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windscreen heating is supplied from', '[{"id": "a", "text": "frequency wild generator, via a rectifier.", "correct": false}, {"id": "b", "text": "frequency wild generator, direct to the windscreen.", "correct": true}, {"id": "c", "text": "DC generator, via a transformer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The stall speed', '[{"id": "a", "text": "does not depend on weight.", "correct": false}, {"id": "b", "text": "increases with an increased weight.", "correct": true}, {"id": "c", "text": "decreases with an increased weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing has a span of 50 feet and an area of 200 square feet. Its mean chord would be', '[{"id": "a", "text": "4 feet.", "correct": true}, {"id": "b", "text": "10 feet.", "correct": false}, {"id": "c", "text": "7.5 feet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing spoilers, when used asymmetrically, are associated with', '[{"id": "a", "text": "ailerons.", "correct": true}, {"id": "b", "text": "elevators.", "correct": false}, {"id": "c", "text": "rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As a subsonic aircraft speeds-up, its Centre of Pressure', '[{"id": "a", "text": "is unaffected.", "correct": false}, {"id": "b", "text": "moves forward.", "correct": false}, {"id": "c", "text": "moves aft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Slats are used to', '[{"id": "a", "text": "ensure the boundary layer does not separate from the wing surface too soon.", "correct": true}, {"id": "b", "text": "decrease the stalling angle.", "correct": false}, {"id": "c", "text": "change the wing camber.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Deploying a secondary flight control surface will', '[{"id": "a", "text": "not affect the angle of attack .", "correct": false}, {"id": "b", "text": "decrease the angle of attack of the aerofoil.", "correct": false}, {"id": "c", "text": "increase the angle of attack of the aerofoil .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is yawing to the left, where would you position the trim tab on the rudder to correct?', '[{"id": "a", "text": "To the right.", "correct": false}, {"id": "b", "text": "To the centre.", "correct": false}, {"id": "c", "text": "To the left.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A plain flap', '[{"id": "a", "text": "when retracted forms the lower surface of the wing.", "correct": false}, {"id": "b", "text": "when extended provides a slot between the wing and the flap.", "correct": false}, {"id": "c", "text": "when extended rotates on a simple hinge as if to bend the trailing edge of the wing down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is flying with a left wing low, where would you move the left aileron trim tab to correct?', '[{"id": "a", "text": "Up", "correct": true}, {"id": "b", "text": "Down", "correct": false}, {"id": "c", "text": "Moving the aileron trim tab will not correct the situation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a leading edge flap is fully extended, what is the slot in the wing for?', '[{"id": "a", "text": "To allow the flap to retract into it when it retracts.", "correct": false}, {"id": "b", "text": "To increase the lift.", "correct": false}, {"id": "c", "text": "To re-energise the boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sweepback on the wing will', '[{"id": "a", "text": "cause stall to occur at lower angles of attack", "correct": false}, {"id": "b", "text": "reduce tendency to tip stall.", "correct": false}, {"id": "c", "text": "increase tendency to tip stall.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With respect to differential aileron control, which of the following is true?', '[{"id": "a", "text": "The up -going and down - going ailerons both deflect to the same angle.", "correct": false}, {"id": "b", "text": "The up -going aileron moves through a smaller angle than the down-going aileron.", "correct": false}, {"id": "c", "text": "The down-going aileron moves through a smaller angle tha n the up-going aileron.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aeroplane fin is of symmetrical aerofoil section and will therefore provide a side -load', '[{"id": "a", "text": "only if a suitable angle of attack develops due to yaw.", "correct": false}, {"id": "b", "text": "only when the rudder is moved.", "correct": false}, {"id": "c", "text": "if a suitable angle of attack develops due either yaw or rudder movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft left wing is flying low. The aileron trimmer control to the left aileron trim tab in the cockpit would be', '[{"id": "a", "text": "moved -down causing the left aileron to move down.", "correct": false}, {"id": "b", "text": "moved -up causing the left aileron to move up.", "correct": false}, {"id": "c", "text": "moved -up causing the left aileron to move down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is true regarding deployment of Slats / Krueger flaps?', '[{"id": "a", "text": "Krueger flaps increase the critical angle of attack, Slats do not.", "correct": false}, {"id": "b", "text": "Slats form a slot, Krueger flaps do not.", "correct": true}, {"id": "c", "text": "Slats increase the critical angle of attack, Krue ger flaps do not.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a swept back wing, in which of the following locations would Krueger Flaps be fitted?', '[{"id": "a", "text": "Outboard leading edge.", "correct": false}, {"id": "b", "text": "Inboard leading edge.", "correct": true}, {"id": "c", "text": "The trailing edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane performs a straight and level horizontal flight at the same angle of attack at two different altitudes: (all other factors of importance being constant, assume ISA conditions and no compressibility effects)', '[{"id": "a", "text": "the TAS at the higher altitude is higher.", "correct": true}, {"id": "b", "text": "the TAS at the higher altitude is lower.", "correct": false}, {"id": "c", "text": "the TAS at both altitudes is the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Extending the flaps while maintaining a constant angle of attack (all other factors constant)', '[{"id": "a", "text": "the aircraft will climb.", "correct": true}, {"id": "b", "text": "the aircraft will yaw.", "correct": false}, {"id": "c", "text": "the aircraft will sink suddenly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What pitching moment will be generated when Fowler flaps are deployed on an aircraft with a high mounted (T - tail) tailplane?', '[{"id": "a", "text": "An aircraft nose down pitching moment.", "correct": true}, {"id": "b", "text": "The nose up pitching moment will be balanced by the nose down pitching moment.", "correct": false}, {"id": "c", "text": "An aircraft nose up pitching moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An increase in aspect ratio will', '[{"id": "a", "text": "cause VbaseMD to be increased.", "correct": false}, {"id": "b", "text": "cause induced drag to increase.", "correct": false}, {"id": "c", "text": "cause VbaseMD to be reduced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Geometric washout means that', '[{"id": "a", "text": "the tip of the wing has more angle of attack than the root.", "correct": false}, {"id": "b", "text": "there is an airflow along the wing that keeps it clean.", "correct": false}, {"id": "c", "text": "the tip of the wing has l ess angle of attack than the root.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a slot in a wing is to', '[{"id": "a", "text": "speed up the airflow and increase lift.", "correct": false}, {"id": "b", "text": "provide housing for the slat.", "correct": false}, {"id": "c", "text": "act as venturi, accelerate the air and re - energise boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do vortex generators work?', '[{"id": "a", "text": "Reduce the adverse pressure gradient.", "correct": false}, {"id": "b", "text": "Take energy from free stream and introduce it into the boundary layer.", "correct": true}, {"id": "c", "text": "Re-direct slantwise flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Winglets', '[{"id": "a", "text": "decrease the static lateral stability.", "correct": false}, {"id": "b", "text": "create an elliptical lift distribution.", "correct": false}, {"id": "c", "text": "decrease the induced drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which part of the wing of a swept - wing aircraft stalls first?', '[{"id": "a", "text": "Both stall together.", "correct": false}, {"id": "b", "text": "Root stalls first.", "correct": false}, {"id": "c", "text": "Tip stalls first.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A function of vortex generators in the transonic regime is to', '[{"id": "a", "text": "reduce boundary layer separation drag when shockwaves form.", "correct": true}, {"id": "b", "text": "prevent the rearward shift of CP on swept wing stalls.", "correct": false}, {"id": "c", "text": "reduce wing root compres sion effects.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During flight, an aircraft is yawing to the right. The aircraft would have a tendency to fly', '[{"id": "a", "text": "right wing low.", "correct": true}, {"id": "b", "text": "left wing low.", "correct": false}, {"id": "c", "text": "nose up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During acceleration in level flight', '[{"id": "a", "text": "the transition point on the wing moves forward.", "correct": false}, {"id": "b", "text": "the lift coeffici ent reduces.", "correct": true}, {"id": "c", "text": "the wing stagnation point moves aft .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As altitude increases, the equivalent airspeed at which an aeroplane stalls in a particular configuration will', '[{"id": "a", "text": "remain the same regardless of altitude.", "correct": true}, {"id": "b", "text": "remain equal to the calibrated airspeed.", "correct": false}, {"id": "c", "text": "decrease as the true airspeed decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a drop in ambient temperature, an aircraft service ceiling will', '[{"id": "a", "text": "not be affected.", "correct": false}, {"id": "b", "text": "lower.", "correct": false}, {"id": "c", "text": "rise.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aeroplane is flying at an airspeed which is 1.3 times its basic stalling speed, the coefficient of lift as a percentage of the maximum lift coefficient (CLmax) would be', '[{"id": "a", "text": "59%.", "correct": true}, {"id": "b", "text": "130%.", "correct": false}, {"id": "c", "text": "77% .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To maintain level flight, if the angle of attack is increased the speed must be', '[{"id": "a", "text": "increased in the same ratio as the lift/drag ratio decreases.", "correct": false}, {"id": "b", "text": "reduced.", "correct": true}, {"id": "c", "text": "increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flap selec tion at constant IAS in straight and level flight will increase the', '[{"id": "a", "text": "maximum lift coefficient (CLmax) and the drag.", "correct": true}, {"id": "b", "text": "lift and the drag.", "correct": false}, {"id": "c", "text": "lift coefficient and the drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In straight and level flight, if airspeed ... the angle of attack ... and the incidence angle...', '[{"id": "a", "text": "increases; decreases; decreases.", "correct": false}, {"id": "b", "text": "increases; increases; decreases.", "correct": false}, {"id": "c", "text": "decreases; increases; remains constant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What must happen to the CL when flaps are deployed while maintaining a constant IAS in straight and level flight?', '[{"id": "a", "text": "Remain constant.", "correct": true}, {"id": "b", "text": "Decrease.", "correct": false}, {"id": "c", "text": "Increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If VS is 100 kt in straight and level flight, during a 45 bank turn VS will be', '[{"id": "a", "text": "119 kts.", "correct": true}, {"id": "b", "text": "100 kts.", "correct": false}, {"id": "c", "text": "140 kts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the effect on TAS if altitude is increased to 35,000 ft while flying at a constant Mach number?', '[{"id": "a", "text": "Remain the same.", "correct": false}, {"id": "b", "text": "Increase then remain constant.", "correct": false}, {"id": "c", "text": "Decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If IAS is doubled, by which of the following factors should the original CL be multiplied to maintain level flight?', '[{"id": "a", "text": "4.0", "correct": false}, {"id": "b", "text": "0.5", "correct": false}, {"id": "c", "text": "0.25", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft is in a steady climb, how will the wing stalling angle be affected?', '[{"id": "a", "text": "The stalling angle will remain the same, regardless of altitude.", "correct": true}, {"id": "b", "text": "The stalling angle will in crease with increasing altitude.", "correct": false}, {"id": "c", "text": "The stalling angle will reduce with increasing altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The centre of pressure is in its most forward position', '[{"id": "a", "text": "when t he angle of attack is equal to the stalling angle of attack.", "correct": true}, {"id": "b", "text": "when the angle of attack exceeds the stalling angle of attack.", "correct": false}, {"id": "c", "text": "when the angle of attack is smaller than the stalling angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The angle of attack at which an aircraft stalls', '[{"id": "a", "text": "increases with an increase in gross weight.", "correct": false}, {"id": "b", "text": "remains constant regardless of gross weight.", "correct": true}, {"id": "c", "text": "varies with gross weight and density altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The following factors increase stall speed:', '[{"id": "a", "text": "A higher weight, selecting a higher flap setting, a forward c.g. shift.", "correct": false}, {"id": "b", "text": "An increase in load factor, a forward c.g. shift, decrease in thrust.", "correct": true}, {"id": "c", "text": "A lower weight, decreasing bank angle, a smaller flap setting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stall speed in a turn is proportional to', '[{"id": "a", "text": "weight.", "correct": false}, {"id": "b", "text": "the square root of the load factor.", "correct": true}, {"id": "c", "text": "lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane has a stalling speed of 100 kt in a steady level flight. When the aeroplane is flying a level turn with a load factor of 1.5, the stalling speed is', '[{"id": "a", "text": "122 kt.", "correct": true}, {"id": "b", "text": "141 kt.", "correct": false}, {"id": "c", "text": "82 kt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing stalling angle is', '[{"id": "a", "text": "decreased in a turn.", "correct": false}, {"id": "b", "text": "unaffected by a turn.", "correct": true}, {"id": "c", "text": "increased in a turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What effect does an increased load have on an aircraft?', '[{"id": "a", "text": "The aircraft will suffer immediate structural failure.", "correct": false}, {"id": "b", "text": "The aircraft will have a tendency to roll and yaw.", "correct": false}, {"id": "c", "text": "The aircraft will stall at a higher speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which stall has the greatest angle of attack?', '[{"id": "a", "text": "Deep stall.", "correct": true}, {"id": "b", "text": "Low speed stall.", "correct": false}, {"id": "c", "text": "High speed stall (shock stall).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A jet aeroplane cruises buffet free at high constant altitude in significant turbulence. Which type of stall can occur if this aeroplane decelerates?', '[{"id": "a", "text": "Shock stall.", "correct": false}, {"id": "b", "text": "Low speed stall.", "correct": false}, {"id": "c", "text": "Accelerated stall.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a swept wing aeroplane at low airspeed, the pitch -up phenomenon', '[{"id": "a", "text": "is caused by wingtip stall.", "correct": true}, {"id": "b", "text": "never occurs, since a swept wing is a remedy to pitch up.", "correct": false}, {"id": "c", "text": "is caused by extension of trailing edge lift augmentation devices.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following statements about stall speed is correct?', '[{"id": "a", "text": "Increasing the angle of sweep of the wing will decrease the stall speed.", "correct": false}, {"id": "b", "text": "Use of a T-tail will decrease the stall speed.", "correct": false}, {"id": "c", "text": "Decreasing the angle of sweep of the wing will decrease the stall speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are the wing stalling angle and the lift coefficient affected when altitude increases and EAS is held constant?', '[{"id": "a", "text": "The lift coefficient remains constant and the wing stalling angle will reduce.", "correct": false}, {"id": "b", "text": "The lift coefficient and the wing stalling angle both decrease.", "correct": false}, {"id": "c", "text": "The lift coefficient and the wing stalling angle both remain constant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Increase of wing loading will', '[{"id": "a", "text": "decrease the minimum gliding angle.", "correct": false}, {"id": "b", "text": "increase the stall speed.", "correct": true}, {"id": "c", "text": "decrease take off speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The most common stall sensing devices are normally located', '[{"id": "a", "text": "on the upper surface of the wing.", "correct": false}, {"id": "b", "text": "at or near the wing leading edge.", "correct": true}, {"id": "c", "text": "on the lower surface of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If angle of attack is increased beyond th e critical angle of attack, the lift coefficient ... and the stagnation point moves...', '[{"id": "a", "text": "decreases; rearward", "correct": false}, {"id": "b", "text": "increases; rearward", "correct": false}, {"id": "c", "text": "decreases; forward", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a turn, the wing stalling angle', '[{"id": "a", "text": "remains unchanged.", "correct": true}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As the angle of attack of a wing is increased, the centre of pressure will reach its most forward position on the wing', '[{"id": "a", "text": "just before the wing stalls.", "correct": true}, {"id": "b", "text": "when the aircraft is stalling.", "correct": false}, {"id": "c", "text": "after stall recovery.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which kind of boundary layer has the strongest change in velocity close to the surface?', '[{"id": "a", "text": "Turbulent boundary layer.", "correct": true}, {"id": "b", "text": "No difference.", "correct": false}, {"id": "c", "text": "Laminar boundary layer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One disadvantage of the swept back wing is it is stalling characteristics. At the stall', '[{"id": "a", "text": "tip stall will occur first, which produces a nose -down moment.", "correct": false}, {"id": "b", "text": "tip stall will occur first, which produces a pitch -up moment.", "correct": true}, {"id": "c", "text": "wing root stall will occur first, which produces a rolling moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following aircraft designs would be most prone to super stall?', '[{"id": "a", "text": "T-tail.", "correct": true}, {"id": "b", "text": "Swept forward wing.", "correct": false}, {"id": "c", "text": "Swept back wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The stall speed in a 60° banked turn increases by the following factor:', '[{"id": "a", "text": "1.", "correct": false}, {"id": "b", "text": "1.41.", "correct": true}, {"id": "c", "text": "2.00.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The speed range between high and low speed buffet', '[{"id": "a", "text": "increases during descent at a constant IAS.", "correct": true}, {"id": "b", "text": "decreases during a descent at a constant Mach number.", "correct": false}, {"id": "c", "text": "increas es during climb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The boundary layer of a wing is caused by', '[{"id": "a", "text": "a layer on the wing in which the stream velocity is lower than the free stream velocity, due to friction.", "correct": true}, {"id": "b", "text": "suction at the upper wing side.", "correct": false}, {"id": "c", "text": "a turbulent stream pattern around the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pitch -up effect of an aeroplane with swept wing in a stall is due to the', '[{"id": "a", "text": "forward movement of the centre of gravity.", "correct": false}, {"id": "b", "text": "wing root stalling first.", "correct": false}, {"id": "c", "text": "wing tip stalling first.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft with a typical aerofoil is in level flight at low speed and high angle of attack, the normal axis is', '[{"id": "a", "text": "horizontal from side to side.", "correct": false}, {"id": "b", "text": "nearly vertical,", "correct": true}, {"id": "c", "text": "vertical.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane has a stall speed of 78 KCAS at its gross weight of 6.850 lbs. What is the stall speed when the weight is 5.000 lbs?', '[{"id": "a", "text": "67 KCAS", "correct": true}, {"id": "b", "text": "91 KCAS", "correct": false}, {"id": "c", "text": "78 KCAS", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What causes a swept wing aircraft to pitch-up at the stall?', '[{"id": "a", "text": "Rearward movement of the CP.", "correct": false}, {"id": "b", "text": "Spanwise flow.", "correct": true}, {"id": "c", "text": "Separated airflow a t the root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When all other factors of importance are constant, the stall speed increases when', '[{"id": "a", "text": "spoilers are retracted.", "correct": false}, {"id": "b", "text": "pulling out of a dive.", "correct": true}, {"id": "c", "text": "weight decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is the correct order of configuration to give an increasing critical angle of attack?', '[{"id": "a", "text": "Trailin g edge flaps extended, clean wing, slats extended.", "correct": true}, {"id": "b", "text": "Slats extended, clean wing, trailing edge flaps extended.", "correct": false}, {"id": "c", "text": "Clean wing, trailing edge flaps extended, slats extended.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the percentage increase in stall speed in a 45° bank turn', '[{"id": "a", "text": "19%.", "correct": true}, {"id": "b", "text": "10%.", "correct": false}, {"id": "c", "text": "45%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft wing stalls', '[{"id": "a", "text": "a wing which is not swept back will stall from the root and the CP will move forwards.", "correct": false}, {"id": "b", "text": "a swept back wing will stall from the tip and the CP will move forward.", "correct": true}, {"id": "c", "text": "a swept back wing will stall from the root and the CP will move aft .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At the same weight, with the CG at its forward limit', '[{"id": "a", "text": "VbaseS is higher, the stalling angle is unchanged.", "correct": true}, {"id": "b", "text": "VbaseS is lower, the stalling angle is unchanged.", "correct": false}, {"id": "c", "text": "VbaseS is higher, the stalling angle is greater.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Two identical aeroplanes A and B are flying horizontal steady turns. Further data is: A: W=1500 kg Bank= 20° TAS= 130 kt, B: W= 1500 kg Bank= 20° TAS= 200 kt. Which of the following statements is correct?', '[{"id": "a", "text": "The rate of turn A is larger than the rate of tur n B.", "correct": true}, {"id": "b", "text": "The turn radius A is larger than the turn radius B.", "correct": false}, {"id": "c", "text": "The load factor A is larger than the load factor B.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following situations leads to a decreasing stall speed (IAS)?', '[{"id": "a", "text": "Increasing air density.", "correct": false}, {"id": "b", "text": "Increasing load factor.", "correct": false}, {"id": "c", "text": "Decreasing weight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The critical angle of attack', '[{"id": "a", "text": "increases if the CG is moved forward.", "correct": false}, {"id": "b", "text": "changes with an increase in gross weight.", "correct": false}, {"id": "c", "text": "remains unchanged regardless of gross weight .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane has been loaded in such a manner that the centre of gravity is located behind the aft centre of gravity limit. One undesirable flight characteristic a pilot might experience with this aeroplane would be', '[{"id": "a", "text": "difficulty in recovering from a stalled condition.", "correct": true}, {"id": "b", "text": "a longer takeoff run.", "correct": false}, {"id": "c", "text": "stalling at higher -than -normal airspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'V[base=so] is defined as the', '[{"id": "a", "text": "stalling speed or minimum takeoff safety speed.", "correct": false}, {"id": "b", "text": "stalling speed or minimum steady flight speed in a specified configuration.", "correct": false}, {"id": "c", "text": "stalling speed or minimum steady flight speed in the landing configuration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With the centre of gravity on the forward limit, the stalling speed would be', '[{"id": "a", "text": "lower than with the centre of gravity on the aft limit.", "correct": false}, {"id": "b", "text": "the same as with the centre of gravity on the aft limit.", "correct": false}, {"id": "c", "text": "higher than with the centre of gravity on the aft limit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The following takes place at the transition point on a wing:', '[{"id": "a", "text": "The airflow separates completely from the wing surface.", "correct": false}, {"id": "b", "text": "The boundary layer makes the transition from laminar flow to the turbulent boundary layer.", "correct": true}, {"id": "c", "text": "The total dynamic and static pressure comes to a standstill.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A low wing loading (aircraft weight has been reduced)', '[{"id": "a", "text": "decreases stalling speed and la nding speed.", "correct": true}, {"id": "b", "text": "increases take -off run, stalling speed and landing speed.", "correct": false}, {"id": "c", "text": "increases stalling speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stalling speed in a 15° bank level turn is 60kt. The stalling speed in a 45° bank level turn will be', '[{"id": "a", "text": "60 kts.", "correct": false}, {"id": "b", "text": "70 kts.", "correct": true}, {"id": "c", "text": "50 kts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How does stalling speed (IAS) vary with altitude?', '[{"id": "a", "text": "It remains constant at lower altitudes but decreases at higher altitudes due to compressibility effects.", "correct": false}, {"id": "b", "text": "It remains constant.", "correct": true}, {"id": "c", "text": "It increases with increasing altitude, because the density decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As the centre of gravity is changed, recovery from a stall becomes progressively', '[{"id": "a", "text": "becomes progressively more difficult as the centre of gravity moves aft.", "correct": true}, {"id": "b", "text": "is unaffected by centre of gravity position.", "correct": false}, {"id": "c", "text": "becomes progressively more difficult as the centre of gravity moves forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To ensure that a wing stalls at the root first, stall we dges are', '[{"id": "a", "text": "installed at the wing trailing edge at the wing root.", "correct": false}, {"id": "b", "text": "installed on the wing leading edge at the wing root.", "correct": true}, {"id": "c", "text": "installed on the wing leading edge at the wing tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following statements about boundary layers is correct?', '[{"id": "a", "text": "The turbulent boundary layer gives a lower skin friction than the laminar boundary layer.", "correct": false}, {"id": "b", "text": "The turbulent boundary layer is thinner than the laminar boundary layer.", "correct": false}, {"id": "c", "text": "The turbulent boundary layer has more kinetic energy than the laminar boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The angle of attack at which a wing stalls will', '[{"id": "a", "text": "remain the same regardless of centre of gravity position.", "correct": true}, {"id": "b", "text": "increase if the centre of gravity is moved aft.", "correct": false}, {"id": "c", "text": "increase if the centre of gravity is moved forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Entering the stall the centre of pressure of a straight (1) wing and of a strongly swept back wing (2) will', '[{"id": "a", "text": "(1) move aft, (2) move forward.", "correct": true}, {"id": "b", "text": "(1) not move (2) move forward.", "correct": false}, {"id": "c", "text": "(1) move aft, (2) not move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compared with stalling airspeed (V S ) in a given configuration, the airspeed at which stick shaker will be triggered is', '[{"id": "a", "text": "greater than V[base=S].", "correct": true}, {"id": "b", "text": "V[base=S].", "correct": false}, {"id": "c", "text": "less than V[base=S].", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A boundary layer fence on a swept wing will', '[{"id": "a", "text": "increase the critical Mach Number.", "correct": false}, {"id": "b", "text": "improve the low speed characteristics.", "correct": true}, {"id": "c", "text": "improve the high speed characteristics.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the straight and level stall speed is 100 kt, what will be the stall speed in a 1.5g turn?', '[{"id": "a", "text": "81 kts", "correct": false}, {"id": "b", "text": "122 kts", "correct": true}, {"id": "c", "text": "150 kts", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How does stalling speed vary with load factor?', '[{"id": "a", "text": "It increases proportionally with the square root of the load factor.", "correct": true}, {"id": "b", "text": "It decreases inversely with the load factor.", "correct": false}, {"id": "c", "text": "It decreases inversely with the square root of the load factor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When entering a stall, the CG of a straight wing will (1) and of a strongly swept wing will (2)', '[{"id": "a", "text": "(1) move aft, (2) move aft.", "correct": false}, {"id": "b", "text": "(1) not move, (2) not move.", "correct": true}, {"id": "c", "text": "(1) move aft, (2) not move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After the transition p oint between the laminar and turbulent boundary layer', '[{"id": "a", "text": "the mean speed increases and the friction drag decreases.", "correct": false}, {"id": "b", "text": "the boundary layer gets thicker and the speed decreases.", "correct": false}, {"id": "c", "text": "the mean speed and friction drag increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The wing of an aeroplane will never st all at low subsonic speeds as long as', '[{"id": "a", "text": "there is a nose -down attitude.", "correct": false}, {"id": "b", "text": "the IAS exceeds the power -on stall speed.", "correct": false}, {"id": "c", "text": "the angle of attack is smaller than the value at which the stall occurs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The load factor is', '[{"id": "a", "text": "the ratio of thrust to weight.", "correct": false}, {"id": "b", "text": "the ratio of lift to weight.", "correct": true}, {"id": "c", "text": "the ratio of lift to drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which type of stall has the largest associated angle of attack?', '[{"id": "a", "text": "Deep stall.", "correct": true}, {"id": "b", "text": "Shock stall.", "correct": false}, {"id": "c", "text": "Low speed stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which statement is correct about the laminar and turbulent boundary layer?', '[{"id": "a", "text": "Friction drag is lower in the laminar layer.", "correct": true}, {"id": "b", "text": "Friction drag is lower in the turbulent layer.", "correct": false}, {"id": "c", "text": "Separation point will occur earlier in the turbulent layer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A slotted flap will increase the CLmax by', '[{"id": "a", "text": "increasing only the camber of the aerofoil.", "correct": false}, {"id": "b", "text": "increasing the critical angle of attack.", "correct": false}, {"id": "c", "text": "increasing the camber of the aerofoil and improving the boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a trailing edge flap is lowered fully', '[{"id": "a", "text": "the C of P moves to the rear and lift/drag ratio is unaffected.", "correct": false}, {"id": "b", "text": "the C of P moves to the rear and lift/drag ratio is decreased.", "correct": true}, {"id": "c", "text": "the C of P moves to the rear and lift/drag ratio is increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which statement is correct?', '[{"id": "a", "text": "Extension of flaps will increase (CL/CD)max, causing the minimum rate of descent to decrease.", "correct": false}, {"id": "b", "text": "Extension of flaps causes a reduction of the stall speed, the maximum glide distance also reduces.", "correct": true}, {"id": "c", "text": "Spoiler extension decreases the stall speed and the minimum rate of descent, but increases the minimum", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the angle of attack of an aircraft is progressively increased, the wing centre of pressure will reach its most forward position', '[{"id": "a", "text": "when the aircraft has stalled.", "correct": false}, {"id": "b", "text": "at the optimum angle of attack of the wing.", "correct": false}, {"id": "c", "text": "at the maximum lift coefficient ( C[base=lmax] ).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the most effective flap system?', '[{"id": "a", "text": "Split flap.", "correct": false}, {"id": "b", "text": "Single slotted flap.", "correct": false}, {"id": "c", "text": "Fowler flap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane with swept back wings is equipped with slats and/or leading edge (L.E.) flaps. One possible efficient way to arrange the leading edge devices on the wings is', '[{"id": "a", "text": "Wing roots: L.E. flaps Wing tips: no devices.", "correct": false}, {"id": "b", "text": "Wing roots: L.E. flaps Wing tips: slats.", "correct": true}, {"id": "c", "text": "Wing roots: slats Wing tips: L.E. flaps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following statements about the difference between Krueger flaps and slats is correct?', '[{"id": "a", "text": "Deploying a slat will form a slot deploying a Krueger flap does not.", "correct": true}, {"id": "b", "text": "Deploying a Krueger flap will increas e critical angle of attack, deploying a slat does not.", "correct": false}, {"id": "c", "text": "Deploying a slat will increase critical angle of attack, deploying a Krueger flap does not.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vortex generators', '[{"id": "a", "text": "change the turbulent boundary layer into a laminar boundary layer.", "correct": false}, {"id": "b", "text": "reduce the span wise flow on swept wing.", "correct": false}, {"id": "c", "text": "transfer energy from the free airflow into the boundary layer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When vortex generators are fitted they will normally be found', '[{"id": "a", "text": "towards the wing trailing edge.", "correct": false}, {"id": "b", "text": "towards the wing root to act as a stall inducer.", "correct": false}, {"id": "c", "text": "near the wing leading edge in front of control surfaces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During the extension of the flaps at a constant angle of attack the aeroplane starts to: (all other factors of importance being constant)', '[{"id": "a", "text": "bank.", "correct": false}, {"id": "b", "text": "sink suddenly.", "correct": false}, {"id": "c", "text": "climb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Deploying a Fowler flap, the flap will', '[{"id": "a", "text": "turn d own, then move aft.", "correct": false}, {"id": "b", "text": "move aft, then turn down.", "correct": true}, {"id": "c", "text": "just move aft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane has the following flap settings: 0°, 15°, 30° and 45°. Slats can be selected too. Which of the above selections will produce the greatest negative influence on the CL/CD ratio?', '[{"id": "a", "text": "Flaps from 0° to 15°.", "correct": false}, {"id": "b", "text": "Flaps from 30° to 45°.", "correct": true}, {"id": "c", "text": "Flaps from 15° to 30°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The effect of Winglets is', '[{"id": "a", "text": "reduction in induced drag.", "correct": true}, {"id": "b", "text": "elliptical pressure distribution increases.", "correct": false}, {"id": "c", "text": "decrease in stall speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When flaps are extended in a straight and level flight at constant IAS, the lift coefficient will eventually', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "remain the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When spoilers are used as speed brakes', '[{"id": "a", "text": "they do not affect wheel braking action during landing.", "correct": false}, {"id": "b", "text": "at same angle of attack, CD is increased and CL is decreased.", "correct": true}, {"id": "c", "text": "at same angle of attack, CL remains unaffected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a trailing edge flap is lowered during flight from take-off position to fully down position, one will experience', '[{"id": "a", "text": "a large increase in lift and a small increase in drag.", "correct": false}, {"id": "b", "text": "a small increase in lift and a lar ge increase in drag.", "correct": true}, {"id": "c", "text": "a large increase in lift and a large increase in drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of an auto- slat system?', '[{"id": "a", "text": "Extend automatically when a certain value of angle of attack is exceeded.", "correct": true}, {"id": "b", "text": "Provide automatically slat IN selection after take-off.", "correct": false}, {"id": "c", "text": "Ensures that the slats are always extended when the ground/flight system is in the ground position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following series of configurations has an increasing critical angle of attack?', '[{"id": "a", "text": "Flaps only extended, clean wing, slats only extended.", "correct": true}, {"id": "b", "text": "Slats only extended, flaps only extended, clean wing.", "correct": false}, {"id": "c", "text": "Clean wing, flaps only extended, slats only extended.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where on the surface of a typical aerofoil will flow separation normally start at high angles of attack?', '[{"id": "a", "text": "Upper side leading edge.", "correct": false}, {"id": "b", "text": "Lower side leading edge.", "correct": false}, {"id": "c", "text": "Upper side trailing edge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the flaps are lowered but the airspeed is kept constant, to maintain level flight', '[{"id": "a", "text": "the nose must be pitched down.", "correct": true}, {"id": "b", "text": "the altitude must be held constant.", "correct": false}, {"id": "c", "text": "the nose must be pitched up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The effects of leading edge slats', '[{"id": "a", "text": "increase camber, increase suction peak on main wing, increase effective angle of attack and move", "correct": false}, {"id": "b", "text": "C[base=Lmax) to higher angle of attack.", "correct": false}, {"id": "c", "text": "increase boundary layer energy, increase suction peak on main wing section, move C[base=Lmax) to a", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flaps are used in order to', '[{"id": "a", "text": "increase max lift coefficient by increasing max angle of attack.", "correct": false}, {"id": "b", "text": "increase max L/D.", "correct": false}, {"id": "c", "text": "decrease stalling speed and reduce max angle of attac k thereby achieving a more nose down attitude near", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Deflection of leading edge flaps will', '[{"id": "a", "text": "increase critical angle of attack.", "correct": true}, {"id": "b", "text": "decrease C[base=Lmax].", "correct": false}, {"id": "c", "text": "decrease drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During flap down selection in a continuous straight and level flight at constant IAS and weight', '[{"id": "a", "text": "the lift coefficient and the drag coefficient increase.", "correct": false}, {"id": "b", "text": "the stall speed increases.", "correct": false}, {"id": "c", "text": "the centre of pressure moves aft, lift coefficient and the drag coefficient increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'C[base=Lmax] may be increased by the use of', '[{"id": "a", "text": "both flaps and slats.", "correct": true}, {"id": "b", "text": "flaps.", "correct": false}, {"id": "c", "text": "slats.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compared with the flap up configuration the maximum angle of attack for the flaps down configuration is', '[{"id": "a", "text": "unchanged.", "correct": false}, {"id": "b", "text": "larger.", "correct": false}, {"id": "c", "text": "smaller.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compared with the flap down configuration the maximum angle of attack for the flaps up configuration is', '[{"id": "a", "text": "smaller.", "correct": false}, {"id": "b", "text": "larger.", "correct": true}, {"id": "c", "text": "unchanged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the pitching moment affected if flaps are deployed in straight and level flight?', '[{"id": "a", "text": "Depends on wing position.", "correct": true}, {"id": "b", "text": "Pitch up.", "correct": false}, {"id": "c", "text": "Pitch down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the effect of lowering leading edge and trailing edge flaps in flight?', '[{"id": "a", "text": "Cl decreases, Cd increases and the stalling angle of attack reduces.", "correct": false}, {"id": "b", "text": "Cl increases, Cd increases and the stalling angle of attack increases.", "correct": true}, {"id": "c", "text": "Cl increases, Cd remains the same and the stalling angle of attack increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Lowering the inboard flaps causes the wing Centre of Pressure', '[{"id": "a", "text": "to move outboard towards the wing tips.", "correct": false}, {"id": "b", "text": "to move forward.", "correct": false}, {"id": "c", "text": "to move inboard towards the wing root.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Slats', '[{"id": "a", "text": "re -energise the boundary layer thereby increasing the stalling angle of attack.", "correct": true}, {"id": "b", "text": "re -energise the boundary layer thereby decreasing the stalling angle of attack.", "correct": false}, {"id": "c", "text": "de-energise the boundary layer, thereby decreasing the stalling angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When deploying the flaps the effective angle of attack', '[{"id": "a", "text": "remains the same.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vortex generators mounted on the upper wing surface will', '[{"id": "a", "text": "increase the interference drag of the trailing edge flaps.", "correct": false}, {"id": "b", "text": "decrease the shock wave induced separation.", "correct": true}, {"id": "c", "text": "decrease the stalling speed by increase of the tangential velocity of the swept wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'It is possible to reduce the span wise airflow over swept wings, due to adverse pressure gradients, by', '[{"id": "a", "text": "wing fences.", "correct": true}, {"id": "b", "text": "trailing edge vortex generators.", "correct": false}, {"id": "c", "text": "increased anhedral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After take-off the slats (when installed) are always retracted later than the flaps. Why?', '[{"id": "a", "text": "Because SLATS EXTENDED provides a better view from the cockpit than FLAPS EXTENDED.", "correct": false}, {"id": "b", "text": "Because SLATS EXTENDED gives a large decrease in stall speed with relatively less drag.", "correct": true}, {"id": "c", "text": "Because FLAPS EXTENDED gives a large decrease in stall speed with relatively less drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In order to maintain straight and level flight at a constant airspeed, whilst the flaps are being retracted, the angle of attack will', '[{"id": "a", "text": "remain constant.", "correct": false}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If flaps are deployed at constant IAS in straight and level flight, the magnitude of tip vortices will eventually: (flap span less than wing span)', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "remain the same.", "correct": false}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The trailing edge flaps, when extended', '[{"id": "a", "text": "worsen the best angle of glide.", "correct": true}, {"id": "b", "text": "significantly increase the angle of attack for maximum lift.", "correct": false}, {"id": "c", "text": "improve the best angle of glide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the main purposes of using flaps during approach and landing is to', '[{"id": "a", "text": "increase the angle of descent without increasing the airspeed.", "correct": true}, {"id": "b", "text": "shift the centre of gravity aft.", "correct": false}, {"id": "c", "text": "decrease the angle of descent without increasing the airspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The use of a slot in the leading edge of the wing enables the aeroplane to fly at a slower speed because', '[{"id": "a", "text": "the laminar part of the boundary layer gets thicker.", "correct": false}, {"id": "b", "text": "it delays the stall to a higher angle of attack.", "correct": true}, {"id": "c", "text": "it changes the camber of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the effect of deploying leading edge flaps?', '[{"id": "a", "text": "Decrease the critical angle of attack.", "correct": false}, {"id": "b", "text": "Not affect the critical angle of attack.", "correct": false}, {"id": "c", "text": "Increase the critical angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The lift coefficient C[base=L] of a wing at a given angle of attack', '[{"id": "a", "text": "is incre ased by the use of high lift devices.", "correct": true}, {"id": "b", "text": "is constant and not affected by high lift devices.", "correct": false}, {"id": "c", "text": "is dependent on the surface area of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The optimum angle of attack for a typical aerofoil is about ____, and the actual angle of attack will be clo se to this optimum angle during _______.', '[{"id": "a", "text": "4°, cruise", "correct": true}, {"id": "b", "text": "4°, a stall", "correct": false}, {"id": "c", "text": "16°, a stall", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Upon extension of a spoiler on a wing', '[{"id": "a", "text": "C[base=D] is increased and C[base=L] is decreased.", "correct": true}, {"id": "b", "text": "C[base=L] is increased, while C[base=D] remains unaffected", "correct": false}, {"id": "c", "text": "only C[base=L] is decreased (C[base=D] remains unaffected)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the weight of an aircraft is increased, the maximum lift - to -drag ratio will', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "not be affected.", "correct": true}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With reference to differential aileron control', '[{"id": "a", "text": "drag decreases on the outer wing.", "correct": false}, {"id": "b", "text": "drag increases on the outer wing.", "correct": false}, {"id": "c", "text": "drag increases on the inner wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Why are vortex generators often fitted on aircraft with straight wings?', '[{"id": "a", "text": "To delay boundary layer separation.", "correct": true}, {"id": "b", "text": "To reduce span wise airflow towards the wing root on the intrados.", "correct": false}, {"id": "c", "text": "To reduce span wise airflow towards the wi ng tips on the extrados.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Induced drag curve characteristics of a slender delta wing are such that there is', '[{"id": "a", "text": "an increase in gradient with wing speed.", "correct": false}, {"id": "b", "text": "decrease in gradient with wing speed.", "correct": true}, {"id": "c", "text": "no change in gradient with wing speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is yawing left, to correct, the trim tab on the rudder would need to be positioned', '[{"id": "a", "text": "to the left, moving the rudder right.", "correct": true}, {"id": "b", "text": "to the centre.", "correct": false}, {"id": "c", "text": "to the right, moving the rudder left.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The tropopause exists at about', '[{"id": "a", "text": "18,000 ft.", "correct": false}, {"id": "b", "text": "36,000 ft.", "correct": true}, {"id": "c", "text": "30,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which leading edge device improves the laminar flow over the wing?', '[{"id": "a", "text": "Flap", "correct": false}, {"id": "b", "text": "Flap and slat", "correct": false}, {"id": "c", "text": "Slat", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Due to the change in lift coefficient accompanying extension of the flaps, to maintain the lift constant it would be necessary to', '[{"id": "a", "text": "keep the pitch attitude constant.", "correct": false}, {"id": "b", "text": "raise the nose.", "correct": false}, {"id": "c", "text": "lower the nose.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Due to the tailplane angle of attack change, the flap-induced downwash on the tailplane', '[{"id": "a", "text": "will tend to cause an aircraft nose-up pitch.", "correct": true}, {"id": "b", "text": "will tend to cause an aircraft nose down pitch.", "correct": false}, {"id": "c", "text": "may cause a nose-down or nose-up pitch depending upon the initial tailplane load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Downward displacement of an aileron', '[{"id": "a", "text": "increases the angle at which its wing stalls.", "correct": false}, {"id": "b", "text": "decreases the angle at which its wing will stall.", "correct": true}, {"id": "c", "text": "has no effect on its wing stalling angle, it only affects the stalling speed on that wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The stalling speed of an aircraft', '[{"id": "a", "text": "is increased when it is heavier.", "correct": true}, {"id": "b", "text": "does not change.", "correct": false}, {"id": "c", "text": "is increased when it is lighter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With an increase in the amount of flap deployment, the stalling angle of a wing', '[{"id": "a", "text": "increases.", "correct": false}, {"id": "b", "text": "remains the same.", "correct": false}, {"id": "c", "text": "decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The primary function of a flap is', '[{"id": "a", "text": "to alter the lift of an aerofoil.", "correct": true}, {"id": "b", "text": "to alter the position of the centre of gravity.", "correct": false}, {"id": "c", "text": "to trim the aircraft longitudinally.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a bank and turn', '[{"id": "a", "text": "extra lift is not required if thrust is increased.", "correct": false}, {"id": "b", "text": "extra lift is required.", "correct": true}, {"id": "c", "text": "extra lift is not required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The angle of attack at which stall occurs', '[{"id": "a", "text": "can be varied by using flaps and slats.", "correct": true}, {"id": "b", "text": "cannot be varied, it is always constant.", "correct": false}, {"id": "c", "text": "depends on the weight of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft stalls', '[{"id": "a", "text": "lift increases and drag decreases.", "correct": false}, {"id": "b", "text": "lift and drag increase.", "correct": false}, {"id": "c", "text": "lift decreases and drag increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft stalling speed will', '[{"id": "a", "text": "increase with an increase in weight.", "correct": true}, {"id": "b", "text": "be unaffected by aircraft weight changes since it is dependant upon the angle of attack.", "correct": false}, {"id": "c", "text": "only change if the MTWA were changed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Changes in aircraft weight', '[{"id": "a", "text": "cause corresponding changes in total drag due to the associated lift change.", "correct": true}, {"id": "b", "text": "will not affect total drag since it is dependant only upon speed.", "correct": false}, {"id": "c", "text": "will only affect total drag if the lift is kept constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is a controlling factor of turbulence and skin friction?', '[{"id": "a", "text": "Aspect ratio.", "correct": false}, {"id": "b", "text": "Fineness ratio.", "correct": false}, {"id": "c", "text": "Countersunk rivets used on skin exterior.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When airflow velocity over an upper cambered surface of an aerofoil decreases, what takes place?', '[{"id": "a", "text": "Pressure decreases, lift increases.", "correct": false}, {"id": "b", "text": "Pressure increases, lift decreases.", "correct": true}, {"id": "c", "text": "Pressure increases, lift increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Krueger flap is', '[{"id": "a", "text": "a flap which extends rearwards but does not lower.", "correct": false}, {"id": "b", "text": "a leading edge slat which extends forward.", "correct": false}, {"id": "c", "text": "a leading edge flap which hinges forward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The layer of air over the surface of an aerofoil which is slower moving, in relation to the rest of the airflow, is known as', '[{"id": "a", "text": "camber layer.", "correct": false}, {"id": "b", "text": "boundary layer.", "correct": true}, {"id": "c", "text": "none of the above are correct.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A leading edge slat is a device for', '[{"id": "a", "text": "decreasing wing drag.", "correct": false}, {"id": "b", "text": "increasing the stalling angle of the wing.", "correct": true}, {"id": "c", "text": "decreasing the stalling angle of the wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A split flap increases lift by increasing', '[{"id": "a", "text": "the surface area.", "correct": false}, {"id": "b", "text": "the angle of attachment of the lower hinged portion.", "correct": true}, {"id": "c", "text": "the camber of the top surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the trailing edge flaps are lowered, the aircraft will', '[{"id": "a", "text": "pitch nose down.", "correct": true}, {"id": "b", "text": "pitch nose up.", "correct": false}, {"id": "c", "text": "sink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dutch roll is', '[{"id": "a", "text": "a type of slow roll.", "correct": false}, {"id": "b", "text": "a combined yawing and rolling motion.", "correct": true}, {"id": "c", "text": "primarily a pitching instability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft with an all-moving tailplane, pitch up is caused by', '[{"id": "a", "text": "up movement of the elevator trim tab.", "correct": false}, {"id": "b", "text": "increasing tailplane incidence.", "correct": false}, {"id": "c", "text": "decreasing tailplane incidence.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On aircraft fitted with spoilers for lateral control, roll to the right is caused by', '[{"id": "a", "text": "right spoilers extending, left spoilers remaining retracted.", "correct": true}, {"id": "b", "text": "left and right spoilers extending.", "correct": false}, {"id": "c", "text": "left spoilers extending, right spoilers remaining retracted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An automatic slat will lift by itself when the angle of attack is', '[{"id": "a", "text": "low.", "correct": false}, {"id": "b", "text": "high.", "correct": true}, {"id": "c", "text": "high or low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which flap will increase wing area and camber?', '[{"id": "a", "text": "Fowler", "correct": true}, {"id": "b", "text": "Split", "correct": false}, {"id": "c", "text": "Slot", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which wing increases drag when the ailerons are moved?', '[{"id": "a", "text": "Both wings increase drag but the wing with the up-going aileron increases more.", "correct": false}, {"id": "b", "text": "Both wings increase drag but the wing with the down-going aileron increases more.", "correct": true}, {"id": "c", "text": "Both wings have an equal increase in drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A balance tab', '[{"id": "a", "text": "is used to trim the appropriate axis of the aircraft.", "correct": false}, {"id": "b", "text": "effectively increases the area of the control surface.", "correct": false}, {"id": "c", "text": "assists the pilot to move the controls.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An example of a secondary flight control is a', '[{"id": "a", "text": "flap.", "correct": true}, {"id": "b", "text": "elevator.", "correct": false}, {"id": "c", "text": "aileron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing tip vortices are strongest when', '[{"id": "a", "text": "flying into a headwind.", "correct": false}, {"id": "b", "text": "flying high speed straight and level flight.", "correct": false}, {"id": "c", "text": "flying slowly at high angles of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flight spoilers', '[{"id": "a", "text": "can be used with differential ailerons to reduce adverse yaw in a turn.", "correct": false}, {"id": "b", "text": "can be used to decrease lift to allow controlled descent without reduction of airspeed.", "correct": true}, {"id": "c", "text": "can be deployed on the down going wing in a turn to increase lift on that wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the aircraft is flying nose heavy, which direction would you move the elevator trim tab?', '[{"id": "a", "text": "Down to move elevator up.", "correct": true}, {"id": "b", "text": "Up to move elevator up.", "correct": false}, {"id": "c", "text": "Up to move elevator down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Slats', '[{"id": "a", "text": "act as an air brake.", "correct": false}, {"id": "b", "text": "increase the overall surface area and lift effect of wing.", "correct": false}, {"id": "c", "text": "keep the boundary layer from separating for longer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Due to the change of lift forces resulting from the extension of flaps in flight', '[{"id": "a", "text": "nose should remain in the same position, maintaining same AoA.", "correct": false}, {"id": "b", "text": "nose should be lowered, reducing AoA.", "correct": true}, {"id": "c", "text": "nose should be raised, increasing AoA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ailerons control the aircraft in the', '[{"id": "a", "text": "directional plane.", "correct": false}, {"id": "b", "text": "lateral plane.", "correct": true}, {"id": "c", "text": "longitudinal plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An anti-balance tab is used', '[{"id": "a", "text": "for trimming the aircraft.", "correct": false}, {"id": "b", "text": "to give more feel to the controls.", "correct": true}, {"id": "c", "text": "to relieve stick loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dutch roll is movement in', '[{"id": "a", "text": "yaw and pitch.", "correct": false}, {"id": "b", "text": "pitch and roll.", "correct": false}, {"id": "c", "text": "yaw and roll.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is aerodynamically stable', '[{"id": "a", "text": "C of P moves back.", "correct": false}, {"id": "b", "text": "aircraft becomes too sensitive.", "correct": false}, {"id": "c", "text": "aircraft returns to trimmed attitude.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When pulling out of a dive (e.g. looping) the angle of attack', '[{"id": "a", "text": "decreases.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A laminar boundary layer is __________ and has ______ drag than a turbulent layer.', '[{"id": "a", "text": "thicker; less", "correct": false}, {"id": "b", "text": "thicker; more", "correct": false}, {"id": "c", "text": "thinner; less", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The advantage of a turbulent boundary layer over a laminar boundary layer is', '[{"id": "a", "text": "decreases energy.", "correct": false}, {"id": "b", "text": "less tendency to separate.", "correct": true}, {"id": "c", "text": "thinner.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The boundary layer is considered to be turbulent', '[{"id": "a", "text": "just aft of the separation point.", "correct": false}, {"id": "b", "text": "just in front of the transition point.", "correct": false}, {"id": "c", "text": "between the transition and separation points.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Instability giving roll and yaw', '[{"id": "a", "text": "is longitudinal stability.", "correct": false}, {"id": "b", "text": "is lateral stability.", "correct": false}, {"id": "c", "text": "is dutch roll.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vortex generators are fitted to', '[{"id": "a", "text": "move transition point rearwards.", "correct": false}, {"id": "b", "text": "advance the onset of flow separation.", "correct": false}, {"id": "c", "text": "move transition point forwards.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Leading edge flaps', '[{"id": "a", "text": "increase stalling angle of the wing.", "correct": true}, {"id": "b", "text": "decrease stalling angle of the wing.", "correct": false}, {"id": "c", "text": "do not change the stalling angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Krueger flaps are on', '[{"id": "a", "text": "either the leading or training edge.", "correct": false}, {"id": "b", "text": "the trailing edge.", "correct": false}, {"id": "c", "text": "the leading edge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sweepback will', '[{"id": "a", "text": "decrease lateral stability.", "correct": false}, {"id": "b", "text": "increase lateral stability.", "correct": true}, {"id": "c", "text": "not affect lateral stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A plain flap', '[{"id": "a", "text": "is attached to the leading edge of the wing.", "correct": false}, {"id": "b", "text": "forms part of lower trailing edge.", "correct": false}, {"id": "c", "text": "does not increase the wing area on deployment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A split flap, when deployed', '[{"id": "a", "text": "is used only on high speed aircraft.", "correct": false}, {"id": "b", "text": "increases drag with little lift coefficient increase, from intermediate to fully down.", "correct": true}, {"id": "c", "text": "increases lift without a corresponding increase in drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air above approximately Mach 0.7 is', '[{"id": "a", "text": "compressible.", "correct": true}, {"id": "b", "text": "incompressible.", "correct": false}, {"id": "c", "text": "compressible only when above the speed of sound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Supersonic air passing through a divergent duct causes the', '[{"id": "a", "text": "pressure to increase, velocity to increase.", "correct": false}, {"id": "b", "text": "pressure to increase, velocity to decrease.", "correct": false}, {"id": "c", "text": "pressure to decrease, velocity to increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft flying below the tropopause descends at a constant True Airspeed. Its Mach. No. will', '[{"id": "a", "text": "not change.", "correct": false}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mach trim operation is enabled by', '[{"id": "a", "text": "an autopilot trim motor.", "correct": false}, {"id": "b", "text": "an electric motor.", "correct": false}, {"id": "c", "text": "a mach trim actuator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A shock wave is a very thin region in which there is a sudden decrease of', '[{"id": "a", "text": "pressure.", "correct": false}, {"id": "b", "text": "temperature.", "correct": false}, {"id": "c", "text": "velocity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For a wing of low thickness-chord ratio the critical Mach number will be', '[{"id": "a", "text": "higher than wing of high thickness-chord ratio.", "correct": true}, {"id": "b", "text": "the same as a wing of high thickness-chord ratio.", "correct": false}, {"id": "c", "text": "lower than wing of high thickness-chord ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High speed buffet is caused by', '[{"id": "a", "text": "airflow being detached by shock wave and flow striking the tail.", "correct": true}, {"id": "b", "text": "high speed airflow striking the leading edge.", "correct": false}, {"id": "c", "text": "the shock wave striking the tail.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A nose down change of trim (tuck-under) occurs due to shock induced', '[{"id": "a", "text": "tip stall on a straight wing aircraft.", "correct": false}, {"id": "b", "text": "tip stall on a delta wing aircraft.", "correct": false}, {"id": "c", "text": "root stall on a delta wing aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A symmetrical aerofoil is accelerating through Mach 1 with an angle of attack of 0°. A shock wave will form', '[{"id": "a", "text": "on the upper surface only and move aft.", "correct": false}, {"id": "b", "text": "on the upper and lower surface and will move aft until the point of maximum camber.", "correct": false}, {"id": "c", "text": "on the upper and lower surface and will move aft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At speeds greater than mach 1, airflow in the boundary layer is', '[{"id": "a", "text": "supersonic.", "correct": false}, {"id": "b", "text": "subsonic.", "correct": true}, {"id": "c", "text": "stationary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Total Drag at high Mach numbers is a combination of', '[{"id": "a", "text": "profile drag, form drag, induced drag and wave drag.", "correct": false}, {"id": "b", "text": "wave drag, interference drag, form drag, and induced drag.", "correct": false}, {"id": "c", "text": "induced drag, wave drag, form drag, skin friction drag and interference drag.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is a high speed stall?', '[{"id": "a", "text": "Separation of the airflow due to shockwave formation.", "correct": true}, {"id": "b", "text": "A stall caused by increasing the load factor (g) during a manoeuvre.", "correct": false}, {"id": "c", "text": "A stall due to exceeding the critical angle of attack at high speed during a manoeuvre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a standard day, at which altitude will the speed of sound be the greatest?', '[{"id": "a", "text": "Sea level", "correct": true}, {"id": "b", "text": "10,000 ft", "correct": false}, {"id": "c", "text": "20,000 ft", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following will increase the Critical Mach Number of an aerofoil?', '[{"id": "a", "text": "Increasing the aspect ratio of the wings.", "correct": false}, {"id": "b", "text": "Using a thin airfoil and sweeping the wings back.", "correct": true}, {"id": "c", "text": "Decreasing the fineness ratio of the wings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As an aircraft accelerates through the transonic region, the centre of pressure tends to', '[{"id": "a", "text": "move forward.", "correct": false}, {"id": "b", "text": "turn into a shock wave.", "correct": false}, {"id": "c", "text": "move rearward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Supersonic air going through an incipient shock wave will decrease its speed and', '[{"id": "a", "text": "increase temperature and decrease density.", "correct": false}, {"id": "b", "text": "decrease temperature and increase density.", "correct": false}, {"id": "c", "text": "increase temperature and increase density.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft travelling at speeds greater than Mach 1 the boundary layer is', '[{"id": "a", "text": "stationary.", "correct": true}, {"id": "b", "text": "thicker than if the aircraft were travelling slower than Mach 1.", "correct": false}, {"id": "c", "text": "supersonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At speeds above Mach 1, shockwaves will form above and below the wing', '[{"id": "a", "text": "at the leading edge.", "correct": false}, {"id": "b", "text": "at the trailing edge.", "correct": false}, {"id": "c", "text": "at both the leading edge and the trailing edge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A high speed aircraft with MACH warning will', '[{"id": "a", "text": "warn when Mach 1 has been exceeded.", "correct": false}, {"id": "b", "text": "warn when coming to limits of upper envelope.", "correct": false}, {"id": "c", "text": "warn when M[base=crit] is reached.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Above the critical Mach number, the drag coefficient', '[{"id": "a", "text": "decreases", "correct": false}, {"id": "b", "text": "remains the same", "correct": false}, {"id": "c", "text": "increases", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At high Mach Numbers above Mach 2.2, some aircraft metals', '[{"id": "a", "text": "such as aluminium, become brittle", "correct": false}, {"id": "b", "text": "lose their strength due to the kinetic heating effect", "correct": true}, {"id": "c", "text": "will shrink due to the extreme pressures involved", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mach trim operates', '[{"id": "a", "text": "along the longitudinal axis", "correct": true}, {"id": "b", "text": "along the lateral axis", "correct": false}, {"id": "c", "text": "to reduce Dutch roll", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To increase critical mach number', '[{"id": "a", "text": "the wings are swept", "correct": true}, {"id": "b", "text": "elevons are fitted", "correct": false}, {"id": "c", "text": "tailerons are fitted", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft experiences a large loss of lift and a big increase in drag in straight and level flight, what would be the most probable cause?', '[{"id": "a", "text": "Severe head winds", "correct": false}, {"id": "b", "text": "Atmospheric conditions", "correct": false}, {"id": "c", "text": "Aircraft reached its critical mach number", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Mach Trimmer is a device which', '[{"id": "a", "text": "switches out trim control to prevent damage in the transonic speed range", "correct": false}, {"id": "b", "text": "prevents the aircraft from exceeding its critical Mach No", "correct": false}, {"id": "c", "text": "automatically compensates for trim changes in the transonic region", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Critical Mach No. may be increased by', '[{"id": "a", "text": "using more powerful engines", "correct": false}, {"id": "b", "text": "sweeping back the wing", "correct": true}, {"id": "c", "text": "using a higher thickness/chord ratio wing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mach Number is defined as', '[{"id": "a", "text": "IAS divided by the local speed of sound", "correct": false}, {"id": "b", "text": "TAS divided by local speed of sound", "correct": true}, {"id": "c", "text": "speed of sound at sea level divided by local speed of sound", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The reason for sharp leading edged wings on high speed aircraft is to', '[{"id": "a", "text": "enable the shockwave to be accurately positioned", "correct": true}, {"id": "b", "text": "decrease wave drag", "correct": false}, {"id": "c", "text": "decrease boundary layer", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Critical Mach Number is defined as', '[{"id": "a", "text": "that number at which the airflow becomes supersonic", "correct": false}, {"id": "b", "text": "that free-stream Mach Number at which some part of the airflow over the aircraft becomes sonic", "correct": true}, {"id": "c", "text": "the minimum mach number at which the aircraft can go supersonic", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The transonic region is a region of', '[{"id": "a", "text": "all subsonic", "correct": false}, {"id": "b", "text": "mixed airflow", "correct": true}, {"id": "c", "text": "all supersonic", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wave drag', '[{"id": "a", "text": "increases in the supersonic region", "correct": false}, {"id": "b", "text": "increases in the transonic region", "correct": true}, {"id": "c", "text": "increases at the low speed stall", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For increased Mcrit', '[{"id": "a", "text": "decrease sweepback", "correct": false}, {"id": "b", "text": "decrease thickness/chord ratio", "correct": true}, {"id": "c", "text": "decrease true airspeed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Symptoms of shock stall are', '[{"id": "a", "text": "compressibility effects, buffet and loss of control", "correct": false}, {"id": "b", "text": "buffet, loss of control, and instability", "correct": true}, {"id": "c", "text": "decrease in speed, buffet and movement of the centre of pressure", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sweepback increases Mcrit by', '[{"id": "a", "text": "decreasing the amount of airflow over the highest point on the aerofoil section", "correct": true}, {"id": "b", "text": "increasing the amount of airflow over the highest point on the aerofoil section", "correct": false}, {"id": "c", "text": "decreasing the amount of airflow over the lowest point on the aerofoil section", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The critical Mach number is', '[{"id": "a", "text": "the Mach No. when the aircraft reaches the speed of sound", "correct": false}, {"id": "b", "text": "the Mach No. when a shock wave forms at the leading edge", "correct": false}, {"id": "c", "text": "the aircraft Mach. No. when the airflow reaches the speed of sound at some point on the aircraft", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Above the Critical Mach No. the drag coefficient will', '[{"id": "a", "text": "start to increase", "correct": true}, {"id": "b", "text": "remain the same", "correct": false}, {"id": "c", "text": "start to decrease", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing of low thickness/chord ratio, the Critical Mach No. will be', '[{"id": "a", "text": "lower than a wing of high thickness/chord ratio", "correct": false}, {"id": "b", "text": "higher than a wing of high thickness/chord ratio", "correct": true}, {"id": "c", "text": "the same as a wing of high thickness/chord ratio", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aeroplane flying above the Critical Mach No. will usually experience', '[{"id": "a", "text": "an oscillation in pitch", "correct": false}, {"id": "b", "text": "a nose up pitch", "correct": false}, {"id": "c", "text": "a nose down pitch", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tuck-under can be counteracted by', '[{"id": "a", "text": "trim tabs", "correct": false}, {"id": "b", "text": "mach trim", "correct": true}, {"id": "c", "text": "aileron reversal", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What causes tuck‑under?', '[{"id": "a", "text": "Aileron reversal", "correct": false}, {"id": "b", "text": "Flap‑back effect", "correct": false}, {"id": "c", "text": "Shock stall", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With an increase in altitude under I.S.A. conditions, the temperature in the troposphere', '[{"id": "a", "text": "decreases", "correct": true}, {"id": "b", "text": "remains constant", "correct": false}, {"id": "c", "text": "increases", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air either side of an oblique shockwave is generally', '[{"id": "a", "text": "subsonic", "correct": false}, {"id": "b", "text": "sonic", "correct": false}, {"id": "c", "text": "supersonic", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Downstream of a normal shock wave', '[{"id": "a", "text": "pressure decreases temperature increases", "correct": false}, {"id": "b", "text": "pressure and temperature increase", "correct": true}, {"id": "c", "text": "pressure and temperature decrease", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Speed of sound varies with', '[{"id": "a", "text": "pressure", "correct": false}, {"id": "b", "text": "altitude", "correct": false}, {"id": "c", "text": "temperature", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Immediately downstream of a normal shockwave, air is always', '[{"id": "a", "text": "the same as upstream", "correct": false}, {"id": "b", "text": "supersonic", "correct": false}, {"id": "c", "text": "subsonic", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Increased sweepback', '[{"id": "a", "text": "raises Mcrit", "correct": true}, {"id": "b", "text": "decreases stability", "correct": false}, {"id": "c", "text": "improves tip stall characteristics", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerodynamic heating', '[{"id": "a", "text": "increases with skin friction", "correct": false}, {"id": "b", "text": "increases as a function of airspeed", "correct": true}, {"id": "c", "text": "decreases with altitude", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To overcome ineffective control surface problems in the transonic region', '[{"id": "a", "text": "Frise ailerons may be used", "correct": false}, {"id": "b", "text": "hydraulic powered elevators may be used", "correct": false}, {"id": "c", "text": "an all moving tailplane may be used", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft flying below the tropopause descends at a constant True Airspeed, its Mach. No. will', '[{"id": "a", "text": "decrease", "correct": true}, {"id": "b", "text": "increase", "correct": false}, {"id": "c", "text": "remain the same", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To counter the effect of a shift of centre of pressure as an aircraft flies through the transonic region, fuel is pumped', '[{"id": "a", "text": "backwards", "correct": true}, {"id": "b", "text": "forwards", "correct": false}, {"id": "c", "text": "sideways", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To make flying controls more effective at high speed', '[{"id": "a", "text": "vortex generators are used", "correct": true}, {"id": "b", "text": "area rule is used", "correct": false}, {"id": "c", "text": "wing fences are used", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft flying above the tropopause descends at a constant True Airspeed, its Mach. No. will', '[{"id": "a", "text": "increase", "correct": false}, {"id": "b", "text": "remain the same", "correct": true}, {"id": "c", "text": "decrease", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The velocity of sound with an increase in altitude will', '[{"id": "a", "text": "decrease", "correct": true}, {"id": "b", "text": "remain constant", "correct": false}, {"id": "c", "text": "increase", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mach number equals the ratio of', '[{"id": "a", "text": "altitude to airspeed", "correct": false}, {"id": "b", "text": "true airspeed to local sonic speed", "correct": true}, {"id": "c", "text": "sonic speed to indicated airspeed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tuck-under is caused by', '[{"id": "a", "text": "tip stall on a swept wing aircraft", "correct": false}, {"id": "b", "text": "root stall on a swept wing aircraft", "correct": true}, {"id": "c", "text": "tip stall on a straight wing aircraft", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of sweepback on an aerofoil is to', '[{"id": "a", "text": "decrease drag", "correct": false}, {"id": "b", "text": "increase Mcrit", "correct": true}, {"id": "c", "text": "decrease Mcrit", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As the airspeed over a cambered wing is increased, a shock wave will appear initially', '[{"id": "a", "text": "near the point of maximum curvature", "correct": true}, {"id": "b", "text": "at the leading edge", "correct": false}, {"id": "c", "text": "at the trailing edge", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ATA zone 500 is the', '[{"id": "a", "text": "engine", "correct": false}, {"id": "b", "text": "right wing", "correct": false}, {"id": "c", "text": "left wing", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ATA zone 330 is the', '[{"id": "a", "text": "right horizontal stabiliser", "correct": false}, {"id": "b", "text": "vertical stabiliser", "correct": false}, {"id": "c", "text": "left horizontal stabiliser", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A structure which, if it failed, would cause aircraft to crash is', '[{"id": "a", "text": "primary", "correct": true}, {"id": "b", "text": "integral", "correct": false}, {"id": "c", "text": "essential", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The method used on a work card to indicate the approximate location of a component is', '[{"id": "a", "text": "stations", "correct": false}, {"id": "b", "text": "datum", "correct": false}, {"id": "c", "text": "zones", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A loss of strength resulting from cyclic loading is known as', '[{"id": "a", "text": "metal fatigue", "correct": true}, {"id": "b", "text": "age hardening", "correct": false}, {"id": "c", "text": "fail safe", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Zone 320 under the ATA system is', '[{"id": "a", "text": "vertical stabiliser", "correct": true}, {"id": "b", "text": "central fuselage", "correct": false}, {"id": "c", "text": "horizontal stabiliser", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When doing a bonding check the maximum resistance between component and earth is', '[{"id": "a", "text": "0.005ohms", "correct": false}, {"id": "b", "text": "1/50 ohms", "correct": false}, {"id": "c", "text": "50 milliohms", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fuel drain of a combustion heater must be protected from', '[{"id": "a", "text": "ice build-up", "correct": true}, {"id": "b", "text": "lightning strike", "correct": false}, {"id": "c", "text": "accidental damage", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Engine mounts provide for', '[{"id": "a", "text": "longitudinal movement", "correct": true}, {"id": "b", "text": "torsional movement", "correct": false}, {"id": "c", "text": "lateral movement", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dyna engine mounts', '[{"id": "a", "text": "reduce vibration from engine to airframe", "correct": true}, {"id": "b", "text": "prevent all vibration from engine to airframe", "correct": false}, {"id": "c", "text": "are constructed from plastic", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is damage to the nose cone of an aircraft prevented during a lightning strike?', '[{"id": "a", "text": "Earthing Strap", "correct": false}, {"id": "b", "text": "Bonding Strip", "correct": true}, {"id": "c", "text": "Special paint", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tension is the stress of', '[{"id": "a", "text": "elongating or stretch", "correct": true}, {"id": "b", "text": "crush or compression", "correct": false}, {"id": "c", "text": "twisting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Fuselage Station is a', '[{"id": "a", "text": "lateral point on aircraft fuse", "correct": false}, {"id": "b", "text": "longitudinal point on the aircraft fuselage", "correct": true}, {"id": "c", "text": "lateral point on aircraft wing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Composite materials are bonded by', '[{"id": "a", "text": "special paint", "correct": true}, {"id": "b", "text": "copper wire", "correct": false}, {"id": "c", "text": "aluminium wire", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ATA Zone 100 is', '[{"id": "a", "text": "upper fuselage", "correct": false}, {"id": "b", "text": "lower fuselage", "correct": true}, {"id": "c", "text": "left-hand wing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The bonding lead to a remote aircraft component must be', '[{"id": "a", "text": "0.25 in wide and 22 AWG", "correct": false}, {"id": "b", "text": "22 AWG", "correct": false}, {"id": "c", "text": "0.5 in wide", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What force is an I-Beam subjected to?', '[{"id": "a", "text": "Tension", "correct": false}, {"id": "b", "text": "Bending", "correct": true}, {"id": "c", "text": "Shear", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radome is protected from static electricity build-up by', '[{"id": "a", "text": "special conductive grease", "correct": false}, {"id": "b", "text": "conductive paint", "correct": true}, {"id": "c", "text": "bonding strips", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Precise points are located on an aircraft by a system of', '[{"id": "a", "text": "frame stations, vertical lines and lateral lines", "correct": false}, {"id": "b", "text": "frame stations, water lines and buttock lines", "correct": true}, {"id": "c", "text": "longitudinal, vertical and lateral lines", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is an example of a fail safe structure?', '[{"id": "a", "text": "Longeron", "correct": false}, {"id": "b", "text": "Stringer", "correct": true}, {"id": "c", "text": "Spar", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Damage tolerant design', '[{"id": "a", "text": "is applied only to secondary structure", "correct": false}, {"id": "b", "text": "allows for certain damage to the structure to go un-repaired between scheduled maintenance", "correct": true}, {"id": "c", "text": "allows for damage to structure by distributing loads to other structure", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the ATA 100 zonal system the passenger entry door will have a designation of', '[{"id": "a", "text": "400", "correct": false}, {"id": "b", "text": "800", "correct": true}, {"id": "c", "text": "600", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which area of the aircraft is subject to hoop stress?', '[{"id": "a", "text": "Wings", "correct": false}, {"id": "b", "text": "Pressure cabin", "correct": true}, {"id": "c", "text": "Control surfaces", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Shear stress is described as', '[{"id": "a", "text": "compressing forces", "correct": false}, {"id": "b", "text": "pulling forces", "correct": false}, {"id": "c", "text": "slip away under the action of forces", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ground cable must be', '[{"id": "a", "text": "single strand copper wire 0.5 in. cross sectional area", "correct": false}, {"id": "b", "text": "single strand 18 AWG", "correct": false}, {"id": "c", "text": "copper stranded 0.5 in. cross sectional area", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where on the aircraft is FS245, RWS45?', '[{"id": "a", "text": "245 inches from the nose of the aircraft and 45 inches from the centreline of the right wing", "correct": false}, {"id": "b", "text": "245 inches from the datum line of the aircraft and 45 inches from the centreline of the right wing", "correct": true}, {"id": "c", "text": "245 inches from the nose of the aircraft and 45 inches from the tip of the right wing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the radome protected from lightning strike?', '[{"id": "a", "text": "Special paint", "correct": false}, {"id": "b", "text": "Special grease on the hinges", "correct": false}, {"id": "c", "text": "Diverter strips", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If you short the two prongs with the single prong of a bonding tester together, what would the gauge read?', '[{"id": "a", "text": "Centre scale", "correct": false}, {"id": "b", "text": "Zero", "correct": true}, {"id": "c", "text": "Full scale deflection", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A condition after which a permanent deformation of a material is caused, is known as', '[{"id": "a", "text": "strain", "correct": true}, {"id": "b", "text": "shear", "correct": false}, {"id": "c", "text": "bending", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Semi-monocoque construction', '[{"id": "a", "text": "is used only for the fuselage", "correct": false}, {"id": "b", "text": "utilizes the safe-life design concept", "correct": false}, {"id": "c", "text": "offers good damage resistance", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Most radio aerials are', '[{"id": "a", "text": "not bonded", "correct": false}, {"id": "b", "text": "bonded", "correct": true}, {"id": "c", "text": "insulated from the fuselage", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Secondary bonding is usually provided with', '[{"id": "a", "text": "18 AWG", "correct": true}, {"id": "b", "text": "single strand 0.25 inch", "correct": false}, {"id": "c", "text": "stranded copper 0.25 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Water Lines (WLs) are measured points on a', '[{"id": "a", "text": "wing line", "correct": false}, {"id": "b", "text": "horizontal line", "correct": false}, {"id": "c", "text": "vertical line", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The various parts of the aircraft airframe are maintained at the same potential by', '[{"id": "a", "text": "earthing", "correct": false}, {"id": "b", "text": "bonding", "correct": true}, {"id": "c", "text": "static wicks", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cross sectional area of a secondary conductor must be not less than', '[{"id": "a", "text": "22 SWG x 0.5", "correct": false}, {"id": "b", "text": "22 SWG x 0.25", "correct": false}, {"id": "c", "text": "18 SWG for a single wire", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What governs the ultimate fatigue life of an aircraft?', '[{"id": "a", "text": "Landings", "correct": false}, {"id": "b", "text": "Flying Hours", "correct": true}, {"id": "c", "text": "Pressure Cycles", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The main forces on an aircraft structure are', '[{"id": "a", "text": "tension, compression, torsion and shear", "correct": true}, {"id": "b", "text": "tension, compression, twisting and shear", "correct": false}, {"id": "c", "text": "tension, compression, twisting and shear", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The life of the structure is counted by', '[{"id": "a", "text": "flying hours", "correct": true}, {"id": "b", "text": "landings", "correct": false}, {"id": "c", "text": "pressurization cycle", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are buttock lines?', '[{"id": "a", "text": "Vertical measurement lines", "correct": false}, {"id": "b", "text": "Horizontal measurement lines", "correct": false}, {"id": "c", "text": "Measurements from the centre line", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aircraft fibreglass panels are protected against lightning strikes, partially by', '[{"id": "a", "text": "conductive paint", "correct": true}, {"id": "b", "text": "non-conductive paint", "correct": false}, {"id": "c", "text": "bonding", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A member taking a compression load is called a', '[{"id": "a", "text": "beam", "correct": false}, {"id": "b", "text": "strut", "correct": true}, {"id": "c", "text": "cable", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stringers are used in which of the following types of aircraft fuselage construction?', '[{"id": "a", "text": "Semi-monocoque", "correct": true}, {"id": "b", "text": "Truss type", "correct": false}, {"id": "c", "text": "Monocoque", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing stations are measured', '[{"id": "a", "text": "outboard from the wing root", "correct": false}, {"id": "b", "text": "inboard from the wing upper surface", "correct": false}, {"id": "c", "text": "outboard from the fuselage centreline", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What load is a tie rod designed to accept?', '[{"id": "a", "text": "Bending", "correct": false}, {"id": "b", "text": "Tensile", "correct": true}, {"id": "c", "text": "Torsion", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a colour is used to identify primary structure, it will be', '[{"id": "a", "text": "yellow", "correct": false}, {"id": "b", "text": "green", "correct": false}, {"id": "c", "text": "red", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is primary structure?', '[{"id": "a", "text": "Stringer", "correct": false}, {"id": "b", "text": "Frame", "correct": false}, {"id": "c", "text": "Skin", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuselage station numbers are measured from the front of the aircraft in', '[{"id": "a", "text": "inches", "correct": true}, {"id": "b", "text": "feet", "correct": false}, {"id": "c", "text": "feet and inches", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Structure with built‑in redundancy is called', '[{"id": "a", "text": "failsafe", "correct": true}, {"id": "b", "text": "double safe", "correct": false}, {"id": "c", "text": "safe life", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stress', '[{"id": "a", "text": "is the load per unit area acting on a material", "correct": true}, {"id": "b", "text": "is the deformation of a material caused by applied load", "correct": false}, {"id": "c", "text": "is the property of a material to resist fracture", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A piece of structure which must be replaced at a specified number of cycles, flying hours or years, regardless of its physical condition is what type of item?', '[{"id": "a", "text": "Fail-safe", "correct": false}, {"id": "b", "text": "Safe-life", "correct": true}, {"id": "c", "text": "Condition monitored", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Safe-life is', '[{"id": "a", "text": "the sharing of loads between adjacent members", "correct": false}, {"id": "b", "text": "the maximum number of flying hours that should elapse before a major structural failure occurs", "correct": true}, {"id": "c", "text": "the minimum number of flying hours that should elapse before a major structural failure occurs", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Bending stresses are a combination of', '[{"id": "a", "text": "tension and compression stresses", "correct": true}, {"id": "b", "text": "torsional and compression stresses", "correct": false}, {"id": "c", "text": "tension and shear stresses", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Airworthiness Notice that refers to structural surveys is', '[{"id": "a", "text": "Notice 65", "correct": false}, {"id": "b", "text": "Notice 89", "correct": true}, {"id": "c", "text": "Notice 79", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Structural survey inspections are normally called up by the', '[{"id": "a", "text": "maintenance engineer", "correct": false}, {"id": "b", "text": "manufacturer", "correct": true}, {"id": "c", "text": "operator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where are wing stations measured from?', '[{"id": "a", "text": "Butt Line (BL)", "correct": true}, {"id": "b", "text": "Zone Line (ZL)", "correct": false}, {"id": "c", "text": "Water Line (WL)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is Zone 323?', '[{"id": "a", "text": "Between rear spar and trailing edge", "correct": false}, {"id": "b", "text": "Tip of vertical stabiliser", "correct": false}, {"id": "c", "text": "Between front and rear spar", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To prevent a system being affected by high current flows after a lightning strike to a composite aircraft, electricity is discharged through', '[{"id": "a", "text": "electrically connected primary conductors", "correct": true}, {"id": "b", "text": "a sprayed coat of non-conductive paint", "correct": false}, {"id": "c", "text": "a sprayed coat of conductive paint", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A structural member intended to resist compression is a', '[{"id": "a", "text": "strut", "correct": true}, {"id": "b", "text": "tie", "correct": false}, {"id": "c", "text": "web", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft structure, having multiple load paths, is known as a', '[{"id": "a", "text": "fail-safe design", "correct": true}, {"id": "b", "text": "monocoque design", "correct": false}, {"id": "c", "text": "safe-life design", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wrinkling of the skin on the upper surface of the fuselage indicates', '[{"id": "a", "text": "sagging", "correct": true}, {"id": "b", "text": "shedding", "correct": false}, {"id": "c", "text": "hogging", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a redundant structure fails it becomes', '[{"id": "a", "text": "fatigued", "correct": false}, {"id": "b", "text": "safe-life", "correct": false}, {"id": "c", "text": "failsafe", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A redundant structure is', '[{"id": "a", "text": "on-condition structure", "correct": false}, {"id": "b", "text": "a safe-life structure", "correct": false}, {"id": "c", "text": "a failsafe structure", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The measurement of the fuselage perpendicular to horizontal plane measured in inches from bottom of the fuselage is', '[{"id": "a", "text": "water line", "correct": true}, {"id": "b", "text": "fuselage station", "correct": false}, {"id": "c", "text": "butt line", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the four stresses to be considered when building an aircraft?', '[{"id": "a", "text": "Compression, Torsion, Tension, Shear", "correct": true}, {"id": "b", "text": "Compression, Tension, Torsion, Stress", "correct": false}, {"id": "c", "text": "Compression, Torsion, Stress, Strain", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A structure that has a high designed reserve strength would be classified as', '[{"id": "a", "text": "primary", "correct": true}, {"id": "b", "text": "secondary", "correct": false}, {"id": "c", "text": "tertiary", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An example of primary stress is', '[{"id": "a", "text": "shear", "correct": false}, {"id": "b", "text": "tension", "correct": true}, {"id": "c", "text": "bending", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the water line?', '[{"id": "a", "text": "The datum from which vertical locations refer", "correct": true}, {"id": "b", "text": "The zero datum from which all lateral locations are measured", "correct": false}, {"id": "c", "text": "A line below which redux bonding can not be used", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Lateral stations have station zero at the', '[{"id": "a", "text": "centreline", "correct": true}, {"id": "b", "text": "left wing-tip", "correct": false}, {"id": "c", "text": "nose", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Airworthiness requirements for large aircraft are found in', '[{"id": "a", "text": "ANO 25", "correct": false}, {"id": "b", "text": "CS 25", "correct": true}, {"id": "c", "text": "JAR 25", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Diffusion bonding and superplastic forming provides', '[{"id": "a", "text": "high stiffness and high ductility", "correct": true}, {"id": "b", "text": "high strength and high ductility", "correct": false}, {"id": "c", "text": "high strength and high stiffness", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When applying a doubler plate, what else could you use for extra strength?', '[{"id": "a", "text": "Thicker material", "correct": false}, {"id": "b", "text": "A waffle plate", "correct": true}, {"id": "c", "text": "A tripler plate", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hi-lok fastener installation requires that', '[{"id": "a", "text": "an interference fit hole is drilled", "correct": true}, {"id": "b", "text": "the shank is lubricated", "correct": false}, {"id": "c", "text": "the fastener is accurately torqued", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stringers', '[{"id": "a", "text": "are attached to the frame", "correct": false}, {"id": "b", "text": "do not pass through bulkheads", "correct": true}, {"id": "c", "text": "run the full length on all aircraft", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Contact between titanium and phosphate ester fluid should be avoided because', '[{"id": "a", "text": "there is no effect", "correct": false}, {"id": "b", "text": "it makes the titanium soft", "correct": false}, {"id": "c", "text": "it makes the titanium brittle", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The optimum atmospheric conditions for painting aircraft is', '[{"id": "a", "text": "between 65oF and 75oF with less than 75% relative humidity", "correct": false}, {"id": "b", "text": "between 65oC and 75oC with more than 75% relative humidity", "correct": false}, {"id": "c", "text": "between 60oF and 77oF with less than 75% relative humidity", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What kind of seal is used on firewall bulkheads?', '[{"id": "a", "text": "None is required", "correct": false}, {"id": "b", "text": "Fire-proof grommets", "correct": true}, {"id": "c", "text": "Soft rubber", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To remove a rivet you should', '[{"id": "a", "text": "drill it all the way through", "correct": false}, {"id": "b", "text": "drill to the depth of the head", "correct": true}, {"id": "c", "text": "drill half way through", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The two stages in a good adhesive bond are', '[{"id": "a", "text": "wetting and Setting", "correct": true}, {"id": "b", "text": "wetting and gripping", "correct": false}, {"id": "c", "text": "spreading and setting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Prior to aluminium alloy bonding, we use', '[{"id": "a", "text": "acid etch", "correct": true}, {"id": "b", "text": "alkaline etch", "correct": false}, {"id": "c", "text": "solvent etch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a primer is to', '[{"id": "a", "text": "help bonding of the topcoat", "correct": true}, {"id": "b", "text": "provide shiny surface for the topcoat", "correct": false}, {"id": "c", "text": "provide flexible surface for the top coat", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In semi-monocoque construction, compression loads are taken by', '[{"id": "a", "text": "frames", "correct": false}, {"id": "b", "text": "bulkheads", "correct": false}, {"id": "c", "text": "stringers", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Most large transport aircraft skins are', '[{"id": "a", "text": "7075.", "correct": false}, {"id": "b", "text": "2024.", "correct": true}, {"id": "c", "text": "5056.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following statements is correct, in relation to PLI washers used in critical bolted joints?', '[{"id": "a", "text": "PLI washers can be affected by thread or nut friction or by lubrication.", "correct": false}, {"id": "b", "text": "PLI washers can only be used with self locking nuts and the washers should be used once.", "correct": true}, {"id": "c", "text": "PLI washers can be used more than once, providing they are used in critical bolted joints.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What opposes buckling in a semi-monocoque structure?', '[{"id": "a", "text": "Stringers", "correct": true}, {"id": "b", "text": "Bulkheads", "correct": false}, {"id": "c", "text": "Frames", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a monocoque structure, which component carries the majority of the loads?', '[{"id": "a", "text": "Stringers", "correct": false}, {"id": "b", "text": "Skin", "correct": true}, {"id": "c", "text": "Longerons", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which anti-corrosive treatment is found on alloy steels?', '[{"id": "a", "text": "Zinc plating", "correct": false}, {"id": "b", "text": "Nickel plating", "correct": false}, {"id": "c", "text": "Cadmium plating", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What material can be chromated as a protection against corrosion?', '[{"id": "a", "text": "Alluminium alloys", "correct": false}, {"id": "b", "text": "Magnesium alloys", "correct": true}, {"id": "c", "text": "Ferros alloys", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When carrying out a symmetry check on a large aircraft, what method of measurement is normally used?', '[{"id": "a", "text": "Steel tape and spring balance.", "correct": true}, {"id": "b", "text": "Longitudinal alignment method.", "correct": false}, {"id": "c", "text": "Lateral alignment method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Paint remover substances', '[{"id": "a", "text": "should only be used once.", "correct": false}, {"id": "b", "text": "are not damaging to any aircraft parts.", "correct": false}, {"id": "c", "text": "are damaging to some aircraft parts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Kevlar should be stored', '[{"id": "a", "text": "horizontally.", "correct": false}, {"id": "b", "text": "in moisture proof bags.", "correct": true}, {"id": "c", "text": "vertically.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Battery trays are', '[{"id": "a", "text": "absorbent to soak up electrolyte.", "correct": false}, {"id": "b", "text": "metal with PVC coating and anti corrosive paint.", "correct": true}, {"id": "c", "text": "metal for earthing purposes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The primary purpose of sealant in use in pressurised aircraft is', '[{"id": "a", "text": "to prevent corrosion.", "correct": false}, {"id": "b", "text": "to provide external streamlining.", "correct": false}, {"id": "c", "text": "to seal the cabin.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When installing a ''Hi-lock'' bolt, it is necessary to', '[{"id": "a", "text": "simply fit the bolt as they are prelubricated.", "correct": true}, {"id": "b", "text": "lubricate the collar.", "correct": false}, {"id": "c", "text": "lubricate the shank and threads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sealant or levelling compound is installed during structure repair:', '[{"id": "a", "text": "according to separate manufacturer''s documentations such as BAC.", "correct": false}, {"id": "b", "text": "according to SB instructions.", "correct": false}, {"id": "c", "text": "according to AMM and SRM chapter 51.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A bonded waffle doubler, as well as acting as a skin strengthener, also acts as a', '[{"id": "a", "text": "jury strut.", "correct": false}, {"id": "b", "text": "shear tie.", "correct": false}, {"id": "c", "text": "tear stopper.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the faying surfaces of a repair?', '[{"id": "a", "text": "Edges of repair metal.", "correct": false}, {"id": "b", "text": "Middle of repair.", "correct": false}, {"id": "c", "text": "Material under repair.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dissimilar metal fusion bonding is best for', '[{"id": "a", "text": "low strength high toughness.", "correct": false}, {"id": "b", "text": "high strength high toughness.", "correct": false}, {"id": "c", "text": "high strength high stiffness.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ideal conditions for paint spraying an aircraft are', '[{"id": "a", "text": "20°C to 30°C and humidity below 70%.", "correct": false}, {"id": "b", "text": "15°C to 25°C and humidity below 75%.", "correct": true}, {"id": "c", "text": "15°C to 25°C and humidity above 60%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the types of true bonded joints?', '[{"id": "a", "text": "Mechanical and specific.", "correct": true}, {"id": "b", "text": "Mechanical and cemented.", "correct": false}, {"id": "c", "text": "Cemented and specific.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Why is a joggle joint used?', '[{"id": "a", "text": "To add strength.", "correct": false}, {"id": "b", "text": "To provide a flush fit.", "correct": true}, {"id": "c", "text": "To provide a smooth contour to surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When both sides of a structural repair are not easily reached, which type of fastener would you use?', '[{"id": "a", "text": "Hi lock bolt.", "correct": false}, {"id": "b", "text": "Pop rivet.", "correct": false}, {"id": "c", "text": "Blind rivet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With regard to extraneous spilt fluids', '[{"id": "a", "text": "they may be harmful to the aircraft structure.", "correct": true}, {"id": "b", "text": "they should only be cleaned up if they are on the external surface of the aircraft.", "correct": false}, {"id": "c", "text": "they can be ignored, they provide extra protection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Skin panels may be strengthened by', '[{"id": "a", "text": "struts.", "correct": false}, {"id": "b", "text": "cleats.", "correct": false}, {"id": "c", "text": "stringers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the normal form of construction of a spar?', '[{"id": "a", "text": "One boom mounted under a web.", "correct": false}, {"id": "b", "text": "Two webs separated by a boom.", "correct": false}, {"id": "c", "text": "Two booms separated by a web.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A crack stopper is fitted', '[{"id": "a", "text": "before a crack starts, to slow its rate of propagation.", "correct": true}, {"id": "b", "text": "before a crack starts, to prevent its initiation.", "correct": false}, {"id": "c", "text": "after a crack starts, to slow its rate of propagation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following should be accomplished before jacking an aircraft?', '[{"id": "a", "text": "Determine the fuel tanks are empty.", "correct": false}, {"id": "b", "text": "Install critical stress panels or plates.", "correct": true}, {"id": "c", "text": "Remove all optional equipment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Synthetic resins are made from nylon, vinyl and', '[{"id": "a", "text": "asphalt.", "correct": false}, {"id": "b", "text": "cellulose.", "correct": false}, {"id": "c", "text": "acrylics.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the advantages of the semi-monocoque construction is that it', '[{"id": "a", "text": "is easier to manufacture.", "correct": false}, {"id": "b", "text": "shares the loads.", "correct": true}, {"id": "c", "text": "takes all the loads in the skin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fully monocoque fuselage, all the loads are carried by the', '[{"id": "a", "text": "skin.", "correct": true}, {"id": "b", "text": "frames.", "correct": false}, {"id": "c", "text": "longerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Intercostals are', '[{"id": "a", "text": "longitudinal fuselage members attached at each end to adjacent frames.", "correct": true}, {"id": "b", "text": "vertical struts joining the upper and lower wings of a biplane.", "correct": false}, {"id": "c", "text": "compression ribs in cantilever wings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Joints that are designed to stop the propagation of cracks are known as', '[{"id": "a", "text": "secondary joints.", "correct": false}, {"id": "b", "text": "failsafe joints.", "correct": true}, {"id": "c", "text": "crack limiting joints.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft has alkaline batteries, the battery compartment drain pipes will be', '[{"id": "a", "text": "aluminium alloy.", "correct": false}, {"id": "b", "text": "plastic.", "correct": false}, {"id": "c", "text": "stainless steel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An overweight landing is one in which the aircraft has', '[{"id": "a", "text": "a misplaced centre of gravity on landing.", "correct": false}, {"id": "b", "text": "an excessive fuel load on take-off.", "correct": false}, {"id": "c", "text": "too much kinetic energy on landing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Symmetry checks should be carried out', '[{"id": "a", "text": "in the hanger with the aircraft on jacks.", "correct": true}, {"id": "b", "text": "in the hangar with the aircraft on its wheels.", "correct": false}, {"id": "c", "text": "on the ramp with the aircraft on its wheels.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a wash primer and primer is to', '[{"id": "a", "text": "provide more aerodynamic finish for top-coat.", "correct": false}, {"id": "b", "text": "provide a flexible surface for top-coat.", "correct": false}, {"id": "c", "text": "help bonding for top-coat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dents are generally not permitted in a tubular member', '[{"id": "a", "text": "if the major axis of the dent is parallel to the tube axis irrespective of the location.", "correct": false}, {"id": "b", "text": "if they are located in the middle third of the length of the member.", "correct": true}, {"id": "c", "text": "if they are located in the end thirds of the length of the member.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an item is cocooned, the visual indicator will indicate', '[{"id": "a", "text": "toxic gases.", "correct": false}, {"id": "b", "text": "humidity.", "correct": true}, {"id": "c", "text": "temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The maximum permissible bow in a steel tube is', '[{"id": "a", "text": "1 in 400.", "correct": false}, {"id": "b", "text": "1 in 200,", "correct": false}, {"id": "c", "text": "1 in 600.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Buckling in a semi-monocoque structure is prevented by', '[{"id": "a", "text": "bulkheads.", "correct": false}, {"id": "b", "text": "stringers.", "correct": true}, {"id": "c", "text": "longerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which loads do longerons resist?', '[{"id": "a", "text": "Bending, compression and tensile.", "correct": true}, {"id": "b", "text": "Torsional only.", "correct": false}, {"id": "c", "text": "Bending, compression, tensile and torsion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Blowout panels are fitted to floors of pressurised aircraft to', '[{"id": "a", "text": "provide access for pressurising the cargo bays.", "correct": false}, {"id": "b", "text": "provide access for pressurising the cabin.", "correct": false}, {"id": "c", "text": "provide venting should a differential pressure build up across the floor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are passenger windows normally made from?', '[{"id": "a", "text": "Glass", "correct": false}, {"id": "b", "text": "Acrylic", "correct": true}, {"id": "c", "text": "Acrylic / glass laminate", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A firewall bulkhead is usually made from', '[{"id": "a", "text": "tungsten.", "correct": false}, {"id": "b", "text": "titanium.", "correct": true}, {"id": "c", "text": "steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Acrylic windows must be able to flex in-situ because they have', '[{"id": "a", "text": "slight shrinkage due to age.", "correct": false}, {"id": "b", "text": "smaller coefficient of expansion than surrounding structure.", "correct": false}, {"id": "c", "text": "larger coefficient of expansion than surrounding structure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cargo bay must have signs stating', '[{"id": "a", "text": "maximum loadings.", "correct": true}, {"id": "b", "text": "maximum dimensions.", "correct": false}, {"id": "c", "text": "no hazardous cargo.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Zone D Cargo compartment windows', '[{"id": "a", "text": "are made from fire retardant Perspex.", "correct": false}, {"id": "b", "text": "must be blanked off.", "correct": true}, {"id": "c", "text": "must have blinds pulled down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire zone in which a crew member could enter to fight a fire is', '[{"id": "a", "text": "class B.", "correct": true}, {"id": "b", "text": "class E.", "correct": false}, {"id": "c", "text": "class A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windscreen delamination is', '[{"id": "a", "text": "separation of the glass from the vinyl interlayer.", "correct": true}, {"id": "b", "text": "bubbling of the glass due to overheat.", "correct": false}, {"id": "c", "text": "windscreen peeling away from the airframe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the ideal storage temperature for windscreen panels?', '[{"id": "a", "text": "50°C to 70°C.", "correct": false}, {"id": "b", "text": "30°C to 50°C.", "correct": false}, {"id": "c", "text": "50°F to 70°F .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the maximum temperature of warm water which is used to clean dirty aircraft acrylic panels?', '[{"id": "a", "text": "125°F", "correct": false}, {"id": "b", "text": "104°F", "correct": true}, {"id": "c", "text": "40°F", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are passenger door pressure loads transmitted to the fuselage structure?', '[{"id": "a", "text": "By door stops.", "correct": true}, {"id": "b", "text": "By the pressure seal.", "correct": false}, {"id": "c", "text": "Through the latching mechanism.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Passenger cabin windows are constructed with two panes and a seal between them. Under normal flight conditions which pane(s) take the differential pressure loads?', '[{"id": "a", "text": "Inner", "correct": false}, {"id": "b", "text": "Both", "correct": true}, {"id": "c", "text": "Outer", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are passenger seats secured to the floor?', '[{"id": "a", "text": "By the front legs while the back attachment provides anti rattle.", "correct": false}, {"id": "b", "text": "By both front and back legs.", "correct": false}, {"id": "c", "text": "By the back legs while the front attachment provides anti rattle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A material commonly used for pressure bulkhead sealing is', '[{"id": "a", "text": "soft rubber.", "correct": true}, {"id": "b", "text": "aluminium.", "correct": false}, {"id": "c", "text": "PTFE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When acrylic and sheet metal is joined together, allowance should be made for', '[{"id": "a", "text": "galvanic corrosion of the metal.", "correct": false}, {"id": "b", "text": "expansion of the acrylic due to heat .", "correct": true}, {"id": "c", "text": "expansion of the metal due to heat .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is Perspex resistant to?', '[{"id": "a", "text": "Acetone", "correct": false}, {"id": "b", "text": "MEK", "correct": false}, {"id": "c", "text": "Kerosene", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a pressurised aircraft cabin window, the differential pressure can be taken by', '[{"id": "a", "text": "the scratch panel .", "correct": false}, {"id": "b", "text": "the inner pane only .", "correct": false}, {"id": "c", "text": "both main panes .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the vinyl interlayer in window construction is', '[{"id": "a", "text": "to increase static strength.", "correct": false}, {"id": "b", "text": "to improve on brittle behaviour.", "correct": true}, {"id": "c", "text": "to enable inclusion of heater film .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On passenger aircraft of two or more zones', '[{"id": "a", "text": "there should be at least one exit per zone.", "correct": true}, {"id": "b", "text": "the seat backs fold forward at over wing emergency exits.", "correct": false}, {"id": "c", "text": "the emergency exits are to be clearly signed .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Class D cargo bay windows require', '[{"id": "a", "text": "double acrylic panels .", "correct": false}, {"id": "b", "text": "the blind down for flight .", "correct": false}, {"id": "c", "text": "fire proof coatings .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cargo bay panels are normally constructed from', '[{"id": "a", "text": "monolithic Nomex .", "correct": false}, {"id": "b", "text": "Fibreglass and resin .", "correct": true}, {"id": "c", "text": "Kevlar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fatigue life of a pressure hull is based on', '[{"id": "a", "text": "the number of negative differential pressure applications.", "correct": false}, {"id": "b", "text": "the number of explosive decompressions.", "correct": false}, {"id": "c", "text": "the total number of pressurizations.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In pressurized aircraft, undercarriage bays', '[{"id": "a", "text": "are unpressurised .", "correct": true}, {"id": "b", "text": "may be pressurized or unpressurised .", "correct": false}, {"id": "c", "text": "are pressurized .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The main longitudinal members in a fuselage are called', '[{"id": "a", "text": "spars .", "correct": false}, {"id": "b", "text": "frames.", "correct": false}, {"id": "c", "text": "longerons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A partition within the aircraft''s structure is called a', '[{"id": "a", "text": "bulkheads.", "correct": true}, {"id": "b", "text": "cleats.", "correct": false}, {"id": "c", "text": "frame.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When inspecting stowage doors, special attention should be given to the', '[{"id": "a", "text": "catches .", "correct": true}, {"id": "b", "text": "light microswitches .", "correct": false}, {"id": "c", "text": "trim .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Seat track cutouts provide for various seat spacings, usually in', '[{"id": "a", "text": "half inch increments .", "correct": false}, {"id": "b", "text": "one foot increments .", "correct": false}, {"id": "c", "text": "one inch increments .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wall mounted flight attendant seats are fixed to', '[{"id": "a", "text": "tracks .", "correct": false}, {"id": "b", "text": "stanchions .", "correct": true}, {"id": "c", "text": "rails .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windshields are heated to', '[{"id": "a", "text": "maintain strength and toughness only .", "correct": false}, {"id": "b", "text": "demist, ant-ice and maintain strength and toughness .", "correct": true}, {"id": "c", "text": "prevent misting and icing only .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The internal doors of an aircraft', '[{"id": "a", "text": "only carry pressure loads when the aircraft is at cruise altitude .", "correct": false}, {"id": "b", "text": "carry pressure loads .", "correct": false}, {"id": "c", "text": "never carry pressure loads .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pressure door warning light illuminates only when the door is', '[{"id": "a", "text": "not locked .", "correct": true}, {"id": "b", "text": "locked .", "correct": false}, {"id": "c", "text": "not fully opened .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an electrically operated cargo door lifting actuator fails, it may be operated', '[{"id": "a", "text": "be electrical ground power .", "correct": false}, {"id": "b", "text": "by alternate actuators .", "correct": false}, {"id": "c", "text": "manually by winding .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After installation of an acrylic window panel, protective paper and adhesive remaining on the panel may be removed by use of soap and water and', '[{"id": "a", "text": "Cellulose thinners .", "correct": false}, {"id": "b", "text": "Methylated spirits .", "correct": true}, {"id": "c", "text": "MEK .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If heat is applied to the vinyl interlayer of an aircraft windscreen, its ability to withstand impact will', '[{"id": "a", "text": "increase .", "correct": true}, {"id": "b", "text": "decrease .", "correct": false}, {"id": "c", "text": "not change .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When fitting a transparent plastic panel (acrylic) to a metal frame, provision must be made for the relative movement of the panel and the frame for the reason of', '[{"id": "a", "text": "the known slight shrinkage of the panel due to ageing", "correct": false}, {"id": "b", "text": "the lower coefficient of expansion of the transparent panel when compared with the frame", "correct": false}, {"id": "c", "text": "the higher coefficient of expansion of the transparent panel when compared with the frame", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Perspex is resistant to', '[{"id": "a", "text": "Paraffin .", "correct": true}, {"id": "b", "text": "C.T.C.", "correct": false}, {"id": "c", "text": "Acetone .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Moisture drain valves in a pressurised fuselage', '[{"id": "a", "text": "are open all the time to ensure the bilge areas are well drained .", "correct": false}, {"id": "b", "text": "are open when the cabin is depressurised.", "correct": true}, {"id": "c", "text": "are open when the cabin is pressurised .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wide body transport aircraft have cabin floor vents', '[{"id": "a", "text": "to equalise pressures above and below the floor after the loss of a cargo compartment door .", "correct": true}, {"id": "b", "text": "to ensure adequate ventilation of the underfloor areas .", "correct": false}, {"id": "c", "text": "to provide access to class A cargo compartments in the event of fire .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an inspection, you are aware of vinyl bubbling. What action is required?', '[{"id": "a", "text": "Replace the defective window .", "correct": false}, {"id": "b", "text": "Only replace the window if the ''bubbling'' affects vision .", "correct": true}, {"id": "c", "text": "No action is required with this defect .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Passenger windows in jet transport aircraft normally have', '[{"id": "a", "text": "two structural panes .", "correct": true}, {"id": "b", "text": "one structural pane .", "correct": false}, {"id": "c", "text": "three structural panes .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A plug type window is fitted', '[{"id": "a", "text": "from the outside.", "correct": false}, {"id": "b", "text": "from the inside.", "correct": true}, {"id": "c", "text": "from either side.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air is used to seal the cabin door in pressure cabins. The source of this air is usually', '[{"id": "a", "text": "cabin pressurised air.", "correct": true}, {"id": "b", "text": "from storage bottles.", "correct": false}, {"id": "c", "text": "ambient pressurised air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Drain valves are normally closed by', '[{"id": "a", "text": "rubber strips.", "correct": false}, {"id": "b", "text": "cabin air pressure.", "correct": true}, {"id": "c", "text": "spring pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Drain holes in unpressurised areas are', '[{"id": "a", "text": "always closed.", "correct": false}, {"id": "b", "text": "always open.", "correct": true}, {"id": "c", "text": "either open or closed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cargo compartment in which there is a separate approved smoke or fire detector system to give warning and means to shut off the ventilating airflow to the compartment is a', '[{"id": "a", "text": "Class ''E'' compartment.", "correct": true}, {"id": "b", "text": "Class ''B'' compartment.", "correct": false}, {"id": "c", "text": "Class ''C'' compartment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aircraft frames are constructed of', '[{"id": "a", "text": "''U'' section.", "correct": false}, {"id": "b", "text": "''I'' section.", "correct": false}, {"id": "c", "text": "''Z'' section.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The life of a fuselage depends on', '[{"id": "a", "text": "the pressurisation cycles excluding maximum differential.", "correct": false}, {"id": "b", "text": "the pressurisation cycles not including ground cycles.", "correct": false}, {"id": "c", "text": "all pressurisation cycles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Passenger cabin seat rails form part of the', '[{"id": "a", "text": "longerons.", "correct": true}, {"id": "b", "text": "stringers.", "correct": false}, {"id": "c", "text": "frames.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A false rib is usually used to', '[{"id": "a", "text": "support and give aerodynamic shape to the wing leading edge.", "correct": true}, {"id": "b", "text": "lose a torsion box structure.", "correct": false}, {"id": "c", "text": "allow the fitment of aileron control tubes through a wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The main undercarriage is attached to the', '[{"id": "a", "text": "rear main spar.", "correct": false}, {"id": "b", "text": "front main spar.", "correct": false}, {"id": "c", "text": "aircraft structure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aspect ratio of 8 could mean', '[{"id": "a", "text": "mean chord 64 ft., span 8 ft.", "correct": false}, {"id": "b", "text": "span squared 64 ft., chord 8 ft.", "correct": false}, {"id": "c", "text": "span 64 ft., mean chord 8 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A spar web will take loads in', '[{"id": "a", "text": "shear.", "correct": true}, {"id": "b", "text": "bending.", "correct": false}, {"id": "c", "text": "tension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One purpose of a rib is to', '[{"id": "a", "text": "maintain the correct contour of an aerofoils covering.", "correct": true}, {"id": "b", "text": "support the bending loads on a fuselage.", "correct": false}, {"id": "c", "text": "form the main lateral member in an aerofoil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is a cantilever wing?', '[{"id": "a", "text": "One that has external supporting struts.", "correct": false}, {"id": "b", "text": "One that has no external supporting struts.", "correct": true}, {"id": "c", "text": "One that folds for access to limited space.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing''s leading edge would have provisions and linkages for slats and', '[{"id": "a", "text": "leading edge flaps.", "correct": true}, {"id": "b", "text": "slots.", "correct": false}, {"id": "c", "text": "trailing edge flaps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A spar web is', '[{"id": "a", "text": "an area between two spar caps.", "correct": true}, {"id": "b", "text": "a rib/spar joint.", "correct": false}, {"id": "c", "text": "a member between the spar and wing/fuselage connection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A leading edge slat is attached to the', '[{"id": "a", "text": "slat track.", "correct": true}, {"id": "b", "text": "wing upper skin.", "correct": false}, {"id": "c", "text": "front spar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A spar is tapered from root to tip because', '[{"id": "a", "text": "shear forces are greatest at the root.", "correct": false}, {"id": "b", "text": "bending moment is greatest at the root.", "correct": true}, {"id": "c", "text": "centre of lift occurs close to the root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a mono- spar wing, what gives the wing its profile contour?', '[{"id": "a", "text": "Ribs.", "correct": true}, {"id": "b", "text": "Milled stringers.", "correct": false}, {"id": "c", "text": "The position of the spars.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cantilever wing is a', '[{"id": "a", "text": "swept -back wing.", "correct": false}, {"id": "b", "text": "usual airliner wing.", "correct": true}, {"id": "c", "text": "top wing of a biplane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aileron reversal is caused by a structure that has a low stiffness in', '[{"id": "a", "text": "torsion.", "correct": true}, {"id": "b", "text": "bending.", "correct": false}, {"id": "c", "text": "shear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The final coat of sealing in a integral fuel tank is called', '[{"id": "a", "text": "interfay.", "correct": false}, {"id": "b", "text": "fillet.", "correct": false}, {"id": "c", "text": "brush coat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The mid-spar is fitted in large aircraft to', '[{"id": "a", "text": "provide redundant design.", "correct": false}, {"id": "b", "text": "support fitting the engine mount & landing gear mount.", "correct": false}, {"id": "c", "text": "assist the main spar with operational loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing bending and shear loads are taken by', '[{"id": "a", "text": "main spar.", "correct": true}, {"id": "b", "text": "skin.", "correct": false}, {"id": "c", "text": "spar cap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The principle load bearing members of the wing are', '[{"id": "a", "text": "struts,", "correct": false}, {"id": "b", "text": "ribs,", "correct": false}, {"id": "c", "text": "spars,", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Upper wing skin on a large transport aircraft is made from', '[{"id": "a", "text": "7075.", "correct": true}, {"id": "b", "text": "2024.", "correct": false}, {"id": "c", "text": "7118.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft with a variable incidence trimming tailplane, the tailplane incidence changes', '[{"id": "a", "text": "if the control column is moved back or forward.", "correct": false}, {"id": "b", "text": "if the trim wheel is turned back or forward.", "correct": true}, {"id": "c", "text": "automatically if the elevator moves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Variable incidence tailplanes', '[{"id": "a", "text": "move rapidly when trimming the aircraft during the landing approach and slowly at all other times.", "correct": false}, {"id": "b", "text": "move rapidly when trimming the aircraft during climb out and landing approach and slowly during cruise.", "correct": true}, {"id": "c", "text": "always move slowly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To correct for nose heaviness on an aircraft fitted with a variable incidence tailplane, the incidence of the tailplane would be', '[{"id": "a", "text": "increased, which is done by lowering the leading edge.", "correct": false}, {"id": "b", "text": "decreased, which is done by lowering the trailing edge.", "correct": false}, {"id": "c", "text": "decreased, which is done by lowering the leading edge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An upward elevator deflection on the reverse camber tailplane', '[{"id": "a", "text": "will increase tailplane download.", "correct": true}, {"id": "b", "text": "may increase or decrease download depending upon the aircraft C of G position.", "correct": false}, {"id": "c", "text": "will decrease tailplane download.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The direction of travel of an electrically operated variable incidence tailplane is determined by', '[{"id": "a", "text": "direction of rotation of the electric motor.", "correct": false}, {"id": "b", "text": "solenoid operated clutches.", "correct": true}, {"id": "c", "text": "a gearbox.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The four main structural items making up a horizontal stabiliser are', '[{"id": "a", "text": "spar, rib, stringers, skin panels.", "correct": true}, {"id": "b", "text": "spar, rib, longerons, skin panels.", "correct": false}, {"id": "c", "text": "spar, rib, bulkheads, skin panels.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The web of an ''I'' beam takes mainly which type of load?', '[{"id": "a", "text": "Shear", "correct": true}, {"id": "b", "text": "Bending", "correct": false}, {"id": "c", "text": "Tension", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The term ''empennage'' incorporates:', '[{"id": "a", "text": "rudder, ailerons, spoilers.", "correct": false}, {"id": "b", "text": "elevators, stabiliser, ailerons.", "correct": false}, {"id": "c", "text": "elevators, stabiliser, rudder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A ''frise'' aileron is incorporated to', '[{"id": "a", "text": "provide aerodynamic balancing so assisting the pilot to move the control.", "correct": false}, {"id": "b", "text": "ensure aileron control is retained at high angles of attack.", "correct": false}, {"id": "c", "text": "equalize aileron drag in a turn.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Control surface flutter may be caused by', '[{"id": "a", "text": "incorrect angular movement of trim tabs.", "correct": false}, {"id": "b", "text": "high static friction in trim tab control tabs.", "correct": false}, {"id": "c", "text": "excessive play in trim tab attachments.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The outboard ailerons on some large aircraft', '[{"id": "a", "text": "are isolated at high speeds.", "correct": true}, {"id": "b", "text": "are isolated to improve sensitivity.", "correct": false}, {"id": "c", "text": "are isolated at low speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The balance tab is an auxiliary surface fitted to a main control surface', '[{"id": "a", "text": "operating automatically to assist the pilot in moving the controls.", "correct": true}, {"id": "b", "text": "operated independently at which point in the length of cable the tensiometer is applied.", "correct": false}, {"id": "c", "text": "operating automatically to provide ''feel'' to the controls.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An elevator controls the aircraft motion in', '[{"id": "a", "text": "pitch.", "correct": true}, {"id": "b", "text": "roll.", "correct": false}, {"id": "c", "text": "yaw.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerodynamic balance', '[{"id": "a", "text": "will cause CP to move towards the trailing edge and cause instability.", "correct": false}, {"id": "b", "text": "will reduce aerodynamic loading.", "correct": true}, {"id": "c", "text": "will cause CP to move forward of hinge and cause overbalance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The extension to the rudder (shaded portion shown on the diagram), is provided to', '[{"id": "a", "text": "make the pilot aware of the aerodynamic forces encountered when moving the control.", "correct": false}, {"id": "b", "text": "provide aerodynamic assistance for the pilot when moving the rudder.", "correct": true}, {"id": "c", "text": "prevent control surface flutter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerodynamic balancing of flight controls is achieved by', '[{"id": "a", "text": "providing a portion of the control surface ahead of the hinge point.", "correct": true}, {"id": "b", "text": "placing a weight ahead of the hinge point.", "correct": false}, {"id": "c", "text": "placing a weight in the leading edge of the control surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A horn balance is', '[{"id": "a", "text": "a projection of the outer edge of the control surface forward of the hinge line.", "correct": true}, {"id": "b", "text": "a rod projecting forward from the control surface with a weight on the end.", "correct": false}, {"id": "c", "text": "a rod projecting upward from the main control surface to which the control cables are attached.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A control surface is mass balanced by', '[{"id": "a", "text": "the attachment of weights acting forward of the hinge line.", "correct": true}, {"id": "b", "text": "the attachment of weights acting on the hinge line.", "correct": false}, {"id": "c", "text": "fitting a balance tab.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An excess of aerodynamic balance would move the control surface centre of pressure', '[{"id": "a", "text": "rearwards, resulting in loss of assistance.", "correct": false}, {"id": "b", "text": "forwards, resulting in an unstable overbalance.", "correct": true}, {"id": "c", "text": "rearwards, resulting in too much assistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerodynamic balance is used to', '[{"id": "a", "text": "prevent flutter of the flying controls.", "correct": false}, {"id": "b", "text": "reduce the control load to zero.", "correct": false}, {"id": "c", "text": "make the flying controls easier to move.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is attached to the rear of the vertical stabilizer?', '[{"id": "a", "text": "Elevator", "correct": false}, {"id": "b", "text": "Rudder", "correct": true}, {"id": "c", "text": "Aileron", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flying control mass balance weight', '[{"id": "a", "text": "keeps the control surface C of G as close to the trailing edge as possible.", "correct": false}, {"id": "b", "text": "tends to move the control surface C of G close to the hinge line.", "correct": true}, {"id": "c", "text": "tends to move the control surface C of G forward of the hinge line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The method employed to mass balance control surfaces is to', '[{"id": "a", "text": "attach weights forward of the hinge line.", "correct": true}, {"id": "b", "text": "fit bias strips to the trailing edge of the surfaces.", "correct": false}, {"id": "c", "text": "allow the leading edge of the surface to project into the airflow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A control surface is provided with aerodynamic balancing to', '[{"id": "a", "text": "increase stability.", "correct": false}, {"id": "b", "text": "decrease the drag when the control is deflected.", "correct": false}, {"id": "c", "text": "assist the pilot in moving the control.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Construction such as horn balance and inset hinge balance installed on control surface assembly', '[{"id": "a", "text": "is meant to trim CG of control surfaces.", "correct": false}, {"id": "b", "text": "serves as a ''servo'' system of balance.", "correct": false}, {"id": "c", "text": "has same effect of the balance tab.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flutter can be reduced by using', '[{"id": "a", "text": "mass balancing.", "correct": true}, {"id": "b", "text": "servo tabs.", "correct": false}, {"id": "c", "text": "a horn balance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fin helps to give', '[{"id": "a", "text": "directional stability about the longitudinal axis.", "correct": false}, {"id": "b", "text": "directional stability about the normal axis.", "correct": true}, {"id": "c", "text": "longitudinal stability about the normal axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An elevator provides control about the', '[{"id": "a", "text": "longitudinal axis.", "correct": false}, {"id": "b", "text": "lateral axis.", "correct": true}, {"id": "c", "text": "horizontal stabilizer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flying control mass balance weight', '[{"id": "a", "text": "tends to move the control surface C of G close to the hinge line.", "correct": true}, {"id": "b", "text": "keeps the control surface C of G as close to the trailing edge as possible.", "correct": false}, {"id": "c", "text": "ensures that the C of G always acts to aid the pilot thus relieving control column load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of anti-balance tabs is to', '[{"id": "a", "text": "trim the aircraft.", "correct": false}, {"id": "b", "text": "relieve stick loads.", "correct": false}, {"id": "c", "text": "give more feel to the control column.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerodynamic balance of a control surface may be achieved', '[{"id": "a", "text": "by weights added to the control surface aft of the hinge line.", "correct": false}, {"id": "b", "text": "by a horn at the extremity of the surface forward of the hinge line.", "correct": true}, {"id": "c", "text": "by a trimming strip at the trailing edge of the surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following are primary control surfaces?', '[{"id": "a", "text": "Elevators, ailerons, rudder.", "correct": true}, {"id": "b", "text": "Roll spoilers, elevators, tabs.", "correct": false}, {"id": "c", "text": "Elevators, roll spoilers, tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pylon structural member supports the', '[{"id": "a", "text": "empennage.", "correct": false}, {"id": "b", "text": "engine.", "correct": true}, {"id": "c", "text": "centre section.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ATA chapter for Nacelles/Pylons is', '[{"id": "a", "text": "54.", "correct": true}, {"id": "b", "text": "55.", "correct": false}, {"id": "c", "text": "53.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing mounted podded engines and integral fuel tanks', '[{"id": "a", "text": "reduce tailplane download.", "correct": false}, {"id": "b", "text": "provide increased safety if the undercarriage collapses on landing.", "correct": false}, {"id": "c", "text": "provide wing bending relief.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The mounting bolts are tightened so the engine can move', '[{"id": "a", "text": "fore and aft.", "correct": true}, {"id": "b", "text": "laterally, longitudinally, vertically.", "correct": false}, {"id": "c", "text": "torsionally.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Jet engines are usually mounted by', '[{"id": "a", "text": "welded steel tubing.", "correct": false}, {"id": "b", "text": "forged mounts and bolted to aircraft forged structure.", "correct": true}, {"id": "c", "text": "aluminium castings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the minimum cabin air mass flow?', '[{"id": "a", "text": "1 lbs per minute per person.", "correct": false}, {"id": "b", "text": "0.5 lbs per minute per person.", "correct": true}, {"id": "c", "text": "10 lbs per minute per person.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following can be used on the ground?', '[{"id": "a", "text": "Turbo fan.", "correct": true}, {"id": "b", "text": "Turbo brake.", "correct": false}, {"id": "c", "text": "Turbo compressor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The function of the mass airflow control valve is to', '[{"id": "a", "text": "ensure system operating pressure is not exceeded.", "correct": false}, {"id": "b", "text": "maintain a reasonable mass flow of air into the cabin irrespective of aircraft altitude.", "correct": true}, {"id": "c", "text": "ensure that constant airflow out of the cabin is dictated by cabin altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air supplied for pressurization and conditioning is', '[{"id": "a", "text": "hottest from a compressor driven by an engine gear box.", "correct": false}, {"id": "b", "text": "the same for both the above sources.", "correct": false}, {"id": "c", "text": "hottest from an engine compressor bleed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In most pressurization systems, the amount of compressed air delivered to the cabin is', '[{"id": "a", "text": "variable, depending on the amount selected by the cabin rate of change selector.", "correct": false}, {"id": "b", "text": "reasonably constant irrespective of altitude.", "correct": true}, {"id": "c", "text": "constant at any particular altitude but varies for different altitudes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Bleed Air air-conditioning system, the warm air supply is provided by', '[{"id": "a", "text": "the compressor of the gas turbine engine.", "correct": true}, {"id": "b", "text": "the engine exhaust heat.", "correct": false}, {"id": "c", "text": "the gas turbine exhaust.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How much air is required for the Flight Deck?', '[{"id": "a", "text": "10 cubic feet/minute.", "correct": true}, {"id": "b", "text": "Whatever the captain sets.", "correct": false}, {"id": "c", "text": "10 lbs/minute.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The function of an air mass flow control valve is to', '[{"id": "a", "text": "control the airflow out of the cabin.", "correct": false}, {"id": "b", "text": "ensure that system differential pressure is not exceeded.", "correct": false}, {"id": "c", "text": "maintain a reasonably constant air mass flow into the cabin at all altitudes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The function of spill valves is to control', '[{"id": "a", "text": "the rate of pressurization.", "correct": false}, {"id": "b", "text": "cabin pressure differential.", "correct": false}, {"id": "c", "text": "air supply to the cabin.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a mass flow controller is to', '[{"id": "a", "text": "ensure the cabin altitude remains constant during cruise at all altitudes.", "correct": false}, {"id": "b", "text": "allow pilot to select the desired cabin altitude.", "correct": false}, {"id": "c", "text": "ensure that a constant mass of air is delivered to cabin at all times.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a ''Spill'' valve in a cabin air supply system is', '[{"id": "a", "text": "to relieve the pressure in the air supply ducting to atmosphere.", "correct": false}, {"id": "b", "text": "to spill overboard excess air delivered at S.L. and lower altitudes.", "correct": true}, {"id": "c", "text": "to give a heating effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The mass flow delivery from engine driven blowers is controlled by', '[{"id": "a", "text": "engine speed variations.", "correct": false}, {"id": "b", "text": "automatic control devices.", "correct": false}, {"id": "c", "text": "spill valves.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A spill valve opens', '[{"id": "a", "text": "to prevent an excessive pressure difference.", "correct": false}, {"id": "b", "text": "to control the flow to the cabin.", "correct": true}, {"id": "c", "text": "to control the air from the cabin to outside.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pack valve controls', '[{"id": "a", "text": "air flow.", "correct": true}, {"id": "b", "text": "air temperature.", "correct": false}, {"id": "c", "text": "trim air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In large air conditioning systems, the main fan is activated to', '[{"id": "a", "text": "ensure conditioned air is distributed.", "correct": false}, {"id": "b", "text": "ensure conditioned air is distributed and maintain positive duct pressure.", "correct": true}, {"id": "c", "text": "ensure positive duct pressure is maintained.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a reduction in pack outlet temp is demanded, the temperature of the air at the outlet of the ACM compressor will', '[{"id": "a", "text": "rise.", "correct": false}, {"id": "b", "text": "fall.", "correct": false}, {"id": "c", "text": "remain the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cockpit ventilation is required to be', '[{"id": "a", "text": "10 litres per crew member per minute.", "correct": false}, {"id": "b", "text": "10 cu/ft per crew member per minute.", "correct": true}, {"id": "c", "text": "selected by the crew.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A large aircraft air conditioning system''s cabin temperature control', '[{"id": "a", "text": "is selectable for each zone individually from the flight station.", "correct": true}, {"id": "b", "text": "involves modulating the pack valve.", "correct": false}, {"id": "c", "text": "all zone temperatures are controlled from one master switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An advantage of using air cycle system over the vapour cycle system in aircraft is', '[{"id": "a", "text": "both air conditioning and pressurization are obtained.", "correct": true}, {"id": "b", "text": "weight reduction by avoiding big tanks carrying freon gas.", "correct": false}, {"id": "c", "text": "less hazardous than vapour cycle system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the maximum allowable concentration (by volume) of carbon monoxide in occupied aircraft compartment?', '[{"id": "a", "text": "0.005% (50 p.p.m)", "correct": true}, {"id": "b", "text": "0.02 % (200 p.p.m)", "correct": false}, {"id": "c", "text": "0.01 % (100 p.p.m)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The first component that the charged air enters from the IP compressor is', '[{"id": "a", "text": "the bleed valve.", "correct": false}, {"id": "b", "text": "the check valve.", "correct": true}, {"id": "c", "text": "the pre-cooler.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The thermostatic valve sensing bulb is located just before', '[{"id": "a", "text": "the evaporator.", "correct": false}, {"id": "b", "text": "the compressor.", "correct": true}, {"id": "c", "text": "the condenser.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A refrigerant is used in which of the following?', '[{"id": "a", "text": "Vapour cycle.", "correct": true}, {"id": "b", "text": "Pneumatic pump.", "correct": false}, {"id": "c", "text": "Air cycle machine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A water separator is located', '[{"id": "a", "text": "upstream of the turbine.", "correct": false}, {"id": "b", "text": "downstream of turbine.", "correct": true}, {"id": "c", "text": "downstream of heat exchanger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The velocity of air from the cabin ventilation system should not exceed', '[{"id": "a", "text": "120 feet per minute.", "correct": true}, {"id": "b", "text": "40 feet per minute.", "correct": false}, {"id": "c", "text": "20 feet per minute.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In typical vapour cycle system, the sub-cooler', '[{"id": "a", "text": "is a heat exchanger to superheat the vapour.", "correct": true}, {"id": "b", "text": "cools the vapour further to prevent slugging.", "correct": false}, {"id": "c", "text": "delivers extra cooling effect when the aircraft is on ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an air conditioning system, heat is added to air by', '[{"id": "a", "text": "restricting compressor inlet.", "correct": true}, {"id": "b", "text": "restricting compressor outlet.", "correct": false}, {"id": "c", "text": "restricting duct outlets.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air conditioning systems', '[{"id": "a", "text": "increase the temperature of air.", "correct": false}, {"id": "b", "text": "decrease the temperature of air.", "correct": true}, {"id": "c", "text": "increase and decrease the temperature of air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An air cycle machine turbine', '[{"id": "a", "text": "drives compressor to decrease temperature.", "correct": false}, {"id": "b", "text": "drives compressor to pressurise aircraft.", "correct": false}, {"id": "c", "text": "drives compressor to increase temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air exiting the compressor side of an ACM', '[{"id": "a", "text": "will have decreased pressure and temperature.", "correct": false}, {"id": "b", "text": "no change in temperature or pressure as it is a centrifugal compressor.", "correct": false}, {"id": "c", "text": "will have increased pressure and temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the water trap located in a bootstrap compressor?', '[{"id": "a", "text": "At the inlet of the compressor.", "correct": false}, {"id": "b", "text": "At the inlet of the turbine.", "correct": true}, {"id": "c", "text": "At the outlet of the compressor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the silencer located in a ''blower'' air conditioning system?', '[{"id": "a", "text": "At the inlet to the cabin.", "correct": false}, {"id": "b", "text": "At the outlet of the blower.", "correct": true}, {"id": "c", "text": "At the inlet of the blower.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When does a ''blower'' air conditioning system produce the most air?', '[{"id": "a", "text": "At low altitudes.", "correct": false}, {"id": "b", "text": "It is not affected by altitude.", "correct": true}, {"id": "c", "text": "At high altitudes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an air conditioning system, before distribution, the air goes through the', '[{"id": "a", "text": "flow control valve.", "correct": false}, {"id": "b", "text": "TCV and mixer valve.", "correct": false}, {"id": "c", "text": "TCV.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a cabin air recirculation system, recirculated air and fresh air are supplied in the proportions', '[{"id": "a", "text": "50% of fresh air, 50% of recirculated air.", "correct": false}, {"id": "b", "text": "60% of fresh air, 40% of recirculated air.", "correct": true}, {"id": "c", "text": "40% of fresh air, 60% of recirculated air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An air-to-air heat exchanger is provided to', '[{"id": "a", "text": "increase the air supply temperature.", "correct": false}, {"id": "b", "text": "provide an emergency ram air supply.", "correct": false}, {"id": "c", "text": "reduce the air supply temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Temperature control of cabin air is achieved by', '[{"id": "a", "text": "varying the ambient airflow to the heat exchanger.", "correct": false}, {"id": "b", "text": "controlling the water vapour in the supply.", "correct": false}, {"id": "c", "text": "regulating the amount of air by-passing the cooling system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In pressurized aircraft, temperature conditioning is mainly achieved by', '[{"id": "a", "text": "adding heat to the pressurising air.", "correct": false}, {"id": "b", "text": "extracting heat from the pressurising air.", "correct": true}, {"id": "c", "text": "varying cabin pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If pressurisation air supplies come from an engine compressor, an internal oil leak will', '[{"id": "a", "text": "not affect the issue as it is automatically detected and vented overboard.", "correct": false}, {"id": "b", "text": "not contaminate the air.", "correct": false}, {"id": "c", "text": "contaminate the air.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cold air unit produces a drop in temperature by', '[{"id": "a", "text": "driving the unit''s compressor.", "correct": false}, {"id": "b", "text": "reducing pressure.", "correct": false}, {"id": "c", "text": "reducing pressure and driving the unit''s compressor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Heating for pressure cabins is obtained from', '[{"id": "a", "text": "driving the units compressor.", "correct": false}, {"id": "b", "text": "air supply heated by the pressurising process.", "correct": true}, {"id": "c", "text": "only by adding heat electrically to the air supplies.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cold air unit allows for cabin temperatures to be', '[{"id": "a", "text": "lower than ambient air temperature despite compression heating.", "correct": false}, {"id": "b", "text": "same as ambient temperature, despite compression heating.", "correct": false}, {"id": "c", "text": "a little more than ambient air temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cold air unit produces a drop in temperature by', '[{"id": "a", "text": "directing compressed air into a heat exchanger.", "correct": false}, {"id": "b", "text": "air supply to the cabin.", "correct": false}, {"id": "c", "text": "expanding hot air across a turbine which is driving a compressor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a ''muff'' or air ducting is built around the engine exhaust system and air is directed around inside the muffler, this is an', '[{"id": "a", "text": "thermal heater.", "correct": false}, {"id": "b", "text": "exhaust heater.", "correct": true}, {"id": "c", "text": "combustion heater.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a turbo fan cold air system, the heat exchanger cooling air is', '[{"id": "a", "text": "ram air from ambient conditions.", "correct": true}, {"id": "b", "text": "air bled directly from engine or through blower.", "correct": false}, {"id": "c", "text": "bled from cabin air supply duct..", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Conditioned air is', '[{"id": "a", "text": "temperature and pressure adjusted.", "correct": true}, {"id": "b", "text": "moisture removed.", "correct": false}, {"id": "c", "text": "oxygen added.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following sometimes inhibits an air conditioning pack?', '[{"id": "a", "text": "Flap position switches.", "correct": false}, {"id": "b", "text": "Undercarriage switches.", "correct": false}, {"id": "c", "text": "Throttle switches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When carrying out a ground pressure test, you should use', '[{"id": "a", "text": "a G.P.U. and A.P.U. combination.", "correct": false}, {"id": "b", "text": "ground trolley and clean air.", "correct": true}, {"id": "c", "text": "the aircraft engines because you can test the whole system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ventilation air in the aircraft cabin must have a minimum humidity of', '[{"id": "a", "text": "60 percent.", "correct": false}, {"id": "b", "text": "30 percent.", "correct": true}, {"id": "c", "text": "20 percent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Boot-Strap Air Conditioning supply system the source of compressed air is from', '[{"id": "a", "text": "gas turbine compressor bleed air.", "correct": true}, {"id": "b", "text": "gas turbine intake ram air.", "correct": false}, {"id": "c", "text": "ram air at the wing leading edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The temperature within the cabin of the aircraft is normally maintained at', '[{"id": "a", "text": "20ºC to 24ºC.", "correct": false}, {"id": "b", "text": "18ºC to 24ºC,", "correct": true}, {"id": "c", "text": "12ºC to 18ºC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a ''bootstrap'' cooling system the supply of air is first', '[{"id": "a", "text": "passed across an expansion turbine, then compressed and passed through a heat exchanger.", "correct": false}, {"id": "b", "text": "compressed then passed through a heat exchanger and across an expansion turbine.", "correct": true}, {"id": "c", "text": "passes across an expansion turbine, then directly to the heat exchanger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The humidity within a passenger cabin should', '[{"id": "a", "text": "not be less than 60%.", "correct": false}, {"id": "b", "text": "be between 30% and 70%.", "correct": true}, {"id": "c", "text": "not be greater than 40%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the principles of cooling employed in an air cycle system is', '[{"id": "a", "text": "by surface heat exchange in the C.A.U.", "correct": false}, {"id": "b", "text": "by compression of ambient air across a turbine.", "correct": false}, {"id": "c", "text": "conversion of heat energy to mechanical energy in the C.A.U.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before filling a vapour cycle cooling system', '[{"id": "a", "text": "pre-heat the system to 100°F.", "correct": false}, {"id": "b", "text": "flush the system with a solvent.", "correct": false}, {"id": "c", "text": "apply suction to remove air and moisture.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rate of flow of air from the punkha louvers should not be less than', '[{"id": "a", "text": "25 ft/min.", "correct": true}, {"id": "b", "text": "300 ft/min.", "correct": false}, {"id": "c", "text": "200 ft/min.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the case of a vapour cycle cooling, system heat is removed from the charge air by', '[{"id": "a", "text": "reducing the pressure of a vapour.", "correct": false}, {"id": "b", "text": "changing a liquid into a vapour.", "correct": true}, {"id": "c", "text": "changing a vapour into a liquid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Subsequent to passing through the primary heat exchanger, the supply air in a turbo-fan cold air system flows to the', '[{"id": "a", "text": "inter cooler or secondary heat exchanger.", "correct": false}, {"id": "b", "text": "turbine.", "correct": false}, {"id": "c", "text": "fan.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The heat exchanger in a turbo-fan system is cooled by', '[{"id": "a", "text": "air bled from the main cabin supply duct.", "correct": false}, {"id": "b", "text": "ambient ram air.", "correct": true}, {"id": "c", "text": "engine bleed air or blower air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The effective temperature of a cabin is given by', '[{"id": "a", "text": "temperature and humidity.", "correct": true}, {"id": "b", "text": "temperature only.", "correct": false}, {"id": "c", "text": "temperature, humidity, thermal inertia and heat load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the refrigerant dissipates heat in a vapour cycle system', '[{"id": "a", "text": "the vapour converts to a liquid.", "correct": true}, {"id": "b", "text": "the liquid converts to a vapour.", "correct": false}, {"id": "c", "text": "the liquid sublimates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'International markings for air conditioning pipelines are', '[{"id": "a", "text": "triangles.", "correct": false}, {"id": "b", "text": "rectangles.", "correct": false}, {"id": "c", "text": "dots.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cabin humidifier is operated', '[{"id": "a", "text": "on the ground.", "correct": false}, {"id": "b", "text": "at high altitudes.", "correct": true}, {"id": "c", "text": "at low altitudes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A turbo fan CAU used for air cycle cooling will', '[{"id": "a", "text": "not affect the charge air pressure.", "correct": false}, {"id": "b", "text": "decrease pressure and temperature of the charge air.", "correct": true}, {"id": "c", "text": "increase the pressure but decrease the temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressurisation system operation may be inhibited by', '[{"id": "a", "text": "air/ground microswitches.", "correct": false}, {"id": "b", "text": "flap microswitches.", "correct": false}, {"id": "c", "text": "throttle microswitches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin outflow valves provide', '[{"id": "a", "text": "outflow of cabin pressure and pressure warning.", "correct": false}, {"id": "b", "text": "outflow of cabin pressure and ventilation.", "correct": true}, {"id": "c", "text": "cabin positive pressure and negative (suction) pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On the ramp, the pre-cooler obtains its cooling action by', '[{"id": "a", "text": "fan inducement.", "correct": true}, {"id": "b", "text": "gas expansion.", "correct": false}, {"id": "c", "text": "ram air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The electrical spill-valve operates on signals from', '[{"id": "a", "text": "the venturi metering duct.", "correct": true}, {"id": "b", "text": "the latching solenoid.", "correct": false}, {"id": "c", "text": "the pressure controller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During taxiing, the cabin pressure in a large aircraft is', '[{"id": "a", "text": "below atmospheric pressure.", "correct": false}, {"id": "b", "text": "above atmospheric pressure.", "correct": true}, {"id": "c", "text": "at atmospheric pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin pressure is normally controlled by the rate of', '[{"id": "a", "text": "air discharge.", "correct": true}, {"id": "b", "text": "climb or decent.", "correct": false}, {"id": "c", "text": "air supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As an aircraft descends from cruising altitude (34,000ft), the cabin altitude must', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "stay the same.", "correct": false}, {"id": "c", "text": "decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The signal line between the controller and discharge valve is leaking. This will cause', '[{"id": "a", "text": "the cabin pressure to decrease.", "correct": false}, {"id": "b", "text": "it w ill not effect on cabin pressure.", "correct": false}, {"id": "c", "text": "the cabin pressure to increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The basic system of cabin pressurisation is to arrange a constant', '[{"id": "a", "text": "outlet and vary the inlet..", "correct": false}, {"id": "b", "text": "inlet and vary the outlet.", "correct": true}, {"id": "c", "text": "inlet and outlet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the differential capsule in a pressure controller is to control', '[{"id": "a", "text": "the rate of pressurisation.", "correct": false}, {"id": "b", "text": "cabin differential pressure.", "correct": true}, {"id": "c", "text": "cabin air flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a pressurised aircraft at maximum differential pressure and a cabin pressure increase occurs, the differential capsule in the pressure controller will', '[{"id": "a", "text": "let pressurisation to be switched off until leaks cause a drop in pressure.", "correct": false}, {"id": "b", "text": "have a constant mass flow.", "correct": false}, {"id": "c", "text": "let all pressurising air to be spilled overboard.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A comfortable rate of cabin altitude climb for passengers is', '[{"id": "a", "text": "500 ft. per min.", "correct": true}, {"id": "b", "text": "100 ft. per min.", "correct": false}, {"id": "c", "text": "300 ft. per min.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before carrying out a ground pressure check,', '[{"id": "a", "text": "turn on all instruments.", "correct": false}, {"id": "b", "text": "check all pitot and static lines are fitted.", "correct": true}, {"id": "c", "text": "set altimeter to QNH.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On touch -down of aircraft', '[{"id": "a", "text": "the outflow valve will be shut.", "correct": false}, {"id": "b", "text": "the cabin pressure will be zero.", "correct": false}, {"id": "c", "text": "the outflow valve will be fully open.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When pressurising the aircraft on the ground for test purposes, internal doors, cupboards etc. must be', '[{"id": "a", "text": "all open.", "correct": true}, {"id": "b", "text": "removed.", "correct": false}, {"id": "c", "text": "all closed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Prior to conducting a ground pressurisation test, it is necessary to', '[{"id": "a", "text": "reset/disable the pressure controller.", "correct": true}, {"id": "b", "text": "disconnect the emergency pressure relief valve.", "correct": false}, {"id": "c", "text": "set QFE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the flightdeck of an unpressurised aircraft, there is a gauge that shows', '[{"id": "a", "text": "aircraft altitude.", "correct": true}, {"id": "b", "text": "cabin differential pressure.", "correct": false}, {"id": "c", "text": "cabin pressure altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin differential pressure is the pressure difference between', '[{"id": "a", "text": "sea level air pressure and indicated dynamic pressure in the cabin.", "correct": false}, {"id": "b", "text": "8,000ft and standard barometric pressure.", "correct": false}, {"id": "c", "text": "the pressure inside the aircraft and the ambient air pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the pressure controller is set to 0 ft.', '[{"id": "a", "text": "maximum differential is reached immediately after take-off.", "correct": false}, {"id": "b", "text": "cabin will not pressurise.", "correct": true}, {"id": "c", "text": "cabin remains at sea level until maximum differential.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During a pressurisation check at maximum differential, if the engines are shut-down', '[{"id": "a", "text": "cabin ROC indicator gives indication of cabin seal efficiency.", "correct": true}, {"id": "b", "text": "aircraft remains pressurised until the dump valve opens.", "correct": false}, {"id": "c", "text": "outflow valve opens immediately.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin pressure is maintained by', '[{"id": "a", "text": "controlling the output of the compressor.", "correct": false}, {"id": "b", "text": "controlling the supply of air to the cabin.", "correct": false}, {"id": "c", "text": "controlling the amount of air discharged from the cabin.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Control of rate of change of cabin pressure is', '[{"id": "a", "text": "equally important in descent and ascent.", "correct": false}, {"id": "b", "text": "most important in descent.", "correct": true}, {"id": "c", "text": "most important in ascent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin rate of climb is shown by', '[{"id": "a", "text": "warning lights.", "correct": false}, {"id": "b", "text": "a special instrument.", "correct": true}, {"id": "c", "text": "a double scale on the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During normal pressurized climb following take-off', '[{"id": "a", "text": "the cabin R.O.C. is more than ambient R.O.C.", "correct": false}, {"id": "b", "text": "the cabin R.O.C. is less than ambient R.O.C.", "correct": true}, {"id": "c", "text": "the differential pressure is constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin differential pressure is the difference between', '[{"id": "a", "text": "8,000 ft and sea level.", "correct": false}, {"id": "b", "text": "cabin pressure and ambient pressure.", "correct": true}, {"id": "c", "text": "I.S.A. conditions and aircraft altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin altitude in pressurized flight is the', '[{"id": "a", "text": "pressure altitude of the cabin as corrected to mean sea level I.S.A. conditions.", "correct": false}, {"id": "b", "text": "altitude at which cabin altitude equals outside air pressure.", "correct": false}, {"id": "c", "text": "altitude corresponding to cabin pressure irrespective of the altitude for the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft has reached max. diff. and is at constant level (altitude) the system allows for', '[{"id": "a", "text": "constant mass flow.", "correct": true}, {"id": "b", "text": "all pressurising air to be spilled overboard.", "correct": false}, {"id": "c", "text": "pressurisation to be switched off until leaks cause a drop in pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The control of ventilating and pressurising air released to atmosphere is achieved by a', '[{"id": "a", "text": "pressure controller/dump valve combination.", "correct": false}, {"id": "b", "text": "discharge valve/inwards relief valve combination.", "correct": false}, {"id": "c", "text": "pressure controller/discharge valve combination.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Rate of change of cabin pressure is most noticeably shown on a', '[{"id": "a", "text": "cabin pressure gauge.", "correct": false}, {"id": "b", "text": "cabin altimeter.", "correct": false}, {"id": "c", "text": "cabin V.S.I.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressurisation control ensures that', '[{"id": "a", "text": "the cabin is always maintained at sea level.", "correct": false}, {"id": "b", "text": "pressurisation does not start before aircraft is above 8,000 ft.", "correct": false}, {"id": "c", "text": "at operational altitude the cabin altitude is below 10,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), '''Pitot'' and ''Static'' lines during a cabin pressure test should be', '[{"id": "a", "text": "cross connected.", "correct": false}, {"id": "b", "text": "connected.", "correct": true}, {"id": "c", "text": "disconnected,", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the cabin pressure fails to reach its maximum cabin pressure differential the', '[{"id": "a", "text": "discharge valve should be adjusted.", "correct": false}, {"id": "b", "text": "outward relief valve is inoperative.", "correct": false}, {"id": "c", "text": "pressure controller should be adjusted.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the aircraft has reached its maximum cabin pressure differential the', '[{"id": "a", "text": "discharge valve opens.", "correct": true}, {"id": "b", "text": "mass flow ceases through the cabin.", "correct": false}, {"id": "c", "text": "discharge valve closes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Would you operate the flying controls during a cabin pressure ground test?', '[{"id": "a", "text": "Yes", "correct": true}, {"id": "b", "text": "Occasionally", "correct": false}, {"id": "c", "text": "No", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which component must be isolated when carrying out a ground cabin pressure test?', '[{"id": "a", "text": "Pressure relief valve.", "correct": false}, {"id": "b", "text": "Pressure discharge valve.", "correct": true}, {"id": "c", "text": "Pressure regulator controller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cabin pressure air leak from the front of the fuselage is', '[{"id": "a", "text": "not effective in any way.", "correct": false}, {"id": "b", "text": "most desirable because it increases the air-flow.", "correct": false}, {"id": "c", "text": "most undesirable because of the drag created.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The principle of cabin pressurisation is', '[{"id": "a", "text": "cabin altitude climbs eventually to that of the aircraft.", "correct": false}, {"id": "b", "text": "whilst the aircraft climbs to altitude, the cabin climbs to a lower altitude.", "correct": true}, {"id": "c", "text": "cabin altitude will always maintain a constant differential to that of aircraft altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the cabin differential pressure has reached the required value and the height is maintained', '[{"id": "a", "text": "the pressure system ceases to function until the cabin pressure is reduced.", "correct": false}, {"id": "b", "text": "constant mass airflow is permitted through the cabin.", "correct": true}, {"id": "c", "text": "all pressurized air is spilled to atmosphere.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin pressure controller maintains a pre-set cabin altitude by', '[{"id": "a", "text": "regulating the position of the outflow valve.", "correct": true}, {"id": "b", "text": "regulating the position of the inward relief valve.", "correct": false}, {"id": "c", "text": "regulating the mass flow into the cabin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If cabin height is set lower than airfield height when the aircraft is on the ground with squat switches overridden, then the outflow valve will normally', '[{"id": "a", "text": "not operate.", "correct": false}, {"id": "b", "text": "remain closed.", "correct": true}, {"id": "c", "text": "open.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cabin altitude is', '[{"id": "a", "text": "the difference between cabin pressure and atmospheric pressure.", "correct": false}, {"id": "b", "text": "the equivalent height of the aircraft above sea level.", "correct": true}, {"id": "c", "text": "the actual height of the aircraft above sea level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cabin differential pressure is', '[{"id": "a", "text": "the equivalent height of the aircraft above sea level.", "correct": false}, {"id": "b", "text": "the difference between cabin pressure and atmospheric pressure.", "correct": true}, {"id": "c", "text": "the actual height of the aircraft above sea level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The outflow of air from the cabin is regulated by', '[{"id": "a", "text": "the outflow valves.", "correct": true}, {"id": "b", "text": "the dump control valves.", "correct": false}, {"id": "c", "text": "the vent valves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an altitude of 8000 feet is selected on the cabin pressure controller and provided maximum cabin pressure differential is not exceeded', '[{"id": "a", "text": "sea level cabin conditions will be maintained to 8000 feet aircraft altitude.", "correct": false}, {"id": "b", "text": "8000 feet cabin conditions will be maintained at aircraft altitudes above 8000 feet.", "correct": true}, {"id": "c", "text": "8000 feet cabin conditions will be maintained at all aircraft altitudes from sea level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If cabin pressure is increasing, the cabin rate of change indicator will show', '[{"id": "a", "text": "zero, provided the rate of change is within the normally accepted limits.", "correct": false}, {"id": "b", "text": "a rate of climb.", "correct": false}, {"id": "c", "text": "a rate of descent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During a normal climb from aerodrome level with the pressurization system ''ON''', '[{"id": "a", "text": "the pressurization system does not control pressure until 10,000 ft is reached.", "correct": false}, {"id": "b", "text": "the cabin differential pressure is maintained constant.", "correct": false}, {"id": "c", "text": "the atmospheric pressure decreases more quickly than the cabin pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Rate of change of cabin pressure is', '[{"id": "a", "text": "selected by the pilot and controlled by the pressure controller.", "correct": true}, {"id": "b", "text": "automatic.", "correct": false}, {"id": "c", "text": "selected by the pilot and controlled by the spill valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft has a maximum differential pressure of 8.5 PSI at cruising altitude. If the ambient pressure is 2.9 PSI, the pressure inside the cabin at cruising altitude would be', '[{"id": "a", "text": "8.5 PSI.", "correct": false}, {"id": "b", "text": "11.4 PSI.", "correct": true}, {"id": "c", "text": "5.6 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin differential is determined only by', '[{"id": "a", "text": "the height at which the aircraft is flying.", "correct": false}, {"id": "b", "text": "the selected cabin height.", "correct": false}, {"id": "c", "text": "the height at which the aircraft is flying and by the selected cabin height.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the pilot selected a cabin height of 8000 ft. whilst taxiing and activated the pressurization system, the cabin pressure would', '[{"id": "a", "text": "decrease to a pressure equivalent to about 500 ft.", "correct": false}, {"id": "b", "text": "remain at ground level pressure.", "correct": true}, {"id": "c", "text": "decrease to a pressure equivalent to 8000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A silencer is installed in a pressurization system to reduce', '[{"id": "a", "text": "engine noise coming through the ventilators.", "correct": false}, {"id": "b", "text": "the noise from the high speed of airflow within the system.", "correct": false}, {"id": "c", "text": "the noise from the blowers and/or compressors in the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To avoid discomfort, the rate of change of pressure should be low, particularly', '[{"id": "a", "text": "when cabin pressure is decreasing.", "correct": false}, {"id": "b", "text": "during descent.", "correct": true}, {"id": "c", "text": "during ascent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is operating at 40,000 ft. the pressurization ensures that', '[{"id": "a", "text": "sea level pressure is maintained in the cabin.", "correct": false}, {"id": "b", "text": "the cabin pressure is progressively increased until the operational height is reached.", "correct": false}, {"id": "c", "text": "the cabin pressure is equivalent to an altitude of less than 10,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pressure controller activates', '[{"id": "a", "text": "the spill valve.", "correct": false}, {"id": "b", "text": "the blower or compressor.", "correct": false}, {"id": "c", "text": "the cabin discharge valve.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When cruising near the operational ceiling, the flight altitude set on the pressurization control panel may be 500 ft. more than the actual flight altitude so as to prevent', '[{"id": "a", "text": "inward relief valve operation.", "correct": false}, {"id": "b", "text": "pressure controller hunting.", "correct": true}, {"id": "c", "text": "safety valve operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cabin rate of climb is shown', '[{"id": "a", "text": "on a specific indicator.", "correct": true}, {"id": "b", "text": "as being inside or outside limits by green and red lights, a gauge being used.", "correct": false}, {"id": "c", "text": "by a differential scale on the aircraft rate of climb indicator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A water separator would be installed in a pressurization system to', '[{"id": "a", "text": "collect any rain accompanying the ram air.", "correct": false}, {"id": "b", "text": "extract surplus water from the charge air.", "correct": true}, {"id": "c", "text": "extract water from the cabin air before it is discharged to atmosphere.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin pressure controller maintains a particular cabin altitude by control of', '[{"id": "a", "text": "cabin mass air flow.", "correct": false}, {"id": "b", "text": "inward relief valve position.", "correct": false}, {"id": "c", "text": "outflow valve position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ditching control is used for', '[{"id": "a", "text": "closing all valves and inlets.", "correct": true}, {"id": "b", "text": "rapid aircraft depressurisation.", "correct": false}, {"id": "c", "text": "deploying life rafts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inwards relief valves usually open at a negative differential pressure not exceeding', '[{"id": "a", "text": "0.16 p.s.i.", "correct": false}, {"id": "b", "text": "1.2 p.s.i.", "correct": true}, {"id": "c", "text": "0.5 p.s.i.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Failure of the normal maximum differential pressure control is catered for by', '[{"id": "a", "text": "inwards relief valve.", "correct": false}, {"id": "b", "text": "cabin safety relief valves.", "correct": true}, {"id": "c", "text": "spill valves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A negative differential pressure is prevented by', '[{"id": "a", "text": "a blow off valve.", "correct": false}, {"id": "b", "text": "an inward relief valve.", "correct": true}, {"id": "c", "text": "a spill valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft employing a heater system on the air conditioning system, after an overheat, how is the heater reset?', '[{"id": "a", "text": "After cooling below 300°C it auto resets.", "correct": false}, {"id": "b", "text": "On ground only by engineer.", "correct": true}, {"id": "c", "text": "After it cools the pilot resets.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ditching control is used to', '[{"id": "a", "text": "maintain cabin pressure at sea level", "correct": false}, {"id": "b", "text": "close the outflow valves.", "correct": true}, {"id": "c", "text": "achieve rapid depressurisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A safety valve will normally relieve at', '[{"id": "a", "text": "lower differential pressure than the discharge valve.", "correct": false}, {"id": "b", "text": "higher differential pressure than the discharge valve.", "correct": true}, {"id": "c", "text": "negative differential pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inward vent valves will operate when', '[{"id": "a", "text": "depressurising after descent.", "correct": false}, {"id": "b", "text": "cabin altitude exceeds aircraft altitude.", "correct": true}, {"id": "c", "text": "aircraft altitude exceeds cabin altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An inward relief valve will operate', '[{"id": "a", "text": "after an aircraft has landed, to restore ground level conditions is the cabin.", "correct": false}, {"id": "b", "text": "when cabin pressure is lower than ambient pressure.", "correct": true}, {"id": "c", "text": "when climbing with pressurization ''OFF''.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inward vent valves are fitted to', '[{"id": "a", "text": "limit positive differentials.", "correct": false}, {"id": "b", "text": "increase ventilation.", "correct": false}, {"id": "c", "text": "limit negative differentials.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An inward relief valve is installed in a pressurization system to ensure that the pressure hull of an aircraft is not subjected to', '[{"id": "a", "text": "too high an internal pressure.", "correct": false}, {"id": "b", "text": "forces which would cause the aircraft to explode.", "correct": false}, {"id": "c", "text": "a high negative differential pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Failure of the normal maximum pressure differential control is allowed for by fitting', '[{"id": "a", "text": "inwards relief valves.", "correct": false}, {"id": "b", "text": "airport altitude selectors.", "correct": false}, {"id": "c", "text": "safety relief valve.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cabin altitude is protected against reaching an altitude of 13,000 ft. by', '[{"id": "a", "text": "altitude sensor.", "correct": true}, {"id": "b", "text": "cabin over pressure relief valve.", "correct": false}, {"id": "c", "text": "bellows in the outflow valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To what position is the inward relief valve spring loaded?', '[{"id": "a", "text": "Open", "correct": false}, {"id": "b", "text": "Both position", "correct": false}, {"id": "c", "text": "Closed", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the cabin altitude increases above the normal maximum', '[{"id": "a", "text": "an inward relief valve opens.", "correct": false}, {"id": "b", "text": "a warning light comes on in the cockpit.", "correct": true}, {"id": "c", "text": "compressor delivery is automatically boosted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inward relief valves are interconnected in pressurized aircraft', '[{"id": "a", "text": "to achieve maximum pressure differential.", "correct": false}, {"id": "b", "text": "to relieve cabin pressure and allow outside pressure to be greater.", "correct": false}, {"id": "c", "text": "to allow controlled pressure during descent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The inward relief valve is usually set to operate at a cabin differential of', '[{"id": "a", "text": "-0.5 PSI.", "correct": true}, {"id": "b", "text": "+0.5 PSI.", "correct": false}, {"id": "c", "text": "+9.25 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of these barometric instruments uses a restrictor to compute its output?', '[{"id": "a", "text": "VSI", "correct": true}, {"id": "b", "text": "Machmeter", "correct": false}, {"id": "c", "text": "ASI", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A standby ADI uses', '[{"id": "a", "text": "a vertical gyro.", "correct": true}, {"id": "b", "text": "a space gyro.", "correct": false}, {"id": "c", "text": "an earth gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Indicator glasses are ''bloomed'' to', '[{"id": "a", "text": "reduce reflections.", "correct": true}, {"id": "b", "text": "minimise parallex error.", "correct": false}, {"id": "c", "text": "render dust unable to settle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Slat asymmetry may be monitored by using', '[{"id": "a", "text": "position pick-offs.", "correct": true}, {"id": "b", "text": "spring actuators.", "correct": false}, {"id": "c", "text": "torque sensors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A standby compass has a pair of magnets for adjustment. They are initially placed', '[{"id": "a", "text": "parallel with each other.", "correct": true}, {"id": "b", "text": "90 degrees to each other.", "correct": false}, {"id": "c", "text": "45 degrees to each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Component P affects', '[{"id": "a", "text": "coefficient B.", "correct": true}, {"id": "b", "text": "coefficient A.", "correct": false}, {"id": "c", "text": "coefficient C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A vacuum mercury gauge reads 5 in. This pressure is', '[{"id": "a", "text": "above zero pressure.", "correct": false}, {"id": "b", "text": "below ambient pressure.", "correct": true}, {"id": "c", "text": "above ambient pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A gyro spinning on a vertical axis will detect the aircraft''s', '[{"id": "a", "text": "yaw and pitch.", "correct": false}, {"id": "b", "text": "yaw only.", "correct": false}, {"id": "c", "text": "roll and pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial horizon uses', '[{"id": "a", "text": "a directional gyro.", "correct": false}, {"id": "b", "text": "a vertical gyro.", "correct": true}, {"id": "c", "text": "a rate gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vibration levels are indicated to the flight crew in', '[{"id": "a", "text": "relative amplitude.", "correct": true}, {"id": "b", "text": "phons.", "correct": false}, {"id": "c", "text": "db.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rigging of a non magnetic proximity sensor requires', '[{"id": "a", "text": "checking the target clearance in the FAR position against reference figures.", "correct": false}, {"id": "b", "text": "checking the target clearance in the NEAR position against reference figures.", "correct": true}, {"id": "c", "text": "ensuring the target contacts the sensor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do you detect and locate a leak in a pitot-static system?', '[{"id": "a", "text": "Isolate the component and perform a systematic check, starting from the instrument.", "correct": false}, {"id": "b", "text": "Pressurize the system and use the soap bubble detection method.", "correct": true}, {"id": "c", "text": "Disconnect each line in turn and perform a pressure leak test.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Following replacement of a separately mounted compass corrector box, a compass calibration swing will be required', '[{"id": "a", "text": "without exception.", "correct": true}, {"id": "b", "text": "only if initial variation is greater than 5 degrees.", "correct": false}, {"id": "c", "text": "onlyif the correctors are not matched to the ones being removed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A +/. symbol on a compass system indicates', '[{"id": "a", "text": "magnetic deviation and compass card are in alignment.", "correct": false}, {"id": "b", "text": "compass card and directional gyro are being synchronised.", "correct": true}, {"id": "c", "text": "failure of the compass system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During climb the pressure in the VSI capsule will be', '[{"id": "a", "text": "equal to the pressure in the case.", "correct": false}, {"id": "b", "text": "greater than the pressure in the case.", "correct": false}, {"id": "c", "text": "lower than the pressure in the case.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Corrections to a mechanical ASI are for', '[{"id": "a", "text": "square law and temperature.", "correct": false}, {"id": "b", "text": "square law.", "correct": false}, {"id": "c", "text": "square law error and temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Two fundamental properties of a gyro are', '[{"id": "a", "text": "wander and rigidity.", "correct": false}, {"id": "b", "text": "rigidity and precession.", "correct": true}, {"id": "c", "text": "precession and wander.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vertical gyros are limited to 85 degrees movement in pitch to prevent', '[{"id": "a", "text": "gyro topple.", "correct": false}, {"id": "b", "text": "gimbal lock.", "correct": true}, {"id": "c", "text": "pitch overshoot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tacho generator pointer is moved by', '[{"id": "a", "text": "a drag cup coupling.", "correct": true}, {"id": "b", "text": "an AC servo motor.", "correct": false}, {"id": "c", "text": "a torque synchro receiver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An altimeter in a pressurised aircraft at altitude has a case leak. The altimeter will', '[{"id": "a", "text": "over read.", "correct": false}, {"id": "b", "text": "not be affected.", "correct": false}, {"id": "c", "text": "under read.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Under what condition is indicated altitude the same as true altitude?', '[{"id": "a", "text": "Never", "correct": false}, {"id": "b", "text": "At sea level in standard conditions (ISA).", "correct": true}, {"id": "c", "text": "When at 18,000 feet MSL with the altimeter set at 29.92.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The earth''s magnetic dip affects a standby compass', '[{"id": "a", "text": "above its pivot only.", "correct": false}, {"id": "b", "text": "equally above and below its pivot.", "correct": false}, {"id": "c", "text": "below its pivot only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An electrical gyro has usually a speed of', '[{"id": "a", "text": "10,000 RPM.", "correct": false}, {"id": "b", "text": "5,000 RPM.", "correct": false}, {"id": "c", "text": "20,000 RPM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flux valve is used to', '[{"id": "a", "text": "align the directional gyro with the earth''s magnetic field.", "correct": true}, {"id": "b", "text": "align the standby compass with the earth''s magnetic field.", "correct": false}, {"id": "c", "text": "drive the HSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The decision height light will illuminate when', '[{"id": "a", "text": "the decision height is selected.", "correct": false}, {"id": "b", "text": "the aircraft''s indicated altitude is below decision height.", "correct": true}, {"id": "c", "text": "the aircraft''s indicated altitude is above decision height.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Central Air Data Computer (CADC) system, Mach information is derived from', '[{"id": "a", "text": "indicated air speed and total air temperature.", "correct": false}, {"id": "b", "text": "indicated airspeed and altitude.", "correct": true}, {"id": "c", "text": "pitot and static pressures.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What instrument connects to pitot pressure?', '[{"id": "a", "text": "Both the airspeed indicator and the vertical speed indicator.", "correct": false}, {"id": "b", "text": "The vertical speed indicator.", "correct": false}, {"id": "c", "text": "The airspeed indicator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Central Air Data Computer (ADC), the rate of climb of an aircraft is produced in the', '[{"id": "a", "text": "Altitude Module.", "correct": true}, {"id": "b", "text": "Mach Module.", "correct": false}, {"id": "c", "text": "Indicated Airspeed Module.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Central Air Data Computer, altitude is produced from', '[{"id": "a", "text": "static air pressure.", "correct": true}, {"id": "b", "text": "pitot air pressure.", "correct": false}, {"id": "c", "text": "pitot air pressure and total air temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Central Air Data Computer (ADC), Indicated Air Speed (IAS) is produced from', '[{"id": "a", "text": "pitot pressure only.", "correct": false}, {"id": "b", "text": "static pressure only.", "correct": false}, {"id": "c", "text": "pitot and static air pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Tx and Rx rotors of a control synchro are 90 degrees shifted. The output is', '[{"id": "a", "text": "zero.", "correct": true}, {"id": "b", "text": "high.", "correct": false}, {"id": "c", "text": "low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Central Air Data Computer (CADC) system, True Air Speed (TAS) is derived from the Mach information and', '[{"id": "a", "text": "Static Air Pressure.", "correct": false}, {"id": "b", "text": "Pitot Air Pressure.", "correct": false}, {"id": "c", "text": "Total Air Temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Track altitude in a radio altimeter system begins at', '[{"id": "a", "text": "2 500 ft radio alt.", "correct": true}, {"id": "b", "text": "10 000 ft radio alt.", "correct": false}, {"id": "c", "text": "1 000 ft radio alt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On the HSI, the heading is ''valid'' when the HDG flag is', '[{"id": "a", "text": "in view.", "correct": false}, {"id": "b", "text": "green.", "correct": false}, {"id": "c", "text": "out of view.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When testing using a thermocouple test set', '[{"id": "a", "text": "no power is required.", "correct": false}, {"id": "b", "text": "a serviceable battery is required.", "correct": true}, {"id": "c", "text": "a 28 VDC supply is required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the maximum radio altimeter track altitude?', '[{"id": "a", "text": "10,000 ft", "correct": false}, {"id": "b", "text": "2,500 ft", "correct": true}, {"id": "c", "text": "500 ft", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A positive coefficient A adjustment of a compass will give a heading', '[{"id": "a", "text": "increase on East/West headings.", "correct": false}, {"id": "b", "text": "increase on all headings.", "correct": true}, {"id": "c", "text": "decrease on all headings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tacho generator has', '[{"id": "a", "text": "its own independent electric system.", "correct": true}, {"id": "b", "text": "28 V applied.", "correct": false}, {"id": "c", "text": "115 V applied.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What could cause fluctuations in instruments?', '[{"id": "a", "text": "Water in static line.", "correct": true}, {"id": "b", "text": "Static blocked.", "correct": false}, {"id": "c", "text": "Pitot blocked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Compass swing would be required after replacing a', '[{"id": "a", "text": "compass Amplifier.", "correct": false}, {"id": "b", "text": "H.S.I.", "correct": false}, {"id": "c", "text": "compass sensing unit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a turn and slip indicator, the needle points to the right, and the ball is to the left. The aircraft is', '[{"id": "a", "text": "over-banked, slipping into the turn.", "correct": false}, {"id": "b", "text": "over-banked, slipping out of the turn.", "correct": false}, {"id": "c", "text": "under-banked, skidding out of the turn.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'True airspeed computed from IAS takes into account', '[{"id": "a", "text": "radar altitude.", "correct": false}, {"id": "b", "text": "temperature only.", "correct": false}, {"id": "c", "text": "temperature and altitude.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For a given IAS, with an increase in altitude, TAS will', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the attitude director gyro stator situated?', '[{"id": "a", "text": "Inside the rotor.", "correct": true}, {"id": "b", "text": "Underneath the rotor.", "correct": false}, {"id": "c", "text": "Around the rotor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the error in the lubber line called?', '[{"id": "a", "text": "Coefficiant B", "correct": false}, {"id": "b", "text": "Coefficiant P", "correct": false}, {"id": "c", "text": "Index error", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An ECAM system is tested under the following conditions:', '[{"id": "a", "text": "Aircraft on the ground with parking brake set/on.", "correct": true}, {"id": "b", "text": "Aircraft in the air with both engines running.", "correct": false}, {"id": "c", "text": "Aircraft on the ground with one engine running.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Millibar is used to express what kind of pressure?', '[{"id": "a", "text": "Pitot pressure.", "correct": false}, {"id": "b", "text": "Ambient pressure.", "correct": true}, {"id": "c", "text": "Barometric pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The maximum deviation on a standby magnetic compass must not be more than', '[{"id": "a", "text": "5°.", "correct": false}, {"id": "b", "text": "3°.", "correct": true}, {"id": "c", "text": "1°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compass base classification Class 2 is periodically re-surveyed every', '[{"id": "a", "text": "1 year.", "correct": false}, {"id": "b", "text": "5 years.", "correct": false}, {"id": "c", "text": "2 years.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft heading is 270°. The magnetic compass deviation is -1°. The pilot should fly', '[{"id": "a", "text": "271°.", "correct": true}, {"id": "b", "text": "270°.", "correct": false}, {"id": "c", "text": "269°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which instrument are most likely to damage if you have a rapid drop in pressure, when carrying out a pitot-static leak check?', '[{"id": "a", "text": "Air speed indicator.", "correct": false}, {"id": "b", "text": "Altimeter.", "correct": false}, {"id": "c", "text": "Vertical speed indicator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The operation of the Angle of Attack indicator is used to detect airflow direction relative to', '[{"id": "a", "text": "the angle of attack of the aircraft.", "correct": false}, {"id": "b", "text": "the pitch angle of the aircraft.", "correct": false}, {"id": "c", "text": "the longitudinal axis of the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The runway heading is', '[{"id": "a", "text": "QFU.", "correct": true}, {"id": "b", "text": "QDM.", "correct": false}, {"id": "c", "text": "QDR.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Apparent drift of a vertical gyro is a function of', '[{"id": "a", "text": "sin of latitude.", "correct": false}, {"id": "b", "text": "cos of latitude.", "correct": true}, {"id": "c", "text": "tan of latitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A machmeter works', '[{"id": "a", "text": "always except on the ground.", "correct": false}, {"id": "b", "text": "above 10,000 ft.", "correct": false}, {"id": "c", "text": "always.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Radio marker information is displayed on', '[{"id": "a", "text": "ADI.", "correct": true}, {"id": "b", "text": "EICAS.", "correct": false}, {"id": "c", "text": "HSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Angle of Attack alarm is sounding too close to stall. Rectification is to', '[{"id": "a", "text": "move probe down.", "correct": false}, {"id": "b", "text": "move probe laterally.", "correct": false}, {"id": "c", "text": "move probe up.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is alpha angle used?', '[{"id": "a", "text": "Accelerometer.", "correct": false}, {"id": "b", "text": "IRS.", "correct": false}, {"id": "c", "text": "Angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the spinup/rundown brake on a gyro instrument?', '[{"id": "a", "text": "Inner gimbal", "correct": true}, {"id": "b", "text": "Rotating vane", "correct": false}, {"id": "c", "text": "Outer gimbal", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In Airways flying, what is the barometric scale of the altimeter set to?', '[{"id": "a", "text": "1013.25", "correct": true}, {"id": "b", "text": "QFE", "correct": false}, {"id": "c", "text": "QNH", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vibration monitoring signals are sent', '[{"id": "a", "text": "via a signal conditioner to the gauge.", "correct": true}, {"id": "b", "text": "via a half-wave rectifier to the gauge.", "correct": false}, {"id": "c", "text": "direct to the gauge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The vacuum system gauge reads 5 inches of mercury. This is from', '[{"id": "a", "text": "ambient and minus.", "correct": true}, {"id": "b", "text": "zero and positive.", "correct": false}, {"id": "c", "text": "zero and minu.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A direct reading Bourdon gauge has a restriction in the inlet. This is to', '[{"id": "a", "text": "prevent FOD ingestion.", "correct": false}, {"id": "b", "text": "dampen sudden pressure changes.", "correct": true}, {"id": "c", "text": "allow for calibration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The hot junction of thermocouple is', '[{"id": "a", "text": "in the combustion chamber.", "correct": false}, {"id": "b", "text": "aft of combustion chamber.", "correct": true}, {"id": "c", "text": "in the instrument.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a rad. alt. reaches 2,500 ft. what happens to the display?', '[{"id": "a", "text": "Rad. alt. goes out of view.", "correct": true}, {"id": "b", "text": "Error warning in view.", "correct": false}, {"id": "c", "text": "Rad. alt. flag in view.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pitot tubes are heated', '[{"id": "a", "text": "by kinetic heating.", "correct": false}, {"id": "b", "text": "by compressed bleed air.", "correct": false}, {"id": "c", "text": "electrically.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The suction gauge reads 5 inches of mercury. This is', '[{"id": "a", "text": "above ambient pressure.", "correct": false}, {"id": "b", "text": "below ambient pressure.", "correct": true}, {"id": "c", "text": "above zero pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the primary colours for use in CRT displays?', '[{"id": "a", "text": "Red, blue, yellow.", "correct": false}, {"id": "b", "text": "Yellow, cyan, magenta.", "correct": false}, {"id": "c", "text": "Red, blue, green.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Alpha vane signal could be fed to ___________ _____________ when close to stall.', '[{"id": "a", "text": "thrust levers", "correct": true}, {"id": "b", "text": "flap position", "correct": false}, {"id": "c", "text": "fast/slow switch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When performing maintenance operations on an aircraft equipped with RVSM system, and a quick release disconnect connection is disturbed', '[{"id": "a", "text": "a full test of the system should be carried out.", "correct": false}, {"id": "b", "text": "the allowances for the system should be halved.", "correct": false}, {"id": "c", "text": "a full test of the system should be carried out only if the aircraft manufacturer recommends to do so.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For aircraft certificated after 1997 and with RVSM, the maximum tolerance for the system would be', '[{"id": "a", "text": "+/- 500 feet for the system overall.", "correct": false}, {"id": "b", "text": "+/- 300 feet plus +/- 50 feet for instrument errors.", "correct": false}, {"id": "c", "text": "+/- 200 feet plus +/- 50 feet for instrument error.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The HSI provides information on', '[{"id": "a", "text": "VOR, plan, map, ILS, radar.", "correct": true}, {"id": "b", "text": "VOR, ILS, plan, attitude.", "correct": false}, {"id": "c", "text": "VOR, ILS, map, radar, attitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The sensing element of the flux valve', '[{"id": "a", "text": "remains in the same position attached to the aircraft structure.", "correct": true}, {"id": "b", "text": "aligns itself to the new heading as the aircraft turns.", "correct": false}, {"id": "c", "text": "aligns itself to the new heading of the aircraft after it has stabilised.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a compass swing: North error -2 degrees, South error - 2 degrees. The coefficient C is', '[{"id": "a", "text": "+2 degrees.", "correct": false}, {"id": "b", "text": "0 degrees.", "correct": true}, {"id": "c", "text": "-2 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When aligning an aircraft for a compass swing, the maximum allowable error is', '[{"id": "a", "text": "1 degrees.", "correct": false}, {"id": "b", "text": "3 degrees.", "correct": false}, {"id": "c", "text": "5 degrees.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pitot head is fitted on the aircraft. The alignment of pitot head is carried out with', '[{"id": "a", "text": "spirit level.", "correct": false}, {"id": "b", "text": "an inclinometer.", "correct": true}, {"id": "c", "text": "micrometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the weight of an aircraft is increased, the maximum lift-to-drag ratio will', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "not be affected.", "correct": true}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The boundary layer of a body in a moving airstream is', '[{"id": "a", "text": "a layer of air over the surface where the airspeed is changing from free stream velocity to zero velocity.", "correct": true}, {"id": "b", "text": "a layer of air which is moving at free stream speed.", "correct": false}, {"id": "c", "text": "a thin layer of air over the surface where the air is stationary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The transition point located on the wing is the point where', '[{"id": "a", "text": "the boundary layer changes from laminar flow to turbulent flow.", "correct": true}, {"id": "b", "text": "airflow starts separating from the wing.", "correct": false}, {"id": "c", "text": "the airflow changes from subsonic to supersonic flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aeroplane fin is of symmetrical aerofoil section and will therefore provide a side-load', '[{"id": "a", "text": "only if a suitable angle of attack develops due to yaw.", "correct": false}, {"id": "b", "text": "only when the rudder is moved.", "correct": false}, {"id": "c", "text": "if a suitable angle of attack develops due either yaw or rudder movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What kind of gyro is a rate gyro?', '[{"id": "a", "text": "Displacement", "correct": false}, {"id": "b", "text": "Tied down", "correct": true}, {"id": "c", "text": "Space", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radio altimeter system can be self tested', '[{"id": "a", "text": "on the ground only.", "correct": true}, {"id": "b", "text": "both on the ground only and in the air.", "correct": false}, {"id": "c", "text": "in the air only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The apparent wander for directional gyros is', '[{"id": "a", "text": "dependant on longitude.", "correct": false}, {"id": "b", "text": "maximum at the pole.", "correct": false}, {"id": "c", "text": "compensated by applying a constant torque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Directional Gyro is checked every 15 minutes for', '[{"id": "a", "text": "drift.", "correct": true}, {"id": "b", "text": "toppling.", "correct": false}, {"id": "c", "text": "erection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Random drift of a gyro is caused by', '[{"id": "a", "text": "gyro friction and unbalance.", "correct": true}, {"id": "b", "text": "error in roll when aircraft is turning.", "correct": false}, {"id": "c", "text": "aircraft turning with an error in roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Standby Compass adjusting magnets (Flinders Bars) exert the most amount of influence', '[{"id": "a", "text": "when 90 degrees apart.", "correct": true}, {"id": "b", "text": "when parallel to each other", "correct": false}, {"id": "c", "text": "when 45 degrees apart", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With engine static and engine blanks fitted, EPR gauge reads just above 1', '[{"id": "a", "text": "Transmitter is unserviceable.", "correct": false}, {"id": "b", "text": "This is normal.", "correct": false}, {"id": "c", "text": "Gauge requires re-calibration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Coefficient A is adjusted', '[{"id": "a", "text": "at 360 degrees.", "correct": false}, {"id": "b", "text": "at 270 degrees.", "correct": false}, {"id": "c", "text": "on any heading.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With an aircraft which has more than one compass system', '[{"id": "a", "text": "both are adjusted on each heading.", "correct": false}, {"id": "b", "text": "master and slave adjusted, correction card for master only.", "correct": false}, {"id": "c", "text": "master adjusted, slave adjusted, each having a corrected compass card.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A DC electrical cable must be positioned how far away from a compass?', '[{"id": "a", "text": "So as to give no more than 2 degrees deflection of compass.", "correct": false}, {"id": "b", "text": "20 inches.", "correct": false}, {"id": "c", "text": "24 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which pitot probe provides information to the captains instruments?', '[{"id": "a", "text": "Lower.", "correct": false}, {"id": "b", "text": "Upper.", "correct": true}, {"id": "c", "text": "Both.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On the CWP, what does amber indicate?', '[{"id": "a", "text": "Present status.", "correct": false}, {"id": "b", "text": "Warning.", "correct": false}, {"id": "c", "text": "Cautionary info.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which instrument shows Decision Height?', '[{"id": "a", "text": "ECAM.", "correct": false}, {"id": "b", "text": "ADI.", "correct": true}, {"id": "c", "text": "HSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where does the HSI receive GND speed information from?', '[{"id": "a", "text": "INS.", "correct": true}, {"id": "b", "text": "EICAS.", "correct": false}, {"id": "c", "text": "Pitot static probes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When power is switched off, the gimbal brake', '[{"id": "a", "text": "stops outer gimbal.", "correct": false}, {"id": "b", "text": "restricts outer gimbal.", "correct": false}, {"id": "c", "text": "restricts inner gimbal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an EADI the command bars show the', '[{"id": "a", "text": "required flight path compared with horizon.", "correct": false}, {"id": "b", "text": "required flight path compared with aircraft position.", "correct": true}, {"id": "c", "text": "required flight path compared to planned flight path.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The airdata computer inputs to', '[{"id": "a", "text": "mach meter, standby altimeter, ASI.", "correct": false}, {"id": "b", "text": "altimeter, FMC, secondary radar.", "correct": true}, {"id": "c", "text": "cabin rate sensors, mach-meters, ASI, altimeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What deviation is indicated by 2 dots in a VOR system?', '[{"id": "a", "text": "2.5°.", "correct": false}, {"id": "b", "text": "6°.", "correct": false}, {"id": "c", "text": "10°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a compass system, what senses the horizontal component of the earths magnetic field and where is it normally fitted?', '[{"id": "a", "text": "A precession device mounted on the yaw axis of the aircraft.", "correct": false}, {"id": "b", "text": "Flux detectors fitted in the wing tips.", "correct": true}, {"id": "c", "text": "Directional gyro mounted on the roll axis of the aircraft", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An RMI has inputs from VOR and', '[{"id": "a", "text": "a remote compass input.", "correct": false}, {"id": "b", "text": "an azimuth gyro.", "correct": true}, {"id": "c", "text": "no other sources.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a modern HSI, the displays are', '[{"id": "a", "text": "course and direction.", "correct": true}, {"id": "b", "text": "direction and attitude.", "correct": false}, {"id": "c", "text": "course and attitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At what height does the rising runway appear?', '[{"id": "a", "text": "300 ft.", "correct": false}, {"id": "b", "text": "200ft.", "correct": true}, {"id": "c", "text": "500ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An H on the EHSI indicates', '[{"id": "a", "text": "DME hold.", "correct": true}, {"id": "b", "text": "VOR hold.", "correct": false}, {"id": "c", "text": "ILS approach.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compared to air driven gyros, the electric gyro runs', '[{"id": "a", "text": "slower.", "correct": false}, {"id": "b", "text": "same speed.", "correct": false}, {"id": "c", "text": "faster.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pneumatic indicator takes its indications from', '[{"id": "a", "text": "compressor outlet.", "correct": false}, {"id": "b", "text": "compressor inlet.", "correct": false}, {"id": "c", "text": "reservoir.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is apparent drift due to?', '[{"id": "a", "text": "Errors when aircraft banking.", "correct": false}, {"id": "b", "text": "Earths rotation.", "correct": true}, {"id": "c", "text": "Gyro pivot friction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft airspeed indicator has', '[{"id": "a", "text": "pitot to the capsule.", "correct": false}, {"id": "b", "text": "pitot to the capsule and static to the out side of the capsule.", "correct": true}, {"id": "c", "text": "static to the capsule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Above 2500 ft. the rad. alt.', '[{"id": "a", "text": "pointer is hidden behind a mask with off flag out of view.", "correct": true}, {"id": "b", "text": "pointer goes to zero to show system is being monitored.", "correct": false}, {"id": "c", "text": "continues to indicate but with a warning flag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How does a machmeter work?', '[{"id": "a", "text": "True airspeed / indicated airspeed.", "correct": false}, {"id": "b", "text": "True airspeed and speed of sound.", "correct": true}, {"id": "c", "text": "Indicated airspeed / temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When changing a pitot static instrument with quick release couplings', '[{"id": "a", "text": "a leak check is always required.", "correct": false}, {"id": "b", "text": "a leak check is not required.", "correct": false}, {"id": "c", "text": "a leak check is only required if stated by manufacturer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The flux detector element', '[{"id": "a", "text": "changes heading with the heading of the aircraft.", "correct": false}, {"id": "b", "text": "changes it position after the aircraft heading is changed.", "correct": false}, {"id": "c", "text": "gives heading with respect to magnetic north.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If rate feedback in a flight director goes open circuit, position indication will', '[{"id": "a", "text": "oscillate.", "correct": true}, {"id": "b", "text": "be sluggish.", "correct": false}, {"id": "c", "text": "go hard over.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The needle of a resolver is connected to', '[{"id": "a", "text": "two coils and an electromagnet.", "correct": false}, {"id": "b", "text": "two coils only.", "correct": true}, {"id": "c", "text": "two coils and a permanent magnet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the compass fluid has bubbles at low altitude', '[{"id": "a", "text": "this has no influence on compass readings.", "correct": false}, {"id": "b", "text": "this is due to excessive high cabin altitude flying.", "correct": false}, {"id": "c", "text": "this is due to insufficient de-aeration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A remote compass compensator unit is replaced. Which of the following is correct?', '[{"id": "a", "text": "No swing is required if the new heading is within 5 degrees of the old.", "correct": false}, {"id": "b", "text": "A compass swing must be performed.", "correct": true}, {"id": "c", "text": "The swing can be performed at a later date.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A compass has a residual deviation of +1 degree. To fly a heading of 180 degrees the pilot must steer', '[{"id": "a", "text": "181 degrees.", "correct": false}, {"id": "b", "text": "180 degrees.", "correct": false}, {"id": "c", "text": "179 degrees.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is a leading edge flap position indicated in the cockpit?', '[{"id": "a", "text": "Servomotor", "correct": false}, {"id": "b", "text": "A measuring device", "correct": false}, {"id": "c", "text": "Torque synchro", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Machmeter, what type of compensation is there?', '[{"id": "a", "text": "Compensation is not required.", "correct": false}, {"id": "b", "text": "Hair spring", "correct": false}, {"id": "c", "text": "Square-Law compensation", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What effect on the rate of precession will a change of gyro rotor speed have?', '[{"id": "a", "text": "No effect", "correct": false}, {"id": "b", "text": "Increase the rotor speed, decrease the rate of precession.", "correct": true}, {"id": "c", "text": "Decrease the rotor speed, decrease the rate of precession.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A gyroscopic body has its rigidity increased by', '[{"id": "a", "text": "increasing the rotor speed.", "correct": true}, {"id": "b", "text": "decreasing the mass of the rotor.", "correct": false}, {"id": "c", "text": "decreasing the rotor speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a constant torque is applied to a gyroscope, the rate of precession', '[{"id": "a", "text": "increases with a lower rotor speed.", "correct": true}, {"id": "b", "text": "increases with a higher rotor speed.", "correct": false}, {"id": "c", "text": "is unaffected by changes in rotor speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Random drift of a gyro is caused by', '[{"id": "a", "text": "unbalance and bearing friction in the gyro.", "correct": true}, {"id": "b", "text": "aircraft turning with an error in roll.", "correct": false}, {"id": "c", "text": "rotation of the earth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pendulous vane type erection system fitted to a gyro horizon works on the principle of', '[{"id": "a", "text": "increased reaction of the air from a bisected port.", "correct": false}, {"id": "b", "text": "increased reaction of the air from a fully open port.", "correct": true}, {"id": "c", "text": "decreased reaction of the air from a fully open port.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During the normal straight and level flight, the gyro of an electrical artificial horizon is kept erect in pitch by a', '[{"id": "a", "text": "mercury switch in the fore and aft axis controlling a torque motor fitted between the inner and outer gimbal", "correct": false}, {"id": "b", "text": "rings.", "correct": false}, {"id": "c", "text": "torque motor fitted between the outer gimbal ring and the case controlled by a mercury switch in the fore", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The normal erection supply to the mercury switches of the artificial horizon is disconnected', '[{"id": "a", "text": "when the fast erection button is pressed.", "correct": false}, {"id": "b", "text": "during turns.", "correct": true}, {"id": "c", "text": "for the first 40 seconds after initially switching ''ON''.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pitch/bank erection system is used in an electrical gyro horizon to', '[{"id": "a", "text": "give full erection control to the roll switch during a turn.", "correct": false}, {"id": "b", "text": "give full erection control to the pitch switch during a turn.", "correct": false}, {"id": "c", "text": "to prevent the pitch switch giving a false indication due to centrifugal effects during a turn.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fast erection push on an electrical gyro horizon must not be used for a set period after switching on because', '[{"id": "a", "text": "overheating of the gyro rotor windings will occur.", "correct": false}, {"id": "b", "text": "the normal erection switch contact will burn out.", "correct": false}, {"id": "c", "text": "excessive hunting will take place.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Apparent drift of a directional gyro is due to', '[{"id": "a", "text": "bearing friction.", "correct": false}, {"id": "b", "text": "unbalance of the gimbals.", "correct": false}, {"id": "c", "text": "the effect of the earth''s rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The erection system on a directional gyroscope has', '[{"id": "a", "text": "a switch on the inner gimbal controlling a motor on the outer gimbal.", "correct": true}, {"id": "b", "text": "a switch on the outer gimbal controlling a motor on the inner gimbal.", "correct": false}, {"id": "c", "text": "a switch on the inner gimbal controlling a motor on the inner gimbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a rate gyro used to detect movements about a vertical axis, the amount the gimbal ring moves would be increased if the', '[{"id": "a", "text": "spring tension was increased.", "correct": false}, {"id": "b", "text": "rotor speed decreases.", "correct": true}, {"id": "c", "text": "angle through which the gyro moves in azimuth increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Turn and Slip indicator employs', '[{"id": "a", "text": "an azimuth gyro.", "correct": false}, {"id": "b", "text": "a vertical gyro.", "correct": false}, {"id": "c", "text": "a rate gyro.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Turn and Slip indicator, the effect of increasing the rotor speed would be', '[{"id": "a", "text": "it would have no effect.", "correct": false}, {"id": "b", "text": "it would under read.", "correct": false}, {"id": "c", "text": "it would over read.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the information on a directional gyro outer gimbal taken off?', '[{"id": "a", "text": "By a flux take-off device.", "correct": true}, {"id": "b", "text": "By a switch on the outer gimbal.", "correct": false}, {"id": "c", "text": "By a switch on the inner gimbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Why is a directional gyro inner gimbal restricted to +/- 85º?', '[{"id": "a", "text": "To prevent outer gimbal rotating.", "correct": false}, {"id": "b", "text": "To ensure outer gimbal erection system works correctly.", "correct": false}, {"id": "c", "text": "To prevent gyro going into gimbal lock.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The speed of the rotor in a Turn and Slip indicator is approximately', '[{"id": "a", "text": "2,400 rpm.", "correct": false}, {"id": "b", "text": "22,500 rpm.", "correct": false}, {"id": "c", "text": "4,200 rpm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a directional gyro, the inner/outer gimbal is corrected to', '[{"id": "a", "text": "15 sine longitude.", "correct": false}, {"id": "b", "text": "15 cosine latitude.", "correct": false}, {"id": "c", "text": "15 sine latitude.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The electrolyte switches used in gyro systems rely upon', '[{"id": "a", "text": "change in inductance to operate.", "correct": false}, {"id": "b", "text": "change in voltage applied to operate.", "correct": false}, {"id": "c", "text": "change in resistance to operate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Precession of a gyro depends on', '[{"id": "a", "text": "both moment of inertia AND angular velocity of the rotor.", "correct": true}, {"id": "b", "text": "moment of inertia of the rotor only.", "correct": false}, {"id": "c", "text": "angular velocity of the rotor only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Angular momentum of a gyro rotor depends on', '[{"id": "a", "text": "angular velocity of the rotor.", "correct": false}, {"id": "b", "text": "moment of inertia of the rotor.", "correct": false}, {"id": "c", "text": "moment of inertia and angular velocity of the rotor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air driven gyros, compared to electric gyros, generally rotate', '[{"id": "a", "text": "faster.", "correct": false}, {"id": "b", "text": "the same speed.", "correct": false}, {"id": "c", "text": "slower.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Gyro rigidity is proportional to', '[{"id": "a", "text": "mass, and radius of mass from spin axis.", "correct": false}, {"id": "b", "text": "mass and speed.", "correct": false}, {"id": "c", "text": "mass, speed and radius of mass from spin axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Gyro precessional force is', '[{"id": "a", "text": "inversely proportional to the applied force.", "correct": false}, {"id": "b", "text": "proportional to the square of the applied force.", "correct": false}, {"id": "c", "text": "directly proportional to applied force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The speed of a vacuum driven gyro horizon rotor is approximately', '[{"id": "a", "text": "15,000 rpm.", "correct": true}, {"id": "b", "text": "4,200 rpm.", "correct": false}, {"id": "c", "text": "22,000 rpm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A V.S.I. is connected to', '[{"id": "a", "text": "vacuum.", "correct": false}, {"id": "b", "text": "static pressure.", "correct": true}, {"id": "c", "text": "pitot pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a V.S.I. pointer at position 1 on the upper half of the scale it indicates', '[{"id": "a", "text": "100 ft/minute rate of climb.", "correct": false}, {"id": "b", "text": "1,000 ft/minute rate of climb.", "correct": true}, {"id": "c", "text": "1,000 ft/minute rate of descent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After disconnecting the supply to an electrically operated gyro instrument it is recommended that, to allow the gyro rotor to stop, before moving the instrument', '[{"id": "a", "text": "three minutes should elapse.", "correct": false}, {"id": "b", "text": "fifteen minutes should elapse.", "correct": true}, {"id": "c", "text": "seven minutes should elapse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Port and Starboard static vents on an aircraft are inter-connected to', '[{"id": "a", "text": "cancel errors caused in the static system when the aircraft yaws.", "correct": true}, {"id": "b", "text": "reduce compressibility error.", "correct": false}, {"id": "c", "text": "minimize errors caused by leaks in the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following would cause a displacement gyro to topple?', '[{"id": "a", "text": "Running gyro at high speed.", "correct": false}, {"id": "b", "text": "Running gyro at low speed.", "correct": true}, {"id": "c", "text": "Inverting the gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In level flight, a V.S.I. will indicate', '[{"id": "a", "text": "horizontal to left.", "correct": true}, {"id": "b", "text": "vertically up.", "correct": false}, {"id": "c", "text": "vertically down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On descent, the pressure in a V.S.I. capsule', '[{"id": "a", "text": "lags the case pressure.", "correct": false}, {"id": "b", "text": "leads the case pressure.", "correct": true}, {"id": "c", "text": "is the same as case pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A small constant leak in the case of V.S.I. fitted in a pressurized aircraft would, during level flight, cause the instrument to indicate', '[{"id": "a", "text": "zero.", "correct": false}, {"id": "b", "text": "a rate of descent.", "correct": false}, {"id": "c", "text": "a rate of climb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a force is applied to a horizontal gyro, the precession of the rotor will continue until', '[{"id": "a", "text": "plane of rotation is in line with the precessional force.", "correct": false}, {"id": "b", "text": "plane of rotation is in line with the plane of the applied force.", "correct": true}, {"id": "c", "text": "as long as the force is applied.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial horizon has', '[{"id": "a", "text": "the inner gimbal pivoted longitudinally.", "correct": false}, {"id": "b", "text": "the inner gimbal pivoted laterally.", "correct": true}, {"id": "c", "text": "the inner gimbal pivoted vertically.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pressure of one atmosphere is equal to', '[{"id": "a", "text": "1 inch Hg.", "correct": false}, {"id": "b", "text": "14.7 PSI.", "correct": true}, {"id": "c", "text": "100 millibar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the directional gyro', '[{"id": "a", "text": "the outer gimbal is pivoted longitudinally.", "correct": false}, {"id": "b", "text": "the outer gimbal is pivoted vertically.", "correct": true}, {"id": "c", "text": "the outer gimbal is pivoted laterally.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The millibar is a unit of', '[{"id": "a", "text": "atmospheric temperature.", "correct": false}, {"id": "b", "text": "pressure altitude.", "correct": false}, {"id": "c", "text": "barometric pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the Turn and Slip indicator', '[{"id": "a", "text": "the spin axis is longitudinal.", "correct": false}, {"id": "b", "text": "the spin axis is vertical.", "correct": false}, {"id": "c", "text": "the spin axis is lateral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an altimeter, the', '[{"id": "a", "text": "capsule is evacuated and sealed.", "correct": true}, {"id": "b", "text": "capsule and case are connected via a calibrated choke.", "correct": false}, {"id": "c", "text": "inside of the capsule is connected to static pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The units on the calibrated scale of a V.S.I. are expressed in', '[{"id": "a", "text": "hundreds of feet per minute.", "correct": true}, {"id": "b", "text": "miles per hour (mph).", "correct": false}, {"id": "c", "text": "knots (kts).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A standby air supply for gyro operation could be obtained from', '[{"id": "a", "text": "a pitot head.", "correct": false}, {"id": "b", "text": "a tapping from the induction manifold.", "correct": false}, {"id": "c", "text": "a venturi.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A rate two turn is', '[{"id": "a", "text": "180 degrees per minute.", "correct": false}, {"id": "b", "text": "360 degrees per minute.", "correct": true}, {"id": "c", "text": "90 degrees per minute.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rate of turn information from a turn coordinator (compared to a Turn and Slip) is', '[{"id": "a", "text": "less accurate.", "correct": false}, {"id": "b", "text": "more accurate.", "correct": true}, {"id": "c", "text": "more instantaneous.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Temperature correction in a sensitive altimeter mechanism is provided by a', '[{"id": "a", "text": "U-spring acting on the capsule.", "correct": false}, {"id": "b", "text": "bi-metal U-spring acting on the capsule.", "correct": true}, {"id": "c", "text": "balance weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The capsule in a vertical speed indicator will be expanded when the aircraft is', '[{"id": "a", "text": "in level flight.", "correct": false}, {"id": "b", "text": "climbing.", "correct": false}, {"id": "c", "text": "descending.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After replacing an instrument of the pitot-static group, it is necessary to', '[{"id": "a", "text": "blow through the lines with a clean low pressure air supply.", "correct": false}, {"id": "b", "text": "carry out a leak test on the appropriate system(s).", "correct": true}, {"id": "c", "text": "calibrate the instrument concerned.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the pitot and static pipe lines were cross connected at the instrument panel connection, application of pressure to the pitot head would cause the', '[{"id": "a", "text": "altimeter reading to decrease, vertical speed indicator to indicate descent.", "correct": true}, {"id": "b", "text": "altimeter reading to decrease, vertical speed indicator to indicate climb.", "correct": false}, {"id": "c", "text": "altimeter reading to increase, vertical speed indicator to indicate descent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A constant force applied to the inner gimbal of a vertical gyro would cause', '[{"id": "a", "text": "a pitch error and gyro topple.", "correct": false}, {"id": "b", "text": "a continual precession in roll.", "correct": true}, {"id": "c", "text": "a roll error and gyro topple.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A rate of turn indicator dial marked ''2 minutes'' refers to a', '[{"id": "a", "text": "rate 2 turn.", "correct": false}, {"id": "b", "text": "rate 1 turn.", "correct": true}, {"id": "c", "text": "rate 3 turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pitot or static leak check is carried out', '[{"id": "a", "text": "whenever the pitot or static systems are disturbed.", "correct": true}, {"id": "b", "text": "only when an instrument is changed.", "correct": false}, {"id": "c", "text": "only when a leak is suspected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The temperature of boiling water at standard pressure on the Fahrenheit and Centigrade scale is', '[{"id": "a", "text": "212 deg. and 100 deg. respectively.", "correct": true}, {"id": "b", "text": "180 deg. and 100 deg. respectively.", "correct": false}, {"id": "c", "text": "100 deg. and 32 deg. respectively.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A temperature of 59°F is equivalent to', '[{"id": "a", "text": "32°C.", "correct": false}, {"id": "b", "text": "15°C.", "correct": true}, {"id": "c", "text": "14.69°C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aircraft heading (HDG) is', '[{"id": "a", "text": "the angle between True North and the longitudinal axis of the aircraft.", "correct": true}, {"id": "b", "text": "the angle between True North and the actual track.", "correct": false}, {"id": "c", "text": "the angle between True North and the desired track.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wind angle is the direction of the wind measured', '[{"id": "a", "text": "in degrees from the aircraft''s heading.", "correct": false}, {"id": "b", "text": "in degrees from the desired track.", "correct": false}, {"id": "c", "text": "in degrees from True North.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Limit stops are fitted in an artificial horizon to', '[{"id": "a", "text": "reduce gimbal nutation.", "correct": false}, {"id": "b", "text": "prevent gimbal lock.", "correct": true}, {"id": "c", "text": "limit the outer gimbal movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The electrical output from a remote gyro to an attitude director indicator is', '[{"id": "a", "text": "by a control synchro.", "correct": true}, {"id": "b", "text": "by a differential synchro.", "correct": false}, {"id": "c", "text": "by a torque synchro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Agonic lines link places of', '[{"id": "a", "text": "equal variation.", "correct": false}, {"id": "b", "text": "different variation.", "correct": false}, {"id": "c", "text": "zero variation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Position error is caused by', '[{"id": "a", "text": "pitot head position.", "correct": true}, {"id": "b", "text": "instrument location in the instrument panel.", "correct": false}, {"id": "c", "text": "mechanical imperfections in an instrument.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To convert degrees Centigrade to degrees Kelvin', '[{"id": "a", "text": "add 273 degrees.", "correct": true}, {"id": "b", "text": "add 112 degrees.", "correct": false}, {"id": "c", "text": "use the formula (deg C x 9/5) + 32.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Damping on a RATE GYRO can be either', '[{"id": "a", "text": "eddy current, variable spring or moving iron.", "correct": false}, {"id": "b", "text": "viscous, eddy current or air dash pot.", "correct": true}, {"id": "c", "text": "viscous, eddy current or variable spring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Electrical driven gyros are', '[{"id": "a", "text": "rotated faster than air driven gyros.", "correct": true}, {"id": "b", "text": "rotated at the same speed as air driven gyros.", "correct": false}, {"id": "c", "text": "rotated slower than air driven gyros.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a ratiometer temperature indicating circuit, there is a break in the circuit to the bulb. This will give', '[{"id": "a", "text": "full scale deflection.", "correct": true}, {"id": "b", "text": "no scale deflection.", "correct": false}, {"id": "c", "text": "mid scale deflection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With the gyro at normal running speed, a torque applied to the inner gimbal ring of a vertical gyro will cause the', '[{"id": "a", "text": "inner ring to move.", "correct": false}, {"id": "b", "text": "outer ring to move.", "correct": true}, {"id": "c", "text": "outer and inner ring to move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft is descending, the pressure in the altimeter case', '[{"id": "a", "text": "will cause the aneroid capsule to contract.", "correct": true}, {"id": "b", "text": "will cause the aneroid capsule to expand.", "correct": false}, {"id": "c", "text": "will not affect the aneroid capsule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The supply of Desynn indicating system', '[{"id": "a", "text": "is alternating current at 400 c/s.", "correct": false}, {"id": "b", "text": "is alternating current at 50 c/s.", "correct": false}, {"id": "c", "text": "is direct current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A sensitive altimeter reading 100 ft. when the millibar scale is set to the atmospheric pressure at airfield level (QFE)', '[{"id": "a", "text": "indicates that the instrument is unserviceable.", "correct": true}, {"id": "b", "text": "indicates that the aircraft is in a region of high pressure and the reading must be corrected to I.S.A.", "correct": false}, {"id": "c", "text": "standards.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After using a pitot-static test set the pressure in the aircraft static system should be released to the atmosphere by', '[{"id": "a", "text": "venting the static system via an internal bleed in the test set.", "correct": true}, {"id": "b", "text": "removing the static connector from its static vent.", "correct": false}, {"id": "c", "text": "removing the static connector from its static vent after waiting for a period of three minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An altimeter is operated', '[{"id": "a", "text": "by the vacuum system.", "correct": false}, {"id": "b", "text": "by the static system.", "correct": true}, {"id": "c", "text": "by the pitot system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of the bimetallic strip in the altimeter?', '[{"id": "a", "text": "Corrects for capsule elasticity.", "correct": true}, {"id": "b", "text": "Compensates for non-linear tension in the hairspring.", "correct": false}, {"id": "c", "text": "Compensates for change in density.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which axis does the directional gyro spin on?', '[{"id": "a", "text": "Vertical", "correct": false}, {"id": "b", "text": "Horizontal", "correct": true}, {"id": "c", "text": "Both vertical and horizontal", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The capsule in an altimeter responds to', '[{"id": "a", "text": "differential pressure.", "correct": false}, {"id": "b", "text": "gauge pressure.", "correct": false}, {"id": "c", "text": "absolute pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aeroplane monitor on the artificial horizon is fitted to the', '[{"id": "a", "text": "inner gimbal.", "correct": false}, {"id": "b", "text": "rotor.", "correct": false}, {"id": "c", "text": "instrument case.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'True airspeed in an Air Data Computer is a function of', '[{"id": "a", "text": "airspeed and temperature.", "correct": false}, {"id": "b", "text": "airspeed and altitude.", "correct": false}, {"id": "c", "text": "mach number and temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The advantage of an instantaneous V.S.I. over a conventional one is', '[{"id": "a", "text": "it does not require pitot/static pressure.", "correct": false}, {"id": "b", "text": "it has an accelerometer which prevents the lag of a conventional one.", "correct": true}, {"id": "c", "text": "it does not require warming up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For a particular I.A.S. as the density decreases with altitude, the T.A.S.', '[{"id": "a", "text": "remains the same.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The type of gyro used in a gyro compass is a', '[{"id": "a", "text": "directional gyro.", "correct": true}, {"id": "b", "text": "rate gyro.", "correct": false}, {"id": "c", "text": "vertical gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A desiccant used in the storage of instruments', '[{"id": "a", "text": "is sodium-bicarbonate.", "correct": false}, {"id": "b", "text": "is silica-gel.", "correct": true}, {"id": "c", "text": "is anti-freeze oil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Bourdon Tubes have', '[{"id": "a", "text": "toroidal cross section.", "correct": false}, {"id": "b", "text": "circular cross section.", "correct": false}, {"id": "c", "text": "oval cross section.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a Bourdon tube', '[{"id": "a", "text": "one end is sealed and the other end open to atmosphere.", "correct": false}, {"id": "b", "text": "both ends sealed.", "correct": false}, {"id": "c", "text": "one end is sealed and the other end open to the pressure source.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure gauge calibrators (Dead Weight Testers) use the', '[{"id": "a", "text": "Boyle''s Law.", "correct": false}, {"id": "b", "text": "Brahm''s press principle.", "correct": true}, {"id": "c", "text": "Charle''s Law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fluid suitable for use in a Dead Weight Tester is', '[{"id": "a", "text": "anti-freeze oil.", "correct": false}, {"id": "b", "text": "kerosene.", "correct": false}, {"id": "c", "text": "castor-oil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The distance readout on an HSI is', '[{"id": "a", "text": "dialled in by the pilot.", "correct": false}, {"id": "b", "text": "from the aircraft ATC system.", "correct": false}, {"id": "c", "text": "from the aircraft DME system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A gyroscope having one plane of freedom at right angles to the plane of rotation, and its gimbal restrained either electrically or by a spring, is known as', '[{"id": "a", "text": "a rate gyro.", "correct": true}, {"id": "b", "text": "a tied gyro.", "correct": false}, {"id": "c", "text": "an earth gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure may be expressed in', '[{"id": "a", "text": "force per unit area.", "correct": true}, {"id": "b", "text": "force per unit volume.", "correct": false}, {"id": "c", "text": "weight or mass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of the hair spring in a Bourdon tube pressure gauge?', '[{"id": "a", "text": "To reduce ''backlash''.", "correct": true}, {"id": "b", "text": "To act a controlling force.", "correct": false}, {"id": "c", "text": "To return the pointer to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ADIs attitude information is normally obtained from the aircraft''s', '[{"id": "a", "text": "attitude rate gyros.", "correct": false}, {"id": "b", "text": "directional gyros.", "correct": false}, {"id": "c", "text": "vertical gyros.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One dot VOR deviation represents', '[{"id": "a", "text": "5°.", "correct": true}, {"id": "b", "text": "1¼°.", "correct": false}, {"id": "c", "text": "2 miles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An instrument used for measuring negative pressures', '[{"id": "a", "text": "has the Bourdon tube reversed within the case.", "correct": false}, {"id": "b", "text": "cannot be of the Bourdon tube type.", "correct": false}, {"id": "c", "text": "has anti-clockwise pointer movement if Bourdon tube operated.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An absolute pressure gauge measures', '[{"id": "a", "text": "the applied pressure referred to atmospheric pressure.", "correct": false}, {"id": "b", "text": "pressures extremely accurately.", "correct": false}, {"id": "c", "text": "the applied pressure referred to a perfect vacuum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Gauge pressure as indicated on a direct reading Bourdon Tube pressure gauge is equal to', '[{"id": "a", "text": "absolute pressure plus atmospheric pressure.", "correct": false}, {"id": "b", "text": "absolute pressure minus atmospheric pressure.", "correct": true}, {"id": "c", "text": "atmospheric pressure minus absolute pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The to/from indicator on an HSI informs the pilot of which direction he is tracking relative to', '[{"id": "a", "text": "an ILS station.", "correct": false}, {"id": "b", "text": "a VOR station.", "correct": true}, {"id": "c", "text": "an ADF station.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pressure gauge, such as a hydraulic brake pressure gauge, indicates 1,000 p.s.i. In terms of absolute pressure, this represents', '[{"id": "a", "text": "1,014.7 p.s.i.", "correct": true}, {"id": "b", "text": "1,000 p.s.i.", "correct": false}, {"id": "c", "text": "985.3 p.s.i.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To fill a Dead Weight Tester', '[{"id": "a", "text": "screw in hand wheel and fill reservoir.", "correct": true}, {"id": "b", "text": "remove platform and fill cylinder.", "correct": false}, {"id": "c", "text": "screw out hand wheel and fill reservoir.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With an aircraft on the ground and QNH set on the millibar scale of the altimeter, the altimeter will read', '[{"id": "a", "text": "the airfield height.", "correct": true}, {"id": "b", "text": "off scale.", "correct": false}, {"id": "c", "text": "zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking a sensitive altimeter on a pre-flight inspection', '[{"id": "a", "text": "the ambient air pressure is set on the millibar scale.", "correct": true}, {"id": "b", "text": "the standard sea level barometric pressure is always set on the millibar scale.", "correct": false}, {"id": "c", "text": "the ambient air pressure corrected for temperature is set on the millibar scale", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The HSI compass card is positioned by the', '[{"id": "a", "text": "compass system.", "correct": true}, {"id": "b", "text": "heading select knob.", "correct": false}, {"id": "c", "text": "aircraft ADF system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The applied pressure to an A.S.I. varies with the', '[{"id": "a", "text": "cube root of the speed.", "correct": false}, {"id": "b", "text": "square root of the speed.", "correct": false}, {"id": "c", "text": "square of the speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The supply to an A.S.I.', '[{"id": "a", "text": "is static pressure only.", "correct": false}, {"id": "b", "text": "is pitot pressure only.", "correct": false}, {"id": "c", "text": "are pitot and static pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The capsule for an A.S.I. will be expanding when the aircraft is', '[{"id": "a", "text": "climbing.", "correct": false}, {"id": "b", "text": "accelerating.", "correct": true}, {"id": "c", "text": "decelerating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The deflection of the ADI command bars when flying a localiser approach is proportional to', '[{"id": "a", "text": "the difference between the amplitudes on the two modulations.", "correct": true}, {"id": "b", "text": "the difference in amplitude of the two r.f. carriers.", "correct": false}, {"id": "c", "text": "the sum of the amplitude of the two modulations.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is flying straight and level in still air, airspeed will be', '[{"id": "a", "text": "equal to the ground speed.", "correct": true}, {"id": "b", "text": "greater than the ground speed.", "correct": false}, {"id": "c", "text": "less than the ground speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft flying in still air at 400 knots, encounters a head wind of 50 knots, its ground speed is', '[{"id": "a", "text": "450 knots.", "correct": false}, {"id": "b", "text": "350 knots.", "correct": true}, {"id": "c", "text": "400 knots.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To provide a linear scale on an A.S.I., a', '[{"id": "a", "text": "ranging bar and screws are fitted.", "correct": true}, {"id": "b", "text": "bi-metal corrector is employed.", "correct": false}, {"id": "c", "text": "10 to 1 gearing is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A machmeter is an instrument which indicates the speed of', '[{"id": "a", "text": "sound relative to the aircraft''s altitude.", "correct": false}, {"id": "b", "text": "the aircraft relative to the local sonic speed.", "correct": true}, {"id": "c", "text": "the aircraft relative to the speed of sound at ground level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The moving element of a ratiometer has', '[{"id": "a", "text": "one coil.", "correct": false}, {"id": "b", "text": "three coils.", "correct": false}, {"id": "c", "text": "two coils.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When carrying out a pressure leak test on an altimeter, you are checking for leaks in the', '[{"id": "a", "text": "instrument case.", "correct": true}, {"id": "b", "text": "pressure chamber.", "correct": false}, {"id": "c", "text": "capsule stack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an altimeter millibar scale was set to 1013.25 and the barometric pressure at that time was 1020, the altimeter should read', '[{"id": "a", "text": "positive altitude.", "correct": false}, {"id": "b", "text": "below zero feet (negative altitude).", "correct": true}, {"id": "c", "text": "zero feet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft flying towards a VOR station shows indications of 120° and ''TO''. After passing over the station, on the same course, the indications will be', '[{"id": "a", "text": "300° and TO.", "correct": false}, {"id": "b", "text": "120° and FROM.", "correct": true}, {"id": "c", "text": "300° and FROM.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The command bars in a flight director system indicate', '[{"id": "a", "text": "the required path with respect to actual path.", "correct": true}, {"id": "b", "text": "true horizon.", "correct": false}, {"id": "c", "text": "the actual path with respect to required path.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When changing a windscreen panel which has a standby magnetic compass located in the vicinity', '[{"id": "a", "text": "The attachment bolts should be tightened in an anti-clockwise direction around the window.", "correct": false}, {"id": "b", "text": "precautions should be taken that the bonding tag is attached to the correct attachment bolt.", "correct": false}, {"id": "c", "text": "precautions must be taken to ensure that the attachment bolts are of the specified type.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a conventional RMI the angle between the compass datum and the radio pointer arrow is', '[{"id": "a", "text": "the magnetic bearing.", "correct": false}, {"id": "b", "text": "the complimentary bearing.", "correct": false}, {"id": "c", "text": "the relative bearing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A compass is made aperiodic by', '[{"id": "a", "text": "using fluid.", "correct": true}, {"id": "b", "text": "tying it to the case.", "correct": false}, {"id": "c", "text": "locking.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Isogonal lines link places of', '[{"id": "a", "text": "different variation.", "correct": false}, {"id": "b", "text": "equal variation.", "correct": true}, {"id": "c", "text": "zero variation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an artificial horizon Pendulosity Error is caused by', '[{"id": "a", "text": "displacement of erection control device.", "correct": false}, {"id": "b", "text": "bottom lightness of inner gimbals.", "correct": false}, {"id": "c", "text": "bottom heaviness of inner gimbals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If True Airspeed is 470 knots, what is the Equivalent Air speed?', '[{"id": "a", "text": "662 knots", "correct": false}, {"id": "b", "text": "550 knots", "correct": false}, {"id": "c", "text": "278 knots", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the Airspeed Indicator reading is 300 Knots, what is the Calibrated Airspeed?', '[{"id": "a", "text": "293 knots", "correct": false}, {"id": "b", "text": "296 knots", "correct": false}, {"id": "c", "text": "304 knots", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an Artificial Horizon, Erection Error is caused by', '[{"id": "a", "text": "displacement of erection control device.", "correct": true}, {"id": "b", "text": "bottom lightness of inner gimbals.", "correct": false}, {"id": "c", "text": "bottom heaviness of inner gimbals.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Vertical Speed indicator Metering Unit Consist of', '[{"id": "a", "text": "an orifice.", "correct": false}, {"id": "b", "text": "both an orifice and a capillary.", "correct": true}, {"id": "c", "text": "a capillary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flux Valve senses angle of horizontal component with respect to the aircraft''s', '[{"id": "a", "text": "both lateral and longitudinal axis.", "correct": false}, {"id": "b", "text": "lateral axis.", "correct": false}, {"id": "c", "text": "longitudinal axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The manual VOR input is for', '[{"id": "a", "text": "the radio magnetic indicator.", "correct": false}, {"id": "b", "text": "the course deviation bar.", "correct": true}, {"id": "c", "text": "the ADI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After correction of the north-south heading reading on a compass swing, the resultant correction is known as', '[{"id": "a", "text": "correct heading.", "correct": false}, {"id": "b", "text": "residual deviation.", "correct": true}, {"id": "c", "text": "magnetic heading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Apparent drift on directional gyro is corrected by', '[{"id": "a", "text": "mercury switch on outer ring.", "correct": false}, {"id": "b", "text": "series of balance holes drilled in gyro rotor.", "correct": false}, {"id": "c", "text": "an adjustment nut on inner ring.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a micro adjuster is replaced in a compass system, you would', '[{"id": "a", "text": "carry out a new compass swing.", "correct": true}, {"id": "b", "text": "set it up the same as the one removed.", "correct": false}, {"id": "c", "text": "set it to zero datum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a compass swing: North error -2 degrees, South error + 2 degrees. The coefficient C is', '[{"id": "a", "text": "-2 degrees.", "correct": true}, {"id": "b", "text": "0 degrees.", "correct": false}, {"id": "c", "text": "+2 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Purpose of Altitude Alerting is to warn the pilot of', '[{"id": "a", "text": "approach to or deviation from selected altitude.", "correct": true}, {"id": "b", "text": "altitude information.", "correct": false}, {"id": "c", "text": "selection of altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aircraft certified before 1997 with RVSM, maximum tolerance for the system is', '[{"id": "a", "text": "+/- 500ft system tolerance.", "correct": false}, {"id": "b", "text": "+/- 200ft system, +/-50ft for instrument error.", "correct": false}, {"id": "c", "text": "+/- 300ft system, +/-50ft for instrument error.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Machmeters work on', '[{"id": "a", "text": "static.", "correct": false}, {"id": "b", "text": "pitot and static.", "correct": true}, {"id": "c", "text": "pitot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft with Mach warning will warn', '[{"id": "a", "text": "when M(base=crit) is reached.", "correct": true}, {"id": "b", "text": "when Mach 1 is exceeded.", "correct": false}, {"id": "c", "text": "when envelope limit is reached.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An HSI provides what information?', '[{"id": "a", "text": "VOR, plan, ILS, map, radar.", "correct": true}, {"id": "b", "text": "VOR, map, attitude, ILS.", "correct": false}, {"id": "c", "text": "VOR, ILS, plan, attitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Compressibility error in a pitot head is caused by', '[{"id": "a", "text": "misalignment of pitot head.", "correct": false}, {"id": "b", "text": "compression of air in the tube at high speed.", "correct": true}, {"id": "c", "text": "blockage in the pitot tube.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The earth''s magnetic field is', '[{"id": "a", "text": "horizontal across the earth.", "correct": false}, {"id": "b", "text": "vertical at the poles, horizontal at the magnetic equator.", "correct": true}, {"id": "c", "text": "vertical across the earth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The magnets in a compass corrector micro-adjuster are', '[{"id": "a", "text": "adjusted for coefficient A.", "correct": false}, {"id": "b", "text": "always set to the neutral position.", "correct": false}, {"id": "c", "text": "adjusted to obtain the neutral position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'There is an air bubble in the compass:', '[{"id": "a", "text": "The fluid is not aerated properly.", "correct": false}, {"id": "b", "text": "It is due to high altitude.", "correct": true}, {"id": "c", "text": "It is required, to compensate for expansion of the fluid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flux detector output is a', '[{"id": "a", "text": "A.C. voltage at the same frequency as the excitation voltage.", "correct": false}, {"id": "b", "text": "rectified D.C. voltage.", "correct": false}, {"id": "c", "text": "A.C. voltage at twice the frequency of the excitation voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The general function of the ATC is to', '[{"id": "a", "text": "interrogate other aircraft which reply with an identification signal.", "correct": false}, {"id": "b", "text": "interrogate the ground station which replies with an identification.", "correct": false}, {"id": "c", "text": "reply with an identification signal after being interrogated by a ground station.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ACARS is primarily used for communicating with', '[{"id": "a", "text": "maintenance base.", "correct": true}, {"id": "b", "text": "other aircraft.", "correct": false}, {"id": "c", "text": "air traffic control.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'SELCAL is used to', '[{"id": "a", "text": "alert ground stations.", "correct": false}, {"id": "b", "text": "alert other aircraft.", "correct": false}, {"id": "c", "text": "monitor ground signals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'HF communication frequency is in the range', '[{"id": "a", "text": "23 - 30 kHz.", "correct": false}, {"id": "b", "text": "3-30 MHz.", "correct": true}, {"id": "c", "text": "108 - 118 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The polythene sleeving over a HF antenna is to stop', '[{"id": "a", "text": "lightning strike.", "correct": false}, {"id": "b", "text": "precipitation static.", "correct": false}, {"id": "c", "text": "moisture ingress and corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The term HIRF means', '[{"id": "a", "text": "High Interference Radiated Fields.", "correct": false}, {"id": "b", "text": "High Intensity Radiated Fields.", "correct": true}, {"id": "c", "text": "High Intensity Radio Fields.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an autopilot is Fail Passive,', '[{"id": "a", "text": "the aircraft reverts to fail operational autopilot.", "correct": false}, {"id": "b", "text": "the pilot must resume control and land the aircraft.", "correct": true}, {"id": "c", "text": "the autoland can continue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fundamental theory of operation of a ranging radar is', '[{"id": "a", "text": "frequency of returns.", "correct": false}, {"id": "b", "text": "percentage of emitted signal returned.", "correct": false}, {"id": "c", "text": "time taken to receive returns.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft communication system, HIRF interference is most prominent', '[{"id": "a", "text": "during transmissions only.", "correct": false}, {"id": "b", "text": "at specific frequencies.", "correct": true}, {"id": "c", "text": "across the whole frequency spectrum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What clock is used in a GPS satellite?', '[{"id": "a", "text": "Clock with battery", "correct": false}, {"id": "b", "text": "Atomic", "correct": true}, {"id": "c", "text": "Quartz", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With Control Wheel Steering (CWS), if the flight path is disturbed by the pilot, the course will be corrected by the', '[{"id": "a", "text": "autopilot panel.", "correct": false}, {"id": "b", "text": "flight director input.", "correct": false}, {"id": "c", "text": "normal flight control.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An HF coupling is used to match the', '[{"id": "a", "text": "receiver.", "correct": false}, {"id": "b", "text": "boom-set (headphones and mic).", "correct": false}, {"id": "c", "text": "aerial.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft''s navigation display, distance measuring equipment gives', '[{"id": "a", "text": "slant range to beacon.", "correct": true}, {"id": "b", "text": "height and range to beacon.", "correct": false}, {"id": "c", "text": "ground range to beacon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a modern aircraft flight instrument display system, radio deviation is shown on the', '[{"id": "a", "text": "EHSI.", "correct": false}, {"id": "b", "text": "EADI.", "correct": false}, {"id": "c", "text": "EHSI & EADI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a flight management system, the database is updated every', '[{"id": "a", "text": "1 Month.", "correct": true}, {"id": "b", "text": "2 Months.", "correct": false}, {"id": "c", "text": "3 Months.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a GPS system what type of clock is in the receiver?', '[{"id": "a", "text": "Atomic", "correct": false}, {"id": "b", "text": "Quartz", "correct": true}, {"id": "c", "text": "Battery", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of the autopilot?', '[{"id": "a", "text": "To relieve the flight crew of their duties during long haul flights.", "correct": false}, {"id": "b", "text": "To reduce the flight crew''s workload.", "correct": true}, {"id": "c", "text": "To enable the aircraft to land in bad weather.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On the ATC radio readability scale, what is satisfactory reception?', '[{"id": "a", "text": "1", "correct": false}, {"id": "b", "text": "3", "correct": false}, {"id": "c", "text": "5", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An ADF system includes', '[{"id": "a", "text": "a sense antenna.", "correct": false}, {"id": "b", "text": "both a sense and loop antenna.", "correct": true}, {"id": "c", "text": "a loop antenna.", "correct": false}]'::jsonb, '{B1,B2}'),
