    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is ILS marker beacon frequency?', '[{"id": "a", "text": "50 MHz", "correct": false}, {"id": "b", "text": "75 MHz", "correct": true}, {"id": "c", "text": "100 MHz", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'TCAS is selected', '[{"id": "a", "text": "by a switch, by pilot on selector panel.", "correct": true}, {"id": "b", "text": "automatically.", "correct": false}, {"id": "c", "text": "not available in cruise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The manual VOR input is for', '[{"id": "a", "text": "course deviation bar.", "correct": true}, {"id": "b", "text": "glideslope.", "correct": false}, {"id": "c", "text": "RMI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The mach trim is initiated by', '[{"id": "a", "text": "the autopilot motor.", "correct": true}, {"id": "b", "text": "a PCU.", "correct": false}, {"id": "c", "text": "an electric motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the colour of the middle marker beacon?', '[{"id": "a", "text": "White", "correct": false}, {"id": "b", "text": "Blue", "correct": false}, {"id": "c", "text": "Amber", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A GPS system is formed from', '[{"id": "a", "text": "satellites, processing unit, display unit.", "correct": false}, {"id": "b", "text": "receiver, processing unit, interactive console.", "correct": false}, {"id": "c", "text": "space, control, user.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For aircraft with dual CMCs, when only one CMC is available, it', '[{"id": "a", "text": "must be connected to the right side.", "correct": false}, {"id": "b", "text": "can be connected to either side.", "correct": false}, {"id": "c", "text": "must be connected to the left side.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Laser gyros are', '[{"id": "a", "text": "aligned to the aircraft structure.", "correct": true}, {"id": "b", "text": "aligned to the true north.", "correct": false}, {"id": "c", "text": "aligned to the magnetic north.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Laser gyros', '[{"id": "a", "text": "have rotational parts.", "correct": false}, {"id": "b", "text": "do not have rotational parts.", "correct": true}, {"id": "c", "text": "have no movable parts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radio coupled approach is', '[{"id": "a", "text": "localiser first, followed by glideslope.", "correct": true}, {"id": "b", "text": "glideslope first, followed by localiser.", "correct": false}, {"id": "c", "text": "in any order.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aileron signal is fed to the rudder channel', '[{"id": "a", "text": "for turn command back-up.", "correct": false}, {"id": "b", "text": "for turn coordination.", "correct": true}, {"id": "c", "text": "for yaw damping compensation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rate of G/S warning in GPWS', '[{"id": "a", "text": "changes with radio altitude.", "correct": true}, {"id": "b", "text": "does not change.", "correct": false}, {"id": "c", "text": "changes with barometric altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What frequency are VOR and ILS?', '[{"id": "a", "text": "VHF", "correct": true}, {"id": "b", "text": "HF", "correct": false}, {"id": "c", "text": "UHF", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radio frequency of 16 MHz would be used for', '[{"id": "a", "text": "marker beacons.", "correct": false}, {"id": "b", "text": "HF communications.", "correct": true}, {"id": "c", "text": "weather radar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft lands in autoland. After touch down and thrust reversers are deployed. What happens to autothrottle?', '[{"id": "a", "text": "Advances throttles.", "correct": false}, {"id": "b", "text": "Stays armed for go around in an emergency.", "correct": false}, {"id": "c", "text": "Automatically switches off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pilot''s instinctive cut-out buttons are positioned', '[{"id": "a", "text": "on right side of control wheel.", "correct": false}, {"id": "b", "text": "on left side of control wheel.", "correct": false}, {"id": "c", "text": "on side of control wheel furthest from throttles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ILS and VOR operate in which range', '[{"id": "a", "text": "UHF.", "correct": false}, {"id": "b", "text": "VHF.", "correct": true}, {"id": "c", "text": "HF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'FMC secondary flight-plan is selected', '[{"id": "a", "text": "in the air by the pilot.", "correct": true}, {"id": "b", "text": "by calendar date monthly.", "correct": false}, {"id": "c", "text": "on the ground by the pilot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'GPWS operating in mode 1 and 2 when close to ground will give', '[{"id": "a", "text": "amber warning.", "correct": false}, {"id": "b", "text": "red caption and aural ''whoop whoop pull up''.", "correct": true}, {"id": "c", "text": "red caption and aural ''pull up, undercarriage, flaps, throttle''.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The components of an ILS are', '[{"id": "a", "text": "a localizer and a glide slope.", "correct": false}, {"id": "b", "text": "a localizer, a glide slope and the marker beacons.", "correct": true}, {"id": "c", "text": "a localizer and the marker beacons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In ILS, the glideslope provides', '[{"id": "a", "text": "distance checks.", "correct": false}, {"id": "b", "text": "lateral steering.", "correct": false}, {"id": "c", "text": "vertical steering.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the 90 Hz tone modulation in a localizer receiver predominates, the deviation indicator will show', '[{"id": "a", "text": "fly right.", "correct": true}, {"id": "b", "text": "the flag.", "correct": false}, {"id": "c", "text": "fly left.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Autopilot will operate above what altitude?', '[{"id": "a", "text": "750 ft.", "correct": false}, {"id": "b", "text": "1000 ft.", "correct": false}, {"id": "c", "text": "500 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radio coupled autopilot in pitch uses', '[{"id": "a", "text": "ADF.", "correct": false}, {"id": "b", "text": "VOR.", "correct": false}, {"id": "c", "text": "glideslope.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'EPR and thrust modes in autothrottle are the only modes that can be selected in', '[{"id": "a", "text": "approach.", "correct": false}, {"id": "b", "text": "cruise.", "correct": false}, {"id": "c", "text": "take off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An inertial navigation unit uses pin programming for', '[{"id": "a", "text": "aircraft type.", "correct": false}, {"id": "b", "text": "location.", "correct": true}, {"id": "c", "text": "magnetic orientation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How can it be verified if FMC update is correct?', '[{"id": "a", "text": "FMC via CDU.", "correct": true}, {"id": "b", "text": "BITE.", "correct": false}, {"id": "c", "text": "Dataplate on the FMC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'GPWS will show a fault if the following fails:', '[{"id": "a", "text": "Pressure altimeter.", "correct": false}, {"id": "b", "text": "Radio altimeter.", "correct": true}, {"id": "c", "text": "Air speed indicator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'INS has mercury switches on', '[{"id": "a", "text": "outer gimbal.", "correct": false}, {"id": "b", "text": "inner gimbal.", "correct": false}, {"id": "c", "text": "all gimbals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the runway picture in the EADI moves down during an ILS approach, the aircraft must fly', '[{"id": "a", "text": "up.", "correct": false}, {"id": "b", "text": "nowhere - this is normal on an ILS approach.", "correct": false}, {"id": "c", "text": "down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What modulation is used for the beams of a localiser in an ILS?', '[{"id": "a", "text": "150 Hz left of runway centerline, 90 Hz right of runway centreline.", "correct": false}, {"id": "b", "text": "90 Hz below the glide path, 150 Hz above the glide path.", "correct": false}, {"id": "c", "text": "150 Hz right of runway centerline, 90 Hz left of runway centreline.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In what frequency range does the automatic direction finding (ADF) system operate?', '[{"id": "a", "text": "1025 - 1150 KHz.", "correct": false}, {"id": "b", "text": "190 - 1759 KHz.", "correct": true}, {"id": "c", "text": "108.00 - 117.95 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How does an aircraft distinguish its own Distance Measuring Equipment reply from those for other aircraft?', '[{"id": "a", "text": "By modulation of an audio tone.", "correct": false}, {"id": "b", "text": "By using an alternate frequency.", "correct": false}, {"id": "c", "text": "By changing at random the time delay between the pulse pairs of the interrogation signal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'From where is bearing information received for display on the digital-distance radio-magnetic indicator (DDRMI)?', '[{"id": "a", "text": "From VOR and ADF systems.", "correct": true}, {"id": "b", "text": "From ADF only.", "correct": false}, {"id": "c", "text": "From VOR only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Why is an aerial tuning unit used in a high frequency (HF) communication system?', '[{"id": "a", "text": "To extend or retract the aerial and so vary its physical length.", "correct": false}, {"id": "b", "text": "To electrically lengthen or shorten the aerial for optimum matching of impedance.", "correct": true}, {"id": "c", "text": "To select the transmission/reception frequency in the HF band.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What would be the purpose of an input from an inertial reference system being connected to a weather radar?', '[{"id": "a", "text": "To provide stabilisation for the radar antenna.", "correct": true}, {"id": "b", "text": "To ensure that there is no radar transmission with aircraft on ground.", "correct": false}, {"id": "c", "text": "To place the weather radar target in azimuth and distance for the display.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which systems provide envelope modulation information for a Ground Proximity Warning System (GPWS)', '[{"id": "a", "text": "Autothrottle.", "correct": false}, {"id": "b", "text": "Rudder/ailerons.", "correct": false}, {"id": "c", "text": "Flaps/undercarriage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The FMS navigation database is updated', '[{"id": "a", "text": "daily.", "correct": false}, {"id": "b", "text": "every 28 days.", "correct": true}, {"id": "c", "text": "after a B or C check has been completed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an IRS system you would expect to find', '[{"id": "a", "text": "an azimuth gyro system.", "correct": false}, {"id": "b", "text": "three strap down accelerometers.", "correct": false}, {"id": "c", "text": "ring laser gyros.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an INS system the accelerometer is a mass', '[{"id": "a", "text": "suspended between two springs in a tube.", "correct": true}, {"id": "b", "text": "a mass suspended in free air.", "correct": false}, {"id": "c", "text": "a remotely mounted mass on the airframe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a modern aircraft the ACARS system is used primarily for', '[{"id": "a", "text": "reporting defects on the aircraft automatically.", "correct": false}, {"id": "b", "text": "communications between the aircraft and base.", "correct": true}, {"id": "c", "text": "as part of the passenger telephone system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the main areas of the autopilot?', '[{"id": "a", "text": "Error, correction, follow up, demand.", "correct": false}, {"id": "b", "text": "Error, correction, follow up, command.", "correct": true}, {"id": "c", "text": "Error, correction , demand, resolved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'VHF frequency is', '[{"id": "a", "text": "108 - 118 MHz.", "correct": false}, {"id": "b", "text": "108 - 136 MHz.", "correct": true}, {"id": "c", "text": "108 - 112 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The call system for the captain will have the audio signal of a', '[{"id": "a", "text": "horn.", "correct": false}, {"id": "b", "text": "two tone chrime.", "correct": false}, {"id": "c", "text": "hi tone chime.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Channel 3 on a CVR records', '[{"id": "a", "text": "captain.", "correct": false}, {"id": "b", "text": "first officer.", "correct": false}, {"id": "c", "text": "flightdeck.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'DME works on the frequency of', '[{"id": "a", "text": "UHF.", "correct": true}, {"id": "b", "text": "VHF.", "correct": false}, {"id": "c", "text": "HF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A radial is referenced', '[{"id": "a", "text": "on a compass.", "correct": false}, {"id": "b", "text": "to a VOR.", "correct": false}, {"id": "c", "text": "from a beacon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ADF works by using', '[{"id": "a", "text": "sense aerial.", "correct": false}, {"id": "b", "text": "loop aerial.", "correct": false}, {"id": "c", "text": "both loop and sense aerial.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the next database on the FMC activated?', '[{"id": "a", "text": "Manually, on the ground.", "correct": true}, {"id": "b", "text": "Manually in the air.", "correct": false}, {"id": "c", "text": "Automatically by due date.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What GPWS mode gives a ''Whoop Whoop, Pull-up'' command?', '[{"id": "a", "text": "Mode 3.", "correct": false}, {"id": "b", "text": "Mode 6.", "correct": false}, {"id": "c", "text": "Mode 2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A transponder that is compatible for use with a TCAS system would be', '[{"id": "a", "text": "Mode S.", "correct": true}, {"id": "b", "text": "Mode A.", "correct": false}, {"id": "c", "text": "Mode C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'GPS', '[{"id": "a", "text": "uses 21 satellites equally spaced around 7 orbits.", "correct": false}, {"id": "b", "text": "uses 18 satellites equally spaced around 6 orbits.", "correct": false}, {"id": "c", "text": "uses 24 satellites equally spaced around 6 orbits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Random precession of the inner gimbal ring is detected by placing mercury switches', '[{"id": "a", "text": "on both gimbal rings.", "correct": false}, {"id": "b", "text": "on outer gimbal ring.", "correct": false}, {"id": "c", "text": "on inner gimbal ring.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The IRS laser gyro is a', '[{"id": "a", "text": "displacement gyro.", "correct": false}, {"id": "b", "text": "displaced gyro.", "correct": false}, {"id": "c", "text": "rate gyro.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What manoeuvre does TCAS II advise the pilot to make?', '[{"id": "a", "text": "either RA or TA.", "correct": false}, {"id": "b", "text": "TA.", "correct": false}, {"id": "c", "text": "RA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the shapes of traffic shown on a TCAS display ?', '[{"id": "a", "text": "White diamonds, red squares and amber circles.", "correct": true}, {"id": "b", "text": "White squares, red diamonds and amber circles.", "correct": false}, {"id": "c", "text": "White circles, red diamonds and amber squares.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The laser ring gyro', '[{"id": "a", "text": "does not have a gimbal but does have rotating parts.", "correct": true}, {"id": "b", "text": "has a stabilized platform.", "correct": false}, {"id": "c", "text": "does not have a gimbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), '3 autopilot computers are considered', '[{"id": "a", "text": "Fail Operable.", "correct": true}, {"id": "b", "text": "Fail resistant.", "correct": false}, {"id": "c", "text": "Fail Passive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In autopilot with THS in motion, the', '[{"id": "a", "text": "Auto Trim is inhibited.", "correct": true}, {"id": "b", "text": "elevator is inhibited.", "correct": false}, {"id": "c", "text": "Mach trim is inhibited.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How can a pilot over-ride the auto-throttle?', '[{"id": "a", "text": "By deselecting auto-throttle first.", "correct": false}, {"id": "b", "text": "Manually through a clutch on the throttle levers.", "correct": true}, {"id": "c", "text": "It is not possible.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the autothrottle disconnect switch?', '[{"id": "a", "text": "Within reach of the First Officer", "correct": false}, {"id": "b", "text": "Within reach of the Captain", "correct": false}, {"id": "c", "text": "Within reach of both pilots", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Decca navigation uses', '[{"id": "a", "text": "VHF.", "correct": false}, {"id": "b", "text": "HF.", "correct": false}, {"id": "c", "text": "LF.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'There are two FMS installed on the aircraft. If one FMS fails during flight', '[{"id": "a", "text": "it has no effect, because the second FMS was in the stand-by mode, now it is active.", "correct": false}, {"id": "b", "text": "the failed FMS has a blank screen.", "correct": true}, {"id": "c", "text": "the whole FMS system is unserviceable until the pilot switches over to standby.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following has priority over TCAS warnings?', '[{"id": "a", "text": "Resolution Advisories.", "correct": false}, {"id": "b", "text": "Gear position warning.", "correct": false}, {"id": "c", "text": "Stall warning.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ILS marker beacon operates at a frequency of', '[{"id": "a", "text": "100 MHz.", "correct": false}, {"id": "b", "text": "50 MHz.", "correct": false}, {"id": "c", "text": "75 MHz.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The manual input for the VOR course corrector is related to', '[{"id": "a", "text": "the RMI.", "correct": false}, {"id": "b", "text": "the ILS system.", "correct": false}, {"id": "c", "text": "the CDI offset bar.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flat plate antenna is a', '[{"id": "a", "text": "a Doppler antenna.", "correct": false}, {"id": "b", "text": "a series of slots and wave guides.", "correct": true}, {"id": "c", "text": "parabolic antenna.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To obtain an accurate GPS fix, the GPS receiver must be in line of sight of', '[{"id": "a", "text": "6 satellites.", "correct": false}, {"id": "b", "text": "3 satellites.", "correct": false}, {"id": "c", "text": "4 satellites.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following systems is inhibited when a test is performed of the rad. alt. system?', '[{"id": "a", "text": "altitude alert.", "correct": false}, {"id": "b", "text": "TCAS.", "correct": false}, {"id": "c", "text": "GPWS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The GPS satellite system consists of', '[{"id": "a", "text": "24 satellites and 1 standby satellites.", "correct": false}, {"id": "b", "text": "21 satellites and 3 standby satellites.", "correct": true}, {"id": "c", "text": "20 satellites and 5 standby satellite.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Mode C transponder gives the following info:', '[{"id": "a", "text": "Altitude.", "correct": true}, {"id": "b", "text": "Interrogation.", "correct": false}, {"id": "c", "text": "Altitude and interrogation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The autothrottle system at touchdown will', '[{"id": "a", "text": "apply reverse thrust.", "correct": false}, {"id": "b", "text": "go to idle and disconnect.", "correct": true}, {"id": "c", "text": "go to idle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When will the decision height aural warning sound?', '[{"id": "a", "text": "Before decision height.", "correct": false}, {"id": "b", "text": "After decision height.", "correct": false}, {"id": "c", "text": "At decision height.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'FMCS Pin Programming is allowed', '[{"id": "a", "text": "under CAA Rules.", "correct": false}, {"id": "b", "text": "to compensate for FMC position on the aircraft.", "correct": true}, {"id": "c", "text": "for the database of aircraft landing altitudes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before the aeroplane is moved from the loading pier, the pilot must', '[{"id": "a", "text": "insert the latitude and longitude of the first waypoint into the INS.", "correct": false}, {"id": "b", "text": "insert the latitude and longitude of the pier into the INS.", "correct": true}, {"id": "c", "text": "set the altitude to be fed into the INS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A ''strap-down'' inertial navigation system has', '[{"id": "a", "text": "accelerometers fixed to the airframe and gyros on a stable platform.", "correct": false}, {"id": "b", "text": "accelerometers on a stable platform and gyros fixed to the airframe.", "correct": false}, {"id": "c", "text": "accelerometers and gyros fixed to the airframe.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A force re-balance accelerometer in an IN system has the acceleration force balanced by a', '[{"id": "a", "text": "linear force.", "correct": true}, {"id": "b", "text": "non-linear force.", "correct": false}, {"id": "c", "text": "constant force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An accelerometer in an IN system must be able to detect accelerations down to', '[{"id": "a", "text": "10^-2 g.", "correct": false}, {"id": "b", "text": "10^-3 g.", "correct": false}, {"id": "c", "text": "10^-6 g.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A laser gyro output is', '[{"id": "a", "text": "directly proportional to frequency addition.", "correct": false}, {"id": "b", "text": "directly proportional to angular turning rate.", "correct": true}, {"id": "c", "text": "inversely proportional to angular turning rate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an IN system, Coriolis effect is the result of', '[{"id": "a", "text": "gyro wander.", "correct": false}, {"id": "b", "text": "platform misalignment.", "correct": false}, {"id": "c", "text": "the effect of the earth''s rotation on a stable platform.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Inertial Navigation System computes distance from acceleration by', '[{"id": "a", "text": "two successive integrations.", "correct": true}, {"id": "b", "text": "a differential followed by an integration.", "correct": false}, {"id": "c", "text": "a single integration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Coriolis effect is corrected for by', '[{"id": "a", "text": "re-aligning the stable platform.", "correct": false}, {"id": "b", "text": "adding a correction term to the accelerometer outputs.", "correct": true}, {"id": "c", "text": "torquing the gyros.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an IN system, the output of the accelerometer is linear because of a', '[{"id": "a", "text": "linear spring.", "correct": false}, {"id": "b", "text": "force balance system.", "correct": true}, {"id": "c", "text": "pendulous suspension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The three accelerometers on a stable platform are mounted', '[{"id": "a", "text": "parallel to each other.", "correct": false}, {"id": "b", "text": "120 degrees apart.", "correct": false}, {"id": "c", "text": "orthogonally.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an IN system, the purpose of the stable platform is to', '[{"id": "a", "text": "stop the gyros from toppling.", "correct": false}, {"id": "b", "text": "provide attitude reference.", "correct": false}, {"id": "c", "text": "prevent unwanted acceleration affecting the accelerometers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The type of gyro generally used in an IN system is a', '[{"id": "a", "text": "rate integrating gyro.", "correct": true}, {"id": "b", "text": "rate gyro.", "correct": false}, {"id": "c", "text": "displacement gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Earth rate is approximately', '[{"id": "a", "text": "5 degrees per hour.", "correct": false}, {"id": "b", "text": "84 degrees per hour.", "correct": false}, {"id": "c", "text": "15 degrees per hour.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a gimbal system, the stable platform is the', '[{"id": "a", "text": "azimuth gimbal.", "correct": true}, {"id": "b", "text": "pitch gimbal.", "correct": false}, {"id": "c", "text": "roll gimbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To prevent gimbal lock on the stable platform it is normal to use', '[{"id": "a", "text": "three gimbals.", "correct": false}, {"id": "b", "text": "four gimbals.", "correct": true}, {"id": "c", "text": "a pitch gimbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the inertial platform is torqued to perform like a Schuler pendulum', '[{"id": "a", "text": "the platform rotates with respect to the aircraft.", "correct": false}, {"id": "b", "text": "the platform remains fixed with respect to the local vertical.", "correct": false}, {"id": "c", "text": "the platform oscillates with respect to the local vertical.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Schuler pendulum has a period of oscillation of', '[{"id": "a", "text": "84.4 seconds.", "correct": false}, {"id": "b", "text": "8.4 minutes.", "correct": false}, {"id": "c", "text": "84.4 minutes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An IN system requires data from the', '[{"id": "a", "text": "Doppler system.", "correct": false}, {"id": "b", "text": "airdata computer.", "correct": true}, {"id": "c", "text": "satellites.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When in manual mode, the C.D.U. alert lamp of the IN system will flash', '[{"id": "a", "text": "thirty seconds before a track change is required.", "correct": false}, {"id": "b", "text": "when an error is detected.", "correct": false}, {"id": "c", "text": "two minutes before the next waypoint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'XTK (cross track) is the', '[{"id": "a", "text": "angle in degrees that aircraft track is left or right of desired track.", "correct": false}, {"id": "b", "text": "perpendicular distance from the desired track.", "correct": true}, {"id": "c", "text": "actual track across the earth''s surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The output of an INS can be fed to', '[{"id": "a", "text": "attitude indicators.", "correct": true}, {"id": "b", "text": "altimeters.", "correct": false}, {"id": "c", "text": "vertical speed indicators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The three accelerometers on a strapdown platform are mounted', '[{"id": "a", "text": "90Âº to each other.", "correct": true}, {"id": "b", "text": "parallel to each other.", "correct": false}, {"id": "c", "text": "120Âº apart.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A basic I.N.S. platform has', '[{"id": "a", "text": "3 axis accelerometer.", "correct": false}, {"id": "b", "text": "3 accelerometers and 2 gyros (pitch and roll).", "correct": false}, {"id": "c", "text": "2 accelerometers and 3 gyros.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Using I.N.S. an aircraft flies', '[{"id": "a", "text": "great circle arc.", "correct": true}, {"id": "b", "text": "rhumb line.", "correct": false}, {"id": "c", "text": "course directed by ground station.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What must be entered in to the I.N.S. before the aircraft moves?', '[{"id": "a", "text": "Waypoints.", "correct": false}, {"id": "b", "text": "E.T.A.", "correct": false}, {"id": "c", "text": "Present position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Selection of the INS Mode Selector Unit (MSU) to ATT REF is made', '[{"id": "a", "text": "to feed information to the Captain and 1st Officers ADI displays.", "correct": false}, {"id": "b", "text": "when attitude information is lost.", "correct": false}, {"id": "c", "text": "when navigation information is lost.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For the INS, the Battery Unit provides', '[{"id": "a", "text": "standby power when airborne, switched by weight-off switches in the undercarriage.", "correct": false}, {"id": "b", "text": "both when airborne and on the ground.", "correct": true}, {"id": "c", "text": "standby power only when on the ground, to maintain the alignment phase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Control Display Unit (CDU) selection of TKE displays', '[{"id": "a", "text": "distance perpendicular from the selected track.", "correct": false}, {"id": "b", "text": "difference in degrees that the aircraft track is to the right or left of the desired track.", "correct": true}, {"id": "c", "text": "difference in degrees from True North in a clockwise direction from the desired track.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Earth Rate Compensation for an INU is computed from', '[{"id": "a", "text": "the earth''s rotational rate (15Â°/hour) times the sine of the longitude.", "correct": false}, {"id": "b", "text": "the earth''s rotational rate (15Â°/hour) times the cosine of the latitude.", "correct": true}, {"id": "c", "text": "the earth''s rotational rate (15Â°/hour) times the sine of the latitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'INS wind speed is calculated from', '[{"id": "a", "text": "the vectorial addition of IAS and TAS.", "correct": false}, {"id": "b", "text": "the vectorial addition of TAS and GS.", "correct": true}, {"id": "c", "text": "the vectorial addition of IAS and GS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Centripetal error compensation is achieved by', '[{"id": "a", "text": "allowing the platform to oscillate at a fixed rate.", "correct": false}, {"id": "b", "text": "an additional signal is added to the N/S accelerometer to cancel the centripetal error.", "correct": true}, {"id": "c", "text": "the platform is torqued to align the N/S accelerometer along its insensitive axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Transport Rate compensation is achieved by', '[{"id": "a", "text": "an additional signal added to the N/S accelerometer output depending on heading.", "correct": false}, {"id": "b", "text": "allowing the platform to oscillate at a fixed rate.", "correct": false}, {"id": "c", "text": "the platform being torqued by a computed torquing signal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the battery fails on the ground (INS System)', '[{"id": "a", "text": "an amber light appears on the MSU and a horn sounds.", "correct": false}, {"id": "b", "text": "a red warning light appears on the MSU and a horn sounds.", "correct": true}, {"id": "c", "text": "a red light appears on the CDU and a horn sounds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An IRS alignment', '[{"id": "a", "text": "takes 10 minutes and present position must be entered before alignment.", "correct": false}, {"id": "b", "text": "takes 10 minutes and present position can be entered any time during the alignment.", "correct": true}, {"id": "c", "text": "takes 10 minutes and the previous flight shut down present position is used for the alignment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For an IRS system to pass the ''Alignment System Performance Test'' the', '[{"id": "a", "text": "the No. 1 and No.2 must both have the same latitude and longitude present position entered.", "correct": false}, {"id": "b", "text": "entered present latitude and longitude must agree with the latitude and longitude at the last power own.", "correct": false}, {"id": "c", "text": "latitude entered must be within given limits of the latitude computed by IRU.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A laser gyro dither mechanism ensures that', '[{"id": "a", "text": "the contra-rotating beams are synchronised together.", "correct": false}, {"id": "b", "text": "optical ''backscatter'' does not cause the contra-rotating beams to lock together.", "correct": true}, {"id": "c", "text": "that the two contra-rotating beams each operate at different frequencies.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The localiser deviation signal for the flight director comes from the', '[{"id": "a", "text": "flight director computer.", "correct": false}, {"id": "b", "text": "VHF comm system.", "correct": false}, {"id": "c", "text": "VHF nav system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The heading error signal used in the heading select mode', '[{"id": "a", "text": "is the difference between the desired heading and the actual heading.", "correct": true}, {"id": "b", "text": "is the difference between the desired course and the actual course.", "correct": false}, {"id": "c", "text": "comes direct from the compass system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The crab angle of the aircraft during VOR or LOC modes is displayed by the', '[{"id": "a", "text": "difference between the course arrow and aircraft heading.", "correct": true}, {"id": "b", "text": "difference between the selected heading and aircraft heading.", "correct": false}, {"id": "c", "text": "selected course counter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'VOR left-right deviation signals come from the', '[{"id": "a", "text": "DME system.", "correct": false}, {"id": "b", "text": "VLF nav system.", "correct": false}, {"id": "c", "text": "VHF nav set.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Above the glideslope, the ILS glideslope signal modulation is', '[{"id": "a", "text": "90 Hz.", "correct": true}, {"id": "b", "text": "150 Hz.", "correct": false}, {"id": "c", "text": "90 KHZ.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The localiser modulation signal to the left of the localiser centre line, as seen from the localiser transmitter, is', '[{"id": "a", "text": "90 Hz.", "correct": false}, {"id": "b", "text": "90 KHz.", "correct": false}, {"id": "c", "text": "150 Hz.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The correct sense demand generated for a selected heading 180Â°, when the aircraft heading is 150Â° is', '[{"id": "a", "text": "turn left.", "correct": false}, {"id": "b", "text": "straight ahead.", "correct": false}, {"id": "c", "text": "turn right.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft is flying along the extended centre line of the runway it is in the', '[{"id": "a", "text": "150 Hz modulation sector.", "correct": false}, {"id": "b", "text": "90 Hz modulation sector.", "correct": false}, {"id": "c", "text": "equi-signal sector.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The localiser system offers approach guidance to the runway in terms of', '[{"id": "a", "text": "the vertical plane.", "correct": false}, {"id": "b", "text": "the horizontal plane.", "correct": true}, {"id": "c", "text": "distance to touch down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The glideslope transmitter is located', '[{"id": "a", "text": "at the end opposite to the approach end of the runway.", "correct": false}, {"id": "b", "text": "adjacent to the touch-down point of the runway.", "correct": true}, {"id": "c", "text": "at the approach end of the runway.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The glideslope and localiser frequencies', '[{"id": "a", "text": "are fixed and common to all runways therefore frequency selection is not necessary.", "correct": false}, {"id": "b", "text": "have to be selected separately.", "correct": false}, {"id": "c", "text": "are paired and one frequency selector suffices for both.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The glideslope system offers approach guidance to runways in terms of', '[{"id": "a", "text": "distance to touchdown.", "correct": false}, {"id": "b", "text": "the vertical plane.", "correct": true}, {"id": "c", "text": "the horizontal plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The glideslope equipment operates in the', '[{"id": "a", "text": "VHF band.", "correct": false}, {"id": "b", "text": "UHF band.", "correct": true}, {"id": "c", "text": "HF band.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The localiser equipment operates in the', '[{"id": "a", "text": "HF band.", "correct": false}, {"id": "b", "text": "VHF band.", "correct": true}, {"id": "c", "text": "UHF band.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft equipment determines the bearing of a ground station by comparing', '[{"id": "a", "text": "the amplitude of two 30 Hz modulations.", "correct": false}, {"id": "b", "text": "the phase of two 30 Hz modulations.", "correct": true}, {"id": "c", "text": "the phase of one 30 Hz modulation with that of a 9960 Hz modulation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The number of different radials provided by a ground station is', '[{"id": "a", "text": "infinite.", "correct": true}, {"id": "b", "text": "180 per quadrant, i.e. 720 in 360°.", "correct": false}, {"id": "c", "text": "360.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following frequencies is allocated to VOR?', '[{"id": "a", "text": "114.3 MHz.", "correct": true}, {"id": "b", "text": "127.2 MHz.", "correct": false}, {"id": "c", "text": "103.9 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerial masts may be damaged by', '[{"id": "a", "text": "water.", "correct": false}, {"id": "b", "text": "killfrost anti-icing fluid.", "correct": false}, {"id": "c", "text": "Skydrol hydraulic fluids.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Most radio aerial masts are', '[{"id": "a", "text": "not bonded.", "correct": false}, {"id": "b", "text": "bonded.", "correct": true}, {"id": "c", "text": "insulated from the fuselage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft is heading due north (magnetic) towards a VOR station the reference and variable signals will be', '[{"id": "a", "text": "270° out of phase.", "correct": false}, {"id": "b", "text": "in phase.", "correct": false}, {"id": "c", "text": "180° out of phase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The middle marker modulation is keyed with', '[{"id": "a", "text": "alternate dots and dashes.", "correct": true}, {"id": "b", "text": "dashes.", "correct": false}, {"id": "c", "text": "dots.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The modulation of the outer marker is', '[{"id": "a", "text": "3000 Hz.", "correct": false}, {"id": "b", "text": "400 Hz.", "correct": true}, {"id": "c", "text": "1300 Hz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The approximate distance of the middle marker from the runway threshold is', '[{"id": "a", "text": "7 miles.", "correct": false}, {"id": "b", "text": "3 miles.", "correct": false}, {"id": "c", "text": "3500 ft..", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Marker information is usually provided to the pilot', '[{"id": "a", "text": "aurally.", "correct": false}, {"id": "b", "text": "both visually and aurally.", "correct": true}, {"id": "c", "text": "visually.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An over station sensor (OSS) detects', '[{"id": "a", "text": "the rapid rate of the VOR signal over the cone of confusion.", "correct": true}, {"id": "b", "text": "radio deviation signals proportional to distance from a localiser transmitter.", "correct": false}, {"id": "c", "text": "radio deviation signals proportional to distance from a VOR transmitter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Incompatible Flight Director modes are', '[{"id": "a", "text": "altitude hold and ILS.", "correct": true}, {"id": "b", "text": "VRU and compass.", "correct": false}, {"id": "c", "text": "VOR and glidepath.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The VOR system comprises', '[{"id": "a", "text": "reference phase signal.", "correct": false}, {"id": "b", "text": "variable and reference phase signals.", "correct": true}, {"id": "c", "text": "variable phase signal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The most sensitive system between ILS and VOR is', '[{"id": "a", "text": "they both have the same sensitivity.", "correct": false}, {"id": "b", "text": "ILS.", "correct": true}, {"id": "c", "text": "VOR.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft is flying on a heading of 000 away from a VOR station, the TO/FROM indicator would show', '[{"id": "a", "text": "to.", "correct": false}, {"id": "b", "text": "from.", "correct": true}, {"id": "c", "text": "no indication.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How does the flight director computer differentiate between VOR and ILS frequencies?', '[{"id": "a", "text": "Frequency discriminator in receiver.", "correct": true}, {"id": "b", "text": "Trigger pulse from ground station.", "correct": false}, {"id": "c", "text": "Discriminator on control panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The glideslope transmitter operates on', '[{"id": "a", "text": "the VHF band.", "correct": false}, {"id": "b", "text": "frequencies of 108 to 118 MHZ.", "correct": false}, {"id": "c", "text": "the UHF band.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pilots instinctive autopilot disengage button is on the', '[{"id": "a", "text": "left of the control column.", "correct": false}, {"id": "b", "text": "right of the control column.", "correct": false}, {"id": "c", "text": "side of the controls away from the throttles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the autopilot automatically disconnects in the autoland mode, the audible warning', '[{"id": "a", "text": "switches off after a time interval.", "correct": false}, {"id": "b", "text": "is switched off by the instinctive cut-out button.", "correct": true}, {"id": "c", "text": "can only be switched off by re-engaging the autopilot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A category 3B aircraft using fail operational automatic landing equipment will have', '[{"id": "a", "text": "a decision height depending on RVR.", "correct": false}, {"id": "b", "text": "a decision height of 50ft.", "correct": false}, {"id": "c", "text": "no decision height.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For an aircraft to be certified for automatic landing, an autothrottle system is', '[{"id": "a", "text": "mandatory.", "correct": false}, {"id": "b", "text": "a matter of choice for the operator.", "correct": false}, {"id": "c", "text": "dependent on the operation of the aircraft at slow speeds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With autothrottle engaged, the application of reverse thrust will', '[{"id": "a", "text": "drive the throttles to the minimum thrust position.", "correct": false}, {"id": "b", "text": "drive the throttles to the reverse thrust position.", "correct": false}, {"id": "c", "text": "disconnect the autothrottle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During ATC transponder operation, side lobe suppression acts to', '[{"id": "a", "text": "mute the DME operation during transmit phase.", "correct": true}, {"id": "b", "text": "mute coms transmission during transponder operation.", "correct": false}, {"id": "c", "text": "supply altitude readout.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During operation of a twin HF radio system transceiver', '[{"id": "a", "text": "#1 HF system operation is inhibited during #2 operation.", "correct": true}, {"id": "b", "text": "both systems can be operated simultaneously.", "correct": false}, {"id": "c", "text": "#1 HF system can transmit but not receive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which L band frequency is not used by DME for transmitting?', '[{"id": "a", "text": "2210 MHz.", "correct": false}, {"id": "b", "text": "1090 MHz.", "correct": true}, {"id": "c", "text": "4133 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Function of ADF & VOR and DME in navigation system with reference to aircraft and beacon is;', '[{"id": "a", "text": "the first provides distance between aircraft and beacon and latter provides bearing line from aircraft to", "correct": false}, {"id": "b", "text": "beacon", "correct": false}, {"id": "c", "text": "the first provides bearing line from aircraft to beacon and latter provides distance between aircraft and", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which two frequencies are paired?', '[{"id": "a", "text": "Which two frequencies are paired?", "correct": false}, {"id": "b", "text": "Glideslope and localizer.", "correct": true}, {"id": "c", "text": "Localizer and DME.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Localizer beam width is the angle where the two edges of beam are apart at the runway threshold by', '[{"id": "a", "text": "7 ft.", "correct": false}, {"id": "b", "text": "700 ft.", "correct": true}, {"id": "c", "text": "70 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens if frequency decreases without altering the physical length of aerial?', '[{"id": "a", "text": "The aerial becomes inductively capacitive.", "correct": false}, {"id": "b", "text": "The aerial becomes capacitively reactive.", "correct": true}, {"id": "c", "text": "The aerial becomes inductively reactive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens if frequency increases without altering the physical length of aerial?', '[{"id": "a", "text": "The aerial becomes inductively reactive.", "correct": true}, {"id": "b", "text": "The aerial becomes capacitively reactive.", "correct": false}, {"id": "c", "text": "The aerial becomes inductively capacitive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aerials provide optimum output at one particular frequency, when its load is purely', '[{"id": "a", "text": "resistive.", "correct": true}, {"id": "b", "text": "capacitive.", "correct": false}, {"id": "c", "text": "inductive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The torque pre-set in an autopilot system is', '[{"id": "a", "text": "to stop the motor overheating.", "correct": false}, {"id": "b", "text": "to give control surface feel.", "correct": false}, {"id": "c", "text": "to allow it to be overridden at a certain force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Most aerials are', '[{"id": "a", "text": "not bonded.", "correct": false}, {"id": "b", "text": "bonded.", "correct": true}, {"id": "c", "text": "made from non-conductive material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Middle Marker beacon is what colour?', '[{"id": "a", "text": "Amber.", "correct": true}, {"id": "b", "text": "White.", "correct": false}, {"id": "c", "text": "Blue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Laser gyros have', '[{"id": "a", "text": "no rotating parts.", "correct": false}, {"id": "b", "text": "moving parts.", "correct": true}, {"id": "c", "text": "a spinning rotor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Laser gyros are aligned to', '[{"id": "a", "text": "magnetic north.", "correct": false}, {"id": "b", "text": "true north.", "correct": false}, {"id": "c", "text": "aircraft structure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Triplex autopilot is', '[{"id": "a", "text": "fail passive.", "correct": false}, {"id": "b", "text": "fail soft.", "correct": false}, {"id": "c", "text": "fail operational.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flight management control system (FMCS) utilises', '[{"id": "a", "text": "ILS, VOR, ADF.", "correct": false}, {"id": "b", "text": "ILS, DME, ADC,", "correct": true}, {"id": "c", "text": "VOR, ADF, DME.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ACARS is', '[{"id": "a", "text": "a navigation system.", "correct": false}, {"id": "b", "text": "a satellite communication system.", "correct": false}, {"id": "c", "text": "a way of reporting defects to maintenance base in flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is an ATC transponder mode ''A'' selected ON?', '[{"id": "a", "text": "The airspeed indicator.", "correct": false}, {"id": "b", "text": "The ATC control panel.", "correct": true}, {"id": "c", "text": "The altimeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many data bases are required in an FMS system?', '[{"id": "a", "text": "2.", "correct": true}, {"id": "b", "text": "1.", "correct": false}, {"id": "c", "text": "3 (one is used for redundancy).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What channel of the autopilot does the glideslope control?', '[{"id": "a", "text": "Pitch.", "correct": true}, {"id": "b", "text": "Yaw.", "correct": false}, {"id": "c", "text": "Roll.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is secondary radar?', '[{"id": "a", "text": "Signal returned from a transponder.", "correct": true}, {"id": "b", "text": "A backup radar on an airfield.", "correct": false}, {"id": "c", "text": "Reflected radar bounce from an aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an autothrottle system, when is EPR or thrust mode used?', '[{"id": "a", "text": "Approach.", "correct": false}, {"id": "b", "text": "Cruise.", "correct": false}, {"id": "c", "text": "Take-off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is Mode 1 & 2 of GPWS used for?', '[{"id": "a", "text": "Excessive descent rate, unsafe terrain clearance.", "correct": false}, {"id": "b", "text": "Excessive descent rate, excessive terrain closure rate.", "correct": true}, {"id": "c", "text": "Excessive terrain closure rate, altitude loss after take-off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For radio communication over a distance of over 250 miles we use', '[{"id": "a", "text": "VHF.", "correct": false}, {"id": "b", "text": "VLF.", "correct": false}, {"id": "c", "text": "HF.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Autopilot, when on approach to landing, how many axis are used?', '[{"id": "a", "text": "3.", "correct": true}, {"id": "b", "text": "2.", "correct": false}, {"id": "c", "text": "1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A lead-acid battery is considered to be fully charged when the', '[{"id": "a", "text": "cells begin to gas freely.", "correct": false}, {"id": "b", "text": "SG reaches 1.180.", "correct": false}, {"id": "c", "text": "SG and voltage remain constant for specified period.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A diode across a contactor', '[{"id": "a", "text": "reduces contact bounce.", "correct": false}, {"id": "b", "text": "enables it to be connected to either an AC or DC circuit.", "correct": false}, {"id": "c", "text": "reduces contact arcing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The preferred method of battery charging a Ni-Cad battery is constant', '[{"id": "a", "text": "voltage.", "correct": false}, {"id": "b", "text": "power.", "correct": false}, {"id": "c", "text": "current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A battery in situ on an aircraft', '[{"id": "a", "text": "charges at a fairly constant rate because generator voltage remains constant.", "correct": false}, {"id": "b", "text": "may charged at an excessive rate if initial battery voltage is low.", "correct": true}, {"id": "c", "text": "may charge slowly if initial battery voltage is low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To parallel an alternating current generator with one or more other generators, phase A must be', '[{"id": "a", "text": "90 degrees out-of-phase and ABC.", "correct": false}, {"id": "b", "text": "in-phase with other generators and CBA only.", "correct": false}, {"id": "c", "text": "in-phase with other generators and ABC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an unparalleled twin generator alternating current system, the phase of the second generator to be brought on line', '[{"id": "a", "text": "must be in-phase prior to paralleling.", "correct": false}, {"id": "b", "text": "is unimportant.", "correct": true}, {"id": "c", "text": "is important if the first generator fails.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The power supply for aircraft is', '[{"id": "a", "text": "28VDC, 115VAC, 400Hz.", "correct": true}, {"id": "b", "text": "28VDC, 220VAC, 400Hz.", "correct": false}, {"id": "c", "text": "28VDC, 115VAC, 200Hz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a Direct Current circuit, Current Limiters', '[{"id": "a", "text": "prevent overheating by limiting current to load.", "correct": true}, {"id": "b", "text": "limit generator field excitation.", "correct": false}, {"id": "c", "text": "limit current to field circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a direct current circuit, current limiters', '[{"id": "a", "text": "allow excessive current to the load circuit.", "correct": false}, {"id": "b", "text": "prevent excessive current to the load circuit.", "correct": true}, {"id": "c", "text": "prevent excessive current to the field circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a current transformer is disconnected from its load', '[{"id": "a", "text": "a resistor should be placed across the terminals.", "correct": false}, {"id": "b", "text": "the terminals should be shorted together.", "correct": true}, {"id": "c", "text": "the terminals should be left disconnected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ram Air Turbines have variable fan blades to', '[{"id": "a", "text": "maintain a constant speed.", "correct": true}, {"id": "b", "text": "provide a constant flow rate.", "correct": false}, {"id": "c", "text": "produce maximun hydraulic pressure required by the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a direct current twin generator system, the paralleling relay contacts close when the oncoming generators voltage is', '[{"id": "a", "text": "below bus voltage.", "correct": false}, {"id": "b", "text": "the same as bus voltage.", "correct": false}, {"id": "c", "text": "above bus voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is a commutator found?', '[{"id": "a", "text": "An AC generator.", "correct": false}, {"id": "b", "text": "A DC generator.", "correct": true}, {"id": "c", "text": "A DC alternator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Calculate the battery terminal voltage of a NiCad battery with 15 cells', '[{"id": "a", "text": "18 V.", "correct": true}, {"id": "b", "text": "15 V.", "correct": false}, {"id": "c", "text": "30 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Reactive electrical loads are adjusted by', '[{"id": "a", "text": "adjustment of generator speed.", "correct": false}, {"id": "b", "text": "adjustment of the regulator output.", "correct": true}, {"id": "c", "text": "varying the frequency circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'IDG oil is used for', '[{"id": "a", "text": "internal hydraulic functions only.", "correct": false}, {"id": "b", "text": "cooling, lubrication and internal hydraulic functions.", "correct": true}, {"id": "c", "text": "cooling and lubrication only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A silver oxide cell has a voltage of', '[{"id": "a", "text": "1.55 V.", "correct": true}, {"id": "b", "text": "1.8 V.", "correct": false}, {"id": "c", "text": "1.2 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Lithium cells', '[{"id": "a", "text": "are very efficient.", "correct": false}, {"id": "b", "text": "have an unlimited re-charge cycle capacity.", "correct": false}, {"id": "c", "text": "are not rechargeable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a split bus electrical system, the bus tie breakers are', '[{"id": "a", "text": "always closed in flight.", "correct": false}, {"id": "b", "text": "always open in flight.", "correct": true}, {"id": "c", "text": "only closed in an emergency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Parallel electrical system bus tie breakers are', '[{"id": "a", "text": "closed in flight and open on ground.", "correct": false}, {"id": "b", "text": "closed on ground and open in flight.", "correct": false}, {"id": "c", "text": "always closed in flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Whilst synchronising generators, frequency bias is adjusted on', '[{"id": "a", "text": "the on-line generator.", "correct": false}, {"id": "b", "text": "all generators.", "correct": false}, {"id": "c", "text": "the on-coming generator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The GCR will trip during over-voltage', '[{"id": "a", "text": "based upon a fixed time delay circuit.", "correct": false}, {"id": "b", "text": "based upon the amplitude of the over-voltage.", "correct": true}, {"id": "c", "text": "immediately.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a constant voltage AC generator, the voltage is regulated by', '[{"id": "a", "text": "a 3-phase transformer.", "correct": false}, {"id": "b", "text": "varying field voltage.", "correct": false}, {"id": "c", "text": "varying field current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A vibrator type voltage regulator regulates field current by', '[{"id": "a", "text": "just a pair of contact breaker points.", "correct": false}, {"id": "b", "text": "a resistor in parallel with a pair of contact breaker points.", "correct": true}, {"id": "c", "text": "a resistor in series with a pair of contact breaker points.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a current transformer is disconnected, what should be done?', '[{"id": "a", "text": "Resistor placed across terminals.", "correct": false}, {"id": "b", "text": "Left open circuit.", "correct": false}, {"id": "c", "text": "Terminals shorted.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What does the differential sensing coil sense?', '[{"id": "a", "text": "Volts.", "correct": false}, {"id": "b", "text": "Power.", "correct": false}, {"id": "c", "text": "Current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where does the GCU gets its power?', '[{"id": "a", "text": "RAT.", "correct": false}, {"id": "b", "text": "PMG.", "correct": true}, {"id": "c", "text": "Battery.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Galley loads are wired in', '[{"id": "a", "text": "either series or parallel depending on the design.", "correct": false}, {"id": "b", "text": "series.", "correct": false}, {"id": "c", "text": "parallel so load shedding will lower current consumption.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a merz-price protection system of a single phase, if, when a fault occurs, only one relay contactor opens,', '[{"id": "a", "text": "only the relay on the side which has the fault will energise.", "correct": true}, {"id": "b", "text": "then it is probable that one of the relays has failed short circuit.", "correct": false}, {"id": "c", "text": "then it is probable that one of the coils has failed open circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuse-type current limiter', '[{"id": "a", "text": "can be used as a radio suppressor.", "correct": false}, {"id": "b", "text": "limits current flow to a load.", "correct": false}, {"id": "c", "text": "opens a circuit after a time/current condition has been exceeded.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a load is shed from a busbar, the', '[{"id": "a", "text": "busbar voltage decreases.", "correct": false}, {"id": "b", "text": "current consumption from the bar decreases.", "correct": true}, {"id": "c", "text": "busbar voltage increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In unparalleled AC generation systems, the phase rotation of one generator in relation to the others', '[{"id": "a", "text": "must be synchronised prior to paralleling.", "correct": false}, {"id": "b", "text": "is unimportant.", "correct": true}, {"id": "c", "text": "must be BCA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a multi-generator system, the generator which takes more than its reactive power share is protected by', '[{"id": "a", "text": "over-current and under-current protection circuits.", "correct": false}, {"id": "b", "text": "over-excitation and under-excitation protection circuits.", "correct": false}, {"id": "c", "text": "over-voltage and under-voltage protection circuits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a pulsed width modulating type voltage regulator, the generator output voltage is increased by', '[{"id": "a", "text": "increasing the voltage sensed by the voltage regulator.", "correct": false}, {"id": "b", "text": "increasing the mark to space ratio.", "correct": true}, {"id": "c", "text": "decreasing the mark to space ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sharing of electrical loads by paralleled DC generators is controlled by', '[{"id": "a", "text": "automatic load shedding.", "correct": false}, {"id": "b", "text": "equalising circuits which control the field excitation of the generators.", "correct": true}, {"id": "c", "text": "equalising circuits which control the speed of the generators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Excessive commutator sparking can be caused by', '[{"id": "a", "text": "rotating field diode failure.", "correct": false}, {"id": "b", "text": "weak spring tension.", "correct": true}, {"id": "c", "text": "brushes positioned on MNA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before checking the SG of a battery recently removed from an aircraft', '[{"id": "a", "text": "take the temperature of the electrolyte.", "correct": true}, {"id": "b", "text": "carry out a capacity test.", "correct": false}, {"id": "c", "text": "allow to stabilise for one hour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an AC external power plug, the interlock circuit is controlled by pins', '[{"id": "a", "text": "E and F.", "correct": true}, {"id": "b", "text": "A and B.", "correct": false}, {"id": "c", "text": "C and D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Over-voltage protection circuits are activated', '[{"id": "a", "text": "after a fixed time delay.", "correct": false}, {"id": "b", "text": "dependent on the magnitude of the overvoltage.", "correct": true}, {"id": "c", "text": "before the over voltage limit is exceeded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A diode connected across a coil will', '[{"id": "a", "text": "prevent the coil being fitted the wrong way.", "correct": false}, {"id": "b", "text": "prevent back EMF and allow faster switching.", "correct": false}, {"id": "c", "text": "suppress arcing when relay is opening and closing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which fault does not always trip the GCR?', '[{"id": "a", "text": "Over-frequency and under-frequency.", "correct": false}, {"id": "b", "text": "Under-frequency and under-volts.", "correct": true}, {"id": "c", "text": "Over-frequency and over-volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Differential protection in a generating system', '[{"id": "a", "text": "detects current difference between source and load.", "correct": true}, {"id": "b", "text": "uses the volts coil to trip the GCR.", "correct": false}, {"id": "c", "text": "detects voltage difference between source and load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Open phase sensing on a current transformer', '[{"id": "a", "text": "is detected on generator neutral circuit.", "correct": true}, {"id": "b", "text": "is detected using all phases.", "correct": false}, {"id": "c", "text": "is detected using any phase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the battery is switched off in flight, the', '[{"id": "a", "text": "battery is disconnected from bus.", "correct": true}, {"id": "b", "text": "captain''s instruments will be powered from the standby bus.", "correct": false}, {"id": "c", "text": "generator voltage falls to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To flash a generator field the', '[{"id": "a", "text": "generator is on line and producing a voltage less than the flashing voltage.", "correct": false}, {"id": "b", "text": "generator must be stationary.", "correct": true}, {"id": "c", "text": "generator rotates but is not on line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Voltage is controlled by', '[{"id": "a", "text": "the voltage regulator.", "correct": true}, {"id": "b", "text": "the constant speed drive.", "correct": false}, {"id": "c", "text": "the swashplate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Distilled water should be added to a ni-cad battery', '[{"id": "a", "text": "only in the battery workshop.", "correct": true}, {"id": "b", "text": "when fully charged.", "correct": false}, {"id": "c", "text": "at any time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Overflowing electrolyte in a ni-cad battery indicates', '[{"id": "a", "text": "not enough charging current.", "correct": false}, {"id": "b", "text": "low electrolyte temperature.", "correct": false}, {"id": "c", "text": "excessive charging current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During a normal engine shutdown, generator tripping is initiated by', '[{"id": "a", "text": "underfrequency.", "correct": false}, {"id": "b", "text": "undervoltage.", "correct": true}, {"id": "c", "text": "overcurrent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What would you use to neutralise nicad battery spillage?', '[{"id": "a", "text": "Boric acid.", "correct": true}, {"id": "b", "text": "Distilled water.", "correct": false}, {"id": "c", "text": "Bicarbonate of soda.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before operating generators in parallel, their voltages should be matched to prevent', '[{"id": "a", "text": "overloading the generator drive and shearing of splines.", "correct": true}, {"id": "b", "text": "voltage spikes of sufficient magnitude to trigger GCU overvoltage circuits.", "correct": false}, {"id": "c", "text": "large circulating currents developing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Consumer loads are connected to a busbar', '[{"id": "a", "text": "in series so when loads are shed voltage is reduced.", "correct": false}, {"id": "b", "text": "in series so when loads are shed current is reduced.", "correct": false}, {"id": "c", "text": "in parallel so when loads are shed current is reduced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A current transformer connected on the neutral star point of a generator is for', '[{"id": "a", "text": "overload protection.", "correct": false}, {"id": "b", "text": "differential current protection.", "correct": true}, {"id": "c", "text": "negative sequence protection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Differential protection as applied to AC generation systems compares', '[{"id": "a", "text": "ambient pressure to cabin pressure.", "correct": false}, {"id": "b", "text": "generator voltage to busbar voltage.", "correct": false}, {"id": "c", "text": "generator current to busbar current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an AC generation system, the frequency and phase rotation', '[{"id": "a", "text": "is of no consequence after paralleling.", "correct": false}, {"id": "b", "text": "must be synchronised prior to paralleling.", "correct": true}, {"id": "c", "text": "must be out of phase prior to paralleling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Diodes are placed across a contactor to', '[{"id": "a", "text": "prevent contact bounce.", "correct": false}, {"id": "b", "text": "ensure smooth contactor operation.", "correct": true}, {"id": "c", "text": "speed up operation by reducing back EMF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Placing the battery master switch to off during flight will', '[{"id": "a", "text": "shut down the APU.", "correct": false}, {"id": "b", "text": "isolate the battery from the main busbar.", "correct": true}, {"id": "c", "text": "disconnect all power to the main busbar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Whilst operating paralleled AC constant frequency generators, it is important to maintain generator outputs at the same voltage', '[{"id": "a", "text": "to prevent a circulating current of considerable magnitude developing between two or more generators.", "correct": true}, {"id": "b", "text": "to prevent a circulating current developing between two or more TRUs.", "correct": false}, {"id": "c", "text": "to prevent CSD shock loading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A voltage regulator installed in series with a generator field', '[{"id": "a", "text": "uses a current coil in parallel with generator output.", "correct": false}, {"id": "b", "text": "uses a voltage coil in parallel with generator output.", "correct": true}, {"id": "c", "text": "uses a voltage coil in series with generator output.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'CSD warning lights on the flight deck normally indicate', '[{"id": "a", "text": "low oil pressure, low oil temperature.", "correct": false}, {"id": "b", "text": "high oil pressure, low oil temperature.", "correct": false}, {"id": "c", "text": "low oil pressure, high oil temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The output frequency of a hydraulically driven standby generator is controlled by', '[{"id": "a", "text": "an IDG.", "correct": false}, {"id": "b", "text": "a CSD.", "correct": false}, {"id": "c", "text": "an hydraulically actuated swash plate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An AC generator used with a CSD', '[{"id": "a", "text": "does not need a voltage controller because current is kept constant.", "correct": false}, {"id": "b", "text": "does not need a voltage controller because voltage is kept constant.", "correct": false}, {"id": "c", "text": "needs a voltage controller to maintain voltage with increasing load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Power to a GCU is supplied', '[{"id": "a", "text": "initially by a ''field tickling'' supply and then PMG output.", "correct": true}, {"id": "b", "text": "by the battery bus or rectified generator output.", "correct": false}, {"id": "c", "text": "by the generator output only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Trip signals for a GCR are', '[{"id": "a", "text": "underfrequency and overcurrent.", "correct": false}, {"id": "b", "text": "overfrequency and undervoltage.", "correct": false}, {"id": "c", "text": "differential protection and undervoltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Abnormal CSD operation is monitored on the flight deck by observing indications of', '[{"id": "a", "text": "high oil temperature / low oil pressure.", "correct": true}, {"id": "b", "text": "low oil quantity / low oil temperature.", "correct": false}, {"id": "c", "text": "High oil temperature / low oil quantity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wires in hot temperature areas should be bound with', '[{"id": "a", "text": "PVC.", "correct": false}, {"id": "b", "text": "Teflon.", "correct": true}, {"id": "c", "text": "Nomex.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A heat gun should be operated at', '[{"id": "a", "text": "100°C below the specified.", "correct": false}, {"id": "b", "text": "the specified temperature.", "correct": true}, {"id": "c", "text": "100°C above the specified.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High voltages on a generator in a parallel system should be prevented because', '[{"id": "a", "text": "it will cause high circulating current in the bus / other generators.", "correct": false}, {"id": "b", "text": "it will damage the drive shaft.", "correct": false}, {"id": "c", "text": "it will trip the GCR.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Over-voltage condition trips the generator. The time taken to trip the GCU depends on', '[{"id": "a", "text": "time delay circuit.", "correct": false}, {"id": "b", "text": "closing of fuel and hydraulic valves.", "correct": false}, {"id": "c", "text": "amplitude of voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Speed of an HMG is controlled by a', '[{"id": "a", "text": "ID unit.", "correct": false}, {"id": "b", "text": "CSD unit.", "correct": false}, {"id": "c", "text": "swashplate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What will happen if the aircraft battery becomes overheated?', '[{"id": "a", "text": "The power supply to the battery charger will be interrupted.", "correct": true}, {"id": "b", "text": "The hot battery bus will be disconnected from the battery.", "correct": false}, {"id": "c", "text": "The battery charger will switch to trickle charge mode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the temperature increases in a lead acid battery, the SG will', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "decrease.", "correct": true}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On testing a generator it is found to require adjusting, where would you adjust it?', '[{"id": "a", "text": "By means of a remote trimmer.", "correct": false}, {"id": "b", "text": "On the GCU.", "correct": true}, {"id": "c", "text": "In the cockpit on the flight engineers panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Control of hydraulically powered emergency electrical generator frequency is', '[{"id": "a", "text": "by angle of swash plate.", "correct": true}, {"id": "b", "text": "by IDG.", "correct": false}, {"id": "c", "text": "by CSU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a ni-cad battery is fully charged', '[{"id": "a", "text": "the electrolyte level is lower than normal.", "correct": false}, {"id": "b", "text": "the electrolyte level is higher level than normal.", "correct": true}, {"id": "c", "text": "the electrolyte level stays the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Electrical load on aircraft is controlled by', '[{"id": "a", "text": "a GCU.", "correct": false}, {"id": "b", "text": "a BPCU.", "correct": true}, {"id": "c", "text": "an IRS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A 4:1 step-up transformer receives 120VAC in its primary and has 1600 Ohms resistance in its secondary. What is the current drawn from the source?', '[{"id": "a", "text": "3 A.", "correct": false}, {"id": "b", "text": "1.2 A.", "correct": true}, {"id": "c", "text": "0.3 A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After engine start using a Ni-Cad battery, the pilot observes on the battery charger indicator, an initial high current draw followed by a rapid decrease in current', '[{"id": "a", "text": "no cause for concern.", "correct": true}, {"id": "b", "text": "the battery is faulty.", "correct": false}, {"id": "c", "text": "there is a problem with the charging circuit and he must shut-down the engines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a lead-acid battery after numerous checks, one cell has low reading', '[{"id": "a", "text": "It is defective.", "correct": false}, {"id": "b", "text": "It must be replaced.", "correct": true}, {"id": "c", "text": "It needs topping up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A short range passenger aircraft has complete electrical failure. What time duration would the battery be expected to power essential equipment?', '[{"id": "a", "text": "60 minutes.", "correct": false}, {"id": "b", "text": "Forever.", "correct": false}, {"id": "c", "text": "30 minute.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An external power plug has two short pins. These are used for', '[{"id": "a", "text": "a guide for correct alignment of the plug in the socket.", "correct": false}, {"id": "b", "text": "the interlock circuit.", "correct": true}, {"id": "c", "text": "ground handling bus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a synchronising bus bar is', '[{"id": "a", "text": "to enable two propeller systems to be synchronised.", "correct": false}, {"id": "b", "text": "to allow monitoring and trimming from the flight deck.", "correct": true}, {"id": "c", "text": "to monitor total current load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To confirm the state of charge of a ni-cad battery', '[{"id": "a", "text": "subject the battery to load and check the voltage.", "correct": false}, {"id": "b", "text": "measure the discharge time.", "correct": true}, {"id": "c", "text": "subject the battery to load, check voltage and check the SG of each cell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Circulating currents are associated with', '[{"id": "a", "text": "AC generators in parallel.", "correct": true}, {"id": "b", "text": "DC generators in parallel.", "correct": false}, {"id": "c", "text": "AC and DC generators in parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Generator brush bedding', '[{"id": "a", "text": "can be done on the aircraft.", "correct": false}, {"id": "b", "text": "should only be done if 50% of the width and 80% of the length is already being done.", "correct": false}, {"id": "c", "text": "should not be done on the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pitot tubes are heated by', '[{"id": "a", "text": "AC.", "correct": false}, {"id": "b", "text": "AC or DC.", "correct": true}, {"id": "c", "text": "DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Paralleling is used for', '[{"id": "a", "text": "DC electrical generators only.", "correct": false}, {"id": "b", "text": "AC electrical generators only.", "correct": false}, {"id": "c", "text": "AC and DC electrical generators.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Battery charging procedures can be found in ATA', '[{"id": "a", "text": "Chapter 24 Section 21.", "correct": false}, {"id": "b", "text": "Chapter 31 Section 21.", "correct": false}, {"id": "c", "text": "Chapter 24 Section 31.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a carbon pile regulator, the resistive element is', '[{"id": "a", "text": "in parallel with the field and changes resistance with changing length.", "correct": false}, {"id": "b", "text": "in series with the field and changes resistance with changing length.", "correct": false}, {"id": "c", "text": "in series with the field and changes resistance with surface area contact.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Maximum battery temperature on charging before protection circuit starts is', '[{"id": "a", "text": "144 degrees C.", "correct": false}, {"id": "b", "text": "71 degrees F.", "correct": false}, {"id": "c", "text": "144 degrees F.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft has no battery charger, the battery is charged by', '[{"id": "a", "text": "constant current until a predetermined limit when it automatically switches to constant voltage.", "correct": false}, {"id": "b", "text": "constant current.", "correct": false}, {"id": "c", "text": "constant voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The output of a carbon pile regulator with no variation of loading is', '[{"id": "a", "text": "stationary.", "correct": true}, {"id": "b", "text": "pulse width modulating.", "correct": false}, {"id": "c", "text": "fluctuating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a transistor voltage regulator, the voltage output is controlled by', '[{"id": "a", "text": "zeners and transistors.", "correct": true}, {"id": "b", "text": "diodes and transformers.", "correct": false}, {"id": "c", "text": "transformers and transistors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A paralleled relay for a DC system is energised and connected by', '[{"id": "a", "text": "voltage and current coil.", "correct": true}, {"id": "b", "text": "current coil.", "correct": false}, {"id": "c", "text": "voltage coil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Increasing the real load primarily', '[{"id": "a", "text": "increases output voltage and increases frequency.", "correct": false}, {"id": "b", "text": "decreases output voltage.", "correct": false}, {"id": "c", "text": "decreases frequency.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inductive reactive load causes', '[{"id": "a", "text": "increase in torque only.", "correct": false}, {"id": "b", "text": "no effect on torque but produces extra heat dissipated.", "correct": true}, {"id": "c", "text": "increase in torque and increase in heat dissipated.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The power factor of an AC generator identifies the proportion of', '[{"id": "a", "text": "apparent power from the generator that does work.", "correct": false}, {"id": "b", "text": "real power from the generator that does work.", "correct": true}, {"id": "c", "text": "reactive power from the generator that does work.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Differential protection in an AC system protects against', '[{"id": "a", "text": "a reverse current flowing from the battery.", "correct": false}, {"id": "b", "text": "line-line, line-line-line, line-earth faults.", "correct": false}, {"id": "c", "text": "short circuits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When resetting the CSD on the ground, the engine should be', '[{"id": "a", "text": "rotating at idle.", "correct": false}, {"id": "b", "text": "stationary.", "correct": true}, {"id": "c", "text": "rotating at Nsync.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the main purposes of a CSD is to', '[{"id": "a", "text": "enable generators to be paralleled.", "correct": true}, {"id": "b", "text": "maintain constant load on the generator.", "correct": false}, {"id": "c", "text": "prevent engine overload.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an undervolt condition in an AC generator system, the most likely consequence is', '[{"id": "a", "text": "activation of the time delay circuit.", "correct": true}, {"id": "b", "text": "deactivation of the field regulatory TRs", "correct": false}, {"id": "c", "text": "energise the bus tie relay.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If voltage and frequency of the generator drop to zero in flight, it would be an indication that the', '[{"id": "a", "text": "bus tie interlock is inoperative.", "correct": false}, {"id": "b", "text": "phase sequence detection circuit has operated.", "correct": false}, {"id": "c", "text": "CSD driveshaft had sheared.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Assuming all systems are operating normally, as aircraft electrical load increases, generator output voltage will', '[{"id": "a", "text": "decrease and amperage output increases.", "correct": false}, {"id": "b", "text": "increases and amperage output increases.", "correct": false}, {"id": "c", "text": "remain constant and amperage output increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When installing multiple batteries on aircraft, they are connected in', '[{"id": "a", "text": "either parallel or series and switched between as an option.", "correct": true}, {"id": "b", "text": "series.", "correct": false}, {"id": "c", "text": "parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the small pin on the DC ground power connector?', '[{"id": "a", "text": "Ground or earth.", "correct": false}, {"id": "b", "text": "Positive to battery relay.", "correct": false}, {"id": "c", "text": "Positive to external power relay.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is RAT driven?', '[{"id": "a", "text": "Airstream.", "correct": true}, {"id": "b", "text": "Compressor.", "correct": false}, {"id": "c", "text": "Fan.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is an aircraft battery rated?', '[{"id": "a", "text": "Ampere hours.", "correct": true}, {"id": "b", "text": "Watts.", "correct": false}, {"id": "c", "text": "Joules.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the 2 short prongs on an AC plug for?', '[{"id": "a", "text": "Using AC current to pull on interlock circuit.", "correct": false}, {"id": "b", "text": "To prevent arcing during plug connection / disconnection.", "correct": true}, {"id": "c", "text": "To help plug location/fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A vibration contact voltage regulator consists of a shunt winding and a', '[{"id": "a", "text": "current regulation coil in series.", "correct": false}, {"id": "b", "text": "voltage regulating coil in parallel.", "correct": false}, {"id": "c", "text": "voltage regulating coil in series.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of diode in a power GCR?', '[{"id": "a", "text": "To allow flow in the event of failure of the relay.", "correct": false}, {"id": "b", "text": "To speed up the operation.", "correct": false}, {"id": "c", "text": "To prevent back-flow of current in the EMF coil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Eddy currents are', '[{"id": "a", "text": "caused by heating effect of the coil.", "correct": false}, {"id": "b", "text": "caused by resistance of the coil.", "correct": false}, {"id": "c", "text": "circulating currents.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The small pins in the power connector plug are', '[{"id": "a", "text": "neutral.", "correct": false}, {"id": "b", "text": "negative.", "correct": false}, {"id": "c", "text": "positive.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an overvolt is present on an AC generator system, the tripping circuit', '[{"id": "a", "text": "trips at a set level.", "correct": false}, {"id": "b", "text": "trips after a time delay inversely proportional to overvolt amplitude.", "correct": true}, {"id": "c", "text": "trips after a time delay.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an AC distribution system, the purpose of the synchronising bus-bar is to', '[{"id": "a", "text": "provide a means of monitoring the load.", "correct": false}, {"id": "b", "text": "provide interconnection between the generator load busbars.", "correct": true}, {"id": "c", "text": "supply essential services.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vibrating contact voltage regulator sensing coil is', '[{"id": "a", "text": "in parallel with the field windings.", "correct": false}, {"id": "b", "text": "across the generator output.", "correct": true}, {"id": "c", "text": "in series with the field windings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A current transformer connected across the neutral of a 3 phase generator is for', '[{"id": "a", "text": "differential protection.", "correct": true}, {"id": "b", "text": "load monitoring.", "correct": false}, {"id": "c", "text": "phase sequence monitoring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Zener diodes are for', '[{"id": "a", "text": "voltage regulation.", "correct": true}, {"id": "b", "text": "voltage stabilisation.", "correct": false}, {"id": "c", "text": "rectification.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'AC generator output indications are measured in', '[{"id": "a", "text": "KW & KVAR.", "correct": true}, {"id": "b", "text": "KW.", "correct": false}, {"id": "c", "text": "KVA & KW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Load shedding allows', '[{"id": "a", "text": "more voltage to the busbar.", "correct": false}, {"id": "b", "text": "less current to the busbar.", "correct": true}, {"id": "c", "text": "more current to the busbar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How may the output of a transistorised voltage regulator be described?', '[{"id": "a", "text": "Variable AC.", "correct": false}, {"id": "b", "text": "Pulse width modulated DC.", "correct": true}, {"id": "c", "text": "Slightly variable DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the event of complete AC generator failure in an AC split bus-bar generation system, how is power maintained to the essential AC bus-bar?', '[{"id": "a", "text": "By power fed from static inverter only.", "correct": false}, {"id": "b", "text": "By power fed from a battery supplied static inverter.", "correct": true}, {"id": "c", "text": "By power fed from a hot battery bus-bar only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which components within a generator control unit connects the output of the field power supply to the generator exciter?', '[{"id": "a", "text": "Generator control relay.", "correct": true}, {"id": "b", "text": "Generator line contactor.", "correct": false}, {"id": "c", "text": "Generator power pilot relay.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In what units are static inverters rated?', '[{"id": "a", "text": "kVAR.", "correct": false}, {"id": "b", "text": "kVA.", "correct": true}, {"id": "c", "text": "kW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a generator system, a stability winding is used', '[{"id": "a", "text": "to control output current.", "correct": false}, {"id": "b", "text": "in series with the field to prevent oscillations.", "correct": false}, {"id": "c", "text": "to prevent voltage overshoot.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On engine shutdown, what prevents GCR being tripped?', '[{"id": "a", "text": "Under-current.", "correct": false}, {"id": "b", "text": "Under-frequency.", "correct": true}, {"id": "c", "text": "Under-volt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is real and reactive load sharing achieved in an AC parallel generator system?', '[{"id": "a", "text": "Real load by control of the constant speed drives, reactive load by adjustment of generator fields.", "correct": true}, {"id": "b", "text": "Real load by control of generator fields, Reactive loads by adjustment of the constant speed drives.", "correct": false}, {"id": "c", "text": "Real and reactive loads by control of the constant speed drives only. Output voltage is controlled by", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Other than when there is a fault in an aircraft battery or its charging system, when is the charger switched off automatically?', '[{"id": "a", "text": "When there is a failure of one alternator in a split-bus bar system.", "correct": false}, {"id": "b", "text": "When the battery is used for excessively high discharge currents such as in starting.", "correct": true}, {"id": "c", "text": "When the alternators are fully loaded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The trimmer resister in a carbon pile volts regulator is', '[{"id": "a", "text": "in parallel with the generator volts coil.", "correct": false}, {"id": "b", "text": "in series with the generator field.", "correct": false}, {"id": "c", "text": "in series with the generator volts coil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a field relay trips the generator off-line, it can be reset', '[{"id": "a", "text": "after the fault has been cleared.", "correct": true}, {"id": "b", "text": "on the ground only.", "correct": false}, {"id": "c", "text": "by cycling the generator switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a paralleled AC generator system both A phases must be in synchronisation and', '[{"id": "a", "text": "CBA must equal ABC.", "correct": false}, {"id": "b", "text": "phase rotation does not matter.", "correct": false}, {"id": "c", "text": "CBA must equal CBA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When loads are shed from a busbar automatically', '[{"id": "a", "text": "bus bar voltage rises.", "correct": false}, {"id": "b", "text": "bus bar current rises.", "correct": false}, {"id": "c", "text": "bus bar current decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What controls output from the generator?', '[{"id": "a", "text": "BPCU.", "correct": false}, {"id": "b", "text": "ELCU.", "correct": false}, {"id": "c", "text": "GCU.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Specific Gravity in a lead acid battery should give an indication of', '[{"id": "a", "text": "charge.", "correct": true}, {"id": "b", "text": "electrolyte temperature.", "correct": false}, {"id": "c", "text": "electrolyte level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During normal engine shut-down, the generator', '[{"id": "a", "text": "breaker and control relay are both tripped.", "correct": false}, {"id": "b", "text": "control relay is tripped only.", "correct": false}, {"id": "c", "text": "breaker is tripped only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The generator warning light will come on when', '[{"id": "a", "text": "voltage is too high.", "correct": false}, {"id": "b", "text": "voltage is above battery voltage.", "correct": false}, {"id": "c", "text": "voltage is below battery voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When replacing a current transformer', '[{"id": "a", "text": "it can only be fitted one way round.", "correct": true}, {"id": "b", "text": "it can be fitted any way round.", "correct": false}, {"id": "c", "text": "voltage/current selection must be made prior to fitting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The economy coil on a relay', '[{"id": "a", "text": "reduces current required to hold closed.", "correct": true}, {"id": "b", "text": "reduces current required to close.", "correct": false}, {"id": "c", "text": "makes it cheaper to make.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the function of the generator control relay?', '[{"id": "a", "text": "Bring the generator on-line.", "correct": true}, {"id": "b", "text": "Connect the generator to the busbar.", "correct": false}, {"id": "c", "text": "Control output voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The current consumed by a DC starter motor will', '[{"id": "a", "text": "decrease as the engine speed increases.", "correct": true}, {"id": "b", "text": "remain constant.", "correct": false}, {"id": "c", "text": "increase as the engine speed increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A neutralising agent for sulphuric acid is', '[{"id": "a", "text": "sodium bicarbonate.", "correct": true}, {"id": "b", "text": "citric acid.", "correct": false}, {"id": "c", "text": "borax powder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a split bus power distribution system', '[{"id": "a", "text": "each generator supplies its own bus and distribution system in normal operation.", "correct": true}, {"id": "b", "text": "power is split between 115V AC and 28V DC.", "correct": false}, {"id": "c", "text": "generators are paralleled on connection to the tie bus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flashing a generator field', '[{"id": "a", "text": "restores magnetism.", "correct": true}, {"id": "b", "text": "increases resistance.", "correct": false}, {"id": "c", "text": "decreases resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking SG of electrolyte of lead acid battery, what should be taken into account?', '[{"id": "a", "text": "Battery charge.", "correct": false}, {"id": "b", "text": "Electrolyte temperature.", "correct": true}, {"id": "c", "text": "Ambient temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do you check condition of Ni-Cad battery in situ?', '[{"id": "a", "text": "By voltmeter in the cockpit when battery is off load.", "correct": false}, {"id": "b", "text": "By voltmeter connected to the battery terminal.", "correct": false}, {"id": "c", "text": "By voltmeter in the cockpit, when battery is on load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The reactive load circuit in a multi-engined AC generator system', '[{"id": "a", "text": "modifies generator field excitation current.", "correct": true}, {"id": "b", "text": "modifies generator field excitation voltage", "correct": false}, {"id": "c", "text": "modifies generator drive speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A vibrating type voltage regulator uses a volts coil', '[{"id": "a", "text": "in parallel with the generator output.", "correct": true}, {"id": "b", "text": "in series with the generator output.", "correct": false}, {"id": "c", "text": "in series with the current coil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the economy contacts in a relay is to', '[{"id": "a", "text": "reduce the current required to hold the contacts closed.", "correct": true}, {"id": "b", "text": "close the auxiliary contacts before the main contacts.", "correct": false}, {"id": "c", "text": "prevent contact pitting and burning.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A vibrating contact voltage regulator has', '[{"id": "a", "text": "a volts coil in parallel with the points.", "correct": false}, {"id": "b", "text": "a resistor in series with the points.", "correct": false}, {"id": "c", "text": "a resister in parallel with the points.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Brush bedding-in on a starter generator can be carried out', '[{"id": "a", "text": "when 80 percent of the brush area has been previously bedded in, on the bench.", "correct": false}, {"id": "b", "text": "only off the aircraft.", "correct": true}, {"id": "c", "text": "during flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What would be the cause of a low electrolyte level in a nicad battery?', '[{"id": "a", "text": "Evaporation.", "correct": false}, {"id": "b", "text": "Over charging current.", "correct": true}, {"id": "c", "text": "Undercharging current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An AC generator connected to a CSD requires', '[{"id": "a", "text": "no voltage regulator as the CSD will control the voltage.", "correct": false}, {"id": "b", "text": "no voltage regulator as the CSD will control generator frequency.", "correct": false}, {"id": "c", "text": "a separate voltage regulator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If electrolyte from a lead-acid battery is spilled in the battery compartment, which procedure should be followed?', '[{"id": "a", "text": "Apply sodium bicarbonate solution to the affected area followed by a water rinse", "correct": true}, {"id": "b", "text": "Rinse the affected area thoroughly with clean water.", "correct": false}, {"id": "c", "text": "Apply boric acid solution to the affected area followed by a water rinse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which statement regarding the hydrometer reading of a lead-acid storage battery electrolyte is true?', '[{"id": "a", "text": "The hydrometer reading will give a true indication of the capacity of the battery regardless of the electrolyte", "correct": false}, {"id": "b", "text": "temperature.", "correct": false}, {"id": "c", "text": "The hydrometer reading does not require a temperature correction if the electrolyte temperature is 60°F.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An increase in the speed of a DC generator will cause the voltage to rise with the following resultant action in the voltage regulator:-', '[{"id": "a", "text": "The volts coil to exert less pull thus increasing the resistance of the carbon pile.", "correct": false}, {"id": "b", "text": "The volts coil to exert more pull thus increasing the current in the generator field.", "correct": false}, {"id": "c", "text": "The volts coil to increase its magnetic field thus decreasing the field excitation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The equalizing coils on voltage regulators will', '[{"id": "a", "text": "have current passing through them from the higher loaded generator to the lower.", "correct": false}, {"id": "b", "text": "have current passing through them only when the generators are not paralleled.", "correct": false}, {"id": "c", "text": "be connected to each other when the generators are paralleled.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fully charged lead-acid battery will not freeze until extremely low temperatures are reached because', '[{"id": "a", "text": "the acid is in the plates, thereby increasing the specific gravity of the solution.", "correct": false}, {"id": "b", "text": "increased internal resistance generates sufficient heat to prevent freezing.", "correct": false}, {"id": "c", "text": "most of the acid is in the solution.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What determines the amount of current which will flow through a battery while it is being charged by a constant voltage source?', '[{"id": "a", "text": "The ampere-hour capacity of the battery.", "correct": false}, {"id": "b", "text": "The total plate area of the battery.", "correct": false}, {"id": "c", "text": "The state-of-charge of the battery.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The method used to rapidly charge a nickel-cadmium battery utilizes', '[{"id": "a", "text": "constant current and varying voltage.", "correct": false}, {"id": "b", "text": "constant voltage and varying current.", "correct": true}, {"id": "c", "text": "constant current and constant voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The presence of small amounts of potassium carbonate deposits on the top of nickel-cadmium battery cells that have been in service for time is an indication of', '[{"id": "a", "text": "excessive gassing.", "correct": true}, {"id": "b", "text": "normal operation.", "correct": false}, {"id": "c", "text": "excessive plate sulphation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The servicing and charging of nickel-cadmium and lead-acid batteries together in the same service area is likely to result in', '[{"id": "a", "text": "normal battery service life.", "correct": false}, {"id": "b", "text": "increased explosion and/or fire hazard.", "correct": false}, {"id": "c", "text": "contamination of both types of batteries.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the current drawn from No.1 generator of a twin generator DC system is less than that drawn from No.2 generator, the current in the No.2 generator equalizing coil will flow', '[{"id": "a", "text": "in the same direction as the current flow in the voltage coil, reducing the output of No.2 generator.", "correct": true}, {"id": "b", "text": "in the opposite direction to the current flow in the voltage coil, reducing the output of No.2 generator.", "correct": false}, {"id": "c", "text": "in the same direction as the current flow in the voltage coil, increasing the output of No.2 generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a C.S. driven generator, operation of the Disconnect Solenoid will disconnect the generator drive and', '[{"id": "a", "text": "it can only be reset when all loads are switched off.", "correct": false}, {"id": "b", "text": "it will automatically reset itself when the fault is rectified.", "correct": false}, {"id": "c", "text": "resetting can only be carried out on the ground.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a constant frequency AC system, real load sharing is achieved by regulating the', '[{"id": "a", "text": "voltage regulator.", "correct": false}, {"id": "b", "text": "generator drive torque.", "correct": false}, {"id": "c", "text": "generator speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A constant speed drive unit has a warning light indication', '[{"id": "a", "text": "for low speed.", "correct": false}, {"id": "b", "text": "for low oil pressure.", "correct": true}, {"id": "c", "text": "for when it is disconnected from the generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The electrolyte of a nickel-cadmium battery is the lowest when the battery is', '[{"id": "a", "text": "being charged.", "correct": false}, {"id": "b", "text": "in a discharged condition.", "correct": true}, {"id": "c", "text": "under load condition.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Nickel-cadmium batteries which are stored for a long period of time will show a low fluid level because the', '[{"id": "a", "text": "fluid level was not periodically replenished.", "correct": false}, {"id": "b", "text": "fluid evaporates through vents.", "correct": false}, {"id": "c", "text": "electrolyte becomes absorbed in the plates.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How can the state-of-charge of a nickel-cadmium battery be determined?', '[{"id": "a", "text": "By measuring discharge.", "correct": true}, {"id": "b", "text": "By the level of the electrolyte.", "correct": false}, {"id": "c", "text": "By measuring the specific gravity of the electrolyt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What may result if water is added to a nickel-cadmium battery when it is not fully charged?', '[{"id": "a", "text": "No adverse results since water may be added anytime.", "correct": false}, {"id": "b", "text": "The cell temperature will run too low for proper output.", "correct": false}, {"id": "c", "text": "Excessive spewing will occur during the charging cycle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In nickel-cadmium batteries, a rise in cell temperature', '[{"id": "a", "text": "causes an increase in internal resistance.", "correct": false}, {"id": "b", "text": "causes a decrease in internal resistance.", "correct": true}, {"id": "c", "text": "increases cell voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a charging current is applied to a nickel-cadmium battery, the cells emit gas only', '[{"id": "a", "text": "if they are defective.", "correct": false}, {"id": "b", "text": "when the electrolyte level is low.", "correct": true}, {"id": "c", "text": "toward the end of the charging cycle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The equalising coil in the carbon pile regulator', '[{"id": "a", "text": "is connected in series with the carbon pile.", "correct": false}, {"id": "b", "text": "becomes inoperative when the undervolt relay energises.", "correct": false}, {"id": "c", "text": "modifies the effect of the voltage sensing coil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a constant frequency AC system, reactive load sharing is achieved by regulating the', '[{"id": "a", "text": "voltage regulator.", "correct": true}, {"id": "b", "text": "generator drive torque.", "correct": false}, {"id": "c", "text": "generator speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Under-frequency in an AC supply would cause', '[{"id": "a", "text": "overspeeding of AC motors.", "correct": false}, {"id": "b", "text": "overheating of inductive devices.", "correct": true}, {"id": "c", "text": "overvoltage of capacitive devices.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The electrolyte in a lead-acid battery contains', '[{"id": "a", "text": "sulphuric acid.", "correct": true}, {"id": "b", "text": "nitric acid.", "correct": false}, {"id": "c", "text": "hydrochloric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the procedure to be followed after spillage of battery acid, neutralizing may be carried out', '[{"id": "a", "text": "by washing with distilled water.", "correct": false}, {"id": "b", "text": "by applying a coating of petroleum jelly.", "correct": false}, {"id": "c", "text": "with a dilute solution of sodium bicarbonate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Frequency (Hz) is the number of cycles per', '[{"id": "a", "text": "minute.", "correct": false}, {"id": "b", "text": "second", "correct": true}, {"id": "c", "text": "revolution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The three voltages of a three phase generator are', '[{"id": "a", "text": "90 degrees apart.", "correct": false}, {"id": "b", "text": "120 degrees apart.", "correct": true}, {"id": "c", "text": "180 degrees apart.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To restore the level of electrolyte which has been lost due to normal gassing during battery charging', '[{"id": "a", "text": "sulphuric acid must be added.", "correct": false}, {"id": "b", "text": "distilled water must be added.", "correct": true}, {"id": "c", "text": "electrolyte of the same specific gravity as that contained in the battery must be added.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A 12 volt lead-acid battery', '[{"id": "a", "text": "has 24 cells.", "correct": false}, {"id": "b", "text": "has 6 cells.", "correct": true}, {"id": "c", "text": "has 12 cells.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The active component of an A.C. circuit is 4 amps and the reactive is 3 amps. Ammeter reading will be', '[{"id": "a", "text": "5 amps.", "correct": true}, {"id": "b", "text": "7 amps.", "correct": false}, {"id": "c", "text": "3.4 amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a delta connected generator', '[{"id": "a", "text": "phase volts equals 1.73 line volts.", "correct": false}, {"id": "b", "text": "line volts equals 1.73 phase volts.", "correct": false}, {"id": "c", "text": "line volts equals phase volts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The only practical method of maintaining a constant voltage output from an aircraft generator under varying conditions of speed and load is to vary the', '[{"id": "a", "text": "strength of the magnetic field.", "correct": true}, {"id": "b", "text": "number of conductors in the armature.", "correct": false}, {"id": "c", "text": "speed at which the armature rotates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As the generator load is increased (within its rated capacity), the voltage will', '[{"id": "a", "text": "remain constant and the amperage output will increase.", "correct": false}, {"id": "b", "text": "remain constant and the amperage output will decrease.", "correct": false}, {"id": "c", "text": "decrease and the amperage output will increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking the specific gravity of the electrolyte in a battery', '[{"id": "a", "text": "one cell only need be checked as the remainder will read the same.", "correct": false}, {"id": "b", "text": "only the end cells need be checked as they contain the terminals.", "correct": false}, {"id": "c", "text": "each cell should be checked as the readings may differ.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A lead-acid battery is considered to be fully charged when the', '[{"id": "a", "text": "cells begin to gas freely.", "correct": false}, {"id": "b", "text": "S.G. reaches 1.180.", "correct": false}, {"id": "c", "text": "S.G. and voltage remain constant for specified period.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which aircraft circuit would be most likely to use frequency wild 200V AC?', '[{"id": "a", "text": "Hydraulic pump.", "correct": false}, {"id": "b", "text": "Standby compass.", "correct": false}, {"id": "c", "text": "Windscreen heating.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To prevent corrosion at the terminals of a lead-acid battery', '[{"id": "a", "text": "copper connectors are used.", "correct": false}, {"id": "b", "text": "the connectors may be painted.", "correct": false}, {"id": "c", "text": "petroleum jelly may be applied to the connections.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before taking S.G. readings of a lead-acid battery recently removed from an aircraft', '[{"id": "a", "text": "the battery must be charged at the 10 hour rate for one hour.", "correct": false}, {"id": "b", "text": "a period of 1 hour should have elapsed to allow the S.G. to stabilize.", "correct": false}, {"id": "c", "text": "the electrolyte temperature must be noted.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The output of a DC generator is controlled by varying the', '[{"id": "a", "text": "engine speed.", "correct": false}, {"id": "b", "text": "field current.", "correct": true}, {"id": "c", "text": "armature current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A generator rated at 30 kVA power factor 0.8 has a maximum continuous power output of', '[{"id": "a", "text": "37.5 kW.", "correct": false}, {"id": "b", "text": "24 kW.", "correct": true}, {"id": "c", "text": "30 kW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The specific gravity of the electrolyte in a lead-acid battery', '[{"id": "a", "text": "remains constant with changes in the state of charge but is a useful guide to the amount of acid contained in", "correct": false}, {"id": "b", "text": "the electrolyte.", "correct": false}, {"id": "c", "text": "changes with the state of charge and is therefore a measure of the state of charge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A battery which is assumed to be 100% efficient and to have a capacity of 60 ampere-hours at the 10 hour rate will deliver', '[{"id": "a", "text": "60 amps for 10 hours.", "correct": false}, {"id": "b", "text": "60 amps for 10 hours or 6 amps for 10 hours depending upon the rate of demand.", "correct": false}, {"id": "c", "text": "6 amps for 10 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Two 12V 25 ampere batteries connected in series will produce', '[{"id": "a", "text": "12V with 25 ampere hour capacity.", "correct": false}, {"id": "b", "text": "12V with 50 ampere hour capacity.", "correct": false}, {"id": "c", "text": "24V with 25 ampere hour capacity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As an installed battery becomes fully charged by the aircraft generator', '[{"id": "a", "text": "the battery contactor isolates the battery from the generator.", "correct": false}, {"id": "b", "text": "the battery voltage nears its nominal level so the charging current decreases.", "correct": true}, {"id": "c", "text": "the generator voltage decreases to supply the steadily decreasing current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a DC shunt generator without a voltage regulator, if the load increases the generator output voltage will', '[{"id": "a", "text": "decrease", "correct": true}, {"id": "b", "text": "increase", "correct": false}, {"id": "c", "text": "remain constant", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For battery charging, the electrical supply connected to the battery must be', '[{"id": "a", "text": "AC at 50 c.p.s.", "correct": false}, {"id": "b", "text": "DC.", "correct": true}, {"id": "c", "text": "AC at 400 c.p.s.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When using A.C. power on the bus bar you require 28V D.C. for battery charging', '[{"id": "a", "text": "an A.C. transformer and rectifier would be required.", "correct": true}, {"id": "b", "text": "a D.C. transformer and rectifier would be required.", "correct": false}, {"id": "c", "text": "an A.C. inverter would be required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Two similar 12V batteries connected in parallel will produce', '[{"id": "a", "text": "12V e.m.f. with twice the capacity of each battery", "correct": true}, {"id": "b", "text": "24V e.m.f. with the same capacity as each battery.", "correct": false}, {"id": "c", "text": "24V e.m.f. with twice the capacity of each battery.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a nicad battery overheats, it is an indication of', '[{"id": "a", "text": "the generator voltage regulator setting is too low.", "correct": false}, {"id": "b", "text": "thermal runaway.", "correct": true}, {"id": "c", "text": "the generator is not connected to the bus bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The output from an AC generator is taken from', '[{"id": "a", "text": "connections on the stator.", "correct": true}, {"id": "b", "text": "slip rings.", "correct": false}, {"id": "c", "text": "slip rings via commutator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Load sharing on a DC generation system is achieved by', '[{"id": "a", "text": "circulating currents affecting the carbon pile for voltage trimming.", "correct": true}, {"id": "b", "text": "the load differences causing torque signals to vary the engine speed.", "correct": false}, {"id": "c", "text": "tachogenerators varying the generators outputs as the engine speed varies.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a nickel cadmium aircraft battery is not required for immediate service, it should be stored', '[{"id": "a", "text": "in the fully discharged condition.", "correct": true}, {"id": "b", "text": "in a totally dry condition.", "correct": false}, {"id": "c", "text": "in the fully charged condition.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The correct way to determine the state of charge of a nickel-cadmium battery is', '[{"id": "a", "text": "by checking the specific gravity of each cell.", "correct": false}, {"id": "b", "text": "by a complete discharge and a measured recharge.", "correct": true}, {"id": "c", "text": "by checking the voltage of each cell under load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A DC generator will be connected to the busbar after the RCCO contacts close due to', '[{"id": "a", "text": "increasing battery voltage.", "correct": false}, {"id": "b", "text": "increasing generator voltage.", "correct": true}, {"id": "c", "text": "a differential voltage of 0.5V battery voltage higher than generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Spillage of a lead acid electrolyte is detected by', '[{"id": "a", "text": "indicating paper that turns blue.", "correct": false}, {"id": "b", "text": "litmus paper that turns black.", "correct": false}, {"id": "c", "text": "indicating paper that turns red.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To restore electrolyte after spillage', '[{"id": "a", "text": "add distilled water only.", "correct": false}, {"id": "b", "text": "add a mixture of acid and water of the same s.g. as that in the battery.", "correct": true}, {"id": "c", "text": "add acid only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a DC generator fails, the pilot will receive the following indications:-', '[{"id": "a", "text": "Zero current on the ammeter and a red PFWL.", "correct": true}, {"id": "b", "text": "Rising voltage and current discharge with a red PFWL.", "correct": false}, {"id": "c", "text": "An audio bell and red PFWL.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of an inverter is to convert', '[{"id": "a", "text": "DC to AC.", "correct": true}, {"id": "b", "text": "AC to a higher frequency AC.", "correct": false}, {"id": "c", "text": "AC to DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a vibrating-contact type voltage regulator the adjustment of generator voltage is carried out by', '[{"id": "a", "text": "adjustment of voltage coil resistance.", "correct": false}, {"id": "b", "text": "alteration of the field resistance.", "correct": false}, {"id": "c", "text": "alteration of contact spring tension.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Battery SG is measured using a', '[{"id": "a", "text": "hygrometer.", "correct": false}, {"id": "b", "text": "hydrometer.", "correct": true}, {"id": "c", "text": "hypsometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A battery for use on aircraft must have a capacity of', '[{"id": "a", "text": "90%.", "correct": false}, {"id": "b", "text": "80%.", "correct": true}, {"id": "c", "text": "50%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When connecting aircraft batteries, the last lead to connect is the', '[{"id": "a", "text": "positive earth.", "correct": false}, {"id": "b", "text": "positive.", "correct": false}, {"id": "c", "text": "negative.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Polarization in a cell is', '[{"id": "a", "text": "the fact that hydrogen bubbles form on the -ve plate.", "correct": true}, {"id": "b", "text": "the fact that as a battery discharges, the -ve plate''s potential approaches that of the +ve plate''s.", "correct": false}, {"id": "c", "text": "the establishing of a potential across the cell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Battery capacity is checked by', '[{"id": "a", "text": "discharging at a constant current and checking the time taken to reach the discharged state.", "correct": true}, {"id": "b", "text": "measuring the terminal voltage whilst on load and multiplying by the current drawn.", "correct": false}, {"id": "c", "text": "discharging while maintaining the voltage constant by varying a resistor in the circuit and checking the time", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The frequency of an AC generator is dependant on the', '[{"id": "a", "text": "field strength and the speed of the generator.", "correct": false}, {"id": "b", "text": "number of pairs of poles and the speed of the rotor.", "correct": true}, {"id": "c", "text": "number of conductors and the field strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To adjust the voltage output of an AC generator, whilst maintaining constant frequency, it is necessary to', '[{"id": "a", "text": "alter the driving speed.", "correct": false}, {"id": "b", "text": "alter the field current.", "correct": true}, {"id": "c", "text": "alter the reactance of the stator winding circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a paralleled AC generation system load sharing is for', '[{"id": "a", "text": "reactive load only.", "correct": false}, {"id": "b", "text": "real load only.", "correct": false}, {"id": "c", "text": "real and reactive load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Single phase components in a 3 phase system may be connected between', '[{"id": "a", "text": "any phase and earth or between any two phases.", "correct": true}, {"id": "b", "text": "phases A and B only.", "correct": false}, {"id": "c", "text": "the phase and earth only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A frequency wild supply would be suitable for', '[{"id": "a", "text": "deicing loads.", "correct": true}, {"id": "b", "text": "3-phase torque motors.", "correct": false}, {"id": "c", "text": "instruments and navigation systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Three 12V, 40Ah accumulators in series would give', '[{"id": "a", "text": "36V 40Ah.", "correct": true}, {"id": "b", "text": "12V 120Ah.", "correct": false}, {"id": "c", "text": "36V 120Ah.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Three 12V, 40Ah accumulators in parallel would give', '[{"id": "a", "text": "36V 120Ah.", "correct": false}, {"id": "b", "text": "12V 120Ah.", "correct": true}, {"id": "c", "text": "12V 40Ah.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An inverter can be an AC generator driven by', '[{"id": "a", "text": "a DC motor.", "correct": true}, {"id": "b", "text": "an AC motor.", "correct": false}, {"id": "c", "text": "either an AC or DC motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When mixing electrolyte for lead acid batteries', '[{"id": "a", "text": "add water to acid.", "correct": false}, {"id": "b", "text": "the method of mixing is unimportant.", "correct": false}, {"id": "c", "text": "add acid to water.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The RPM of a 6 pole, 400 Hz alternator is', '[{"id": "a", "text": "6000.", "correct": false}, {"id": "b", "text": "8000.", "correct": true}, {"id": "c", "text": "4000.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Apparent power is measured in', '[{"id": "a", "text": "Volt Amps.", "correct": true}, {"id": "b", "text": "Kilovolts.", "correct": false}, {"id": "c", "text": "Watts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Ni-Cad battery consists of 19, 1.2 volt cells. What will be the nominal battery output?', '[{"id": "a", "text": "24V.", "correct": false}, {"id": "b", "text": "22V.", "correct": true}, {"id": "c", "text": "20V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The preferred method of battery charging a Ni-Cad battery is constant', '[{"id": "a", "text": "voltage.", "correct": false}, {"id": "b", "text": "speed.", "correct": false}, {"id": "c", "text": "current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When operating two AC generators unparalleled, the phase of each', '[{"id": "a", "text": "must be in opposition to one another.", "correct": false}, {"id": "b", "text": "is unimportant.", "correct": true}, {"id": "c", "text": "must be synchronized.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the GPU is connected to the aircraft', '[{"id": "a", "text": "it is not paralleled with the aircraft generator.", "correct": true}, {"id": "b", "text": "it is paralleled with the aircraft generator.", "correct": false}, {"id": "c", "text": "it supplies essential services.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A lead-acid battery with 12 cells connected in series (no-load voltage = 2.1 volts per cell) furnishes 10 amperes to a load of 2 ohms resistance. The internal resistance of the battery in this instance is', '[{"id": "a", "text": "5.0 ohms.", "correct": false}, {"id": "b", "text": "0.52 ohms.", "correct": true}, {"id": "c", "text": "2.52 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rating of an aircraft alternator is 40 KVA at PF 0.8 lagging..', '[{"id": "a", "text": "The maximum load under all conditions is 40KW..", "correct": false}, {"id": "b", "text": "The maximum load under all conditions is 40KVA..", "correct": false}, {"id": "c", "text": "The maximum load permitted is 32KW.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An I.D.G (integrated drive generator)', '[{"id": "a", "text": "incorporates the alternator and CSD as one unit.", "correct": true}, {"id": "b", "text": "has separate CSDU.", "correct": false}, {"id": "c", "text": "does not require a CSDU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A P.M.G (Permanent Magnet Generator) is a small built in generator which', '[{"id": "a", "text": "provides initial excitation.", "correct": true}, {"id": "b", "text": "only rotates during starting.", "correct": false}, {"id": "c", "text": "only rotates after starting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To parallel an alternator with another alternator the alternators must have the same', '[{"id": "a", "text": "frequency, RPM and phase relationship.", "correct": false}, {"id": "b", "text": "frequency, voltage and phase relationship.", "correct": true}, {"id": "c", "text": "frequency, RPM and speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Speed of an alternator may be controlled by', '[{"id": "a", "text": "keeping engine rpm constant.", "correct": false}, {"id": "b", "text": "varying the field current.", "correct": false}, {"id": "c", "text": "CSDU (constant speed drive unit).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Frequency wild'' alternators supply', '[{"id": "a", "text": "resistive circuits.", "correct": true}, {"id": "b", "text": "inductive circuits.", "correct": false}, {"id": "c", "text": "capacitive circuits.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The real load of an alternator is directly related to', '[{"id": "a", "text": "output shaft rpm.", "correct": false}, {"id": "b", "text": "output voltage.", "correct": false}, {"id": "c", "text": "output shaft torque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is initial voltage build-up ensured in a brushless generating system, before full output is available from the voltage regulator?', '[{"id": "a", "text": "Permanent magnets are mounted between the exciter field poles.", "correct": true}, {"id": "b", "text": "A switch must be operated by the crew to provide excitation form the dc busbar to bring generator on line.", "correct": false}, {"id": "c", "text": "Excitation from the DC busbars is automatically provided during the start sequence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Insulation resistance of electrical machines is', '[{"id": "a", "text": "normally lower when the machine is hot.", "correct": true}, {"id": "b", "text": "not affected by change of temperature of machine.", "correct": false}, {"id": "c", "text": "normally higher when the machine is hot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a thermistor in a brushless AC generator is to', '[{"id": "a", "text": "keep the resistance of the rectifiers nearly constant at varying temperatures.", "correct": false}, {"id": "b", "text": "compensate for temperature changes in the main AC stator windings.", "correct": false}, {"id": "c", "text": "keep the exciter field resistance nearly constant at varying temperatures.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The term ''random paralleling'' means the incoming alternator''s output voltage frequency and phase relationship is', '[{"id": "a", "text": "the outputs are constant.", "correct": false}, {"id": "b", "text": "the same.", "correct": false}, {"id": "c", "text": "not the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One lamp is connected across corresponding phases of two alternators. They will be synchronised when', '[{"id": "a", "text": "the lamp is extinguished.", "correct": true}, {"id": "b", "text": "the lamp is either at maximum brightness or is extinguished.", "correct": false}, {"id": "c", "text": "the lamp is maximum brightness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Automatic synchronising means that the incoming alternator''s voltage and frequency', '[{"id": "a", "text": "can be synchronised using the two lamps provided at the system''s panel.", "correct": false}, {"id": "b", "text": "can be checked at the system''s electrical panel by selecting the relevant alternator.", "correct": true}, {"id": "c", "text": "cannot be checked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The danger of random paralleling is the possibility of', '[{"id": "a", "text": "ground power disconnection.", "correct": false}, {"id": "b", "text": "disconnection of the other alternators.", "correct": false}, {"id": "c", "text": "crash engagement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is monitored in a constant speed drive?', '[{"id": "a", "text": "High oil temperature and low oil press.", "correct": true}, {"id": "b", "text": "Low oil press and CSD speed.", "correct": false}, {"id": "c", "text": "Low oil temperature and low oil press.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The CSD or IDG speed governor setting', '[{"id": "a", "text": "is not allowed to be adjusted.", "correct": false}, {"id": "b", "text": "is adjusted with the engine stationary.", "correct": false}, {"id": "c", "text": "is adjusted with the engine running.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An external ground power supply can be used for', '[{"id": "a", "text": "only the emergency busbar services.", "correct": false}, {"id": "b", "text": "all normal services required by flight and ground crew.", "correct": true}, {"id": "c", "text": "only the ground handling busbar services.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The APU generator can normally be', '[{"id": "a", "text": "connected in parallel with the aircraft''s main generators.", "correct": false}, {"id": "b", "text": "used during flight as a back up supply if the main aircraft supply fails.", "correct": true}, {"id": "c", "text": "connected in parallel with the ground power supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The impedance on a run of co-axial cable is', '[{"id": "a", "text": "inversely proportional to the length of cable.", "correct": false}, {"id": "b", "text": "proportional to the length of cable.", "correct": false}, {"id": "c", "text": "not affected by length of cable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Galley loads are supplied from the', '[{"id": "a", "text": "main bus bar.", "correct": true}, {"id": "b", "text": "ground service bus.", "correct": false}, {"id": "c", "text": "battery bus bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A ni-cad battery is stored in the', '[{"id": "a", "text": "dry condition.", "correct": false}, {"id": "b", "text": "fully charged condition.", "correct": false}, {"id": "c", "text": "fully discharged condition.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A 6-diode Transformer Rectifier Unit (TRU) changes', '[{"id": "a", "text": "single phase AC to direct current.", "correct": false}, {"id": "b", "text": "direct current to AC.", "correct": false}, {"id": "c", "text": "three phase AC to direct current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A frequency wild AC generator is used for', '[{"id": "a", "text": "deicing loads.", "correct": true}, {"id": "b", "text": "fluorescent lights.", "correct": false}, {"id": "c", "text": "instruments.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What should you do if the electrolyte is found to be low in one cell of a lead acid battery?', '[{"id": "a", "text": "Replace the defective cell.", "correct": false}, {"id": "b", "text": "Top-up the individual cell with distilled water.", "correct": true}, {"id": "c", "text": "Cell is defective, replace the battery.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of the diode on a contactor?', '[{"id": "a", "text": "Prevent spikes.", "correct": true}, {"id": "b", "text": "Prevent bounce.", "correct": false}, {"id": "c", "text": "To prevent current going the wrong way.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Megaphones must be stowed so they can withstand an inertia force of', '[{"id": "a", "text": "9g.", "correct": true}, {"id": "b", "text": "15g.", "correct": false}, {"id": "c", "text": "12g.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cylinder in a life jacket is inflated using', '[{"id": "a", "text": "compressed air.", "correct": false}, {"id": "b", "text": "CO2.", "correct": true}, {"id": "c", "text": "nitrogen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilets must have a smoke detection system', '[{"id": "a", "text": "that gives a warning light in the cockpit.", "correct": true}, {"id": "b", "text": "connected to a pump to pump the smoke out.", "correct": false}, {"id": "c", "text": "that gives a warning light in the cockpit and an aural warning in the main cabin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If seat belt stitching is worn, where are the replacement stitches placed?', '[{"id": "a", "text": "Over the originals.", "correct": true}, {"id": "b", "text": "Diagonally.", "correct": false}, {"id": "c", "text": "Alongside the original.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Type and Quantity of emergency equipment to be carried is specified in which document?', '[{"id": "a", "text": "Schedule 4 of the ANO.", "correct": true}, {"id": "b", "text": "CAAIPs Leaflet 5-7.", "correct": false}, {"id": "c", "text": "Airworthiness Notice 79.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Life jackets are inflated with cylinders of', '[{"id": "a", "text": "Nitrogen.", "correct": false}, {"id": "b", "text": "air.", "correct": false}, {"id": "c", "text": "CO2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After a successful ditching, the liferafts deployment will', '[{"id": "a", "text": "have detailed instructions in a booklet in a seat pocket.", "correct": false}, {"id": "b", "text": "be briefed by the cabin crew.", "correct": false}, {"id": "c", "text": "be rapid and obvious with easily and readily displayed instructions adjacent to the liferafts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cargo and baggage compartments in which a fire is completely confined come under', '[{"id": "a", "text": "Class B.", "correct": false}, {"id": "b", "text": "Class C.", "correct": false}, {"id": "c", "text": "Class D.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do you clean seat belts?', '[{"id": "a", "text": "With MEK.", "correct": false}, {"id": "b", "text": "With white spirit.", "correct": false}, {"id": "c", "text": "With warm water with low alkalinity soap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pilot''s safety harness buckle and adjustment strap is', '[{"id": "a", "text": "not allowed to slip under any forces.", "correct": true}, {"id": "b", "text": "allowed to slip if vertical acceleration exceeds 5G.", "correct": false}, {"id": "c", "text": "allowed to slip if side loads exceed 2.5 G.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How often are life jackets inspected?', '[{"id": "a", "text": "Every 12 months.", "correct": false}, {"id": "b", "text": "In accordance with the AMM.", "correct": false}, {"id": "c", "text": "In accordance with the manufacturers specification.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Inspection proof testing of seat-belts is carried out to', '[{"id": "a", "text": "4.5g.", "correct": false}, {"id": "b", "text": "9g.", "correct": true}, {"id": "c", "text": "0.5g.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where would you find information regarding galley equipment?', '[{"id": "a", "text": "BCARs.", "correct": false}, {"id": "b", "text": "ANO.", "correct": false}, {"id": "c", "text": "AWN 99.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where the aircraft passenger seating capacity exceeds 149 but less than 200 then:', '[{"id": "a", "text": "1 megaphone is required.", "correct": false}, {"id": "b", "text": "3 megaphones are required.", "correct": false}, {"id": "c", "text": "2 megaphones are required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where would you find information on life-raft deployment?', '[{"id": "a", "text": "Cabin safety on-board card.", "correct": false}, {"id": "b", "text": "Cabin operations manual.", "correct": true}, {"id": "c", "text": "JARs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When testing emergency slide bottles', '[{"id": "a", "text": "any pin could be checked by connecting directly to ground.", "correct": false}, {"id": "b", "text": "one pin must be grounded to the cartridge body at one time.", "correct": false}, {"id": "c", "text": "all three pins must be shorted together and grounded to the cartridge body.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The minimum passenger aisle width for an aircraft with a seating capacity of 20 or more is', '[{"id": "a", "text": "15 inches.", "correct": true}, {"id": "b", "text": "dependant upon aircraft type.", "correct": false}, {"id": "c", "text": "24 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aircraft emergency escape slides are usually pressurised with', '[{"id": "a", "text": "helium.", "correct": false}, {"id": "b", "text": "CO2.", "correct": true}, {"id": "c", "text": "oxygen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The CO2 in a life raft is released', '[{"id": "a", "text": "manually.", "correct": true}, {"id": "b", "text": "on contact with water.", "correct": false}, {"id": "c", "text": "electrically.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vertical projected separation between seat rows must be', '[{"id": "a", "text": "5 inches.", "correct": false}, {"id": "b", "text": "4 inches.", "correct": false}, {"id": "c", "text": "3 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the minimum distance between a seat cushion and the seat in-front of it?', '[{"id": "a", "text": "10 inches", "correct": false}, {"id": "b", "text": "7 inches", "correct": true}, {"id": "c", "text": "5 inches", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A galley catering trolley with electrics is classed as', '[{"id": "a", "text": "a controlled item.", "correct": true}, {"id": "b", "text": "an uncontrolled item.", "correct": false}, {"id": "c", "text": "neither, as it is removable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What placard must be visible above a waste paper bin in a toilet?', '[{"id": "a", "text": "No Naked Flame.", "correct": false}, {"id": "b", "text": "No Smoking.", "correct": true}, {"id": "c", "text": "No Cigarettes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Attendant call is achieved by pressing a button on the passenger service unit (PSU). To reset the light', '[{"id": "a", "text": "the button is pulled out.", "correct": false}, {"id": "b", "text": "a reset switch on the attendants panel is operated.", "correct": false}, {"id": "c", "text": "the button is pushed again.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hot fluids in an aircraft galley must have closed container lids at temperatures above', '[{"id": "a", "text": "45°C.", "correct": true}, {"id": "b", "text": "65°C.", "correct": false}, {"id": "c", "text": "55°C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ''fasten seatbelt'' light switch should be in reach of the', '[{"id": "a", "text": "captain.", "correct": false}, {"id": "b", "text": "first officer.", "correct": false}, {"id": "c", "text": "both the captain and the first officer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the EASA regulation of the minimum separation between a seat and another seat or structure?', '[{"id": "a", "text": "10 inches", "correct": false}, {"id": "b", "text": "There is no EASA guideline.", "correct": false}, {"id": "c", "text": "7 inches", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the minimum separation between a seat back cushion and another seat or fixed structure?', '[{"id": "a", "text": "26 inches.", "correct": true}, {"id": "b", "text": "24 inches.", "correct": false}, {"id": "c", "text": "28 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With regard to forward/rearward passenger seat installation', '[{"id": "a", "text": "you can only fit seats as stated in the Declaration of Design and Performance (DPP).", "correct": true}, {"id": "b", "text": "you can fit seats facing forward or rearward.", "correct": false}, {"id": "c", "text": "you can only fit seats facing forward.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is information regarding flame resistant furnishing materials?', '[{"id": "a", "text": "CAAIPs", "correct": false}, {"id": "b", "text": "AWN 58", "correct": false}, {"id": "c", "text": "CAP 747 Mandatory Requirements for Airworthiness", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When loading a cargo aircraft', '[{"id": "a", "text": "the CofG limits of the aircraft could be exceeded under careful monitored circumstances.", "correct": false}, {"id": "b", "text": "the weight limits of the aircraft could be exceeded under careful monitored circumstances.", "correct": false}, {"id": "c", "text": "the manufacturer specifies the maximum floor loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The minimum vertical projected separation between seat rows is', '[{"id": "a", "text": "5 inches.", "correct": false}, {"id": "b", "text": "7 inches.", "correct": false}, {"id": "c", "text": "3 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cargo nets are manufactured from', '[{"id": "a", "text": "polypropylene.", "correct": false}, {"id": "b", "text": "hessian.", "correct": false}, {"id": "c", "text": "nylon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Galley trolleys must have placards indicating', '[{"id": "a", "text": "Must be stowed for take-off, landing and turbulence.", "correct": true}, {"id": "b", "text": "maximum weight, position, flight number.", "correct": false}, {"id": "c", "text": "location, position, flight number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'PTV type entertainment equipment', '[{"id": "a", "text": "has no capacity for digital information processing and transmitting.", "correct": false}, {"id": "b", "text": "is installed with seat electronic unit and multiplexing techniques.", "correct": true}, {"id": "c", "text": "is not the part of maintenance schedule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What type of brakes are employed on a galley cart?', '[{"id": "a", "text": "A brake on one wheel only.", "correct": false}, {"id": "b", "text": "Two colour-coded pedals.", "correct": true}, {"id": "c", "text": "A single pedal bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On large aeroplanes, containerised cargo is held down by', '[{"id": "a", "text": "side cart guides and fore and aft latches.", "correct": true}, {"id": "b", "text": "rope.", "correct": false}, {"id": "c", "text": "netting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Galley equipment which does not need electrical power is called', '[{"id": "a", "text": "controlled equipment.", "correct": false}, {"id": "b", "text": "uncontrolled equipment.", "correct": true}, {"id": "c", "text": "minimum equipment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A galley trolley will be designed to', '[{"id": "a", "text": "does not matter as the trolleys move.", "correct": false}, {"id": "b", "text": "not exceed the floor limits more than 3 times in one hour.", "correct": false}, {"id": "c", "text": "not exceed the floor loading limits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Information on Galley equipment can be found in', '[{"id": "a", "text": "BCAR Section L", "correct": false}, {"id": "b", "text": "Airworthiness Notice 99", "correct": true}, {"id": "c", "text": "CAAIPS", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On pulling the fire handle, the aural warning', '[{"id": "a", "text": "stays on, the light extinguishes, the generator goes off line.", "correct": false}, {"id": "b", "text": "goes off, the light remains on, the generator goes off line.", "correct": true}, {"id": "c", "text": "goes off, the light goes off, hydraulics, bleed air and generator goes off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Chemical fire extinguishers extinguish fires by', '[{"id": "a", "text": "cools the material on fire below ignition point.", "correct": false}, {"id": "b", "text": "releases oxygen to extinguish the fire.", "correct": false}, {"id": "c", "text": "reacting with the oxygen in the air or the flame, rendering it inert.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire test is carried out and the test button is released, but the light remains on. This is because', '[{"id": "a", "text": "there is a fire.", "correct": false}, {"id": "b", "text": "of a high resistance fire wire.", "correct": false}, {"id": "c", "text": "of a broken fire wire.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection system can pass through one zone to another providing', '[{"id": "a", "text": "the system is duplicated.", "correct": false}, {"id": "b", "text": "it is separated by steel.", "correct": false}, {"id": "c", "text": "the system is protected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilet smoke detectors activate', '[{"id": "a", "text": "a warning light and/or indication in cabin.", "correct": true}, {"id": "b", "text": "an auto sprinkler system.", "correct": false}, {"id": "c", "text": "an electric pump to auto vent smoke to atmosphere.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Engine fire bottle pressure at 70°F is', '[{"id": "a", "text": "1250 psi +/- 25.", "correct": false}, {"id": "b", "text": "600psi +/- 25.", "correct": true}, {"id": "c", "text": "1500 psi +/- 25.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the event of a fire being caused by the oxygen supply', '[{"id": "a", "text": "oxygen supply must be stopped.", "correct": true}, {"id": "b", "text": "a dry powder extinguisher is used.", "correct": false}, {"id": "c", "text": "a carbon dioxide extinguisher is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After a fire detection system test, the red light remains ON. This indicates', '[{"id": "a", "text": "high resistance.", "correct": false}, {"id": "b", "text": "a fire.", "correct": false}, {"id": "c", "text": "a short circuit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'First digit number of halogenated hydrocarbon extinguishers represents the number of', '[{"id": "a", "text": "fluorine atoms.", "correct": false}, {"id": "b", "text": "chlorine atoms.", "correct": false}, {"id": "c", "text": "carbon atoms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What type of gas is used as a propellant for a high rate of discharge extinguishing system?', '[{"id": "a", "text": "Carbon dioxide", "correct": false}, {"id": "b", "text": "Nitrogen", "correct": true}, {"id": "c", "text": "Hydrogen", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection system should be', '[{"id": "a", "text": "designed to withstand vibration & mechanical loads sustained during normal operation.", "correct": false}, {"id": "b", "text": "designed to detect fires only.", "correct": false}, {"id": "c", "text": "positioned in a location determined by the manufacture during the design.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which areas of a civil transport aircraft would have smoke detectors fitted?', '[{"id": "a", "text": "Main wheel bays and engine bays.", "correct": false}, {"id": "b", "text": "Passenger cabins and integral fuel tanks.", "correct": false}, {"id": "c", "text": "Freight holds, baggage compartments and equipment bays.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A short circuit on a fire detection element will result in', '[{"id": "a", "text": "system does not work and no readings.", "correct": true}, {"id": "b", "text": "red fire warning light.", "correct": false}, {"id": "c", "text": "false alarm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In which of the following would you expect to find a smoke detector?', '[{"id": "a", "text": "undercarriage bay", "correct": false}, {"id": "b", "text": "APU bay", "correct": false}, {"id": "c", "text": "Battery bay", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'You would expect to find a squib connected to', '[{"id": "a", "text": "a fire suppression system.", "correct": true}, {"id": "b", "text": "a fire detection system.", "correct": false}, {"id": "c", "text": "a smoke detection system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Engine wing firebottles should be charged with nitrogen at 15°C to', '[{"id": "a", "text": "1250 psi.", "correct": false}, {"id": "b", "text": "600 psi.", "correct": true}, {"id": "c", "text": "1500 psi.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire that can be put out by a crew member in a cargo bay is in a', '[{"id": "a", "text": "class B compartment.", "correct": true}, {"id": "b", "text": "class D compartment.", "correct": false}, {"id": "c", "text": "class A compartment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a capacitive fire detection system, if', '[{"id": "a", "text": "there is a break, the system will not work.", "correct": false}, {"id": "b", "text": "there is a break, the system will work but not test satisfactory.", "correct": true}, {"id": "c", "text": "there is a short to earth, the system will work but not test satisfactory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection zone wiring can pass through another fire zone when', '[{"id": "a", "text": "the system is different but the extinguishant is the same.", "correct": false}, {"id": "b", "text": "the system and the extinguishing system are the same.", "correct": true}, {"id": "c", "text": "the system is the same but the extinguishant is different.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a fire test on a Systron Donor fire detector system is carried out', '[{"id": "a", "text": "the signal passes through the centre and back through the outer to give warning.", "correct": false}, {"id": "b", "text": "it checks the integrity of the contacts.", "correct": true}, {"id": "c", "text": "a signal passes through the unbroken centre conductor to produce the warning.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When inspecting lavatory installations', '[{"id": "a", "text": "the ashtray must be made of a thermoplastic material.", "correct": false}, {"id": "b", "text": "the ashtray should not be located close to the toilet paper holder.", "correct": true}, {"id": "c", "text": "''No Smoking'' sign should be fitted next to the ashtrays only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Lavatories must have, in the disposal container', '[{"id": "a", "text": "water/glycol extinguisher with white ball markings indicating when discharged.", "correct": false}, {"id": "b", "text": "Freon extinguisher with black ball markings indicating when discharged.", "correct": true}, {"id": "c", "text": "Freon extinguisher with white ball markings indicating when discharged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection loop must be capable of', '[{"id": "a", "text": "using master warning visual signals only.", "correct": false}, {"id": "b", "text": "using master warning visual and aural signals.", "correct": true}, {"id": "c", "text": "detecting fire/overheat condition within 5 seconds and extinguishing such that after 30 seconds the", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Systron-Donner fire detection system uses', '[{"id": "a", "text": "helium gas.", "correct": true}, {"id": "b", "text": "oxygen gas.", "correct": false}, {"id": "c", "text": "nitrogen gas.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Systron-Donner fire detection system uses', '[{"id": "a", "text": "to protect against continuous flushing.", "correct": false}, {"id": "b", "text": "to protect against the dangers of smoke and fire in the event of an overheat.", "correct": true}, {"id": "c", "text": "to protect against freezing at altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What external warning is there for an APU fire?', '[{"id": "a", "text": "Aural.", "correct": false}, {"id": "b", "text": "Red light.", "correct": false}, {"id": "c", "text": "Both aural and a red light.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Engine fire bottle pressure switches are operated by', '[{"id": "a", "text": "AC or DC.", "correct": false}, {"id": "b", "text": "DC.", "correct": true}, {"id": "c", "text": "AC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fire tests on aircraft internal furnishings must be carried out', '[{"id": "a", "text": "only when equipment items fail random tests.", "correct": true}, {"id": "b", "text": "every two years.", "correct": false}, {"id": "c", "text": "every five years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cockpit check on the engine firewire system is a', '[{"id": "a", "text": "continuity check.", "correct": true}, {"id": "b", "text": "calibration check.", "correct": false}, {"id": "c", "text": "function check.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the fire handle is operated it', '[{"id": "a", "text": "cuts off fuel and hydraulics. Generator remains on line to provide electrical power.", "correct": false}, {"id": "b", "text": "cuts off field current, hydraulics and fuel and operates fire extinguishers.", "correct": true}, {"id": "c", "text": "operates fire extinguisher only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the contamination monitor for, in a Systron Donner fire detection system?', '[{"id": "a", "text": "Integrity comparator.", "correct": false}, {"id": "b", "text": "Volts drop.", "correct": false}, {"id": "c", "text": "Dirty contacts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fireproofing of cabin material should be done', '[{"id": "a", "text": "every 5 years.", "correct": false}, {"id": "b", "text": "when a sample fails.", "correct": true}, {"id": "c", "text": "every 2 years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What test is carried out to ensure serviceability of a squib?', '[{"id": "a", "text": "Bottles are fired.", "correct": false}, {"id": "b", "text": "Safety ohmmeter is used to check voltage.", "correct": false}, {"id": "c", "text": "A continuity check.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a gas firewire system, what causes the firewire caption to come on when heat is applied?', '[{"id": "a", "text": "Capacitance increase.", "correct": false}, {"id": "b", "text": "Pressure.", "correct": true}, {"id": "c", "text": "Continuity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilet fire detection issues can be found in', '[{"id": "a", "text": "AWN 83.", "correct": true}, {"id": "b", "text": "CAAIPs.", "correct": false}, {"id": "c", "text": "AWN 80.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The outside casing of a firewire has', '[{"id": "a", "text": "same potential as ground.", "correct": true}, {"id": "b", "text": "28VDC potential above ground.", "correct": false}, {"id": "c", "text": "115VDC potential above ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A cargo compartment which will contain a fire itself and ventilate is a class', '[{"id": "a", "text": "D.", "correct": true}, {"id": "b", "text": "A.", "correct": false}, {"id": "c", "text": "C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Smoke detectors consist of a', '[{"id": "a", "text": "photoelectric cell detecting 10% smoke.", "correct": true}, {"id": "b", "text": "lamp detecting 2% smoke.", "correct": false}, {"id": "c", "text": "photoelectric cell detecting 2% smoke.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a toilet smoke condition, what would be the indication?', '[{"id": "a", "text": "Light in the cabin.", "correct": false}, {"id": "b", "text": "Either a light or an audible warning in the cabin.", "correct": true}, {"id": "c", "text": "Audible warning in the cabin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What do you check when carrying out an insulation check on a continuous firewire loop?', '[{"id": "a", "text": "The outside of the firewire to earth.", "correct": false}, {"id": "b", "text": "The firewire.", "correct": true}, {"id": "c", "text": "The firewire, sensor & controlle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the fire-handle switch is pulled, a', '[{"id": "a", "text": "red warning light stays on. Generator, hydraulics & fuel stays on.", "correct": false}, {"id": "b", "text": "red warning light stays on. Generator, hydraulics, & fuel is cut off.", "correct": true}, {"id": "c", "text": "red warning light goes off. Generator goes offline.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An indicator pin is protruding from a portable fire extinguisher. What does it indicate?', '[{"id": "a", "text": "The bottle is still pressurized.", "correct": false}, {"id": "b", "text": "Bottle is empty.", "correct": true}, {"id": "c", "text": "Bottle is full.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A hand held fire extinguishers weight is stamped on the', '[{"id": "a", "text": "base of container.", "correct": false}, {"id": "b", "text": "head.", "correct": true}, {"id": "c", "text": "support bracket.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The weight of an extinguisher is stamped', '[{"id": "a", "text": "on base of body.", "correct": false}, {"id": "b", "text": "on bracket.", "correct": false}, {"id": "c", "text": "on head fitting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many fire extinguishers are required on an aircraft having 401 - 500 passengers?', '[{"id": "a", "text": "8.", "correct": false}, {"id": "b", "text": "5.", "correct": false}, {"id": "c", "text": "6.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the minimum number of fire bottles in a cabin with 201- 300 people?', '[{"id": "a", "text": "4 Methyl Bromide.", "correct": false}, {"id": "b", "text": "3 BCF.", "correct": false}, {"id": "c", "text": "4 Fire Extinguishers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Portable fire extinguishers are operated by', '[{"id": "a", "text": "turning upside down and squeeze button/trigger.", "correct": false}, {"id": "b", "text": "breaking the tell tale/tamper-proof seal then operated by the handle.", "correct": true}, {"id": "c", "text": "one single operation until fire extinguisher is empty.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many fire extinguishers are required on an aircraft with 501 passengers?', '[{"id": "a", "text": "7.", "correct": true}, {"id": "b", "text": "5.", "correct": false}, {"id": "c", "text": "6.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How can fire extinguisher be identified as being used?', '[{"id": "a", "text": "Check the tell-tale wire.", "correct": false}, {"id": "b", "text": "Weighed.", "correct": true}, {"id": "c", "text": "Check the pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How often do hand-held extinguishers have to be weighed?', '[{"id": "a", "text": "Bi-annually.", "correct": false}, {"id": "b", "text": "Every 5 years.", "correct": false}, {"id": "c", "text": "Annually.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'CO2 fire extinguishers are used on', '[{"id": "a", "text": "engines only.", "correct": false}, {"id": "b", "text": "all fires in fuselage.", "correct": true}, {"id": "c", "text": "baggage holds only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hand held fire extinguishers are weighed', '[{"id": "a", "text": "in accordance with the approved maintenance schedule.", "correct": true}, {"id": "b", "text": "every 24 months.", "correct": false}, {"id": "c", "text": "every 5 years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an aircraft flying control system employing servo-tabs, the installation of external ground locks to the main control surface', '[{"id": "a", "text": "would also prevent movement of the control column.", "correct": false}, {"id": "b", "text": "would not prevent movement of the control column.", "correct": true}, {"id": "c", "text": "is unnecessary since the system is irreversible and therefore the control surface cannot be displaced by the", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial feel system is required with', '[{"id": "a", "text": "proportional controls.", "correct": false}, {"id": "b", "text": "power operated controls.", "correct": true}, {"id": "c", "text": "power assisted controls.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If aerodynamic balancing is increased, what is the effect on the centre of pressure of the control surface?', '[{"id": "a", "text": "It moves forward.", "correct": true}, {"id": "b", "text": "It is not effected.", "correct": false}, {"id": "c", "text": "It moves back.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A control system in the parallel mode,', '[{"id": "a", "text": "when the rudder moves the control pedals stay in position.", "correct": false}, {"id": "b", "text": "the pedals deflect with the rudder deflection.", "correct": true}, {"id": "c", "text": "the control pedals moves only in the approach.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is a Bowden cable designed for?', '[{"id": "a", "text": "Both pull and push operations.", "correct": true}, {"id": "b", "text": "Push operations only.", "correct": false}, {"id": "c", "text": "Pull operations only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A full time yaw damper system detects', '[{"id": "a", "text": "all frequencies.", "correct": false}, {"id": "b", "text": "only low frequencies.", "correct": false}, {"id": "c", "text": "band pass frequencies.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fly-by-wire systems rely on inputs from', '[{"id": "a", "text": "electrical signals.", "correct": false}, {"id": "b", "text": "the pilot via control rods, and electrical signals.", "correct": true}, {"id": "c", "text": "air-data and ''Q'' feel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The yaw damper', '[{"id": "a", "text": "disengages when an engine fails.", "correct": false}, {"id": "b", "text": "augments aircraft stability.", "correct": true}, {"id": "c", "text": "disengages during a coordinated turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Operation of the stick shaker during landing means', '[{"id": "a", "text": "the aircraft is about to land.", "correct": false}, {"id": "b", "text": "the aircraft is approaching the stall speed.", "correct": true}, {"id": "c", "text": "the aircraft has stalled.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A static friction check is carried out during control surface rigging using', '[{"id": "a", "text": "a spring balance to measure control ''break-out force''.", "correct": true}, {"id": "b", "text": "a cable tensiometer to ensure cable tensions are correct.", "correct": false}, {"id": "c", "text": "a spring balance to ensure there is a minimum amount of feel when the controls are moved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If flaps try to move asymmetrically on selection, they', '[{"id": "a", "text": "stop moving and stay in the same position.", "correct": true}, {"id": "b", "text": "drive to the down position and lock.", "correct": false}, {"id": "c", "text": "drive to the up position and lock.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A stick-shaker comes into operation when the aircraft', '[{"id": "a", "text": "is approaching a stall.", "correct": true}, {"id": "b", "text": "is approaching the ''critical mach number''.", "correct": false}, {"id": "c", "text": "goes supersonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Automatic trim systems on some aircraft installations are actuated with two speeds of operation. Operation at high speed is used during', '[{"id": "a", "text": "aircraft at altitude and straight and level.", "correct": false}, {"id": "b", "text": "flaps down.", "correct": true}, {"id": "c", "text": "mach trim.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With respect to flight spoilers, they', '[{"id": "a", "text": "only operate in flight.", "correct": false}, {"id": "b", "text": "only operate on the ground.", "correct": false}, {"id": "c", "text": "can operate both on the ground and in flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Considering an aileron to rudder crossfeed, in a left wing down turn, the', '[{"id": "a", "text": "rudder moves left.", "correct": true}, {"id": "b", "text": "rudder moves right.", "correct": false}, {"id": "c", "text": "rudder remains in the centre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flight control locks are used', '[{"id": "a", "text": "when working with hydraulics.", "correct": false}, {"id": "b", "text": "are only used in flight.", "correct": false}, {"id": "c", "text": "during gusty weather conditions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A stick shaker acts', '[{"id": "a", "text": "at stall.", "correct": false}, {"id": "b", "text": "after stall.", "correct": false}, {"id": "c", "text": "before stall.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dutch roll is eliminated by', '[{"id": "a", "text": "differential ailerons.", "correct": false}, {"id": "b", "text": "the Dutch Roll damper.", "correct": false}, {"id": "c", "text": "the yaw damper.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A mach trimmer counters', '[{"id": "a", "text": "azimuth instability.", "correct": false}, {"id": "b", "text": "lateral instability.", "correct": false}, {"id": "c", "text": "longitudinal instability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The bearing used in a fibre pulley is', '[{"id": "a", "text": "a plain bearing.", "correct": false}, {"id": "b", "text": "a roller bearing.", "correct": false}, {"id": "c", "text": "a ball bearing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the primary stops fitted to a control run have been contacted', '[{"id": "a", "text": "the secondary stops will just be in contact.", "correct": false}, {"id": "b", "text": "a clearance exists at the secondary stops.", "correct": true}, {"id": "c", "text": "the secondary stops have been over-ridden.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Excessive wear on both sides of the control cable pulley groove is evidence of', '[{"id": "a", "text": "pulley misalignment.", "correct": true}, {"id": "b", "text": "excessive cable tension.", "correct": false}, {"id": "c", "text": "cable misalignment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A universal protractor used to measure degrees of aileron travel should be zeroed', '[{"id": "a", "text": "with the aileron in the neutral position.", "correct": true}, {"id": "b", "text": "with the aileron in the down position.", "correct": false}, {"id": "c", "text": "when the aircraft is in level flight attitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flying control static friction check', '[{"id": "a", "text": "demonstrates the force the pilot requires to overcome system inertia and move the controls.", "correct": true}, {"id": "b", "text": "will demonstrate that a high force is always necessary to operate non-powered controls..", "correct": false}, {"id": "c", "text": "can only be carried out during flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is an aileron balance cable for?', '[{"id": "a", "text": "To allow aircraft to fly hands off.", "correct": false}, {"id": "b", "text": "To allow the cable to be tensioned.", "correct": true}, {"id": "c", "text": "To correct for wing heaviness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The vane of a stall warning system with a flapper switch is activated by the change of the', '[{"id": "a", "text": "stagnation point.", "correct": true}, {"id": "b", "text": "point of lowest pressure.", "correct": false}, {"id": "c", "text": "centre of pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With the elevator trim wheel adjusted fully aft. (nose up), range of movement of the elevator is restricted', '[{"id": "a", "text": "for ''up'' travel movement.", "correct": true}, {"id": "b", "text": "neither up nor down, as movement of the trim tab would make no difference to the movement.", "correct": false}, {"id": "c", "text": "for ''down'' travel movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On the ground, spoilers/speedbrakes deploy to', '[{"id": "a", "text": "60°.", "correct": true}, {"id": "b", "text": "30°.", "correct": false}, {"id": "c", "text": "15°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stick shaker stall warnings should be activated at', '[{"id": "a", "text": "VS.", "correct": false}, {"id": "b", "text": "1.2 VS.", "correct": false}, {"id": "c", "text": "1.05 VS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stick pusher is installed in aircraft when.', '[{"id": "a", "text": "the aircraft is directional unstable.", "correct": false}, {"id": "b", "text": "the aircraft has failed to meet the stalling requirements by normal category.", "correct": true}, {"id": "c", "text": "the aircraft has no yaw damper installed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A horn balance on a control will', '[{"id": "a", "text": "increase degree of movement at high speed.", "correct": true}, {"id": "b", "text": "decrease degree of movement at low speed.", "correct": false}, {"id": "c", "text": "decrease degree of movement at high speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In normal flight, if the control column is pulled back, a servo tab fitted to the elevator will', '[{"id": "a", "text": "move up.", "correct": false}, {"id": "b", "text": "move down.", "correct": true}, {"id": "c", "text": "remain in line with the elevator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In normal flight, if the control wheel is moved to the left, then the aileron on the right wing will initially', '[{"id": "a", "text": "decrease the angle of attack of the right hand wing.", "correct": false}, {"id": "b", "text": "keep the angle of attack of the right wing constant.", "correct": false}, {"id": "c", "text": "increase the angle of attack of the right hand wing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is the speed in level flight that would activate the stall warning?', '[{"id": "a", "text": "VS1G + 15kts.", "correct": false}, {"id": "b", "text": "1.05VS1G.", "correct": true}, {"id": "c", "text": "1.2VS1G.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft fitted with elevons in normal flight, if a column is moved forward, the elevons will', '[{"id": "a", "text": "both move down.", "correct": true}, {"id": "b", "text": "remain stationary.", "correct": false}, {"id": "c", "text": "both move up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The function of the stick pusher is', '[{"id": "a", "text": "to activate and push the stick forward prior to stick shaker.", "correct": false}, {"id": "b", "text": "to vibrate the controls.", "correct": false}, {"id": "c", "text": "to activate and push the stick forward at or beyond a certain value of angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The input to a stick shaker comes from', '[{"id": "a", "text": "the airspeed, and sometimes the rate of change in airspeed.", "correct": false}, {"id": "b", "text": "the angle of attack only.", "correct": false}, {"id": "c", "text": "angle of attack, and sometimes the rate of change in angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stick pushers must be installed in aeroplanes with dangerous stall characteristics. Dangerous stall characteristics include:', '[{"id": "a", "text": "excessive wing drop and deep stall.", "correct": true}, {"id": "b", "text": "pitch down and minor wing drop.", "correct": false}, {"id": "c", "text": "pitch down and increase in speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The sensor of a stall warning system can be activated by a change in the location of the', '[{"id": "a", "text": "transition region.", "correct": false}, {"id": "b", "text": "centre of lift.", "correct": false}, {"id": "c", "text": "stagnation point.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To avoid moments bending the root of the wing, the aircraft will be fitted with', '[{"id": "a", "text": "integrated fuel monitoring system.", "correct": false}, {"id": "b", "text": "symmetrical flight control trim.", "correct": true}, {"id": "c", "text": "automatic trim control for controlled turns and rudder movements.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A yaw damper gain could be fitted with', '[{"id": "a", "text": "decreases sensitivity for decreased speed.", "correct": false}, {"id": "b", "text": "increased sensitivity for increased speed.", "correct": true}, {"id": "c", "text": "decreases sensitivity for increased speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an aircraft system employing balance tabs, the installation of external ground locks between the control surface and the balance tabs', '[{"id": "a", "text": "is unnecessary since the system is irreversible.", "correct": false}, {"id": "b", "text": "would prevent the movement of the control column.", "correct": true}, {"id": "c", "text": "would not prevent the movement of the control column.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The two switches for pitch trim are located', '[{"id": "a", "text": "on the control column acting like an ''AND'' switch.", "correct": true}, {"id": "b", "text": "on the control column acting like an ''OR'' switch.", "correct": false}, {"id": "c", "text": "on the control column with the captain having priority over the First Officer..", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the flaps are sluggish or erratic on final approach, the possible cause may be', '[{"id": "a", "text": "bearing seized.", "correct": false}, {"id": "b", "text": "flap tracks out of rigging.", "correct": false}, {"id": "c", "text": "flap motor internal leakage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Speed brakes are a device used on large transport category aircraft', '[{"id": "a", "text": "to prevent aquaplaning.", "correct": false}, {"id": "b", "text": "for speed reduction after landing.", "correct": false}, {"id": "c", "text": "to increase drag in order to maintain a steeper gradient of descent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In fully Fly By Wire aircraft, wing root bending moments are reduced by', '[{"id": "a", "text": "transfer of fuel from one wing tank to another.", "correct": false}, {"id": "b", "text": "symmetrical application of ailerons.", "correct": true}, {"id": "c", "text": "operation of the elevator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Yaw damping rate changes with', '[{"id": "a", "text": "altitude.", "correct": false}, {"id": "b", "text": "airspeed.", "correct": true}, {"id": "c", "text": "flap position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the main purpose of a frise aileron?', '[{"id": "a", "text": "Increase drag on the up going wing.", "correct": true}, {"id": "b", "text": "Decrease drag on the up going wing.", "correct": false}, {"id": "c", "text": "Help pilot overcome aerodynamic loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens to a hydraulically operated flight control surface when pressure is removed?', '[{"id": "a", "text": "Droop.", "correct": true}, {"id": "b", "text": "Remain in last position.", "correct": false}, {"id": "c", "text": "Go to neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oscillation and hunting of flight control surface are prevented by', '[{"id": "a", "text": "feedback from control surface.", "correct": false}, {"id": "b", "text": "fitting a tachogenerator.", "correct": true}, {"id": "c", "text": "feedback from the servo motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stick shaker activates at a speed which is above the stalling speed by', '[{"id": "a", "text": "7%.", "correct": true}, {"id": "b", "text": "10.321%.", "correct": false}, {"id": "c", "text": "4%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing mounted stall warning vane', '[{"id": "a", "text": "moves up at impending stall.", "correct": true}, {"id": "b", "text": "gives a visual indication of impending stall.", "correct": false}, {"id": "c", "text": "moves down at impending stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During an autopilot controlled turn', '[{"id": "a", "text": "ailerons and rudder will move.", "correct": false}, {"id": "b", "text": "ailerons, rudder and THS will move.", "correct": false}, {"id": "c", "text": "ailerons, rudder and elevators will move.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a full fly-by-wire system, a speedbrake screwjack servomotor is controlled by the', '[{"id": "a", "text": "flight control computer.", "correct": true}, {"id": "b", "text": "flight management and guidance computer.", "correct": false}, {"id": "c", "text": "flight augmentation computer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fly-by-wire aircraft, what controls the roll spoilers?', '[{"id": "a", "text": "Flight augmentation computer.", "correct": false}, {"id": "b", "text": "Flight control computer.", "correct": true}, {"id": "c", "text": "Flight management computer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mass balance weights are used to', '[{"id": "a", "text": "balance the tabs.", "correct": false}, {"id": "b", "text": "balance the trailing edge of flying control surfaces.", "correct": false}, {"id": "c", "text": "counteract flutter on control surfaces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Active load control involves', '[{"id": "a", "text": "intervention & monitoring the human pilot.", "correct": false}, {"id": "b", "text": "limiting the deflection of control surface with airspeed.", "correct": false}, {"id": "c", "text": "varying lift force to control vertical movement of the aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Active load control uses', '[{"id": "a", "text": "elevator and stab.", "correct": false}, {"id": "b", "text": "elevator and aileron.", "correct": false}, {"id": "c", "text": "aileron and spoiler.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the autopilot servo-motor torque setting is to', '[{"id": "a", "text": "protect the servo motor.", "correct": false}, {"id": "b", "text": "prevent control surface runaway.", "correct": true}, {"id": "c", "text": "damp the system oscillation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fully Fly By Wire Aircraft, ground spoilers are deployed automatically when the aircraft is on ground and', '[{"id": "a", "text": "weight on ground switch is activated.", "correct": false}, {"id": "b", "text": "brakes are deployed.", "correct": false}, {"id": "c", "text": "thrust reversers are deployed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fully Fly By Wire aircraft, rudder trim is nulled by the', '[{"id": "a", "text": "Flight Augmentation Computers.", "correct": true}, {"id": "b", "text": "electric flight control unit.", "correct": false}, {"id": "c", "text": "Flight Guidance and Management Compute.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Aileron input is fed into the yaw damper system to', '[{"id": "a", "text": "prevent nose pitching up.", "correct": false}, {"id": "b", "text": "prevent nose pitching down.", "correct": false}, {"id": "c", "text": "prevent adverse yaw in a turn.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pitch trimming in autopilot is initiated by', '[{"id": "a", "text": "continued pitch input.", "correct": true}, {"id": "b", "text": "pitch of aircraft in cruise.", "correct": false}, {"id": "c", "text": "C of G movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Differential aileron control will', '[{"id": "a", "text": "cause a nose up moment.", "correct": false}, {"id": "b", "text": "cause a nose down moment.", "correct": false}, {"id": "c", "text": "prevent yawing in conjunction with rudder input.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a fly-by-wire aircraft, what controls stabilizer trim?', '[{"id": "a", "text": "ELAC and SEC.", "correct": true}, {"id": "b", "text": "ELAC.", "correct": false}, {"id": "c", "text": "SEC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an automatic flight control system, when may the yaw damper be applied?', '[{"id": "a", "text": "During either manual or automatic control.", "correct": true}, {"id": "b", "text": "During automatic control only.", "correct": false}, {"id": "c", "text": "During manual control only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Flutter can be prevented by', '[{"id": "a", "text": "balance panels.", "correct": false}, {"id": "b", "text": "trim tabs.", "correct": false}, {"id": "c", "text": "mass balance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fully fly by wire system, if the elevator loses all electrical power', '[{"id": "a", "text": "servos remain stationary and provide damping.", "correct": true}, {"id": "b", "text": "servos move to neutral and lock.", "correct": false}, {"id": "c", "text": "servos lock at last position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an auto trim system, for the trim system to operate', '[{"id": "a", "text": "operation of the trim controls is required.", "correct": false}, {"id": "b", "text": "autopilot need not be engaged.", "correct": true}, {"id": "c", "text": "autopilot must be engaged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an autopilot coordinated turn, when the turn angle is reached', '[{"id": "a", "text": "both ailerons are down.", "correct": false}, {"id": "b", "text": "the ailerons are faired.", "correct": true}, {"id": "c", "text": "one is up one is down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is automatic angle of attack protection provided?', '[{"id": "a", "text": "Fast/Slow indication.", "correct": false}, {"id": "b", "text": "Reduce flap deployment.", "correct": false}, {"id": "c", "text": "Autothrottle applying more power.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A single failure of fly by wire', '[{"id": "a", "text": "will limit the flight profile.", "correct": false}, {"id": "b", "text": "will reduce the operational height and speed.", "correct": false}, {"id": "c", "text": "has no effect on the aircraft''s operation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fly-by-wire load alleviation function in turbulent weather conditions will result in', '[{"id": "a", "text": "ailerons moving symmetrically upward.", "correct": false}, {"id": "b", "text": "spoiler moving symmetrically upward.", "correct": false}, {"id": "c", "text": "ailerons and spoiler moving symmetrically upward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Autotrim will switch to ''slow'' when', '[{"id": "a", "text": "flaps are retracted.", "correct": true}, {"id": "b", "text": "landing gear up and locked.", "correct": false}, {"id": "c", "text": "flaps are extended.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the stabiliser automatically controlled in normal manual operation?', '[{"id": "a", "text": "Mach/Speed Trim.", "correct": true}, {"id": "b", "text": "Pitch Trim.", "correct": false}, {"id": "c", "text": "Electric Trim.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Spoiler position feedback is provided by a', '[{"id": "a", "text": "an R.V.D.T.", "correct": true}, {"id": "b", "text": "a S.C.M.", "correct": false}, {"id": "c", "text": "a microswitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Rudder ''Q'' limiting', '[{"id": "a", "text": "increases rudder movement with increase in airspeed.", "correct": false}, {"id": "b", "text": "increases feel as airspeed increases.", "correct": false}, {"id": "c", "text": "restricts rudder movement with increase in airspeed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Elevons combine the functions of both', '[{"id": "a", "text": "rudder and elevator.", "correct": false}, {"id": "b", "text": "elevator and aileron.", "correct": true}, {"id": "c", "text": "rudder and aileron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A differential aileron system is designed to', '[{"id": "a", "text": "prevent adverse yaw.", "correct": true}, {"id": "b", "text": "compensate for aileron reversal.", "correct": false}, {"id": "c", "text": "minimise flutter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial feel system is required', '[{"id": "a", "text": "for power operated control systems.", "correct": true}, {"id": "b", "text": "for proportional control systems.", "correct": false}, {"id": "c", "text": "for power assisted control systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tandem P.F.C.U.', '[{"id": "a", "text": "has the actuator rams co-axial.", "correct": true}, {"id": "b", "text": "has two control surfaces under its control.", "correct": false}, {"id": "c", "text": "has the actuator rams parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Active load control uses', '[{"id": "a", "text": "elevator and stab.", "correct": false}, {"id": "b", "text": "ailerons and spoilers.", "correct": true}, {"id": "c", "text": "elevator and ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial feel system is necessary in a powered flying control system to', '[{"id": "a", "text": "increasing the sensitivity of the control system.", "correct": false}, {"id": "b", "text": "prevent overloading of the power control units.", "correct": false}, {"id": "c", "text": "provide the pilot with simulated stick forces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the event of hydraulic failure in a power control system, a requirement of the manual reversion is that it must be', '[{"id": "a", "text": "possible, but not recommended.", "correct": false}, {"id": "b", "text": "operated by the standby hydraulic system.", "correct": false}, {"id": "c", "text": "automatic and instantaneous.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of control cable regulators is to', '[{"id": "a", "text": "maintain preset cable tensions during flight.", "correct": true}, {"id": "b", "text": "compensate for low temperature only.", "correct": false}, {"id": "c", "text": "compensate for high temperature only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Range of movements of power operated flying control surfaces are limited by', '[{"id": "a", "text": "travel of the jack ram.", "correct": false}, {"id": "b", "text": "travel of the jack body.", "correct": false}, {"id": "c", "text": "mechanical stops in the control system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft is controlled about the lateral axis by the', '[{"id": "a", "text": "elevator.", "correct": true}, {"id": "b", "text": "rudder.", "correct": false}, {"id": "c", "text": "ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft is controlled about the normal axis by the', '[{"id": "a", "text": "elevator.", "correct": false}, {"id": "b", "text": "rudder.", "correct": true}, {"id": "c", "text": "ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the Servo Valve in a power operated control is', '[{"id": "a", "text": "to revert the system to manual operation.", "correct": false}, {"id": "b", "text": "to provide pressure to operate the control.", "correct": false}, {"id": "c", "text": "to direct hydraulic fluid to the jack in response to the pilot''s control in cockpit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A stick shaker is a device which', '[{"id": "a", "text": "vibrates the control column near stalling speed.", "correct": true}, {"id": "b", "text": "helps extricate an aircraft from soft ground.", "correct": false}, {"id": "c", "text": "gives a short period of extra lift to assist take off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft is controlled about the longitudinal axis by the', '[{"id": "a", "text": "rudder.", "correct": false}, {"id": "b", "text": "elevator.", "correct": false}, {"id": "c", "text": "ailerons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ruddervators when moved, will move', '[{"id": "a", "text": "together only.", "correct": false}, {"id": "b", "text": "either opposite each other or together, depending on the selection.", "correct": true}, {"id": "c", "text": "opposite to each other only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As a consequence of the C of G being close to its aft limit', '[{"id": "a", "text": "the stick forces will be high in fore and aft pitch, due to the high longitudinal stability.", "correct": false}, {"id": "b", "text": "the stick forces when pitching the nose down will be very high.", "correct": true}, {"id": "c", "text": "the stick forces to manoeuvre longitudinally will be low due to the low stability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An anti-balance tab is moved', '[{"id": "a", "text": "hydraulically.", "correct": false}, {"id": "b", "text": "when the C.G. changes.", "correct": false}, {"id": "c", "text": "via a fixed linkage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A servo tab is operated', '[{"id": "a", "text": "by a trim wheel and moves in the opposite direction to the main control surfaces when moved.", "correct": false}, {"id": "b", "text": "automatically, and moves in the same direction as the main control surfaces.", "correct": false}, {"id": "c", "text": "directly by the pilot to produce forces which in turn move the main control surfaces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking full range of control surface movement, they must be positioned by', '[{"id": "a", "text": "operating the flightdeck/cockpit controls until the system is against the primary stops.", "correct": true}, {"id": "b", "text": "moving them by hand directly until against the secondary stops.", "correct": false}, {"id": "c", "text": "moving them by hand directly until against the primary stops.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The higher speed of the high wing in a banked turn causes it to have more drag than the low wing, this may be compensated for by', '[{"id": "a", "text": "increasing the ''nose up'' pitch by use of the elevators.", "correct": false}, {"id": "b", "text": "use of the rudder control.", "correct": true}, {"id": "c", "text": "operating the ailerons into the opposite sense once the correct angle of bank has been reached.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The type of flap which extends rearwards when lowered is called a', '[{"id": "a", "text": "split flap.", "correct": false}, {"id": "b", "text": "plain flap.", "correct": false}, {"id": "c", "text": "Fowler flap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following trailing edge flaps give an increase in wing area?', '[{"id": "a", "text": "Fowler flap.", "correct": true}, {"id": "b", "text": "Slotted flap.", "correct": false}, {"id": "c", "text": "Split flap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which of the following is not a primary flying control?', '[{"id": "a", "text": "Tailplane.", "correct": true}, {"id": "b", "text": "Elevator.", "correct": false}, {"id": "c", "text": "Rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tab which assists the pilot to move a flying control by moving automatically in the opposite direction to the control surface is called a', '[{"id": "a", "text": "trim tab.", "correct": false}, {"id": "b", "text": "geared balance tab.", "correct": true}, {"id": "c", "text": "servo tab.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is fitted on the aircraft to enable the pilot to reduce his speed rapidly in event of severe turbulence, or speed tending to rise above the ''Never Exceed Limit''?', '[{"id": "a", "text": "Wheel brakes.", "correct": false}, {"id": "b", "text": "Lift dumpers.", "correct": false}, {"id": "c", "text": "Air brakes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When spoilers are used asymmetrically, they combine with', '[{"id": "a", "text": "rudder.", "correct": false}, {"id": "b", "text": "ailerons.", "correct": true}, {"id": "c", "text": "elevators.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is used to correct any tendency of the aircraft to move towards an undesirable flight attitude?', '[{"id": "a", "text": "Balance tabs.", "correct": false}, {"id": "b", "text": "Trim tabs.", "correct": true}, {"id": "c", "text": "Spring tabs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With hydraulic ram operated flying controls, when the pressure is reduced to zero, the flying control surfaces', '[{"id": "a", "text": "remain in the position they were when power was removed.", "correct": false}, {"id": "b", "text": "droop.", "correct": true}, {"id": "c", "text": "stay at neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Powered flying control actuators', '[{"id": "a", "text": "are operated by the autopilot only.", "correct": false}, {"id": "b", "text": "provide feedback to the pilot.", "correct": false}, {"id": "c", "text": "transmit pilot input to the control surfaces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A stick shaker operates', '[{"id": "a", "text": "after the stall.", "correct": false}, {"id": "b", "text": "just before the stall.", "correct": true}, {"id": "c", "text": "at the onset of the stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a power assisted flight control system, the feel required is normally supplied by', '[{"id": "a", "text": "air loads on the control surfaces.", "correct": true}, {"id": "b", "text": "stretching springs.", "correct": false}, {"id": "c", "text": "''Q'' feel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Irreversibility of a fully powered control surface is provided by', '[{"id": "a", "text": "air loads on the control surface.", "correct": false}, {"id": "b", "text": "nulling of the servo valve.", "correct": true}, {"id": "c", "text": "the jack ram being attached to structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), '''Q'' feel units use', '[{"id": "a", "text": "pitot pressure only.", "correct": false}, {"id": "b", "text": "static pressure only.", "correct": false}, {"id": "c", "text": "pitot and static pressures.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Spoiler panels are positioned so that when deployed', '[{"id": "a", "text": "no yaw takes place.", "correct": false}, {"id": "b", "text": "roll will not occur.", "correct": false}, {"id": "c", "text": "pitch trim is not affected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Powered flight control systems are used on transport aircraft', '[{"id": "a", "text": "due to the increase in speed and size of aircraft.", "correct": true}, {"id": "b", "text": "because at low level air density is high.", "correct": false}, {"id": "c", "text": "because the pilot has too many tasks to perform.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A differential aileron control system results in', '[{"id": "a", "text": "aileron drag being reduced on the inner wing in a turn.", "correct": false}, {"id": "b", "text": "aileron drag being reduced on the outer wing in a turn.", "correct": true}, {"id": "c", "text": "aileron drag being compensated by small rudder movements.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Spoiler panels are controlled by', '[{"id": "a", "text": "the aileron control wheel only.", "correct": false}, {"id": "b", "text": "the aileron control wheel and speed brake lever.", "correct": true}, {"id": "c", "text": "a speed brake lever only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A lift transducer is normally fitted', '[{"id": "a", "text": "to the nose area of the aircraft.", "correct": false}, {"id": "b", "text": "on the leading edge of the wing.", "correct": true}, {"id": "c", "text": "on the elevator control system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If electrical power is removed from a fly by wire spoiler system, the spoiler panels', '[{"id": "a", "text": "go to full up.", "correct": false}, {"id": "b", "text": "go to down if any are not already down.", "correct": true}, {"id": "c", "text": "remain where they are.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fly-by-wire control system, the follow-up transducer is fitted to', '[{"id": "a", "text": "the control system computer.", "correct": false}, {"id": "b", "text": "the hydraulic actuator.", "correct": true}, {"id": "c", "text": "the pilot''s input.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The down position of the speed brake lever is detented to', '[{"id": "a", "text": "lock the speed brakes down during flight.", "correct": false}, {"id": "b", "text": "allow the ground speed brakes to be used on touchdown.", "correct": false}, {"id": "c", "text": "prevent inadvertent operation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Asymmetric flap operation is prevented to keep to a minimum the tendancy of', '[{"id": "a", "text": "pitch changes.", "correct": false}, {"id": "b", "text": "yawing.", "correct": false}, {"id": "c", "text": "rolling.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High thrust stall warning is activated when the thrust of opposite engine reads', '[{"id": "a", "text": "greater than 50%.", "correct": false}, {"id": "b", "text": "greater than 75%.", "correct": true}, {"id": "c", "text": "greater than 90%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A differential aileron control is one which gives', '[{"id": "a", "text": "a larger aileron up travel than down.", "correct": true}, {"id": "b", "text": "equal aileron travel in each direction, but variable for stick movement.", "correct": false}, {"id": "c", "text": "the down-going aileron more travel than the up-going one.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the control column is moved back and the hand-wheel turned to the left', '[{"id": "a", "text": "the elevators move up and the left aileron moves down.", "correct": false}, {"id": "b", "text": "the elevators move down and the left aileron moves down.", "correct": false}, {"id": "c", "text": "the left aileron moves up and the elevators move up.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A series type yaw damper', '[{"id": "a", "text": "moves the rudder and the ailerons to damp out Dutch roll.", "correct": false}, {"id": "b", "text": "moves the rudder only.", "correct": true}, {"id": "c", "text": "moves the rudder pedals and the rudder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A stick shaker', '[{"id": "a", "text": "vibrates the elevators to cause buffeting of the airframe.", "correct": false}, {"id": "b", "text": "is a linear actuator attached to the base of the control column.", "correct": false}, {"id": "c", "text": "is an eccentric flywheel driven by an electric motor and mounted on the control column.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the control column is moved forward and to the left', '[{"id": "a", "text": "left aileron moves down, right aileron up, elevator down.", "correct": false}, {"id": "b", "text": "left aileron moves up, right aileron moves down, elevator up.", "correct": false}, {"id": "c", "text": "left aileron moves up, right aileron down, elevator down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On an aircraft fitted with spoilers for lateral control, roll to the right is caused by', '[{"id": "a", "text": "left spoiler extending, right spoiler remaining retracted.", "correct": false}, {"id": "b", "text": "both spoilers extending.", "correct": false}, {"id": "c", "text": "right spoiler extending, left spoiler remaining retracted.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aileron trim control in the cockpit is moved to counteract a tendency to fly left wing low, an aileron trim tab fitted to the port aileron will', '[{"id": "a", "text": "move up and this will cause the left aileron to move down and the right aileron to move up.", "correct": true}, {"id": "b", "text": "move up and cause the left aileron to move down and the right aileron to move down to a lesser degree.", "correct": false}, {"id": "c", "text": "move up and cause the left aileron to move down but the right aileron will remain neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'You have adjusted the elevator trim tab to correct for nose heavy. What was the direction of travel of the trim tab?', '[{"id": "a", "text": "The port elevator tab has moved up and starboard moved down.", "correct": false}, {"id": "b", "text": "The elevator trim tab has moved down.", "correct": true}, {"id": "c", "text": "The elevator trim tab has moved up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pulleys in a flight control system are made from', '[{"id": "a", "text": "brass.", "correct": false}, {"id": "b", "text": "Tufnol or aluminium alloy.", "correct": true}, {"id": "c", "text": "stainless steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tension regulator in the flight control cable system of a large all metal aircraft is used primarily to', '[{"id": "a", "text": "increase cable tension in cold weather.", "correct": false}, {"id": "b", "text": "decrease cable tension in cold weather.", "correct": false}, {"id": "c", "text": "retain a set tension.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An interrupter arm incorporated in a flying control locking mechanism', '[{"id": "a", "text": "dampens the rudder movement.", "correct": false}, {"id": "b", "text": "locks the ailerons and elevators.", "correct": false}, {"id": "c", "text": "restricts movement of the throttles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The yaw damper must be designed to allow the rudder to control in response to the aircraft''s', '[{"id": "a", "text": "dutch roll frequency.", "correct": true}, {"id": "b", "text": "roll frequency.", "correct": false}, {"id": "c", "text": "pitch Frequency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The alpha vane signal can be fed to __________ when the aircraft is close to stall', '[{"id": "a", "text": "fast/slow switch.", "correct": false}, {"id": "b", "text": "throttle lever.", "correct": true}, {"id": "c", "text": "flap position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Moving the elevator trim wheel fully aft, then the', '[{"id": "a", "text": "aircraft tends to roll to the right.", "correct": false}, {"id": "b", "text": "aircraft tends to go nose up.", "correct": true}, {"id": "c", "text": "aircraft tends to go nose down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ground spoilers are used to', '[{"id": "a", "text": "prevent FOD ingestion into the engines on landing and taxiing.", "correct": false}, {"id": "b", "text": "decrease wing loading on landing.", "correct": true}, {"id": "c", "text": "increase wing loading on take-off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The outboard ailerons on some aircraft', '[{"id": "a", "text": "are isolated to prevent aileron reversal.", "correct": true}, {"id": "b", "text": "are isolated to improve sensitivity.", "correct": false}, {"id": "c", "text": "are isolated at slow speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The effect of the rudder on an aircraft can be increased by', '[{"id": "a", "text": "decreasing the velocity of the aircraft.", "correct": false}, {"id": "b", "text": "increasing the altitude of the aircraft.", "correct": false}, {"id": "c", "text": "increasing the distance of the control surfaces from the aircraft''s centre of gravity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuel tanks are numbered', '[{"id": "a", "text": "aft to fwd.", "correct": false}, {"id": "b", "text": "right to left.", "correct": false}, {"id": "c", "text": "fwd to aft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fuel surge tank', '[{"id": "a", "text": "acts as a separate fuel supply tank.", "correct": false}, {"id": "b", "text": "reduces wing bending moment.", "correct": false}, {"id": "c", "text": "acts as a vent in the main tank.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuel crossfeed valve is normally powered by', '[{"id": "a", "text": "AC.", "correct": false}, {"id": "b", "text": "Battery.", "correct": false}, {"id": "c", "text": "DC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When refuelling, as the fuel level increases', '[{"id": "a", "text": "capacitance increases.", "correct": true}, {"id": "b", "text": "capacitive reactance increases.", "correct": false}, {"id": "c", "text": "capacitance decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuel crossfeed valve is usually in', '[{"id": "a", "text": "its last position.", "correct": false}, {"id": "b", "text": "the open position.", "correct": false}, {"id": "c", "text": "the closed position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Sliding couplings in fuel systems are used on', '[{"id": "a", "text": "low pressure systems.", "correct": false}, {"id": "b", "text": "air or vapour systems.", "correct": true}, {"id": "c", "text": "high pressure systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuel surge is prevented by', '[{"id": "a", "text": "having baffles within the tank and supports on the outside to resist fuel surge.", "correct": true}, {"id": "b", "text": "incorporation of an additional surge tank.", "correct": false}, {"id": "c", "text": "having separate compartments within the tank.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When carrying out an insulation check on a fuel probe, what is the Maximum voltage to use', '[{"id": "a", "text": "500 V.", "correct": false}, {"id": "b", "text": "30 V.", "correct": false}, {"id": "c", "text": "250 V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuel cross-feed valve is lubricated', '[{"id": "a", "text": "by air.", "correct": false}, {"id": "b", "text": "by the fuel.", "correct": true}, {"id": "c", "text": "by internal cooling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuel cross feed valves are operated by the', '[{"id": "a", "text": "115 V AC.", "correct": false}, {"id": "b", "text": "battery.", "correct": false}, {"id": "c", "text": "28 V DC bus.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuel systems that are interconnected must have', '[{"id": "a", "text": "separate venting for each tank.", "correct": false}, {"id": "b", "text": "no airspace.", "correct": false}, {"id": "c", "text": "air spaces interconnected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As fuel level increases, system capacitance', '[{"id": "a", "text": "no change.", "correct": false}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When refuelling', '[{"id": "a", "text": "it is important to fill the expansion space in the tank.", "correct": false}, {"id": "b", "text": "it is important not to fill the expansion space in the tank.", "correct": true}, {"id": "c", "text": "the fuel nozzle will automatically cut off the supply when the tank is full.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When using Biopor microbial fuel growth treatment', '[{"id": "a", "text": "it is added to the fuel and burnt.", "correct": true}, {"id": "b", "text": "it is applied dry and left.", "correct": false}, {"id": "c", "text": "it is applied wet and flushed out.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Microbial growth is', '[{"id": "a", "text": "red dots.", "correct": false}, {"id": "b", "text": "brown black slime.", "correct": true}, {"id": "c", "text": "green sludge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Bladder type fuel tanks are secured by', '[{"id": "a", "text": "press type rivets.", "correct": true}, {"id": "b", "text": "contact adhesive.", "correct": false}, {"id": "c", "text": "bolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A zero fuel test on a fuel quantity indicating system is carried out with', '[{"id": "a", "text": "tanks completely empty.", "correct": false}, {"id": "b", "text": "tanks empty apart from unusable fuel.", "correct": true}, {"id": "c", "text": "tanks completely full.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After a tank bag has been replaced, a fuel flow test should be carried out at', '[{"id": "a", "text": "tank outlet.", "correct": false}, {"id": "b", "text": "engine inlet.", "correct": true}, {"id": "c", "text": "tank shut-off valve point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In biologically contaminated fuel, corrosion takes place', '[{"id": "a", "text": "the top of the tank.", "correct": false}, {"id": "b", "text": "the bottom 2 inches of the tank.", "correct": false}, {"id": "c", "text": "below the fungal colonies.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft has ability to transfer fuel in flight, provision must be made to', '[{"id": "a", "text": "shut off fuel before structural damage.", "correct": true}, {"id": "b", "text": "stop engine from using tank during transfer.", "correct": false}, {"id": "c", "text": "provide overflow facility to dump fuel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a fuel system with interconnected vents', '[{"id": "a", "text": "the expansion space must be 2% of the tank capacity.", "correct": true}, {"id": "b", "text": "the expansion space must be 10% of the tank capacity.", "correct": false}, {"id": "c", "text": "an expansion space is not required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuel tanks interconnected must have', '[{"id": "a", "text": "vents to allow overfueling.", "correct": false}, {"id": "b", "text": "protection against overfill for tanks and fuel system.", "correct": true}, {"id": "c", "text": "tank where fuel is fed from both tanks to engine inlet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a FADEC system loses air data input it goes to', '[{"id": "a", "text": "hard reversion.", "correct": false}, {"id": "b", "text": "soft reversion.", "correct": true}, {"id": "c", "text": "mechanical reversion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure refuelling is carried out at', '[{"id": "a", "text": "20 PSI.", "correct": false}, {"id": "b", "text": "15 PSI.", "correct": false}, {"id": "c", "text": "40 PSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cross feed valves permit fuel transfer from', '[{"id": "a", "text": "left tank to right tank.", "correct": false}, {"id": "b", "text": "tank to tank.", "correct": false}, {"id": "c", "text": "any tank to any engine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is fitted to the fuel jettison pipe to prevent vapour ignition?', '[{"id": "a", "text": "A nozzle.", "correct": false}, {"id": "b", "text": "A corona device.", "correct": false}, {"id": "c", "text": "An anti-corona device.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens to the capacitance in a fuel contents gauge as fuel is used?', '[{"id": "a", "text": "Depends on altitude.", "correct": false}, {"id": "b", "text": "Increases.", "correct": false}, {"id": "c", "text": "Decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an aircraft is put into storage for medium / long periods, the fuel tanks should', '[{"id": "a", "text": "be full.", "correct": false}, {"id": "b", "text": "have some fuel left in to prevent sealant from deteriorating/drying out.", "correct": true}, {"id": "c", "text": "be empty.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Integral fuel booster pumps', '[{"id": "a", "text": "require no cooling.", "correct": false}, {"id": "b", "text": "require ram air cooling.", "correct": false}, {"id": "c", "text": "lets the fuel do the cooling.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a scavenge system within a fuel system is', '[{"id": "a", "text": "to ensure that all available fuel can be used.", "correct": true}, {"id": "b", "text": "to ensure that any water in the fuel is constantly dispersed thus reducing microbiological contamination.", "correct": false}, {"id": "c", "text": "to ensure that all unused fuel is returned to the tanks efficiently.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a light fixed wing aircraft, the fuel warning light indicates', '[{"id": "a", "text": "ice blockage, filter popped or pump fail.", "correct": true}, {"id": "b", "text": "the tank does not pressurise.", "correct": false}, {"id": "c", "text": "pump failure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is fuel supplied to a turbine engine?', '[{"id": "a", "text": "By suction from the engine driven fuel pump.", "correct": false}, {"id": "b", "text": "By a fuel boost pump.", "correct": true}, {"id": "c", "text": "By a gravity feed pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuel tank suction valve will open when', '[{"id": "a", "text": "the engine driven pump fails.", "correct": false}, {"id": "b", "text": "the booster pump fails.", "correct": true}, {"id": "c", "text": "both the engine driven and booster pump fail.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To prevent water condensation in a fuel tank', '[{"id": "a", "text": "the tank should be filled as full as possible.", "correct": true}, {"id": "b", "text": "the tank should be filled with the minimum fuel possible.", "correct": false}, {"id": "c", "text": "the filler cap should be left open.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At the lowest point of each vent line you would normally find a', '[{"id": "a", "text": "self draining non-return valve.", "correct": true}, {"id": "b", "text": "NACA duct.", "correct": false}, {"id": "c", "text": "float valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To protect the centre tank fuselage area from a vapour build up', '[{"id": "a", "text": "ram air is circulated around the tank.", "correct": true}, {"id": "b", "text": "cabin air is bled around the tank.", "correct": false}, {"id": "c", "text": "a shroud vent and overboard drain is fitted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a fuel jettison valve is in transit, the magnetic indicator would show', '[{"id": "a", "text": "amber and cross line.", "correct": true}, {"id": "b", "text": "green and in line.", "correct": false}, {"id": "c", "text": "amber and in line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When considering the basic categories of fuel tank construction, which of the following is most prone to leaks?', '[{"id": "a", "text": "Rigid,", "correct": false}, {"id": "b", "text": "Flexible.", "correct": false}, {"id": "c", "text": "Integral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On removal of a fuel tank booster pump, fuel is observed running out of the boost pump canister, this could be caused by', '[{"id": "a", "text": "fuel leaking past the inlet screens.", "correct": false}, {"id": "b", "text": "fuel draining out of the pressure switch bleed.", "correct": false}, {"id": "c", "text": "the pressure outlet check valve is not correctly seated.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Crossfeed valves are normally fitted with', '[{"id": "a", "text": "two 28V DC motors.", "correct": true}, {"id": "b", "text": "two single phase AC motors.", "correct": false}, {"id": "c", "text": "two three-phase AC motors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To replace a water drain valve seal', '[{"id": "a", "text": "the seal of the valve is replaceable without draining the tanks.", "correct": true}, {"id": "b", "text": "the tank must be de-fuelled.", "correct": false}, {"id": "c", "text": "the seal is not replaceable, the whole drain assembly must be replaced.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A shroud vent and overload drain would normally be found on', '[{"id": "a", "text": "fuel tank vent pipes.", "correct": true}, {"id": "b", "text": "fuel jettison system.", "correct": false}, {"id": "c", "text": "the APU fuel feed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To shut-off the LP fuel supply to the engine for the purpose of engine removal you would', '[{"id": "a", "text": "close the cross bleed valve.", "correct": false}, {"id": "b", "text": "pull the fire handle.", "correct": true}, {"id": "c", "text": "close the HP fuel lock.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A leak from a fuel tank which manifests as fuel dripping from the tank is classified as a', '[{"id": "a", "text": "stain.", "correct": false}, {"id": "b", "text": "seep.", "correct": false}, {"id": "c", "text": "run.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Calcium Chromate tablets can be fitted in integral tanks. Before installation the linen bag should be wetted with', '[{"id": "a", "text": "Water.", "correct": true}, {"id": "b", "text": "Methylated Spirit.", "correct": false}, {"id": "c", "text": "Kerosene.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A check valve is fitted to a fuel jettison system to', '[{"id": "a", "text": "prevent the centre from being defuelled.", "correct": false}, {"id": "b", "text": "prevent the dumping of the outer tanks.", "correct": true}, {"id": "c", "text": "automatically stop the fuel jettison operation after a period of time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The advantages of integral fuel tanks are that they', '[{"id": "a", "text": "are easier to design and construct and use the maximum volume of fuel.", "correct": false}, {"id": "b", "text": "are cheaper to manufacture, more durable and easier to maintain.", "correct": false}, {"id": "c", "text": "use the maximum volume for fuel and have the minimum amount of weight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On Large transport aircraft fuel is delivered to each engine using', '[{"id": "a", "text": "a separate system for each engine.", "correct": true}, {"id": "b", "text": "the same system for each engine.", "correct": false}, {"id": "c", "text": "a parallel system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a constant volume hydraulic EDP, the short shaft which engages with the engine gearbox would have', '[{"id": "a", "text": "2 female splined portions separated by a waisted section.", "correct": false}, {"id": "b", "text": "an inner female splined portion and an outer male splined portion.", "correct": false}, {"id": "c", "text": "2 male spline portions seperated by a waisted section designed to shear should the pump seize.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the unit which transforms hydraulic pressure into linear motion?', '[{"id": "a", "text": "A hydraulic pump.", "correct": false}, {"id": "b", "text": "An actuating cylinder.", "correct": true}, {"id": "c", "text": "An accumulator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the unit which transforms hydraulic pressure into rotary motion?', '[{"id": "a", "text": "A hydraulic motor.", "correct": true}, {"id": "b", "text": "An actuating cylinder.", "correct": false}, {"id": "c", "text": "A hydraulic pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which device allows the free flow of fluid in one direction and no fluid flow in the other direction?', '[{"id": "a", "text": "Shutoff valve.", "correct": false}, {"id": "b", "text": "Metering piston.", "correct": false}, {"id": "c", "text": "Check valve.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hydraulic pressure can be restored by', '[{"id": "a", "text": "compressing the air charge in an accumulator.", "correct": true}, {"id": "b", "text": "the use of a pressure/heat exchanger.", "correct": false}, {"id": "c", "text": "compressing the fluid in a reservoir.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An hydraulic accumulator has low air/nitrogen pressure. What will be the indications?', '[{"id": "a", "text": "Full pressure indicated.", "correct": false}, {"id": "b", "text": "Zero pressure indicated.", "correct": false}, {"id": "c", "text": "The cut-out valve chatters.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To enable a hydraulic system to operate two components with different pressures, a', '[{"id": "a", "text": "pressure reducing valve is used.", "correct": true}, {"id": "b", "text": "pressure regulating valve is used.", "correct": false}, {"id": "c", "text": "pressure relief valve is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Restrictor valves are fitted in hydraulic systems to', '[{"id": "a", "text": "control rate of system operation.", "correct": true}, {"id": "b", "text": "limit the maximum pressure.", "correct": false}, {"id": "c", "text": "restrict the rate of pressure build-up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What type of valve prevents pressure from building up until a demand is placed in an open- center hydraulic system?', '[{"id": "a", "text": "An unloading valve.", "correct": false}, {"id": "b", "text": "A selector valve.", "correct": true}, {"id": "c", "text": "A bypass valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an open-centre hydraulic system, system pressure is provided', '[{"id": "a", "text": "only when the selector valve is set to ON.", "correct": true}, {"id": "b", "text": "only when the selector valve is set to OFF.", "correct": false}, {"id": "c", "text": "continuously.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an open-centre hydraulic system, selector valves are positioned', '[{"id": "a", "text": "in parallel.", "correct": false}, {"id": "b", "text": "either in series or in parallel depending on the system design.", "correct": false}, {"id": "c", "text": "in series.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the colour of the band on a hydraulic seal?', '[{"id": "a", "text": "White.", "correct": false}, {"id": "b", "text": "Green.", "correct": true}, {"id": "c", "text": "Yellow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A maintainer valve in a hydraulic system will', '[{"id": "a", "text": "maintain a high pressure to all systems.", "correct": false}, {"id": "b", "text": "allow continued pressure to essential systems during times of reduced supply.", "correct": true}, {"id": "c", "text": "dampen pressure inputs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where is the temperature overheat switch located in a hydraulic pump?.', '[{"id": "a", "text": "In the suction line.", "correct": false}, {"id": "b", "text": "In the case drain.", "correct": true}, {"id": "c", "text": "In the pressure line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens if a component has an internal hydraulic leak?', '[{"id": "a", "text": "Increase in fluid pressure.", "correct": false}, {"id": "b", "text": "Increase in fluid temperature.", "correct": true}, {"id": "c", "text": "Fluid loss.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens to hydraulic fluid when it is overheated?', '[{"id": "a", "text": "Increase alkalinity.", "correct": false}, {"id": "b", "text": "Increase viscosity.", "correct": false}, {"id": "c", "text": "Increase acidity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the hydraulic pump depressurising solenoid actuated?', '[{"id": "a", "text": "Energised both open and closed depending on cockpit selection.", "correct": false}, {"id": "b", "text": "Energised Closed for fail-safe.", "correct": true}, {"id": "c", "text": "Energised Open.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do you prevent hydraulic fluid frothing?', '[{"id": "a", "text": "By pressurising.", "correct": true}, {"id": "b", "text": "Vent Reservoir to atmosphere.", "correct": false}, {"id": "c", "text": "Pass over a tray.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Accumulators as fitted to aircraft hydraulic systems', '[{"id": "a", "text": "are only ever used in an emergency.", "correct": false}, {"id": "b", "text": "store fluid under pressure.", "correct": true}, {"id": "c", "text": "provide additional fluid if leaks occur.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Skydrol hydraulic fluid seal would be made of', '[{"id": "a", "text": "natural rubber.", "correct": false}, {"id": "b", "text": "synthetic rubber.", "correct": false}, {"id": "c", "text": "butyl rubber, ethylene propylene or Teflon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Synthetic hydraulic fluid subjected to overheating is high in', '[{"id": "a", "text": "alkalinity.", "correct": false}, {"id": "b", "text": "acidity.", "correct": true}, {"id": "c", "text": "viscosity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A normal hydraulic system will', '[{"id": "a", "text": "show fluid temperature and quantity.", "correct": false}, {"id": "b", "text": "show pressure and source of hydraulics.", "correct": true}, {"id": "c", "text": "illuminate a light in the cockpit when the system is ready.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A constant volume hydraulic system uses what to relieve pressure in system when no services are being used?', '[{"id": "a", "text": "ACOV.", "correct": true}, {"id": "b", "text": "Pressure relief valve.", "correct": false}, {"id": "c", "text": "Return line back to pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The control of hydraulically powered emergency electrical generator frequency is by', '[{"id": "a", "text": "restriction valve.", "correct": false}, {"id": "b", "text": "angle of swashplate.", "correct": true}, {"id": "c", "text": "IDG.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hydraulic systems normally operate at', '[{"id": "a", "text": "1800 PSI.", "correct": false}, {"id": "b", "text": "3000 PSI.", "correct": true}, {"id": "c", "text": "300 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When flushing hydraulic systems.', '[{"id": "a", "text": "flush with any hydraulic oil.", "correct": false}, {"id": "b", "text": "flush with same hydraulic oil.", "correct": true}, {"id": "c", "text": "flush with methylated spirit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When replenishing a hydraulic system', '[{"id": "a", "text": "use the same/correct hydraulic fluid.", "correct": true}, {"id": "b", "text": "use any hydraulic fluid made by the same manufacturer.", "correct": false}, {"id": "c", "text": "use any hydraulic fluid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When replacing a flexible pipe', '[{"id": "a", "text": "tighten only hand tight.", "correct": false}, {"id": "b", "text": "do a bonding check.", "correct": false}, {"id": "c", "text": "use two spanners to stop pipe from twisting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do you remove air from hydraulic fluid?', '[{"id": "a", "text": "Pass over a tray .", "correct": true}, {"id": "b", "text": "Vent to atmosphere .", "correct": false}, {"id": "c", "text": "Pass through a restriction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pressure control relay in a hydraulic pump is', '[{"id": "a", "text": "used to prevent anything happening until there is hydraulic pressure .", "correct": false}, {"id": "b", "text": "de-energised to start the pump .", "correct": false}, {"id": "c", "text": "energised to the run position .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A constant delivery pump has its output varied with', '[{"id": "a", "text": "regulators .", "correct": true}, {"id": "b", "text": "gears.", "correct": false}, {"id": "c", "text": "servo pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A variable angled pump starts at', '[{"id": "a", "text": "half way position .", "correct": false}, {"id": "b", "text": "maximum stroke.", "correct": true}, {"id": "c", "text": "minimum stroke .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A check flow valve in a hydraulic system prevents', '[{"id": "a", "text": "overpressure.", "correct": false}, {"id": "b", "text": "pump cavitation.", "correct": false}, {"id": "c", "text": "reverse flow.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A duplex seal consist of', '[{"id": "a", "text": "a square section rubber ring within a steel washer .", "correct": false}, {"id": "b", "text": "a rubber ''T'' section ring sandwiched between two Teflon rings.", "correct": false}, {"id": "c", "text": "a hard rubber square section ring with a soft rubber square section inner ring .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When is a hydraulic de-pressurising valve energised?', '[{"id": "a", "text": "When there is sufficient hydraulic pressure available .", "correct": false}, {"id": "b", "text": "When selected off .", "correct": true}, {"id": "c", "text": "When selected on .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fixed volume axial pump contains the following rotating parts:', '[{"id": "a", "text": "Drive Shaft, variable Swash Plate and Cylinder Block .", "correct": false}, {"id": "b", "text": "Drive Shaft, fixed Swash Plate and Cylinder Block .", "correct": true}, {"id": "c", "text": "Drive Shaft, fixed Swash Plate and Valve Block.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An hydraulic closed system is one where', '[{"id": "a", "text": "most of the major components of the system are included in a self contained unit .", "correct": false}, {"id": "b", "text": "there is no pressure at the selector valves when no functions are required .", "correct": false}, {"id": "c", "text": "pressure is maintained at the selector valves at all times .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What constitutes a hydraulic power pack?', '[{"id": "a", "text": "Hydraulic oil accumulator .", "correct": false}, {"id": "b", "text": "Variable swashplate pump.", "correct": false}, {"id": "c", "text": "Reservoir, pump, selector valve, filter .", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an accumulator loses air pressure there will be', '[{"id": "a", "text": "rapid fluctuations of instruments .", "correct": true}, {"id": "b", "text": "rapid depressurisation of system .", "correct": false}, {"id": "c", "text": "pump cavitation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A marker number on a pipe indicates', '[{"id": "a", "text": "the specification of the pipe throughout the pipe run .", "correct": true}, {"id": "b", "text": "the thickness of the wall on the pipe.", "correct": false}, {"id": "c", "text": "the type of fluid used to pressure test the pipe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One reason for fitting an accumulator in a hydraulic system is to', '[{"id": "a", "text": "minimize the possibility of pump cavitation.", "correct": false}, {"id": "b", "text": "relieve excess pressure .", "correct": false}, {"id": "c", "text": "absorb pressure surges.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A thermal relief valve is fitted to a hydraulic system to', '[{"id": "a", "text": "relieve excess pressure .", "correct": true}, {"id": "b", "text": "prevent a leak back of pressure.", "correct": false}, {"id": "c", "text": "prevent excess temperature .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A component in a hydraulic system which ensures instantaneous action when a service is selected is', '[{"id": "a", "text": "selector.", "correct": false}, {"id": "b", "text": "engine driven pump.", "correct": false}, {"id": "c", "text": "accumulator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A shuttle valve is used for', '[{"id": "a", "text": "change over from main to auxiliary system in the case of failure.", "correct": true}, {"id": "b", "text": "preventing fluid loss from a leaking jack.", "correct": false}, {"id": "c", "text": "maintaining fluid press when the emergency system fails.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Restrictor valves in a hydraulic system are used to', '[{"id": "a", "text": "restrict the rate of pressure build up .", "correct": false}, {"id": "b", "text": "control the rate of system operation .", "correct": true}, {"id": "c", "text": "limit the maximum pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a mechanical sequence valve is to ensure the operation of', '[{"id": "a", "text": "landing gear and doors.", "correct": true}, {"id": "b", "text": "safety switches .", "correct": false}, {"id": "c", "text": "brake anti-skid units .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of a non-return valve is to', '[{"id": "a", "text": "isolate one component from another.", "correct": true}, {"id": "b", "text": "restrict the movement of components .", "correct": false}, {"id": "c", "text": "direct fluid to the hydraulic actuator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The end fittings on a NRV are normally different to', '[{"id": "a", "text": "prevent incorrect installation .", "correct": true}, {"id": "b", "text": "allow a full flow from the valve .", "correct": false}, {"id": "c", "text": "facilitate bleeding of the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A hydraulic accumulator is charged with initial nitrogen pressure of 1000 PSI . When the hydraulic system pressure of 3000 PSI is reached, the nitrogen pressure is', '[{"id": "a", "text": "4000 PSI.", "correct": false}, {"id": "b", "text": "3000 PSI.", "correct": true}, {"id": "c", "text": "1000 PSI .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Automatic cut-out valve hammering is caused by', '[{"id": "a", "text": "low accumulator pressure .", "correct": true}, {"id": "b", "text": "relief valve set too high.", "correct": false}, {"id": "c", "text": "moisture in the fluid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hand pumps are normally single cylinder double acting because of the', '[{"id": "a", "text": "two NRVS fitted .", "correct": true}, {"id": "b", "text": "piston ram displacement .", "correct": false}, {"id": "c", "text": "relief valve .", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'During a leak test of a hydraulic system, system pressure', '[{"id": "a", "text": "must be minimum working.", "correct": false}, {"id": "b", "text": "is not important.", "correct": false}, {"id": "c", "text": "must be at maximum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Constant delivery hydraulic pumps', '[{"id": "a", "text": "require an automatic cut-out valve in the system.", "correct": false}, {"id": "b", "text": "are self idling.", "correct": false}, {"id": "c", "text": "require an automatic cut-out valve and accumulator in the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Mechanical sequence valves are operated by', '[{"id": "a", "text": "the operation of a NRV.", "correct": false}, {"id": "b", "text": "the pilot.", "correct": false}, {"id": "c", "text": "a striker pin.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure relay valves are fitted', '[{"id": "a", "text": "before a pressure sequence valve.", "correct": false}, {"id": "b", "text": "before a pressure gauge.", "correct": true}, {"id": "c", "text": "before a pressure relief valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before checking the initial pressure in the hydraulic accumulator', '[{"id": "a", "text": "the reservoir must be checked for correct level.", "correct": false}, {"id": "b", "text": "the fluid pressure must be released.", "correct": true}, {"id": "c", "text": "all air must be bled from the system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hydraulic reservoirs are pressurized to', '[{"id": "a", "text": "provide a reserve of stored energy.", "correct": false}, {"id": "b", "text": "minimize the possibility of pump cavitation.", "correct": true}, {"id": "c", "text": "maintain a constant fluid level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In aircraft hydraulic systems, it is permissible to use', '[{"id": "a", "text": "any fluid of the same specific gravity.", "correct": false}, {"id": "b", "text": "any hydraulic fluid available.", "correct": false}, {"id": "c", "text": "only the specified fluid.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The essential components of a hydraulic system of the constant delivery type are an', '[{"id": "a", "text": "accumulator and relay valve.", "correct": false}, {"id": "b", "text": "accumulator and automatic cut-out valve.", "correct": true}, {"id": "c", "text": "accumulator and shuttle valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An automatic cut-out valve will', '[{"id": "a", "text": "limit pump wear.", "correct": true}, {"id": "b", "text": "prevent the hydraulic lock forming.", "correct": false}, {"id": "c", "text": "raise fluid boiling point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A maintaining valve is fitted to a hydraulic system', '[{"id": "a", "text": "relieve excessive pressure to return.", "correct": false}, {"id": "b", "text": "to maintain a back pressure to the accumulator.", "correct": false}, {"id": "c", "text": "to ensure a supply of fluid to essential services in the event of system failure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A thermal relief valve', '[{"id": "a", "text": "senses fluid pressure.", "correct": true}, {"id": "b", "text": "provides cooling for the fluid.", "correct": false}, {"id": "c", "text": "senses fluid temperature change.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hydraulic systems are normally flushed with', '[{"id": "a", "text": "any clean hydraulic fluid.", "correct": false}, {"id": "b", "text": "methylated spirits.", "correct": false}, {"id": "c", "text": "the same type of fluid as used in the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Phosphate Ester hydraulic fluid requires which kind of seals?', '[{"id": "a", "text": "Butyl Rubber.", "correct": true}, {"id": "b", "text": "Natural Rubber.", "correct": false}, {"id": "c", "text": "Synthetic Rubber.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A RAT hydraulic pump is for', '[{"id": "a", "text": "flying controls if hydraulic power lost.", "correct": true}, {"id": "b", "text": "landing gear and auto-brake systems.", "correct": false}, {"id": "c", "text": "nose wheel steering.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hydraulic hand-pump fluid supply is taken from', '[{"id": "a", "text": "a tap into a convenient return line.", "correct": false}, {"id": "b", "text": "the bottom of the reservoir.", "correct": true}, {"id": "c", "text": "a stack pipe higher than the normal level.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Hand pumps in hydraulic systems are normally', '[{"id": "a", "text": "double acting.", "correct": true}, {"id": "b", "text": "low pressure.", "correct": false}, {"id": "c", "text": "single acting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To enable a hydraulic system to operate two components requiring different pressures', '[{"id": "a", "text": "a pressure reducing valve is used.", "correct": true}, {"id": "b", "text": "a pressure relief valve is used.", "correct": false}, {"id": "c", "text": "a pressure regulating valve is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The force exerted by a hydraulic cylinder is equal to', '[{"id": "a", "text": "pressure x stroke.", "correct": false}, {"id": "b", "text": "area x pressure.", "correct": true}, {"id": "c", "text": "area x volume.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tandem PFCU', '[{"id": "a", "text": "has the rams parallel.", "correct": false}, {"id": "b", "text": "has two control surfaces under its control.", "correct": false}, {"id": "c", "text": "has the actuator rams co-axial.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The reason why slack must be left in a flexible hose during installation, is a flexible hose under pressure', '[{"id": "a", "text": "contracts in length and expands in diameter.", "correct": true}, {"id": "b", "text": "contracts in length and diameter.", "correct": false}, {"id": "c", "text": "expands in length and diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An automatic cut-out valve is necessary in a hydraulic system with', '[{"id": "a", "text": "a fixed volume pump.", "correct": true}, {"id": "b", "text": "pressures above 3000 PSI.", "correct": false}, {"id": "c", "text": "a variable volume pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When should rain repellent be applied to a windscreen?', '[{"id": "a", "text": "When windscreen is wet.", "correct": true}, {"id": "b", "text": "When windscreen is dry.", "correct": false}, {"id": "c", "text": "When windscreen is either wet or dry.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A pressure operated ice detector would', '[{"id": "a", "text": "have a build up of ice that causes a torque switch to illuminate a flight deck annunciator.", "correct": false}, {"id": "b", "text": "be completely covered in ice before causing an alarm to sound on the flight deck.", "correct": false}, {"id": "c", "text": "have a build up of ice on the leading edge that causes a warning light to illuminate on the flight deck.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The flow rate of anti-icing fluid is determined', '[{"id": "a", "text": "by speed of pump.", "correct": false}, {"id": "b", "text": "by flow control valve.", "correct": false}, {"id": "c", "text": "by flow control tubes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Details entered in the operational log regarding the De-Icing is', '[{"id": "a", "text": "area on which used.", "correct": false}, {"id": "b", "text": "type of fluid used and its percentage dilution.", "correct": true}, {"id": "c", "text": "volume of fluid used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The ice protection system that is manufactured on the aircraft skin is', '[{"id": "a", "text": "heater mat.", "correct": false}, {"id": "b", "text": "overshoe.", "correct": false}, {"id": "c", "text": "spraymat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the chemicals used in modern chemical de-icing?', '[{"id": "a", "text": "Isopropyl alcohol.", "correct": false}, {"id": "b", "text": "A mixture of ethylene glycol and alcohol.", "correct": false}, {"id": "c", "text": "Either Isopropyl alcohol or ethylene glycol.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where does ice form on the aircraft?', '[{"id": "a", "text": "Leading edges only.", "correct": false}, {"id": "b", "text": "Areas with larger curvature radius.", "correct": false}, {"id": "c", "text": "Area with smaller curvature radius.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Window anti-icing supply is', '[{"id": "a", "text": "DC.", "correct": false}, {"id": "b", "text": "AC or DC.", "correct": false}, {"id": "c", "text": "AC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ice formed on the object or surface will change its shape, this changes is more detrimental and vulnerable to a', '[{"id": "a", "text": "fast moving object.", "correct": false}, {"id": "b", "text": "large object.", "correct": false}, {"id": "c", "text": "small object.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In which ice detection method, the activation of warning system is through accumulation of ice on a probe projected into the airstream?', '[{"id": "a", "text": "Inferential method.", "correct": false}, {"id": "b", "text": "Ice accretion method.", "correct": true}, {"id": "c", "text": "Impingement method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The inflatable tube of the de-icer boots is made of', '[{"id": "a", "text": "natural rubber.", "correct": false}, {"id": "b", "text": "synthetic rubber.", "correct": false}, {"id": "c", "text": "rubberised fabric.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is rain repellent stored on an aircraft?', '[{"id": "a", "text": "Reservoir, pressurised by the pneumatic system.", "correct": false}, {"id": "b", "text": "Self pressurised container.", "correct": true}, {"id": "c", "text": "Remote container.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When testing windshield wipers, you should', '[{"id": "a", "text": "lift the wipers away from the windshield.", "correct": false}, {"id": "b", "text": "use a continuous flow of water on the windshield.", "correct": true}, {"id": "c", "text": "operate them on a dry windshield.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the correct way of measuring the windshield wiper force prior to adjustment?', '[{"id": "a", "text": "With a spring tension scale.", "correct": true}, {"id": "b", "text": "By measuring the maximum total angle of sweep.", "correct": false}, {"id": "c", "text": "With a torque screwdriver and light thumb pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is a serrated rod ice detector bench tested?', '[{"id": "a", "text": "Screwdriver torque test.", "correct": true}, {"id": "b", "text": "Motor test and go/no-go gap measurement.", "correct": false}, {"id": "c", "text": "By a motor load test.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windshield heating provides', '[{"id": "a", "text": "thermal expansion for a tighter fit.", "correct": false}, {"id": "b", "text": "impact resistance enhancement.", "correct": true}, {"id": "c", "text": "increases strength to resist cabin pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At what pressure and temperature is anti ice fluid applied?', '[{"id": "a", "text": "7°F at 100 PSI.", "correct": false}, {"id": "b", "text": "70°C at 100 PSI.", "correct": true}, {"id": "c", "text": "70°F at 10 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The most important problem of ice accretion on an aeroplane during flight is', '[{"id": "a", "text": "increase in drag.", "correct": false}, {"id": "b", "text": "increase in weight.", "correct": false}, {"id": "c", "text": "reduction in CLmax.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The advantage of leading edge fluid de-icing is', '[{"id": "a", "text": "less of a fire hazard.", "correct": false}, {"id": "b", "text": "more efficient.", "correct": false}, {"id": "c", "text": "aerodynamic shape is not disturbed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On large transport aircraft, the windshield wiper system is', '[{"id": "a", "text": "independent on each side but with the same power source.", "correct": false}, {"id": "b", "text": "one system for both sides but with the same power source.", "correct": false}, {"id": "c", "text": "independent on each side with different power sources.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In which phase of the take-off is the aerodynamic effect of ice located on the wing leading edge most critical?', '[{"id": "a", "text": "The last part of the rotation.", "correct": true}, {"id": "b", "text": "During climb with all engines operating.", "correct": false}, {"id": "c", "text": "All phases of the take-off are equally critical.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Prior to securing a cemented leading edge de-icing boot you must', '[{"id": "a", "text": "paint the surface.", "correct": false}, {"id": "b", "text": "shave rivet to prevent further abrasion.", "correct": false}, {"id": "c", "text": "remove all paint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Prior to securing a screw-fastened leading edge de-icing boot you must', '[{"id": "a", "text": "shave rivet to prevent further abrasion.", "correct": false}, {"id": "b", "text": "paint the surface.", "correct": true}, {"id": "c", "text": "remove all paint.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a ''hot rod'' type of ice detector, it is switched on', '[{"id": "a", "text": "when in the air.", "correct": false}, {"id": "b", "text": "all the time.", "correct": false}, {"id": "c", "text": "when selected by the crew.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ice formation on wings is due to', '[{"id": "a", "text": "ice crystals forming layers on contact with the wing.", "correct": false}, {"id": "b", "text": "supercooled water changing state on contact with the wing.", "correct": true}, {"id": "c", "text": "suspended ice crystals melting on contact with the wing and instantly re-freezing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When a vibrating rod ice detector has de-iced, the warning lamp on the flight deck', '[{"id": "a", "text": "goes out after a set period of time.", "correct": true}, {"id": "b", "text": "goes out after one more cycle.", "correct": false}, {"id": "c", "text": "goes out immediately.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'De-misting of passenger windows is provided by', '[{"id": "a", "text": "sealed window.", "correct": false}, {"id": "b", "text": "air from the cabin.", "correct": true}, {"id": "c", "text": "an electrical heating element.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A deicer boot is completely bonded to the leading edge to', '[{"id": "a", "text": "prevent electrical static build up.", "correct": true}, {"id": "b", "text": "provide more efficient deicer cycles.", "correct": false}, {"id": "c", "text": "provide smoother airflow over leading edge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a cockpit window heater system, the autotransformer', '[{"id": "a", "text": "supplies DC power for heating.", "correct": false}, {"id": "b", "text": "supplies AC Power for heating.", "correct": false}, {"id": "c", "text": "steps up output for severe weather conditions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windshield rain repellent is applied', '[{"id": "a", "text": "when in heavy rain so vision is unobscured.", "correct": false}, {"id": "b", "text": "when rain is on windows and spread by wipers.", "correct": true}, {"id": "c", "text": "before rain and spread on window surface by wipers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pneumatic rain removal systems', '[{"id": "a", "text": "use a pneumatic motor to drive windscreen wipers.", "correct": false}, {"id": "b", "text": "use engine bleed air at high velocity to remove water droplets from windscreen.", "correct": true}, {"id": "c", "text": "are not permitted on large transport aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windscreen wiper torque tests are carried out at', '[{"id": "a", "text": "blade attachment end", "correct": false}, {"id": "b", "text": "the shaft end", "correct": true}, {"id": "c", "text": "centre point of the blade", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Windscreen autotransformers', '[{"id": "a", "text": "step down voltage.", "correct": false}, {"id": "b", "text": "are used to supply extra current under difficult conditions.", "correct": false}, {"id": "c", "text": "step up voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An ice deposit formed when liquid water flows over the airframe before freezing, and which is dense, tough and sticks closely to the surface is called', '[{"id": "a", "text": "rime Ice.", "correct": false}, {"id": "b", "text": "hoar Frost.", "correct": false}, {"id": "c", "text": "glaze Ice.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When testing pitot head heaters', '[{"id": "a", "text": "they must only be switched on for the minimum time required to check serviceability.", "correct": true}, {"id": "b", "text": "they should be switched on for five minutes to allow to stabilise before taking ammeter readings.", "correct": false}, {"id": "c", "text": "they can only be checked by noting the temperature rise of the probe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing thermal anti-ice annunciator is illuminated permanently in flight deck without selection being made. The most probable cause would be', '[{"id": "a", "text": "normal.", "correct": false}, {"id": "b", "text": "a short circuit.", "correct": true}, {"id": "c", "text": "an open circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Air for anti-icing of the wings is obtained from', '[{"id": "a", "text": "either engine compressors or a combustion heater.", "correct": true}, {"id": "b", "text": "engine compressors.", "correct": false}, {"id": "c", "text": "a combustion heater.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The usual material for pipelines in a fluid deice system', '[{"id": "a", "text": "nylon.", "correct": true}, {"id": "b", "text": "stainless steel.", "correct": false}, {"id": "c", "text": "Monel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When operating a windscreen wiper on the ground, make sure to', '[{"id": "a", "text": "place soft cloth between blade and window.", "correct": false}, {"id": "b", "text": "use water as lubricant when operating.", "correct": true}, {"id": "c", "text": "use slow wiper only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is run-back ice?', '[{"id": "a", "text": "Gleam ice.", "correct": false}, {"id": "b", "text": "Glaze ice.", "correct": true}, {"id": "c", "text": "Rime ice.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What should be done if a tyre has creeped round the hub?', '[{"id": "a", "text": "Remove tyre, reposition, then re-inflate.", "correct": false}, {"id": "b", "text": "Remove tyre, reposition the opposite way round to prevent more creep.", "correct": false}, {"id": "c", "text": "Remove from the hub for inspection.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Brake temperature readings provide', '[{"id": "a", "text": "separate brake indicator gauge indications.", "correct": false}, {"id": "b", "text": "master and caution warning.", "correct": true}, {"id": "c", "text": "coloured indications on a CRT display.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Spongy brakes are usually a result of', '[{"id": "a", "text": "external leakage.", "correct": false}, {"id": "b", "text": "air in the system.", "correct": true}, {"id": "c", "text": "internal leakage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Over inflated tyres may cause damage to the', '[{"id": "a", "text": "brake drum.", "correct": false}, {"id": "b", "text": "wheel hub.", "correct": false}, {"id": "c", "text": "wheel flange.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Landing gear comes down and goes up again. A likely cause is', '[{"id": "a", "text": "leak in selector valve.", "correct": true}, {"id": "b", "text": "leak in actuating cylinder.", "correct": false}, {"id": "c", "text": "leak in reservoir.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tyre valve cap is used to', '[{"id": "a", "text": "secure the valve by screwing up to the shoulder of the wheel.", "correct": false}, {"id": "b", "text": "prevent a leak.", "correct": true}, {"id": "c", "text": "secure the valve by screwing up to the valve base.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The drag strut in the main landing gear is fitted to absorb', '[{"id": "a", "text": "turning loads while taxiing.", "correct": false}, {"id": "b", "text": "cross-wind loads on landing.", "correct": false}, {"id": "c", "text": "braking and take-off acceleration loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is a wheel and tyre assembly stored?', '[{"id": "a", "text": "Three quarters of full pressure.", "correct": false}, {"id": "b", "text": "With full pressure.", "correct": false}, {"id": "c", "text": "Inflated to 20-30 PSI.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Anti skid', '[{"id": "a", "text": "applies wheel torque at point of maximum efficiency.", "correct": true}, {"id": "b", "text": "is a 3-option system.", "correct": false}, {"id": "c", "text": "moderates braking with increasing wheel torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The operational hydraulic pressure for the nose wheel steering system of large aircraft normally comes from', '[{"id": "a", "text": "the landing gear up line.", "correct": false}, {"id": "b", "text": "an independent hydraulic system.", "correct": false}, {"id": "c", "text": "the landing gear down line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When removing the wheel with a multiple disks brake, the wheel brake should be', '[{"id": "a", "text": "set OFF (released).", "correct": false}, {"id": "b", "text": "disconnected first.", "correct": false}, {"id": "c", "text": "set ON (applied).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tyre blows a fusible plug. You would', '[{"id": "a", "text": "just change the one with the blown plug.", "correct": false}, {"id": "b", "text": "change the damaged one and the adjacent one.", "correct": true}, {"id": "c", "text": "change all tyres on that truck.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Twin contact tread tyres are fitted to the nose wheel to assist in', '[{"id": "a", "text": "preventing nose wheel shimmy.", "correct": true}, {"id": "b", "text": "deflecting water away from rear mounted engines.", "correct": false}, {"id": "c", "text": "preventing aquaplaning.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Whilst taxiing at low speed, a wheel skids. What is the likely cause?', '[{"id": "a", "text": "There is no fault. Anti-skid system is disabled at low speed.", "correct": true}, {"id": "b", "text": "Anti-skid system is unserviceable.", "correct": false}, {"id": "c", "text": "Faulty wheel speed transducer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A brake debooster valve is provided for', '[{"id": "a", "text": "increasing the pressure and applying the brakes rapidly.", "correct": false}, {"id": "b", "text": "decreasing the pressure and slowly releasing the brakes.", "correct": false}, {"id": "c", "text": "applying brake pressure slowly and releasing the the brakes quickly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Anti-skid systems become deactivated at', '[{"id": "a", "text": "5-10 mph.", "correct": false}, {"id": "b", "text": "10-15 mph.", "correct": false}, {"id": "c", "text": "15-20 mph.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The landing gear is in the down and locked position but the red light is still on. The most probable fault is', '[{"id": "a", "text": "the landing gear down microswitch needs adjusting.", "correct": true}, {"id": "b", "text": "the landing gear up microswitch needs adjusting.", "correct": false}, {"id": "c", "text": "there is a short circuit in the microswitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tubeless tyres are stored', '[{"id": "a", "text": "vertically.", "correct": true}, {"id": "b", "text": "horizontally maximum of four high with smallest diameter tyre on top.", "correct": false}, {"id": "c", "text": "at 15 to 20 P.S.I.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a wheel bogie unit, positive camber is when the', '[{"id": "a", "text": "top of the wheels are closer together.", "correct": false}, {"id": "b", "text": "front of the wheels are closer together.", "correct": false}, {"id": "c", "text": "bottom of the wheels are closer together.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A badly corroded and pitted brake disk will', '[{"id": "a", "text": "produce a loss of fluid.", "correct": false}, {"id": "b", "text": "be serviceable, and provide better grip.", "correct": false}, {"id": "c", "text": "wear brake pads too quickly, and should be replaced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How much oxygen is in a tyre (as a maximum)?', '[{"id": "a", "text": "15% by volume.", "correct": false}, {"id": "b", "text": "5% by pressure.", "correct": false}, {"id": "c", "text": "5% by volume.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tyre specification 32 x 10.75 - 14. What does the 10.75 refer to?', '[{"id": "a", "text": "Section Width.", "correct": true}, {"id": "b", "text": "Overall diameter.", "correct": false}, {"id": "c", "text": "Bead diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When servicing an oleo, fluid comes out of the air valve when the leg is depressurised?.', '[{"id": "a", "text": "Leaking air/oil seals.", "correct": false}, {"id": "b", "text": "Separator plate stuck open.", "correct": false}, {"id": "c", "text": "The leg is serviceable - the separator has bottomed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The type of fluid in an oleo strut will depend upon', '[{"id": "a", "text": "the type of seal material.", "correct": false}, {"id": "b", "text": "heat generated in operation of the system.", "correct": true}, {"id": "c", "text": "type of fluid most readily available.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A restrictor valve', '[{"id": "a", "text": "restrict the extent of travel of the undercarriage.", "correct": false}, {"id": "b", "text": "may be used to slow down undercarriage extension.", "correct": true}, {"id": "c", "text": "speed up the flow in one direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The function of the oil in a shock absorber is to', '[{"id": "a", "text": "absorb the landing shock.", "correct": true}, {"id": "b", "text": "ensure the separator does not bottom.", "correct": false}, {"id": "c", "text": "damp the rebound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The purpose of the flutter plate in a shock absorber is to', '[{"id": "a", "text": "restrict the compression of the air.", "correct": false}, {"id": "b", "text": "permit free flow of oil during compression and restriction of oil during extension.", "correct": true}, {"id": "c", "text": "separate the oil from the air.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Made up wheels should be stored', '[{"id": "a", "text": "horizontal no more than 4 high.", "correct": false}, {"id": "b", "text": "vertical at working pressure.", "correct": false}, {"id": "c", "text": "vertical at 20/30 PSI charge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After MLG down and securely locked, a red light is illuminated in the flight deck. The possible causes are', '[{"id": "a", "text": "shorted sensor.", "correct": false}, {"id": "b", "text": "out of adjustment sensor.", "correct": true}, {"id": "c", "text": "wiring problem.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking for alignment of a MLG, check', '[{"id": "a", "text": "symmetry, tracking, camber.", "correct": true}, {"id": "b", "text": "symmetry, splay, tracking.", "correct": false}, {"id": "c", "text": "symmetry, twist, tracking.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'These markings are found on a tyre, 32 x 10.45 R 14. What does the number 32 mean?', '[{"id": "a", "text": "Inner diameter.", "correct": false}, {"id": "b", "text": "width.", "correct": false}, {"id": "c", "text": "Outer diameter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A green/grey dot marking on aircraft tyre casing represents', '[{"id": "a", "text": "breather points.", "correct": true}, {"id": "b", "text": "military reference.", "correct": false}, {"id": "c", "text": "the light part of the tyre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In detachable flange type wheels, the flange is secured by', '[{"id": "a", "text": "a lock ring.", "correct": true}, {"id": "b", "text": "a retainer plate.", "correct": false}, {"id": "c", "text": "bolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Fuse plugs in aircraft tyres are', '[{"id": "a", "text": "for overpressure protection.", "correct": true}, {"id": "b", "text": "for overtemperature protection.", "correct": false}, {"id": "c", "text": "to deflate the tyre before removal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A breaker strip in an aircraft tyre is', '[{"id": "a", "text": "to provide strength.", "correct": true}, {"id": "b", "text": "to provide a wear indication.", "correct": false}, {"id": "c", "text": "to indicate the position for tyre levers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If fluid leaks along with air whilst oleo charging, this is', '[{"id": "a", "text": "normal.", "correct": false}, {"id": "b", "text": "due to excessive charging pressure.", "correct": false}, {"id": "c", "text": "caused by a leaky seal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A red dot / triangle mark on aircraft tyres means', '[{"id": "a", "text": "military reference.", "correct": false}, {"id": "b", "text": "breather points.", "correct": false}, {"id": "c", "text": "the light part of the tyre.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On selection of MLG down, the gear extends then begins to retract again. The cause is', '[{"id": "a", "text": "a faulty actuator.", "correct": false}, {"id": "b", "text": "gear lowered at too high an airspeed.", "correct": false}, {"id": "c", "text": "a faulty selector valve.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When fitting a tyre, the red dot should be positioned', '[{"id": "a", "text": "opposite the charging valve.", "correct": false}, {"id": "b", "text": "adjacent to the charging valve.", "correct": true}, {"id": "c", "text": "on the other side of the wheel opposite to the charging valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Composite brake units', '[{"id": "a", "text": "have less weight than normal brake units and have increased efficiency at high temperatures.", "correct": true}, {"id": "b", "text": "weigh the same as normal brake units and fade away at high temperatures.", "correct": false}, {"id": "c", "text": "have less weight than normal brake units but fade away at high temperatures.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A restrictor valve can be used', '[{"id": "a", "text": "to increase the speed of the undercarriage extension.", "correct": false}, {"id": "b", "text": "to reduce the speed of the undercarriage extension.", "correct": true}, {"id": "c", "text": "to increase the speed of undercarriage retraction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an undercarriage is lowered, it tends to creep back up. The fault could be', '[{"id": "a", "text": "the emergency system.", "correct": false}, {"id": "b", "text": "a leaky selector valve.", "correct": true}, {"id": "c", "text": "a stuck relief valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vents holes are found on', '[{"id": "a", "text": "tubeless tyres.", "correct": false}, {"id": "b", "text": "tubed tyres.", "correct": false}, {"id": "c", "text": "tubed and tubeless tyres.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'At what temperature does a yellow fuse plug melt at?', '[{"id": "a", "text": "250°C.", "correct": false}, {"id": "b", "text": "200°C.", "correct": true}, {"id": "c", "text": "150°C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cam plate in a nose undercarriage is', '[{"id": "a", "text": "for alignment of the nose wheel steering on nose undercarriage extension.", "correct": false}, {"id": "b", "text": "part of the shimmy damper.", "correct": false}, {"id": "c", "text": "to align for nose wheel on nose undercarriage retraction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is tyre creep related to?', '[{"id": "a", "text": "Tyre moving around the wheel.", "correct": true}, {"id": "b", "text": "Horizontal movement of the tyre.", "correct": false}, {"id": "c", "text": "Vertical movement of the tyre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), '''Aquaplaning'' can be reduced by', '[{"id": "a", "text": "lowering slats.", "correct": false}, {"id": "b", "text": "an anti-skid device.", "correct": true}, {"id": "c", "text": "increased flaring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Why is a hydraulic damper fitted to a nose wheel steering system?', '[{"id": "a", "text": "To centralise the nose leg assembly during an up selection.", "correct": false}, {"id": "b", "text": "To centralise the nose wheel during an up selection.", "correct": false}, {"id": "c", "text": "To reduce vibration and shimmy.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What decides the type of oil used in an undercarriage leg?', '[{"id": "a", "text": "The material of the leg.", "correct": false}, {"id": "b", "text": "Neither, any oil can be used.", "correct": false}, {"id": "c", "text": "The types of seals the leg uses.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an anti-skid system', '[{"id": "a", "text": "brakes release on falling torque.", "correct": false}, {"id": "b", "text": "brakes are modulated to give most efficient braking.", "correct": true}, {"id": "c", "text": "brakes release on rising torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an undercarriage oleo has insufficient deflection, the likely cause is', '[{"id": "a", "text": "oil level too high.", "correct": false}, {"id": "b", "text": "loss of pressure/leakage.", "correct": false}, {"id": "c", "text": "nitrogen pressure too high.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Maxaret is used in what system?', '[{"id": "a", "text": "Self centring landing gear.", "correct": false}, {"id": "b", "text": "Tyre inflation.", "correct": false}, {"id": "c", "text": "Skid control.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pilot receives an audible warning on the flight deck as the aircraft is descending to land. The most likely reason for this warning is', '[{"id": "a", "text": "the landing gear is not locked down.", "correct": true}, {"id": "b", "text": "the airspeed is too high.", "correct": false}, {"id": "c", "text": "the rate of descent is too high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A restrictor in the landing gear hydraulic retraction and lowering system is positioned in the', '[{"id": "a", "text": "landing gear down line.", "correct": false}, {"id": "b", "text": "return line from the landing gear selector.", "correct": false}, {"id": "c", "text": "landing gear up line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wheel speed information is used in auto speed brake systems', '[{"id": "a", "text": "to stow the spoilers automatically when the aircraft has nearly stopped.", "correct": false}, {"id": "b", "text": "to ensure the aircraft is still rolling.", "correct": false}, {"id": "c", "text": "to ensure the aircraft has touched down and to give a slight time lapse before spoiler deployment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fusible plug fitted to an aircraft wheel prevents', '[{"id": "a", "text": "brakes seizure, if brake stators and rotors weld together under excessive temperatures.", "correct": false}, {"id": "b", "text": "over inflation of tyres during servicing.", "correct": false}, {"id": "c", "text": "tyre bursts due to high temperatures created by excessive braking.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the shuttle valve was stuck in the normal position', '[{"id": "a", "text": "neither system will be available.", "correct": false}, {"id": "b", "text": "normal braking will not be available.", "correct": false}, {"id": "c", "text": "emergency braking will not be available.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The breaker strip of a tyre is fitted', '[{"id": "a", "text": "between the tread rubber and the casing piles.", "correct": true}, {"id": "b", "text": "between the apex strip and the casing piles.", "correct": false}, {"id": "c", "text": "between the bead and the casing piles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Nose wheel steering in a modern aircraft is by', '[{"id": "a", "text": "rudder pedals.", "correct": false}, {"id": "b", "text": "the control column.", "correct": false}, {"id": "c", "text": "a separate pilot operated control.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The fusible plugs installed in some aircraft wheel will', '[{"id": "a", "text": "eliminate the need to check air pressure.", "correct": false}, {"id": "b", "text": "melt at a specified elevated temperature.", "correct": true}, {"id": "c", "text": "facilitate servicing of the wheel assembly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Excessive wear in the shoulder area of an aircraft tyre is an indication of', '[{"id": "a", "text": "excessive toe-in.", "correct": false}, {"id": "b", "text": "over-inflation.", "correct": false}, {"id": "c", "text": "under-inflation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ribbed tyres with marker tie bars may be worn to', '[{"id": "a", "text": "the top of the tie bar.", "correct": true}, {"id": "b", "text": "1 mm from the rib base.", "correct": false}, {"id": "c", "text": "the base of the tie bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On large aircraft, bogie type undercarriages are used to', '[{"id": "a", "text": "spread the weight over a large area.", "correct": true}, {"id": "b", "text": "absorb increased landing shock.", "correct": false}, {"id": "c", "text": "prevent skidding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To position the bogie beam at a suitable angle for retraction and landing, a', '[{"id": "a", "text": "snubber is used.", "correct": false}, {"id": "b", "text": "castoring damper is used.", "correct": false}, {"id": "c", "text": "hop damper is used.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On large aircraft, braked wheel assemblies are normally inflated with', '[{"id": "a", "text": "nitrogen and not more than 5% of air.", "correct": true}, {"id": "b", "text": "an argon and CO2 mixture.", "correct": false}, {"id": "c", "text": "nitrogen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Brake deboosters', '[{"id": "a", "text": "reduce the hydraulic pressure entering the brakes.", "correct": true}, {"id": "b", "text": "increase the hydraulic pressure entering the brakes.", "correct": false}, {"id": "c", "text": "assist the operation of the anti-skid unit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A modulator is fitted in conjunction with', '[{"id": "a", "text": "non-return valve.", "correct": false}, {"id": "b", "text": "brake control valves.", "correct": false}, {"id": "c", "text": "anti-skid units.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the case of pressurized aircraft, the nose-wheel bay', '[{"id": "a", "text": "is pressurized to a value higher than ambient but less than cabin pressure.", "correct": false}, {"id": "b", "text": "is not pressurized.", "correct": true}, {"id": "c", "text": "is subject to cabin pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An undercarriage that has the axle mounted directly onto the shock absorber is of which type', '[{"id": "a", "text": "Direct Acting.", "correct": true}, {"id": "b", "text": "Hydro Mechanical.", "correct": false}, {"id": "c", "text": "Articulated.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The minimum aquaplaning ground speed is', '[{"id": "a", "text": "9.6 times the root square of the tyre pressure in psi.", "correct": false}, {"id": "b", "text": "8.6 times the root square of the tyre pressure in psi.", "correct": true}, {"id": "c", "text": "8.6 times the tyre pressure in bar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tubed tyres are stored', '[{"id": "a", "text": "horizontally, up to 4 in total with the smallest at the top.", "correct": true}, {"id": "b", "text": "horizontally, up to 4 in total staggering them to prevent distortion of beads.", "correct": false}, {"id": "c", "text": "horizontally, up to 4 in total in a rack with supporting tubes so each tyre is supported at 2 points.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a main landing gear, what is positive camber?', '[{"id": "a", "text": "Bottom of wheels closer to fuselage centreline.", "correct": true}, {"id": "b", "text": "Front of wheels closer to fuselage centreline.", "correct": false}, {"id": "c", "text": "Top of wheels closer to fuselage centreline.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the landing gear is locked up, the cockpit indicator shows', '[{"id": "a", "text": "no indication.", "correct": true}, {"id": "b", "text": "green light.", "correct": false}, {"id": "c", "text": "red light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking the alignment of a main landing gear, check', '[{"id": "a", "text": "symmetry, tracking, camber.", "correct": true}, {"id": "b", "text": "symmetry, tracking, splay.", "correct": false}, {"id": "c", "text": "symmetry, tracking, twist.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tyre creep could be caused by', '[{"id": "a", "text": "excessive wear.", "correct": false}, {"id": "b", "text": "under pressure.", "correct": true}, {"id": "c", "text": "overpressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When inflating a tyre and you notice ice in the valve stem', '[{"id": "a", "text": "heat the valve stem gently with a blow torch.", "correct": false}, {"id": "b", "text": "carry on inflating as ice in the valve stem is no problem.", "correct": false}, {"id": "c", "text": "wait for ice to melt before carrying on with inflation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A method of helping to prevent aquaplaning is by fitting tyres which have', '[{"id": "a", "text": "a plain tread.", "correct": false}, {"id": "b", "text": "water dispersing treads.", "correct": true}, {"id": "c", "text": "twin contact.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Un-mounted tubeless tyres must be stored', '[{"id": "a", "text": "in the manufactures boxes.", "correct": false}, {"id": "b", "text": "horizontally.", "correct": false}, {"id": "c", "text": "vertically.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a single oleo leg with a stub axle used, the torque links will', '[{"id": "a", "text": "assist the wheel to castor.", "correct": false}, {"id": "b", "text": "keep the wheel in track.", "correct": true}, {"id": "c", "text": "allow the wheel to shimmy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When fitting a tyre to a hub, the red spot on the tyre should be in line with.', '[{"id": "a", "text": "maker''s serial number.", "correct": false}, {"id": "b", "text": "the valve assembly.", "correct": true}, {"id": "c", "text": "opposite side to the valve assembly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A red or yellow line on an inner tube would indicate', '[{"id": "a", "text": "balance indicator.", "correct": false}, {"id": "b", "text": "heavy spot.", "correct": true}, {"id": "c", "text": "light spot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a multi-brake unit with automatic adjusters, brake wear is checked by', '[{"id": "a", "text": "application of the brakes and checking indicator pin protrusion.", "correct": true}, {"id": "b", "text": "using a go-no go gauge to measure the gap between the cylinder and the thrust plate.", "correct": false}, {"id": "c", "text": "measuring the protrusion of the indicator pins with the brakes released.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What colour is the strobe light on the PORT wing?', '[{"id": "a", "text": "White.", "correct": true}, {"id": "b", "text": "Green.", "correct": false}, {"id": "c", "text": "Red.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the arc of a landing light?', '[{"id": "a", "text": "This is not covered in European legislation.", "correct": true}, {"id": "b", "text": "20°.", "correct": false}, {"id": "c", "text": "15°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With aircraft lights - which of the following is true?', '[{"id": "a", "text": "Starboard light green, port light red, tail light white.", "correct": true}, {"id": "b", "text": "Starboard light red, port light green, tail light Red.", "correct": false}, {"id": "c", "text": "Starboard light red, port light green, tail light White.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Emergency floor lighting system is inoperative, then', '[{"id": "a", "text": "the aircraft is allowed to fly empty to a main base.", "correct": false}, {"id": "b", "text": "the aircraft is not allowed to fly until repaired.", "correct": false}, {"id": "c", "text": "the aircraft is allowed to fly in daylight conditions only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A white navigation light, as viewed in the horizontal plane, will be at least', '[{"id": "a", "text": "20 candela.", "correct": true}, {"id": "b", "text": "50 candela.", "correct": false}, {"id": "c", "text": "240 candela.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fluorescent tube contains', '[{"id": "a", "text": "phosphor coatings, rare gases and mercury vapour.", "correct": true}, {"id": "b", "text": "orange coatings, rare gases and mercury vapour.", "correct": false}, {"id": "c", "text": "iodine coatings and rare gases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A white steady light is required', '[{"id": "a", "text": "of at least 3 lumens, at the rear of the aircraft 110 degrees either side of dead astern.", "correct": false}, {"id": "b", "text": "of at least 3 candelas, at the rear of the aircraft 110 degrees either side of dead astern.", "correct": false}, {"id": "c", "text": "of at least 3 candelas, at the rear of the aircraft 70 degrees either side of dead astern.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many floor path lights can you fly with unserviceable?', '[{"id": "a", "text": "15%.", "correct": false}, {"id": "b", "text": "25%.", "correct": true}, {"id": "c", "text": "20%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the arc of a landing light?', '[{"id": "a", "text": "20°.", "correct": false}, {"id": "b", "text": "15°.", "correct": false}, {"id": "c", "text": "11°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The visible angle of a white tail navigation light is', '[{"id": "a", "text": "110°.", "correct": false}, {"id": "b", "text": "11°.", "correct": false}, {"id": "c", "text": "140°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing navigation lights must be visible through which angle?', '[{"id": "a", "text": "125°.", "correct": false}, {"id": "b", "text": "180°.", "correct": false}, {"id": "c", "text": "110°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cockpit dome lighting is provided by the', '[{"id": "a", "text": "battery bus and ground services bus.", "correct": true}, {"id": "b", "text": "ground services bus.", "correct": false}, {"id": "c", "text": "battery bus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Upper and lower strobe lights are coloured', '[{"id": "a", "text": "green.", "correct": false}, {"id": "b", "text": "white.", "correct": false}, {"id": "c", "text": "red.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cargo bay lights on a modern aircraft are supplied by', '[{"id": "a", "text": "the battery bus.", "correct": false}, {"id": "b", "text": "DC handling bus.", "correct": false}, {"id": "c", "text": "AC handling bus.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What will happen if the Master Dim and test switch is switched to the on position?', '[{"id": "a", "text": "Dome lights will illuminate.", "correct": false}, {"id": "b", "text": "All lights will illuminate.", "correct": false}, {"id": "c", "text": "Rectangular indicator lights will illuminate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Escape route lighting must not have more than', '[{"id": "a", "text": "20% obscured.", "correct": true}, {"id": "b", "text": "15% obscured.", "correct": false}, {"id": "c", "text": "10% obscured.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many escape path lights are allowed to be inoperative?', '[{"id": "a", "text": "None.", "correct": false}, {"id": "b", "text": "25%.", "correct": true}, {"id": "c", "text": "10%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The angle of a runway turnoff light is', '[{"id": "a", "text": "40°.", "correct": false}, {"id": "b", "text": "60°.", "correct": false}, {"id": "c", "text": "50°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin fluorescent lighting circuits are supplied with', '[{"id": "a", "text": "28 V AC.", "correct": false}, {"id": "b", "text": "28 V AC.", "correct": false}, {"id": "c", "text": "115 V AC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are passenger reading lights normally tested?', '[{"id": "a", "text": "By using a READ LIGHT TEST switch on the cabin attendant panel.", "correct": true}, {"id": "b", "text": "Each one is switched on individually at passenger panel.", "correct": false}, {"id": "c", "text": "By using a READ LIGHT TEST switch at any passenger panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In what position should the selector switch be for a standby and emergency lighting system during flight?', '[{"id": "a", "text": "Armed.", "correct": true}, {"id": "b", "text": "OFF.", "correct": false}, {"id": "c", "text": "ON.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The emergency lighting system must be designed so that after any single transverse vertical separation of the fuselage during crash landing the maximum amount of emergency lighting that fails is', '[{"id": "a", "text": "10%.", "correct": false}, {"id": "b", "text": "15%.", "correct": false}, {"id": "c", "text": "25%.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A rotating beacon must have a minimum light rating of', '[{"id": "a", "text": "50 candelas.", "correct": false}, {"id": "b", "text": "100 candelas.", "correct": false}, {"id": "c", "text": "20 candelas.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Service lights include', '[{"id": "a", "text": "avionics bay lights, engine scanning lights, baggage compartment lights.", "correct": false}, {"id": "b", "text": "baggage compartment lights, avionics bay lights, refuelling lights.", "correct": true}, {"id": "c", "text": "refuelling lights, engine scanning lights, logo lights.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the ''blow-back'' device on a landing lamp operates, how is it reset?', '[{"id": "a", "text": "The linkage must be repositioned and latched when the aircraft is on the ground.", "correct": false}, {"id": "b", "text": "Select full ''RETRACT''.", "correct": true}, {"id": "c", "text": "It cannot. The unit must be replaced because of the high stress loads experienced.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before touching or disconnecting a strobe light head, a time period must elapse to avoid electrical shock or burning. That time period is at least', '[{"id": "a", "text": "1 minute.", "correct": false}, {"id": "b", "text": "2 minutes.", "correct": true}, {"id": "c", "text": "5 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The rear light of an aircraft must be white and, in addition, must show through an inclusive angle of', '[{"id": "a", "text": "110 degrees and be 5 candelas minimum.", "correct": false}, {"id": "b", "text": "110 degrees and be 40 candelas minimum.", "correct": false}, {"id": "c", "text": "140 degrees and be 3 candelas minimum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Self-illuminating signs', '[{"id": "a", "text": "are self powered and contain phosphor and helium gas.", "correct": false}, {"id": "b", "text": "are instantly seen in dark areas by persons who are not dark adapted.", "correct": true}, {"id": "c", "text": "require a period of daylight, or intense artificial light to operate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When an annunciator light is selected to ''DIM'', the resistor is in', '[{"id": "a", "text": "parallel with the light and the transistor is not conducting.", "correct": false}, {"id": "b", "text": "series with the light and the transistor is not conducting.", "correct": false}, {"id": "c", "text": "series with the light and the transistor is conducting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Storm lights are usually fluorescent lights that are switched on', '[{"id": "a", "text": "because lightning has less effect on fluorescent lamp units.", "correct": false}, {"id": "b", "text": "to reduce the effect of lightning on the pilot''s sight.", "correct": true}, {"id": "c", "text": "and the glare-shield lights are automatically dimmed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Captain and First Officer''s ''Dome'' lights can be dimmed', '[{"id": "a", "text": "individually.", "correct": false}, {"id": "b", "text": "together.", "correct": true}, {"id": "c", "text": "First Officer''s only in emergency mode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the CWS system, the caution light is coloured', '[{"id": "a", "text": "amber.", "correct": true}, {"id": "b", "text": "red.", "correct": false}, {"id": "c", "text": "green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a CWS, which has the highest priority?', '[{"id": "a", "text": "Duct overheat.", "correct": false}, {"id": "b", "text": "Hydraulic pump failure.", "correct": false}, {"id": "c", "text": "Fire warning.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What inert gas is used in a typical strobe light?', '[{"id": "a", "text": "Halon.", "correct": false}, {"id": "b", "text": "Freon.", "correct": false}, {"id": "c", "text": "Xenon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Floor proximity lighting is a mandatory requirement and each light should be spaced', '[{"id": "a", "text": "at 70 inch intervals.", "correct": false}, {"id": "b", "text": "at 60 inch intervals.", "correct": false}, {"id": "c", "text": "at 40 inch intervals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Tritium Gas is used in a', '[{"id": "a", "text": "landing Light.", "correct": false}, {"id": "b", "text": "self illuminating lights.", "correct": true}, {"id": "c", "text": "strobe light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A strobe light is a light unit that takes form of glass tube filled with which gas and its light colour is what?', '[{"id": "a", "text": "Neon gas and blue.", "correct": false}, {"id": "b", "text": "Xenon Gas and blue-white.", "correct": true}, {"id": "c", "text": "Helium gas and white.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The aircraft has a partial failure of its emergency lighting system', '[{"id": "a", "text": "continue with reduced passenger load.", "correct": true}, {"id": "b", "text": "ferry flight to main base for rectification.", "correct": false}, {"id": "c", "text": "ground the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Navigation lights are supplied by the following circuit:', '[{"id": "a", "text": "Single circuit.", "correct": true}, {"id": "b", "text": "Individual circuits.", "correct": false}, {"id": "c", "text": "Dual circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Automatic no smoking sign will illuminate', '[{"id": "a", "text": "below 10,000ft and descending.", "correct": false}, {"id": "b", "text": "when landing gear is down.", "correct": true}, {"id": "c", "text": "unless switched off by the pilot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To purge an unpleasant odour/moisture from an oxygen system, you must', '[{"id": "a", "text": "completely empty and fill the system with nitrogen at least 3 times.", "correct": false}, {"id": "b", "text": "completely empty and fill the system with oxygen at least 3 times.", "correct": true}, {"id": "c", "text": "completely empty and fill the system with air at least 3 times.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen bottles should not be left with less that 500 psi pressure because', '[{"id": "a", "text": "it can damage the diluter demand regulator and would require maintenance.", "correct": false}, {"id": "b", "text": "the oxygen becomes tainted causing anoxia.", "correct": false}, {"id": "c", "text": "it can cause corrosion within the bottle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A dual demand regulator in oxygen system is for', '[{"id": "a", "text": "fitting to either gaseous or chemical oxygen cylinders.", "correct": false}, {"id": "b", "text": "altitude selection.", "correct": false}, {"id": "c", "text": "allowing two people to breath from one cylider.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The oxygen masks for the passengers drop down by', '[{"id": "a", "text": "manual selection from cockpit and automatically by an altitude switch.", "correct": true}, {"id": "b", "text": "automatically by an ltitude switch.", "correct": false}, {"id": "c", "text": "manual selection from cockpit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How would you identify an American oxygen bottle?', '[{"id": "a", "text": "It is painted the same colour as a British oxygen bottle (black).", "correct": false}, {"id": "b", "text": "It is white with green wording.", "correct": false}, {"id": "c", "text": "It is green.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When charging an oxygen cylinder, the pressure goes to zero. Where is the likely fault?', '[{"id": "a", "text": "In the pressure gauge.", "correct": false}, {"id": "b", "text": "In the mask.", "correct": true}, {"id": "c", "text": "In the temperature compensator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many turns of teflon tape are you allowed on oxygen threads and how many threads should have no tape?', '[{"id": "a", "text": "2 turns except first 2 threads.", "correct": true}, {"id": "b", "text": "2 turns except first thread.", "correct": false}, {"id": "c", "text": "1 turn except first thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Anoxia is due to', '[{"id": "a", "text": "release of nitrogen bubbles in the blood.", "correct": false}, {"id": "b", "text": "lack of oxygen.", "correct": true}, {"id": "c", "text": "low air pressure on the body.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The dilutor demand regulator functions', '[{"id": "a", "text": "only when the supply valve is opened by the user.", "correct": false}, {"id": "b", "text": "when the user breathes in.", "correct": true}, {"id": "c", "text": "all the time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To measure moisture in an oxygen system use', '[{"id": "a", "text": "a hygrometer using the dew point method.", "correct": true}, {"id": "b", "text": "litmus paper.", "correct": false}, {"id": "c", "text": "a glass plate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen cylinder test dates', '[{"id": "a", "text": "are painted in white on the cylinder.", "correct": true}, {"id": "b", "text": "may be stencilled on the neck of the cylinder.", "correct": false}, {"id": "c", "text": "are variable depending on discharge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'O2 system pressure has leaked away after charging. What is the most probable cause?', '[{"id": "a", "text": "Supernumerator regular.", "correct": false}, {"id": "b", "text": "Breathing regulator.", "correct": true}, {"id": "c", "text": "Temperature compensator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an O2 system is leaking, where would you most likely find the cause?', '[{"id": "a", "text": "Breathing mask.", "correct": true}, {"id": "b", "text": "Thermal Relief Valve.", "correct": false}, {"id": "c", "text": "Loose connection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'As the cabin altitude reaches 3042 metres', '[{"id": "a", "text": "the 02 masks deploy automatically and hang half way extended.", "correct": true}, {"id": "b", "text": "the 02 masks deploy automatically and the crew activates the system from the emergency panel.", "correct": false}, {"id": "c", "text": "the 02 masks deploy automatically and the crew must activate the system from the cockpit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen cylinders are normally fitted with', '[{"id": "a", "text": "oxygen purity gauge.", "correct": false}, {"id": "b", "text": "temperature gauge.", "correct": false}, {"id": "c", "text": "pressure and quantity gauges.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A demand regulator in a portable oxygen bottle opens', '[{"id": "a", "text": "all the time.", "correct": false}, {"id": "b", "text": "when breathing.", "correct": true}, {"id": "c", "text": "when 100% selected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Portable oxygen bottles are fitted with', '[{"id": "a", "text": "an overpressure indicator.", "correct": false}, {"id": "b", "text": "a demand regulator.", "correct": true}, {"id": "c", "text": "an over temperature indicator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'American made crew oxygen cylinders are', '[{"id": "a", "text": "green in colour with a LH thread.", "correct": false}, {"id": "b", "text": "green in colour with a RH thread.", "correct": true}, {"id": "c", "text": "black in colour with a RH thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which connector has a left hand thread?', '[{"id": "a", "text": "Freon.", "correct": false}, {"id": "b", "text": "N2.", "correct": false}, {"id": "c", "text": "O2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the principle of an O2 generator?', '[{"id": "a", "text": "Sodium chlorate and iron mixed by an electronic detonator.", "correct": false}, {"id": "b", "text": "Sodium chlorate and iron using a mechanical detonator producing O2 when mixed with air.", "correct": true}, {"id": "c", "text": "Sodium chloride and iron mixed by an electronic detonator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What pressure are oxygen cylinders usually pressurised to?', '[{"id": "a", "text": "1800 PSI.", "correct": true}, {"id": "b", "text": "300 PSI.", "correct": false}, {"id": "c", "text": "3000 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen storage cylinders, once charged should be', '[{"id": "a", "text": "turned on by crew.", "correct": false}, {"id": "b", "text": "turned on and safety wire-locked.", "correct": true}, {"id": "c", "text": "turned off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A thermal compensator is used in', '[{"id": "a", "text": "an hydraulic system.", "correct": false}, {"id": "b", "text": "a fuel system.", "correct": false}, {"id": "c", "text": "an oxygen system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When charging an oxygen bottle with gaseous oxygen, the oxygen is', '[{"id": "a", "text": "passed into the bottle as quickly as possible to keep the temperature down.", "correct": false}, {"id": "b", "text": "passed into the bottle slowly to keep the temperature at approximately ambient.", "correct": true}, {"id": "c", "text": "passed into the bottle at any rate as this does not affect temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Where are the left handed threads found in an oxygen system?', '[{"id": "a", "text": "Line valve", "correct": false}, {"id": "b", "text": "Charging connection", "correct": true}, {"id": "c", "text": "Shut-off valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Portable O2 diluter demand valve works when', '[{"id": "a", "text": "the user breathes in.", "correct": true}, {"id": "b", "text": "100% is selected.", "correct": false}, {"id": "c", "text": "less than 500 psi is in bottle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A double headed oxygen pressure regulator is used for', '[{"id": "a", "text": "additional flightcrew.", "correct": true}, {"id": "b", "text": "extra supply in case of emergency.", "correct": false}, {"id": "c", "text": "changes in altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft suddenly drops pressure at 14, 000 ft', '[{"id": "a", "text": "attendant must drop masks.", "correct": false}, {"id": "b", "text": "passenger must get mask from overhead stowage.", "correct": false}, {"id": "c", "text": "masks drop automatically.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How do oxygen cylinders show over pressure?', '[{"id": "a", "text": "Green rupturing disc.", "correct": true}, {"id": "b", "text": "Audible warning.", "correct": false}, {"id": "c", "text": "Red rupturing disc.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A discharged chemical generator is indicated by', '[{"id": "a", "text": "a broken tell-tale wire.", "correct": false}, {"id": "b", "text": "a change in colour.", "correct": true}, {"id": "c", "text": "a protruding pin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A chemical oxygen generator has a supply duration of at least', '[{"id": "a", "text": "15 minutes.", "correct": true}, {"id": "b", "text": "5 minutes.", "correct": false}, {"id": "c", "text": "30 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The oxygen line service valve must be', '[{"id": "a", "text": "wire locked open.", "correct": true}, {"id": "b", "text": "only be wire locked with telltale wire.", "correct": false}, {"id": "c", "text": "wire locked closed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen equipment must be carried by aircraft capable of flying above', '[{"id": "a", "text": "4,000 ft.", "correct": false}, {"id": "b", "text": "10,000ft.", "correct": true}, {"id": "c", "text": "8,000ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The critical altitude for oxygen requirement is approximately', '[{"id": "a", "text": "4,000 ft.", "correct": false}, {"id": "b", "text": "25,000 ft.", "correct": true}, {"id": "c", "text": "38,000 ft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If oxygen is not being supplied in normal flight conditions, the cabin altitude must be', '[{"id": "a", "text": "at a maximum of 12,000 ft.", "correct": false}, {"id": "b", "text": "below 10,000 ft.", "correct": false}, {"id": "c", "text": "at or below 8,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure breathing systems must be used at altitudes', '[{"id": "a", "text": "below 40,000 ft.", "correct": false}, {"id": "b", "text": "above 30,000 ft.", "correct": false}, {"id": "c", "text": "above 40,000 ft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a diluter demand oxygen system', '[{"id": "a", "text": "each member of the crew has a continuous oxygen supply.", "correct": false}, {"id": "b", "text": "oxygen is supplied with a continuous pressure flow.", "correct": false}, {"id": "c", "text": "each member of the crew has a regulator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a continuous flow oxygen system, oxygen is supplied', '[{"id": "a", "text": "on passenger inhaling into the mask.", "correct": false}, {"id": "b", "text": "when the mask is plugged into the socket.", "correct": true}, {"id": "c", "text": "only when the supply has been regulated by the pilot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In the diluter demand oxygen system, selection of emergency on this regulator will result in', '[{"id": "a", "text": "100% oxygen supply as the user inhales.", "correct": false}, {"id": "b", "text": "100% oxygen continuous flow at positive pressure.", "correct": true}, {"id": "c", "text": "100% oxygen at positive pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cylinder of a portable oxygen set is made of', '[{"id": "a", "text": "aluminium.", "correct": false}, {"id": "b", "text": "alloy steel.", "correct": true}, {"id": "c", "text": "stainless steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Portable oxygen cylinders are normally charged to', '[{"id": "a", "text": "1,800 p.s.i.", "correct": true}, {"id": "b", "text": "2,000 p.s.i.", "correct": false}, {"id": "c", "text": "1,200 p.s.i.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Rate of flow of oxygen is given in', '[{"id": "a", "text": "pounds/minute.", "correct": false}, {"id": "b", "text": "litres/minute.", "correct": true}, {"id": "c", "text": "litres/pounds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen cylinders are removed for overhaul and tested', '[{"id": "a", "text": "every 4 years.", "correct": true}, {"id": "b", "text": "every 6 years.", "correct": false}, {"id": "c", "text": "every 3 years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen bottle capacity varies between', '[{"id": "a", "text": "100 - 3200 litres.", "correct": false}, {"id": "b", "text": "200 - 2250 litres.", "correct": false}, {"id": "c", "text": "80 - 2250 litres.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen bottle test and working pressures can be found', '[{"id": "a", "text": "stencilled on the bottle.", "correct": true}, {"id": "b", "text": "stamped on the neck ring.", "correct": false}, {"id": "c", "text": "stamped on a metal label.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After installation, the oxygen bottle on/off valve is', '[{"id": "a", "text": "left in the ''on'' position.", "correct": false}, {"id": "b", "text": "left in the ''off'' position until required.", "correct": false}, {"id": "c", "text": "wire locked in the ''on''.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Dangerous pressure rise in oxygen cylinders', '[{"id": "a", "text": "is relieved by a thermostat.", "correct": false}, {"id": "b", "text": "is relieved by a bursting disc.", "correct": true}, {"id": "c", "text": "is relieved by under pressurising the bottle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To avoid condensation forming in an oxygen cylinder', '[{"id": "a", "text": "cylinder pressure is left at 200/300 p.s.i.", "correct": true}, {"id": "b", "text": "cylinder pressure is left at 100/200 p.s.i.", "correct": false}, {"id": "c", "text": "cylinder pressure is left at 300/400 p.s.i.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What determines the material used for oxygen pipe lines?', '[{"id": "a", "text": "The pressure used in the system.", "correct": true}, {"id": "b", "text": "The whims of the aircraft designer.", "correct": false}, {"id": "c", "text": "The length of the pipe runs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The direction of flow in an oxygen non return valve is indicated', '[{"id": "a", "text": "by colour coding.", "correct": false}, {"id": "b", "text": "by an arrow.", "correct": true}, {"id": "c", "text": "by visual inspection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen filters are made of', '[{"id": "a", "text": "carbon fibres.", "correct": false}, {"id": "b", "text": "sintered bronze.", "correct": true}, {"id": "c", "text": "steel wool.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Satisfactory operation of the oxygen systems is indicated by', '[{"id": "a", "text": "pressure indicators.", "correct": false}, {"id": "b", "text": "flow indicators.", "correct": true}, {"id": "c", "text": "lack of Anoxia.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If a binding thread needs attention on an oxygen system', '[{"id": "a", "text": "no lubricant may be used whatsoever.", "correct": false}, {"id": "b", "text": "Teflon tape may be used.", "correct": true}, {"id": "c", "text": "distilled water may be used sparingly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The international marking for a breathing oxygen pipeline is a series of', '[{"id": "a", "text": "rectangles.", "correct": true}, {"id": "b", "text": "dots.", "correct": false}, {"id": "c", "text": "diamonds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cylinders containing purified oxygen for breathing are painted', '[{"id": "a", "text": "white with a black collar.", "correct": false}, {"id": "b", "text": "black with a white collar.", "correct": true}, {"id": "c", "text": "black.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A suitable leak detecting solution for use on oxygen systems is', '[{"id": "a", "text": "grease free medical soap.", "correct": false}, {"id": "b", "text": "leak testing solution to Spec. MIL-L-25567B.", "correct": true}, {"id": "c", "text": "soapy water.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When charging an oxygen bottle with gaseous oxygen, the oxygen is', '[{"id": "a", "text": "passed into the bottle slowly to keep temperature at approximately ambient.", "correct": true}, {"id": "b", "text": "passed into the bottle at any rate as this does not affect temperature.", "correct": false}, {"id": "c", "text": "passed into the bottle as quickly as possible to keep the temperature down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In areas closely associated with oxygen systems, particular care must be taken to avoid leaving', '[{"id": "a", "text": "traces of oils or greases.", "correct": true}, {"id": "b", "text": "magnesium particles.", "correct": false}, {"id": "c", "text": "acrylic based plastic materials.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When working in the vicinity of an oxygen system', '[{"id": "a", "text": "the area must be well ventilated.", "correct": false}, {"id": "b", "text": "no electrical power must be used.", "correct": false}, {"id": "c", "text": "oil must not come into contact with the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A chemical oxygen generator operates at', '[{"id": "a", "text": "45°K at 10 psi for 15 minutes.", "correct": false}, {"id": "b", "text": "45°C at 10 psi for 15 minutes.", "correct": true}, {"id": "c", "text": "45°F at 10 psi for 15 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When charging an oxygen bottle in situ', '[{"id": "a", "text": "charge slowly through a water trap.", "correct": false}, {"id": "b", "text": "charge in accordance with the temperature/pressure graph.", "correct": true}, {"id": "c", "text": "slacken off the retaining straps first.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The gauge fitted to an oxygen bottle indicates', '[{"id": "a", "text": "purity.", "correct": false}, {"id": "b", "text": "pressure.", "correct": true}, {"id": "c", "text": "temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The application of thread lubrication tape in an oxygen system should be', '[{"id": "a", "text": "applied to all except the first two threads and not more than one complete wrap of tape.", "correct": false}, {"id": "b", "text": "applied to all the threads and not more than one complete wrap of tape.", "correct": false}, {"id": "c", "text": "applied to all except the first two threads and not more than 3 complete wraps of tape.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High pressure lines in oxygen systems are made of', '[{"id": "a", "text": "stainless steel.", "correct": true}, {"id": "b", "text": "aluminium alloy.", "correct": false}, {"id": "c", "text": "titanium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Lubricate oxygen connector threads using', '[{"id": "a", "text": "WD40.", "correct": false}, {"id": "b", "text": "Teflon tape.", "correct": true}, {"id": "c", "text": "hellerene.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is an expended chemical oxygen generator indicated?', '[{"id": "a", "text": "A pressure seal would be broken.", "correct": false}, {"id": "b", "text": "The indicator pin would be protruding.", "correct": false}, {"id": "c", "text": "By a change in colour of heat sensitive paint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Oxygen purging is a process of', '[{"id": "a", "text": "measuring the flow rate from the regulator.", "correct": false}, {"id": "b", "text": "pressure testing the system.", "correct": false}, {"id": "c", "text": "removing moisture from the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To check an oxygen system for moisture', '[{"id": "a", "text": "a sniff test is used.", "correct": false}, {"id": "b", "text": "a hygrometer is used.", "correct": true}, {"id": "c", "text": "pass 72 litres/min through a filter paper in a clean glass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Two compressors driven by separate engines use', '[{"id": "a", "text": "PRVs.", "correct": false}, {"id": "b", "text": "NRVs to prevent compressors driving each other.", "correct": true}, {"id": "c", "text": "Interconnected to share loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the moisture separator is purged in a pneumatic system, it dumps', '[{"id": "a", "text": "the whole system.", "correct": false}, {"id": "b", "text": "just the moisture trap.", "correct": true}, {"id": "c", "text": "the system between compressor and regulator valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High pressure pneumatic pump is a', '[{"id": "a", "text": "butterfly pump.", "correct": false}, {"id": "b", "text": "spur gear.", "correct": false}, {"id": "c", "text": "reciprocating pump.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A silica gel desiccant is required to be replaced', '[{"id": "a", "text": "when half pink and half blue.", "correct": false}, {"id": "b", "text": "when all pink.", "correct": true}, {"id": "c", "text": "when all blue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'High pressure pneumatic source is a', '[{"id": "a", "text": "centrifugal Compressor.", "correct": false}, {"id": "b", "text": "butterfly pump.", "correct": false}, {"id": "c", "text": "reciprocating pump.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a high pressure pneumatic system, if the drain plug for oil and water is left open for long periods of time, the system would', '[{"id": "a", "text": "lose pneumatic pressure partially.", "correct": false}, {"id": "b", "text": "lose pressure from the compressor side only.", "correct": true}, {"id": "c", "text": "lose all pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a pneumatic system, the maintainer valve will be fitted in supply lines to', '[{"id": "a", "text": "essential equipment.", "correct": false}, {"id": "b", "text": "all equipment.", "correct": false}, {"id": "c", "text": "non-essential equipment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the pneumatic water drain trap is left open for a long time it will drain', '[{"id": "a", "text": "all the system.", "correct": false}, {"id": "b", "text": "just the moisture trap.", "correct": false}, {"id": "c", "text": "between the compressor and the PRV.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is important about the air entering a dry air pump?', '[{"id": "a", "text": "It must be filtered.", "correct": true}, {"id": "b", "text": "It must be pressure controlled.", "correct": false}, {"id": "c", "text": "It must be temperature controlled.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pneumatic system pump is a', '[{"id": "a", "text": "rotor vane type.", "correct": false}, {"id": "b", "text": "piston type.", "correct": true}, {"id": "c", "text": "centrifugal type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What type of compressor is used on a pneumatic system?', '[{"id": "a", "text": "Rotary vane type.", "correct": false}, {"id": "b", "text": "Positive displacement type.", "correct": true}, {"id": "c", "text": "Spur gear type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of thermal protection on electric toilet motor?', '[{"id": "a", "text": "Prevent motor overheating and become fire hazard.", "correct": true}, {"id": "b", "text": "Prevent toilet freezing.", "correct": false}, {"id": "c", "text": "Stop motor running beyond 10 seconds if timer become unserviceable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The potable water is delivered to the galleys and toilets by', '[{"id": "a", "text": "electrical pump.", "correct": false}, {"id": "b", "text": "pneumatic pressure.", "correct": true}, {"id": "c", "text": "gravity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilet flush motor is protected from overheat by', '[{"id": "a", "text": "water cooling.", "correct": false}, {"id": "b", "text": "thermal protection.", "correct": true}, {"id": "c", "text": "cooling fan on timer switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Drinking water pipes are prevented from freezing by', '[{"id": "a", "text": "wrapping the pipes with heated tapes or ribbons.", "correct": true}, {"id": "b", "text": "installation of neoprene foam insulation.", "correct": false}, {"id": "c", "text": "placing the pipes adjacent to hot water piping.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A toilet recirculation fan is unserviceable in flight.', '[{"id": "a", "text": "Close toilet until landing.", "correct": true}, {"id": "b", "text": "It can be overcome by thermal compensating device.", "correct": false}, {"id": "c", "text": "You can use the toilet as the toxic chemical toilet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The process of hyperchlorination is to', '[{"id": "a", "text": "fill the tank with potable water.", "correct": false}, {"id": "b", "text": "decontaminate the potable system.", "correct": true}, {"id": "c", "text": "decontaminate the soil tank.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Waste water drain masts', '[{"id": "a", "text": "are heated using low amperage with the aircraft on ground only.", "correct": true}, {"id": "b", "text": "are not heated.", "correct": false}, {"id": "c", "text": "are heated using low amperage in the Air and on ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The heater used on a drain mast would be a', '[{"id": "a", "text": "induction heater.", "correct": false}, {"id": "b", "text": "ribbon heater.", "correct": true}, {"id": "c", "text": "hot air blower.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilet waste valves are', '[{"id": "a", "text": "spring loaded open.", "correct": false}, {"id": "b", "text": "spring loaded closed.", "correct": true}, {"id": "c", "text": "not spring loaded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilets are the subject of', '[{"id": "a", "text": "AWN 80.", "correct": false}, {"id": "b", "text": "AWN 83.", "correct": true}, {"id": "c", "text": "AWN 79.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The centralised soil tank system is flushed by', '[{"id": "a", "text": "recycled soil water.", "correct": false}, {"id": "b", "text": "potable water.", "correct": false}, {"id": "c", "text": "racasan.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A modern aircraft CMC uses', '[{"id": "a", "text": "a CRT screen.", "correct": true}, {"id": "b", "text": "a magnetic fault indicator.", "correct": false}, {"id": "c", "text": "an LED display.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Flight Data Recorder is activated when', '[{"id": "a", "text": "the helicopter''s engines are started.", "correct": true}, {"id": "b", "text": "the helicopter takes off.", "correct": false}, {"id": "c", "text": "when power is applied to the helicopter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An aircraft condition monitoring system', '[{"id": "a", "text": "detects the source of a fault.", "correct": false}, {"id": "b", "text": "stores information for long term error analysis.", "correct": true}, {"id": "c", "text": "sends information to the central maintenance cell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an autoland aircraft fitted with a CMC', '[{"id": "a", "text": "all faults are recorded in Non-Volatile memory.", "correct": true}, {"id": "b", "text": "only Primary Faults are recorded.", "correct": false}, {"id": "c", "text": "all faults are recorded in Volatile memory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a CMC system, where would you find a ''real time'' fault?', '[{"id": "a", "text": "In Fault.", "correct": true}, {"id": "b", "text": "In Test.", "correct": false}, {"id": "c", "text": "In Fault History.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In a CMC, warning signals are generated by', '[{"id": "a", "text": "Warning computer.", "correct": true}, {"id": "b", "text": "FMC.", "correct": false}, {"id": "c", "text": "CMC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the inputs in a CMC is autopilot controls. The data will be stored in', '[{"id": "a", "text": "erased only after end of sector.", "correct": false}, {"id": "b", "text": "volatile memory.", "correct": false}, {"id": "c", "text": "non-volatile memory.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The real time on a CMC is when', '[{"id": "a", "text": "ground test page is selected on the CDU.", "correct": false}, {"id": "b", "text": "existing faults page is selected on the CDU.", "correct": true}, {"id": "c", "text": "fault history page is selected on the CDU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A MCDU is', '[{"id": "a", "text": "to transmit data to ground.", "correct": false}, {"id": "b", "text": "to dialog with the central maintenance computer.", "correct": true}, {"id": "c", "text": "to store fault data.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'With a ACMS quick access recorder', '[{"id": "a", "text": "you must use digital tape.", "correct": false}, {"id": "b", "text": "the tape can have been used previously if it is first bulk erased.", "correct": true}, {"id": "c", "text": "the tape must not have been used before.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Above the glideslope, the ILS glideslope signal modulation is', '[{"id": "a", "text": "90 Hz.", "correct": true}, {"id": "b", "text": "90 KHZ.", "correct": false}, {"id": "c", "text": "150 Hz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In aircraft hydraulic systems, it is permissible to use', '[{"id": "a", "text": "any fluid of the same specific gravity.", "correct": false}, {"id": "b", "text": "any hydraulic fluid available.", "correct": false}, {"id": "c", "text": "only the specified fluid.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To check an oxygen system for moisture', '[{"id": "a", "text": "pass 72 litres/min through a filter paper in a clean glass.", "correct": false}, {"id": "b", "text": "a hygrometer is used.", "correct": true}, {"id": "c", "text": "a sniff test is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the purpose of diode in a power GCR?', '[{"id": "a", "text": "To prevent back-flow of current in the EMF coil.", "correct": true}, {"id": "b", "text": "To speed up the operation.", "correct": false}, {"id": "c", "text": "To allow flow in the event of failure of the relay.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are passenger door pressure loads transmitted to the fuselage structure?', '[{"id": "a", "text": "Through the latching mechanism.", "correct": false}, {"id": "b", "text": "By door stops.", "correct": true}, {"id": "c", "text": "By the pressure seal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To position the bogie beam at a suitable angle for retraction and landing, a', '[{"id": "a", "text": "hop damper is used.", "correct": true}, {"id": "b", "text": "snubber is used.", "correct": false}, {"id": "c", "text": "castoring damper is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection system can pass through one zone to another providing', '[{"id": "a", "text": "it is separated by steel.", "correct": false}, {"id": "b", "text": "the system is protected.", "correct": true}, {"id": "c", "text": "the system is duplicated.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How often do hand-held extinguishers have to be weighed?', '[{"id": "a", "text": "Annually.", "correct": true}, {"id": "b", "text": "Every 5 years.", "correct": false}, {"id": "c", "text": "Bi-annually.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Pressure refuelling is carried out at', '[{"id": "a", "text": "40 PSI.", "correct": true}, {"id": "b", "text": "20 PSI.", "correct": false}, {"id": "c", "text": "15 PSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'For a particular I.A.S. as the density decreases with altitude, the T.A.S.', '[{"id": "a", "text": "decreases.", "correct": false}, {"id": "b", "text": "remains the same.", "correct": false}, {"id": "c", "text": "increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In large air conditioning systems, the main fan is activated to', '[{"id": "a", "text": "ensure positive duct pressure is maintained.", "correct": false}, {"id": "b", "text": "ensure conditioned air is distributed.", "correct": false}, {"id": "c", "text": "ensure conditioned air is distributed and maintain positive duct pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The following takes place at the transition point on a wing:', '[{"id": "a", "text": "The boundary layer makes the transition from laminar flow to the turbulent boundary layer.", "correct": true}, {"id": "b", "text": "The total dynamic and static pressure comes to a standstill.", "correct": false}, {"id": "c", "text": "The airflow separates completely from the wing surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Extending the flaps while maintaining a constant angle of attack (all other factors constant)', '[{"id": "a", "text": "the aircraft will sink suddenly.", "correct": false}, {"id": "b", "text": "the aircraft will yaw.", "correct": false}, {"id": "c", "text": "the aircraft will climb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The advantages of integral fuel tanks are that they', '[{"id": "a", "text": "use the maximum volume for fuel and have the minimum amount of weight.", "correct": true}, {"id": "b", "text": "are cheaper to manufacture, more durable and easier to maintain.", "correct": false}, {"id": "c", "text": "are easier to design and construct and use the maximum volume of fuel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When checking a nicad battery in situ for serviceability', '[{"id": "a", "text": "the electrical circuits must be isolated before installing shorting strips.", "correct": false}, {"id": "b", "text": "a load is applied to the battery and the voltmeter reading noted.", "correct": true}, {"id": "c", "text": "a hydrometer must be used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To ensure that a wing stalls at the root first, stall wedges are', '[{"id": "a", "text": "installed on the wing leading edge at the wing tip.", "correct": false}, {"id": "b", "text": "installed on the wing leading edge at the wing root.", "correct": true}, {"id": "c", "text": "installed at the wing trailing edge at the wing root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Total Drag at high Mach numbers is a combination of', '[{"id": "a", "text": "wave drag, interference drag, form drag, and induced drag.", "correct": false}, {"id": "b", "text": "induced drag, wave drag, form drag, skin friction drag and interference drag.", "correct": true}, {"id": "c", "text": "profile drag, form drag, induced drag and wave drag.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When inflating a tyre and you notice ice in the valve stem', '[{"id": "a", "text": "wait for ice to melt before carrying on with inflation.", "correct": true}, {"id": "b", "text": "heat the valve stem gently with a blow torch.", "correct": false}, {"id": "c", "text": "carry on inflating as ice in the valve stem is no problem.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Due to the change of lift forces resulting from the extension of flaps in flight', '[{"id": "a", "text": "nose should be raised, increasing AoA.", "correct": false}, {"id": "b", "text": "nose should be lowered, reducing AoA.", "correct": true}, {"id": "c", "text": "nose should remain in the same position, maintaining same AoA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is true regarding deployment of Slats / Krueger flaps?', '[{"id": "a", "text": "Krueger flaps increase the critical angle of attack, Slats do not.", "correct": false}, {"id": "b", "text": "Slats form a slot, Krueger flaps do not.", "correct": true}, {"id": "c", "text": "Slats increase the critical angle of attack, Krueger flaps do not.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Buckling in a semi-monocoque structure is prevented by', '[{"id": "a", "text": "longerons.", "correct": false}, {"id": "b", "text": "bulkheads.", "correct": false}, {"id": "c", "text": "stringers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Vortex generators are fitted to', '[{"id": "a", "text": "move transition point forwards.", "correct": true}, {"id": "b", "text": "advance the onset of flow separation.", "correct": false}, {"id": "c", "text": "move transition point rearwards.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Glideslope controls autopilot in', '[{"id": "a", "text": "roll.", "correct": false}, {"id": "b", "text": "yaw.", "correct": false}, {"id": "c", "text": "pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The transition point located on the wing is the point where', '[{"id": "a", "text": "airflow starts separating from the wing.", "correct": false}, {"id": "b", "text": "the boundary layer changes from laminar flow to turbulent flow.", "correct": true}, {"id": "c", "text": "the airflow changes from subsonic to supersonic flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Ram Air Turbines have variable fan blades to', '[{"id": "a", "text": "maintain a constant speed.", "correct": true}, {"id": "b", "text": "produce maximun hydraulic pressure required by the system.", "correct": false}, {"id": "c", "text": "provide a constant flow rate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the main purpose of a frise aileron?', '[{"id": "a", "text": "Increase drag on the up going wing.", "correct": true}, {"id": "b", "text": "Decrease drag on the up going wing.", "correct": false}, {"id": "c", "text": "Help pilot overcome aerodynamic loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A wing mounted stall warning vane', '[{"id": "a", "text": "moves down at impending stall.", "correct": false}, {"id": "b", "text": "moves up at impending stall.", "correct": true}, {"id": "c", "text": "gives a visual indication of impending stall.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Bending stresses are a combination of', '[{"id": "a", "text": "torsional and compression stresses.", "correct": false}, {"id": "b", "text": "tension and compression stresses.", "correct": true}, {"id": "c", "text": "tension and shear stresses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a mono-spar wing, what gives the wing its profile contour?', '[{"id": "a", "text": "Milled stringers.", "correct": false}, {"id": "b", "text": "The position of the spars.", "correct": false}, {"id": "c", "text": "Ribs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The GPS satellite system consists of', '[{"id": "a", "text": "20 satellites and 5 standby satellite.", "correct": false}, {"id": "b", "text": "24 satellites and 1 standby satellites.", "correct": false}, {"id": "c", "text": "21 satellites and 3 standby satellites.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'FM improvements affect what system?', '[{"id": "a", "text": "VHF, VOR and ILS.", "correct": true}, {"id": "b", "text": "ADF, VHF and ILS.", "correct": false}, {"id": "c", "text": "ADF, VOR and ILS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The pneumatic system pump is a', '[{"id": "a", "text": "piston type.", "correct": true}, {"id": "b", "text": "centrifugal type.", "correct": false}, {"id": "c", "text": "rotor vane type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the reply frequency of an aircraft transponder?', '[{"id": "a", "text": "1090 MHz.", "correct": true}, {"id": "b", "text": "1030 MHz.", "correct": false}, {"id": "c", "text": "1000 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In an artificial horizon Pendulosity Error is caused by', '[{"id": "a", "text": "displacement of erection control device.", "correct": false}, {"id": "b", "text": "bottom lightness of inner gimbals.", "correct": false}, {"id": "c", "text": "bottom heaviness of inner gimbals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'To enable a hydraulic system to operate two components with different pressures, a', '[{"id": "a", "text": "pressure reducing valve is used.", "correct": true}, {"id": "b", "text": "pressure relief valve is used.", "correct": false}, {"id": "c", "text": "pressure regulating valve is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Critical Mach No. may be increased by', '[{"id": "a", "text": "using more powerful engines.", "correct": false}, {"id": "b", "text": "sweeping back the wing.", "correct": true}, {"id": "c", "text": "using a higher thickness/chord ratio wing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Wing bending and shear loads are taken by', '[{"id": "a", "text": "spar cap.", "correct": false}, {"id": "b", "text": "main spar.", "correct": true}, {"id": "c", "text": "skin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Subsequent to passing through the primary heat exchanger, the supply air in a turbo-fan cold air system flows to the', '[{"id": "a", "text": "inter cooler or secondary heat exchanger.", "correct": false}, {"id": "b", "text": "fan.", "correct": true}, {"id": "c", "text": "turbine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The final coat of sealing in a integral fuel tank is called', '[{"id": "a", "text": "interfay.", "correct": false}, {"id": "b", "text": "brush coat.", "correct": true}, {"id": "c", "text": "fillet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which systems provide envelope modulation information for a Ground Proximity Warning System (GPWS)', '[{"id": "a", "text": "Autothrottle.", "correct": false}, {"id": "b", "text": "Flaps/undercarriage.", "correct": true}, {"id": "c", "text": "Rudder/ailerons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When turbulence mode is selected, which other mode will not be available?', '[{"id": "a", "text": "VOR.", "correct": false}, {"id": "b", "text": "Heading Hold.", "correct": false}, {"id": "c", "text": "ALT Hold.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Stalling speed in a 15° bank level turn is 60kt. The stalling speed in a 45° bank level turn will be', '[{"id": "a", "text": "70 kts.", "correct": true}, {"id": "b", "text": "60 kts.", "correct": false}, {"id": "c", "text": "50 kts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If the weight of an aircraft is increased, the maximum lift-to-drag ratio will', '[{"id": "a", "text": "not be affected.", "correct": true}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When entering a stall, the CG of a straight wing will (i) and of a strongly swept wing will (ii)', '[{"id": "a", "text": "(i) not move, (ii) not move.", "correct": true}, {"id": "b", "text": "(i) move aft, (ii) move aft.", "correct": false}, {"id": "c", "text": "(i) move aft, (ii) not move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Upper surface wing skin is usually made from', '[{"id": "a", "text": "5056.", "correct": false}, {"id": "b", "text": "2024.", "correct": false}, {"id": "c", "text": "7075.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Toilets are the subject of', '[{"id": "a", "text": "AWN 80.", "correct": false}, {"id": "b", "text": "AWN 79.", "correct": false}, {"id": "c", "text": "AWN 83.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A tab which assists the pilot to move a flying control by moving automatically in the opposite direction to the control surface is called a', '[{"id": "a", "text": "trim tab.", "correct": false}, {"id": "b", "text": "servo tab.", "correct": false}, {"id": "c", "text": "geared balance tab.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Composite brake units', '[{"id": "a", "text": "have less weight than normal brake units and have increased efficiency at high temperatures.", "correct": true}, {"id": "b", "text": "weigh the same as normal brake units and fade away at high temperatures.", "correct": false}, {"id": "c", "text": "have less weight than normal brake units but fade away at high temperatures.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A capacitive fire wire', '[{"id": "a", "text": "will neither work nor test if broken circuit.", "correct": false}, {"id": "b", "text": "will work but not test if broken circuit.", "correct": true}, {"id": "c", "text": "will work but not test if short circuited.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An over station sensor (OSS) detects', '[{"id": "a", "text": "radio deviation signals proportional to distance from a localiser transmitter.", "correct": false}, {"id": "b", "text": "the rapid rate of the VOR signal over the cone of confusion.", "correct": true}, {"id": "c", "text": "radio deviation signals proportional to distance from a VOR transmitter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the principles of cooling employed in an air cycle system is', '[{"id": "a", "text": "by surface heat exchange in the C.A.U.", "correct": false}, {"id": "b", "text": "conversion of heat energy to mechanical energy in the C.A.U..", "correct": true}, {"id": "c", "text": "by compression of ambient air across a turbine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The angle of attack at which a wing stalls will', '[{"id": "a", "text": "remain the same regardless of centre of gravity position.", "correct": true}, {"id": "b", "text": "increase if the centre of gravity is moved forward.", "correct": false}, {"id": "c", "text": "increase if the centre of gravity is moved aft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The control of ventilating and pressurising air released to atmosphere is achieved by a', '[{"id": "a", "text": "pressure controller/dump valve combination.", "correct": false}, {"id": "b", "text": "pressure controller/discharge valve combination.", "correct": true}, {"id": "c", "text": "discharge valve/inwards relief valve combination.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'If an aircraft has alkaline batteries, the battery compartment drain pipes will be', '[{"id": "a", "text": "stainless steel.", "correct": true}, {"id": "b", "text": "aluminium alloy.", "correct": false}, {"id": "c", "text": "plastic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On passenger aircraft of two or more zones', '[{"id": "a", "text": "the seat backs fold forward at over wing emergency exits.", "correct": false}, {"id": "b", "text": "the emergency exits are to be clearly signed.", "correct": false}, {"id": "c", "text": "there should be at least one exit per zone.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What is the maximum allowable concentration (by volume) of carbon monoxide in occupied aircraft compartment?', '[{"id": "a", "text": "0.01 % (100 p.p.m).", "correct": false}, {"id": "b", "text": "0.02 % (200 p.p.m).", "correct": false}, {"id": "c", "text": "0.005% (50 p.p.m).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How are passenger reading lights normally tested?', '[{"id": "a", "text": "Each one is switched on individually at passenger panel.", "correct": false}, {"id": "b", "text": "By using a READ LIGHT TEST switch on the cabin attendant panel.", "correct": true}, {"id": "c", "text": "By using a READ LIGHT TEST switch at any passenger panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Frequency (Hz) is the number of cycles per', '[{"id": "a", "text": "revolution.", "correct": false}, {"id": "b", "text": "minute.", "correct": false}, {"id": "c", "text": "second.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Frequency wild'' alternators supply', '[{"id": "a", "text": "resistive circuits.", "correct": true}, {"id": "b", "text": "capacitive circuits.", "correct": false}, {"id": "c", "text": "inductive circuits.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'You would expect to find a squib connected to', '[{"id": "a", "text": "a fire detection system.", "correct": false}, {"id": "b", "text": "a fire suppression system.", "correct": true}, {"id": "c", "text": "a smoke detection system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On engine shutdown, what prevents GCR being tripped?', '[{"id": "a", "text": "Under-frequency.", "correct": true}, {"id": "b", "text": "Under-current.", "correct": false}, {"id": "c", "text": "Under-volt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When pressurising the aircraft on the ground for test purposes, internal doors, cupboards etc. must be', '[{"id": "a", "text": "all closed.", "correct": false}, {"id": "b", "text": "all open.", "correct": true}, {"id": "c", "text": "removed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When replacing a flexible pipe', '[{"id": "a", "text": "do a bonding check.", "correct": false}, {"id": "b", "text": "tighten only hand tight.", "correct": false}, {"id": "c", "text": "use two spanners to stop pipe from twisting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is the the glideslope frequency chosen on the navigation control panel?', '[{"id": "a", "text": "Via the G/S selector knob.", "correct": false}, {"id": "b", "text": "It is not manually chosen. It is paired with the localizer frequency.", "correct": true}, {"id": "c", "text": "It is not manually chosen. It is paired with the VOR frequency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'An artificial feel system is required', '[{"id": "a", "text": "for power assisted control systems.", "correct": false}, {"id": "b", "text": "for power operated control systems.", "correct": true}, {"id": "c", "text": "for proportional control systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The servicing and charging of nickel-cadmium and lead-acid batteries together in the same service area is likely to result in', '[{"id": "a", "text": "contamination of both types of batteries.", "correct": true}, {"id": "b", "text": "normal battery service life.", "correct": false}, {"id": "c", "text": "increased explosion and/or fire hazard.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Turn and Slip indicator employs', '[{"id": "a", "text": "a rate gyro.", "correct": true}, {"id": "b", "text": "an azimuth gyro.", "correct": false}, {"id": "c", "text": "a vertical gyro.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What are the four stresses to be considered when building an aircraft?', '[{"id": "a", "text": "Compression, Torsion, Tension, Shear.", "correct": true}, {"id": "b", "text": "Compression, Torsion, Stress, Strain.", "correct": false}, {"id": "c", "text": "Compression, Tension, Torsion, Stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'When the fire-handle switch is pulled, a', '[{"id": "a", "text": "red warning light stays on. Generator, hydraulics, & fuel is cut off.", "correct": true}, {"id": "b", "text": "red warning light goes off. Generator goes offline.", "correct": false}, {"id": "c", "text": "red warning light stays on. Generator, hydraulics & fuel stays on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'After a tank bag has been replaced, a fuel flow test should be carried out at', '[{"id": "a", "text": "tank outlet.", "correct": false}, {"id": "b", "text": "engine inlet.", "correct": true}, {"id": "c", "text": "tank shut-off valve point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Before filling a vapour cycle cooling system', '[{"id": "a", "text": "pre-heat the system to 100°F.", "correct": false}, {"id": "b", "text": "apply suction to remove air and moisture.", "correct": true}, {"id": "c", "text": "flush the system with a solvent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What happens if you reduce the curvature of the leading edge?', '[{"id": "a", "text": "Advance the shock wave formation.", "correct": false}, {"id": "b", "text": "It will have no effect on shock wave formation.", "correct": false}, {"id": "c", "text": "Delay the shock wave formation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'One of the advantages of the semi-monocoque construction is that it', '[{"id": "a", "text": "is easier to manufacture.", "correct": false}, {"id": "b", "text": "takes all the loads in the skin.", "correct": false}, {"id": "c", "text": "shares the loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'HF aerials have weak points designed at', '[{"id": "a", "text": "both ends.", "correct": false}, {"id": "b", "text": "the back end.", "correct": true}, {"id": "c", "text": "the front end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Restrictor valves are fitted in hydraulic systems to', '[{"id": "a", "text": "restrict the rate of pressure build-up.", "correct": false}, {"id": "b", "text": "limit the maximum pressure.", "correct": false}, {"id": "c", "text": "control rate of system operation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fire detection system should be', '[{"id": "a", "text": "positioned in a location determined by the manufacture during the design.", "correct": true}, {"id": "b", "text": "designed to detect fires only.", "correct": false}, {"id": "c", "text": "designed to withstand vibration & mechanical loads sustained during normal operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'In typical vapour cycle system, the sub-cooler', '[{"id": "a", "text": "cools the vapour further to prevent slugging.", "correct": false}, {"id": "b", "text": "is a heat exchanger to superheat the vapour.", "correct": true}, {"id": "c", "text": "delivers extra cooling effect when the aircraft is on ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A constant speed drive unit has a warning light indication', '[{"id": "a", "text": "for when it is disconnected from the generator.", "correct": false}, {"id": "b", "text": "for low speed.", "correct": false}, {"id": "c", "text": "for low oil pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The Middle Marker beacon is what colour?', '[{"id": "a", "text": "White", "correct": false}, {"id": "b", "text": "Amber.", "correct": true}, {"id": "c", "text": "Blue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a CWS, which has the highest priority?', '[{"id": "a", "text": "Hydraulic pump failure.", "correct": false}, {"id": "b", "text": "Fire warning.", "correct": true}, {"id": "c", "text": "Duct overheat", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A universal protractor used to measure degrees of aileron travel should be zeroed', '[{"id": "a", "text": "when the aircraft is in level flight attitude.", "correct": false}, {"id": "b", "text": "with the aileron in the neutral position.", "correct": true}, {"id": "c", "text": "with the aileron in the down position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Over-voltage condition trips the generator. The time taken to trip the GCU depends on', '[{"id": "a", "text": "time delay circuit.", "correct": false}, {"id": "b", "text": "amplitude of voltage.", "correct": true}, {"id": "c", "text": "closing of fuel and hydraulic valves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The cabin altitude is', '[{"id": "a", "text": "the actual height of the aircraft above sea level.", "correct": false}, {"id": "b", "text": "the equivalent height of the aircraft above sea level.", "correct": true}, {"id": "c", "text": "the difference between cabin pressure and atmospheric pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How is an aircraft battery rated?', '[{"id": "a", "text": "Ampere hours", "correct": true}, {"id": "b", "text": "Joules", "correct": false}, {"id": "c", "text": "Watts", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Airworthiness requirements for large aircraft are found in', '[{"id": "a", "text": "ANO 25", "correct": false}, {"id": "b", "text": "JAR 25", "correct": false}, {"id": "c", "text": "CS 25", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What pressure are oxygen cylinders usually pressurised to?', '[{"id": "a", "text": "1800 PSI", "correct": true}, {"id": "b", "text": "300 PSI", "correct": false}, {"id": "c", "text": "3000 PSI", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'How many programs can a FMC store?', '[{"id": "a", "text": "Two. One active and one standby.", "correct": true}, {"id": "b", "text": "One current.", "correct": false}, {"id": "c", "text": "Two. Both active.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'What determines the material used for oxygen pipe lines?', '[{"id": "a", "text": "The whims of the aircraft designer.", "correct": false}, {"id": "b", "text": "The length of the pipe runs.", "correct": false}, {"id": "c", "text": "The pressure used in the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The input to a stick shaker comes from', '[{"id": "a", "text": "angle of attack, and sometimes the rate of change in angle of attack.", "correct": true}, {"id": "b", "text": "the airspeed, and sometimes the rate of change in airspeed.", "correct": false}, {"id": "c", "text": "the angle of attack only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'ATA zone 330 is the', '[{"id": "a", "text": "vertical stabiliser.", "correct": false}, {"id": "b", "text": "left horizontal stabiliser.", "correct": true}, {"id": "c", "text": "right horizontal stabiliser.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'From where is bearing information received for display on the digital-distance radio-magnetic indicator (DDRMI)?', '[{"id": "a", "text": "From VOR and ADF systems.", "correct": true}, {"id": "b", "text": "From VOR only.", "correct": false}, {"id": "c", "text": "From ADF only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Calcium Chromate tablets can be fitted in integral tanks. Before installation the linen bag should be wetted with', '[{"id": "a", "text": "Kerosene.", "correct": false}, {"id": "b", "text": "Water.", "correct": true}, {"id": "c", "text": "Methylated Spirit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Seat track cutouts provide for various seat spacings, usually in', '[{"id": "a", "text": "one inch increments.", "correct": true}, {"id": "b", "text": "one foot increments.", "correct": false}, {"id": "c", "text": "half inch increments.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A large aircraft air conditioning system''s cabin temperature control', '[{"id": "a", "text": "is selectable for each zone individually from the flight station.", "correct": true}, {"id": "b", "text": "involves modulating the pack valve.", "correct": false}, {"id": "c", "text": "all zone temperatures are controlled from one master switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Topping up a Ni-Cad battery in situ', '[{"id": "a", "text": "is permitted.", "correct": false}, {"id": "b", "text": "is only allowed in the shop.", "correct": false}, {"id": "c", "text": "is not allowed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A redundant structure is', '[{"id": "a", "text": "a safe-life structure.", "correct": false}, {"id": "b", "text": "on-condition structure.", "correct": false}, {"id": "c", "text": "a failsafe structure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Paint remover substances', '[{"id": "a", "text": "should only be used once.", "correct": false}, {"id": "b", "text": "are damaging to some aircraft parts.", "correct": true}, {"id": "c", "text": "are not damaging to any aircraft parts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'The mass flow delivery from engine driven blowers is controlled by', '[{"id": "a", "text": "automatic control devices.", "correct": false}, {"id": "b", "text": "engine speed variations.", "correct": false}, {"id": "c", "text": "spill valves.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On a modern aircraft flight instrument display system, radio deviation is shown on the', '[{"id": "a", "text": "EADI.", "correct": false}, {"id": "b", "text": "EHSI & EADI.", "correct": true}, {"id": "c", "text": "EHSI.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Which instrument are most likely to damage if you have a rapid drop in pressure, when carrying out a pitot-static leak check?', '[{"id": "a", "text": "Vertical speed indicator.", "correct": true}, {"id": "b", "text": "Air speed indicator.", "correct": false}, {"id": "c", "text": "Altimeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A fuel crossfeed valve is usually in', '[{"id": "a", "text": "the closed position.", "correct": true}, {"id": "b", "text": "its last position.", "correct": false}, {"id": "c", "text": "the open position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'On large aircraft, braked wheel assemblies are normally inflated with', '[{"id": "a", "text": "nitrogen.", "correct": true}, {"id": "b", "text": "nitrogen and not more than 5% of air.", "correct": false}, {"id": "c", "text": "an argon and CO2 mixture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Track altitude in a radio altimeter system begins at', '[{"id": "a", "text": "2 500 ft radio alt..", "correct": true}, {"id": "b", "text": "1 000 ft radio alt..", "correct": false}, {"id": "c", "text": "10 000 ft radio alt..", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A Schuler pendulum has a period of oscillation of', '[{"id": "a", "text": "8.4 minutes.", "correct": false}, {"id": "b", "text": "84.4 seconds.", "correct": false}, {"id": "c", "text": "84.4 minutes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A lead-acid battery is considered to be fully charged when the', '[{"id": "a", "text": "cells begin to gas freely.", "correct": false}, {"id": "b", "text": "S.G. and voltage remain constant for specified period.", "correct": true}, {"id": "c", "text": "S.G. reaches 1.180.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Voltage is controlled by', '[{"id": "a", "text": "the constant speed drive.", "correct": false}, {"id": "b", "text": "the voltage regulator.", "correct": true}, {"id": "c", "text": "the swashplate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Deploying a secondary flight control surface will', '[{"id": "a", "text": "decrease the angle of attack of the aerofoil.", "correct": false}, {"id": "b", "text": "increase the angle of attack of the aerofoil.", "correct": true}, {"id": "c", "text": "not affect the angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'Cabin differential pressure is the pressure difference between', '[{"id": "a", "text": "8,000ft and standard barometric pressure.", "correct": false}, {"id": "b", "text": "the pressure inside the aircraft and the ambient air pressure.", "correct": true}, {"id": "c", "text": "sea level air pressure and indicated dynamic pressure in the cabin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M11.21'), 'A flying control mass balance weight', '[{"id": "a", "text": "keeps the control surface C of G as close to the trailing edge as possible.", "correct": false}, {"id": "b", "text": "ensures that the C of G always acts to aid the pilot thus relieving control column load.", "correct": false}, {"id": "c", "text": "tends to move the control surface C of G close to the hinge line.", "correct": true}]'::jsonb, '{B1,B2}');
